    void DeviceGraphOrchestrator::clearPendingMTPPrefillTerminalArchiveReady()
    {
        mtp_prefill_terminal_archive_ready_.valid = false;
        mtp_prefill_terminal_archive_ready_.producer_stream = nullptr;
    }

    bool DeviceGraphOrchestrator::prepareLivePrefixMutationReadyEvent(
        void *producer_stream,
        const char *producer_name)
    {
        if (!state_.device_id.is_gpu())
            return true;
        if (!producer_stream)
        {
            LOG_ERROR(
                "[DeviceGraphOrchestrator] Live prefix mutation event "
                "preflight requires an explicit stream for producer="
                << (producer_name && producer_name[0] != '\0'
                        ? producer_name
                        : "unknown"));
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        retirePendingPrefixPayloadUses(/*wait_for_all=*/false);

        auto &ready = live_prefix_mutation_ready_;
        if (ready.event)
        {
            if (ready.producer_stream &&
                ready.producer_stream != producer_stream)
            {
                LOG_ERROR(
                    "[DeviceGraphOrchestrator] Live prefix mutation event "
                    "preflight found an unconsumed event on another stream");
                return false;
            }
            ready.producer_stream = producer_stream;
            return true;
        }

        void *raw_event =
            backend->createEvent(state_.device_id.gpu_ordinal());
        if (!raw_event)
        {
            LOG_ERROR(
                "[DeviceGraphOrchestrator] Failed to allocate live prefix "
                "mutation readiness event during preflight");
            return false;
        }
        const int device_ordinal = state_.device_id.gpu_ordinal();
        ready.event = std::shared_ptr<void>(
            raw_event,
            [backend, device_ordinal](void *event)
            {
                if (event)
                    backend->destroyEvent(event, device_ordinal);
            });
        ready.producer_stream = producer_stream;
        return true;
    }

    bool DeviceGraphOrchestrator::recordLivePrefixMutationReady(
        void *producer_stream,
        const char *producer_name,
        std::vector<PrefixBlockHandle> retained_payload_sources,
        std::vector<std::shared_ptr<void>> retained_device_sources)
    {
        if (!state_.device_id.is_gpu())
            return true;
        if (!producer_stream)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Live prefix mutation readiness requires an explicit producer stream");
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        auto &ready = live_prefix_mutation_ready_;
        if (!ready.event &&
            !prepareLivePrefixMutationReadyEvent(
                producer_stream,
                producer_name))
        {
            if (!retained_payload_sources.empty() ||
                !retained_device_sources.empty())
            {
                LOG_ERROR(
                    "[DeviceGraphOrchestrator] Prefix restore reached commit "
                    "without a preflighted completion event");
                std::terminate();
            }
            return false;
        }
        if (ready.producer_stream != producer_stream)
        {
            LOG_ERROR(
                "[DeviceGraphOrchestrator] Live prefix mutation commit stream "
                "does not match its preflighted event stream");
            if (!retained_payload_sources.empty() ||
                !retained_device_sources.empty())
            {
                std::terminate();
            }
            return false;
        }

        if (!backend->recordEvent(
                ready.event.get(),
                state_.device_id.gpu_ordinal(),
                producer_stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to record live prefix mutation readiness event");
            if (!retained_payload_sources.empty() ||
                !retained_device_sources.empty() ||
                !ready.retained_payload_sources.empty() ||
                !ready.retained_device_sources.empty())
            {
                /*
                 * The backend accepted asynchronous reads from cache-owned
                 * bytes but cannot publish their completion edge. Releasing
                 * those owners or changing to synchronous execution would both
                 * violate the production contract, so stop immediately.
                 */
                std::terminate();
            }
            return false;
        }

        for (auto &source : retained_payload_sources)
        {
            ready.retained_payload_sources.push_back(std::move(source));
        }
        for (auto &source : retained_device_sources)
        {
            ready.retained_device_sources.push_back(std::move(source));
        }
        ready.valid = true;
        ready.producer_stream = producer_stream;
        ready.live_state_epoch = live_replay_state_epoch_;
        PerfStatsCollector::addCounter(
            "mtp",
            "live_prefix_mutation_ready_events",
            1.0,
            perfPhaseName(),
            state_.device_id.toString(),
            {{"producer", producer_name && producer_name[0] != '\0'
                              ? producer_name
                              : "unknown"},
             {"live_state_epoch", std::to_string(ready.live_state_epoch)}});
        return true;
    }

    bool DeviceGraphOrchestrator::waitForPendingLivePrefixMutationReady(
        void *consumer_stream,
        const char *consumer_name)
    {
        if (!state_.device_id.is_gpu())
            return true;
        auto &ready = live_prefix_mutation_ready_;
        if (!ready.valid)
            return true;
        if (!consumer_stream)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Pending live prefix mutation consumer requires an explicit stream");
            return false;
        }
        if (!ready.event)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Pending live prefix mutation is marked valid without an event");
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        const bool same_stream = ready.producer_stream == consumer_stream;
        if (!same_stream &&
            !backend->streamWaitEvent(
                consumer_stream,
                ready.event.get(),
                state_.device_id.gpu_ordinal()))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to queue live prefix mutation wait for consumer="
                      << (consumer_name && consumer_name[0] != '\0'
                              ? consumer_name
                              : "unknown"));
            return false;
        }

        PerfStatsCollector::addCounter(
            "mtp",
            "live_prefix_mutation_ready_waits",
            1.0,
            perfPhaseName(),
            state_.device_id.toString(),
            {{"consumer", consumer_name && consumer_name[0] != '\0'
                              ? consumer_name
                              : "unknown"},
             {"same_stream", boolTag(same_stream)},
             {"live_state_epoch", std::to_string(ready.live_state_epoch)}});
        clearPendingLivePrefixMutationReady();
        return true;
    }

    bool DeviceGraphOrchestrator::waitForPendingLivePrefixMutationReadyForObservation(
        void *consumer_stream,
        const char *consumer_name) const
    {
        if (!state_.device_id.is_gpu())
            return true;
        const auto &ready = live_prefix_mutation_ready_;
        if (!ready.valid)
            return true;
        if (!consumer_stream)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Pending live prefix mutation observation requires an explicit stream");
            return false;
        }
        if (!ready.event)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Pending live prefix mutation observation is marked valid without an event");
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        const bool same_stream = ready.producer_stream == consumer_stream;
        if (!same_stream &&
            !backend->streamWaitEvent(
                consumer_stream,
                ready.event.get(),
                state_.device_id.gpu_ordinal()))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to queue live prefix mutation observation wait for consumer="
                      << (consumer_name && consumer_name[0] != '\0'
                              ? consumer_name
                              : "unknown"));
            return false;
        }

        PerfStatsCollector::addCounter(
            "mtp",
            "live_prefix_mutation_observation_waits",
            1.0,
            perfPhaseName(),
            state_.device_id.toString(),
            {{"consumer", consumer_name && consumer_name[0] != '\0'
                              ? consumer_name
                              : "unknown"},
             {"same_stream", boolTag(same_stream)},
             {"live_state_epoch", std::to_string(ready.live_state_epoch)}});
        return true;
    }

    void DeviceGraphOrchestrator::clearPendingLivePrefixMutationReady()
    {
        auto &ready = live_prefix_mutation_ready_;
        if (ready.event &&
            (!ready.retained_payload_sources.empty() ||
             !ready.retained_device_sources.empty()))
        {
            PendingPrefixPayloadUse pending;
            pending.completion_event = std::move(ready.event);
            pending.retained_payload_sources =
                std::move(ready.retained_payload_sources);
            pending.retained_device_sources =
                std::move(ready.retained_device_sources);
            pending_prefix_payload_uses_.push_back(std::move(pending));
        }

        ready.valid = false;
        ready.producer_stream = nullptr;
        ready.live_state_epoch = 0;
        ready.retained_payload_sources.clear();
        ready.retained_device_sources.clear();
        ready.event.reset();
        retirePendingPrefixPayloadUses(/*wait_for_all=*/false);
    }

    void DeviceGraphOrchestrator::retirePendingPrefixPayloadUses(
        bool wait_for_all) const
    {
        if (pending_prefix_payload_uses_.empty())
            return;

        IBackend *backend = getBackendFor(state_.device_id);
        std::vector<PendingPrefixPayloadUse> still_pending;
        still_pending.reserve(pending_prefix_payload_uses_.size());
        size_t retired = 0;

        for (auto &pending : pending_prefix_payload_uses_)
        {
            if (!pending.valid())
                continue;

            bool complete = false;
            if (wait_for_all)
            {
                complete =
                    backend &&
                    backend->waitForEvent(
                        pending.completion_event.get(),
                        state_.device_id.gpu_ordinal());
                if (!complete)
                {
                    LOG_ERROR(
                        "[DeviceGraphOrchestrator] Could not close an exact "
                        "prefix restore payload event during teardown");
                    std::terminate();
                }
            }
            else
            {
                try
                {
                    auto &gpu_context =
                        GPUDeviceContextPool::instance().getContext(
                            state_.device_id);
                    bool event_ready = false;
                    const bool query_succeeded =
                        gpu_context.queryEventChecked(
                            pending.completion_event.get(),
                            event_ready);
                    complete = query_succeeded && event_ready;
                }
                catch (const std::exception &error)
                {
                    LOG_DEBUG(
                        "[DeviceGraphOrchestrator] Could not query prefix "
                        "restore payload completion on "
                        << state_.device_id.toString() << ": "
                        << error.what());
                    complete = false;
                }
            }

            if (complete)
            {
                ++retired;
                continue;
            }
            still_pending.push_back(std::move(pending));
        }

        pending_prefix_payload_uses_.swap(still_pending);
        if (retired > 0)
        {
            PerfStatsCollector::addCounter(
                "prefix_cache",
                "restore_payload_uses_retired",
                static_cast<double>(retired),
                "restore",
                state_.device_id.toString(),
                {{"waited", wait_for_all ? "true" : "false"}});
        }
    }

    bool DeviceGraphOrchestrator::waitForLiveInferenceStateReadyForObservation(
        void *observation_stream,
        const char *observation_name,
        DeviceTimelineRole observation_role) const
    {
        if (!state_.device_id.is_gpu())
            return true;
        if (!observation_stream)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Live inference-state observation requires an explicit stream");
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "live_inference_state_observation",
                "ExplicitObservationStream",
                observation_name);
        }

        const char *consumer =
            observation_name && observation_name[0] != '\0'
                ? observation_name
                : "live_inference_state_observation";

        /*
         * This method is the read-only counterpart to the restore/truncate and
         * forward-consumer handoff paths.  Do not add ad hoc waits at probe or
         * prefix-cache call sites: if a new live-state owner is introduced, it
         * belongs here so every host-visible KV/GDN/MTP export observes the
         * same producer set.
         */
        if (!waitForPendingLivePrefixCheckpointReadyForObservation(
                observation_stream,
                consumer))
        {
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "live_inference_state_observation",
                "LivePrefixCheckpointReady",
                consumer);
        }
        if (!waitForPendingAcceptedSpecPublicationReadyForObservation(
                observation_stream,
                consumer))
        {
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "live_inference_state_observation",
                "AcceptedSpecPublicationReady",
                consumer);
        }
        if (!waitForPendingLivePrefixMutationReadyForObservation(
                observation_stream,
                consumer))
        {
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "live_inference_state_observation",
                "LivePrefixMutationReady",
                consumer);
        }
        if (!waitForPendingLiveGraphProducersForObservation(
                observation_stream,
                consumer,
                observation_role))
        {
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "live_inference_state_observation",
                "LiveGraphProducersReady",
                consumer);
        }
        const DeviceResidentMTPTransactionLease transaction =
            currentDeviceResidentMTPTransactionLease();
        if (transaction.valid() &&
            !waitForDeviceResidentMTPTransaction(
                transaction,
                observation_stream,
                consumer))
        {
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "live_inference_state_observation",
                "MTPTransactionReady",
                consumer);
        }
        if (!waitForDeviceResidentLogicalSequenceStateMailboxForObservation(
                observation_stream,
                consumer))
        {
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "live_inference_state_observation",
                "LogicalSequenceStateReady",
                consumer);
        }
        return true;
    }

    bool DeviceGraphOrchestrator::prepareAllPositionVerifierGraphMetadata(
        const ForwardInput &input,
        void *execution_stream,
        DeviceId execution_device)
    {
        if (!compute_all_position_logits_ ||
            !compute_row_indexed_all_position_logits_)
        {
            return true;
        }

        // CPU row selection consumes the row plan captured in the graph builder.
        // The metadata workspace is needed only when GPU cached graphs read row
        // indices from persistent device buffers during replay.
        if (!state_.device_id.is_gpu())
        {
            PerfStatsCollector::addCounter(
                "mtp",
                "verifier_row_metadata_path",
                1.0,
                "decode",
                state_.device_id.toString(),
                {{"path", "cpu_builder_row_plan"},
                 {"rows", std::to_string(row_indexed_all_position_logits_row_count_)}});
            return true;
        }

        if (!execution_stream)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Row-indexed GPU verifier metadata upload requires an explicit stream");
            return false;
        }

        /*
         * The all-position verifier reads both the main live state and the
         * shifted MTP KV cache prepared by the immediately preceding sidecar
         * catch-up step.  Full sidecar forwards publish a logits-stream
         * handoff, but KV-only catch-up intentionally publishes a narrower
         * shifted-KV event.  Consume that event here so cached verifier graph
         * replay cannot race a deferred shifted-cache append.
         */
        if (!waitForPendingShiftedMTPKVReady(
                execution_stream,
                "all_position_verifier_shifted_mtp_kv"))
        {
            return false;
        }

        const DeviceId metadata_device =
            execution_device.is_gpu() ? execution_device : state_.device_id;
        IBackend *backend = getBackendFor(metadata_device);
        if (!backend)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] No backend for verifier metadata upload on "
                      << metadata_device.toString());
            return false;
        }
        if (!waitForPendingLogitsStream(
                PendingLogitsStreamRole::MTPSidecar,
                execution_stream,
                "all_position_verifier_graph"))
        {
            return false;
        }

        const int expected_rows = row_indexed_all_position_logits_row_count_;
        if (!pending_mtp_spec_verifier_input_plan_)
        {
            /*
             * Request-batched GPU prefill is not a verifier transaction. Its
             * row-select stage reads request lengths directly from the arena
             * and derives flattened terminal rows inside the captured kernel.
             * Do not upload a host row shadow into the verifier workspace: that
             * buffer has a separate lifetime and remains exclusively owned by
             * actual verifier metadata producers.
             */
            if (request_batched_prefill_logits_row_count_ >= expected_rows &&
                input.sequence_lengths_device &&
                input.batch_size == expected_rows &&
                input.seq_len > 0)
            {
                PerfStatsCollector::addCounter(
                    "mtp",
                    "verifier_row_metadata_path",
                    1.0,
                    "prefill",
                    metadata_device.toString(),
                    {{"path", "request_batched_prefill_resident_lengths"},
                     {"rows", std::to_string(expected_rows)}});
                return true;
            }

            LOG_ERROR("[DeviceGraphOrchestrator] Row-indexed GPU verifier graph has no pending MTP row plan or request-prefill row plan");
            return false;
        }

        const auto &plan = *pending_mtp_spec_verifier_input_plan_;
        if (plan.compact_logit_row_count != expected_rows)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Verifier row plan count "
                      << plan.compact_logit_row_count
                      << " does not match graph row count " << expected_rows);
            return false;
        }
        if (mtp_verifier_outcome_graph_mode_ ==
            MTPVerifierOutcomeGraphMode::Greedy)
        {
            const auto &transaction =
                greedy_verifier_outcome_graph_transaction_;
            if (transaction.state !=
                    GreedyVerifierOutcomeGraphState::Armed ||
                transaction.verifier_token_count != expected_rows ||
                !mtp_verifier_stop_tokens_dev_)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Greedy verifier graph controls do not match the compact row plan"
                          << " state="
                          << static_cast<int>(transaction.state)
                          << " transaction_rows="
                          << transaction.verifier_token_count
                          << " graph_rows=" << expected_rows
                          << " stop_buffer="
                          << mtp_verifier_stop_tokens_dev_);
                return false;
            }
            if (!backend->hostToDeviceOnStream(
                    mtp_verifier_stop_tokens_dev_,
                    transaction.stop_tokens.data(),
                    sizeof(int32_t) *
                        sampling_math::
                            kSpeculativeBatchMaxStopTokens,
                    metadata_device.gpu_ordinal(),
                    execution_stream))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to upload graph-owned greedy verifier stop controls");
                return false;
            }
            if (!publishPreparedArenaGraphInput(
                    BufferId::MTP_VERIFIER_STOP_TOKENS,
                    mtp_verifier_stop_tokens_dev_,
                    execution_stream,
                    metadata_device,
                    "greedy_verifier_stop_controls"))
            {
                return false;
            }
            if (!backend->enqueueConfigureMTPGreedyPenaltyPolicyDevice(
                    mtp_greedy_penalty_policy_dev_,
                    transaction.penalty_policy.presence_penalty,
                    transaction.penalty_policy.frequency_penalty,
                    transaction.penalty_policy
                            .first_token_already_in_history != 0,
                    metadata_device.gpu_ordinal(),
                    execution_stream))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to publish graph-owned greedy penalty policy");
                return false;
            }
            if (!publishPreparedArenaGraphInput(
                    BufferId::MTP_GREEDY_PENALTY_POLICY,
                    mtp_greedy_penalty_policy_dev_,
                    execution_stream,
                    metadata_device,
                    "greedy_verifier_penalty_policy"))
            {
                return false;
            }
            PerfStatsCollector::addCounter(
                "mtp",
                "graph_owned_greedy_control_uploads",
                1.0,
                "decode",
                metadata_device.toString(),
                {{"bytes",
                  std::to_string(
                      sizeof(int32_t) *
                      sampling_math::
                          kSpeculativeBatchMaxStopTokens)},
                 {"rows", std::to_string(expected_rows)},
                 {"presence_penalty",
                  std::to_string(
                      transaction.penalty_policy.presence_penalty)},
                 {"frequency_penalty",
                  std::to_string(
                      transaction.penalty_policy.frequency_penalty)},
                 {"pending_condition",
                  transaction.penalty_policy
                                  .first_token_already_in_history != 0
                      ? "true"
                      : "false"}});
        }
        else if (greedy_verifier_outcome_graph_transaction_.state !=
                 GreedyVerifierOutcomeGraphState::Idle)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Armed greedy verifier controls reached metadata preparation without the greedy graph policy");
            return false;
        }
        if (plan.request_count <= 0 ||
            plan.request_count != input.batch_size ||
            input.seq_len <= 0 ||
            input.batch_size * input.seq_len >
                stochastic_target_row_capacity_)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Grouped verifier position geometry does not fit its persistent arena owner: plan_requests="
                      << plan.request_count
                      << " graph_batch=" << input.batch_size
                      << " graph_seq_len=" << input.seq_len
                      << " capacity=" << stochastic_target_row_capacity_);
            return false;
        }
        if (!mtp_verifier_position_ids_dev_ ||
            input.position_ids_device != mtp_verifier_position_ids_dev_)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] GPU grouped verifier is not bound to its device-owned position row");
            return false;
        }

        const auto upload = uploadMTPSpecDecodeVerifierInputPlan(
            plan,
            mtp_spec_decode_metadata_binding_,
            metadata_device,
            backend,
            execution_stream);
        if (!upload.ok)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to upload verifier row metadata: "
                      << upload.error);
            return false;
        }

        const auto &ptrs = mtp_spec_decode_metadata_binding_.devicePointers();
        if (!ptrs.base_cached_tokens)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Verifier metadata workspace has no base-cache snapshot buffer");
            return false;
        }
        if (!state_.kv_cache)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Cannot snapshot verifier base cache count without a KV cache");
            return false;
        }
        const int request_count = plan.request_count;
        const int32_t *base_count_device =
            state_.kv_cache->deviceSequenceCachedTokenCountPtr(/*seq_idx=*/0);
        if (!base_count_device)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] KV cache cannot expose a device-owned base cached-token count for verifier publication");
            return false;
        }
        /*
         * Expand the canonical next-position scalar for each request into the
         * full physical verifier matrix before graph replay. This launch is
         * ordered after every prior live-state event by
         * prepareLiveStateForForwardGraphExecution() and before RoPE's dynamic
         * pointer refresh below. The graph therefore observes the publication
         * just completed on device, even though the legacy host cursor remains
         * deliberately stale.
         */
        if (!backend->enqueuePrepareMTPVerifierPositionIds(
                base_count_device,
                request_count,
                input.seq_len,
                metadata_device.gpu_ordinal(),
                execution_stream,
                mtp_verifier_position_ids_dev_))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to expand device-owned grouped verifier positions");
            return false;
        }
        /*
         * Snapshot before verifier graph replay.  The same stream later executes
         * the verifier, so this D2D copy is ordered before the append/state stages
         * advance the live KV count.  Publication can then consume
         * BASE_CACHED_TOKENS after the verifier without any host-side scalar copy.
         */
        if (!backend->deviceCopyAsync(
                ptrs.base_cached_tokens,
                base_count_device,
                sizeof(int32_t) * static_cast<size_t>(request_count),
                metadata_device.gpu_ordinal(),
                execution_stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to snapshot device-owned verifier base cache count");
            return false;
        }
        mtp_publication_base_cache_snapshot_ready_ = true;
        mtp_publication_base_cache_snapshot_request_count_ = request_count;

        PerfStatsCollector::addCounter(
            "mtp",
            "verifier_row_metadata_upload_bytes",
            static_cast<double>(upload.bytes_uploaded),
            "decode",
            metadata_device.toString());
        PerfStatsCollector::addCounter(
            "mtp",
            "verifier_base_cache_device_snapshots",
            1.0,
            "decode",
            metadata_device.toString(),
            {{"requests", std::to_string(request_count)}});
        PerfStatsCollector::addCounter(
            "mtp",
            "verifier_device_position_expansions",
            1.0,
            "decode",
            metadata_device.toString(),
            {{"requests", std::to_string(request_count)},
             {"padded_seq_len", std::to_string(input.seq_len)},
             {"rows", std::to_string(request_count * input.seq_len)}});
        PerfStatsCollector::addCounter(
            "mtp",
            "verifier_row_metadata_path",
            1.0,
            "decode",
            metadata_device.toString(),
            {{"path", "persistent_workspace"},
             {"rows", std::to_string(expected_rows)}});
        if (!materializePendingMTPVerifierInputTokensOnDevice(
                execution_stream,
                metadata_device))
        {
            return false;
        }
        if (!publishPreparedArenaGraphInput(
                BufferId::MTP_VERIFIER_INPUT_TOKENS,
                mtp_verifier_input_tokens_dev_,
                execution_stream,
                metadata_device,
                "mtp_verifier_input_tokens"))
        {
            return false;
        }
        return true;
    }

    bool DeviceGraphOrchestrator::prepareLiveStateForForwardGraphExecution(
        const ForwardInput &input,
        void *execution_stream,
        DeviceId execution_device)
    {
        if (!state_.device_id.is_gpu())
            return true;
        (void)input;
        if (!waitForPendingRequestStateReset(
                execution_stream,
                DeviceTimelineRole::MainForwardGraph,
                "forward_graph_request_state_reset"))
        {
            return false;
        }
        if (!waitForPendingRequestInputAdmission(
                execution_stream,
                "forward_graph_request_input"))
        {
            return false;
        }
        if (!waitForPendingDeviceMoERebalanceMaintenance(
                execution_stream,
                "forward_graph"))
        {
            return false;
        }
        const bool has_accepted_publication =
            accepted_spec_publication_ready_.valid;
        const bool has_live_checkpoint =
            live_prefix_checkpoint_ready_.valid;
        const bool has_prefill_terminal_archive =
            mtp_prefill_terminal_archive_ready_.valid;
        const bool has_live_mutation =
            live_prefix_mutation_ready_.valid;
        const bool has_logical_mailbox =
            device_resident_logical_sequence_state_mailbox_.valid();
        if (!has_accepted_publication &&
            !has_live_checkpoint &&
            !has_prefill_terminal_archive &&
            !has_live_mutation &&
            !has_logical_mailbox)
            return true;
        if (!execution_stream)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Pending resident live-state handoff requires an explicit forward stream");
            return false;
        }

        const DeviceId consumer_device =
            execution_device.is_gpu() ? execution_device : state_.device_id;
        if (consumer_device != state_.device_id)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Resident live-state handoff wait requested on "
                      << consumer_device.toString()
                      << " but live state belongs to " << state_.device_id.toString());
            return false;
        }
        if (!waitForPendingLivePrefixCheckpointReady(
                execution_stream,
                "forward_graph_live_checkpoint_source"))
        {
            return false;
        }
        /*
         * A main graph is one of two users of the terminal-selection event: it
         * must not overwrite the source hidden tensor before archival
         * completes, while the next MTP sidecar still needs to read the
         * archived payload. Queue the source-protection wait without consuming
         * the payload handoff; the sidecar or an explicit terminal refresh
         * remains its semantic owner.
         */
        if (!waitForPendingMTPPrefillTerminalArchiveReadyForObservation(
                execution_stream,
                "forward_graph_mtp_prefill_terminal_archive_source"))
        {
            return false;
        }
        if (!waitForPendingAcceptedSpecPublicationReady(
                execution_stream,
                "forward_graph_live_state_consumer"))
        {
            return false;
        }
        if (!waitForPendingLivePrefixMutationReady(
                execution_stream,
                "forward_graph_live_prefix_mutation"))
        {
            return false;
        }
        return waitForDeviceResidentLogicalSequenceStateMailbox(
            execution_stream,
            "forward_graph_logical_state_consumer");
    }

    const float *DeviceGraphOrchestrator::getAllPositionLogits() const
    {
        TensorBase *tensor = state_.all_position_logits.get();
        return publishLogitsTensorToHost(
            tensor,
            HostLogitsSurface::AllPositionVerifier,
            "getAllPositionLogits");
    }

    std::string DeviceGraphOrchestrator::mtpDecodeUnsupportedReason() const
    {
        return {};
    }

    bool DeviceGraphOrchestrator::supportsMTPTokenCoordination() const
    {
        const IGlobalTPContext *ctx = globalTPContextForMTPCoordination();
        return ctx && ctx->degree() > 1;
    }

    bool DeviceGraphOrchestrator::usesMirroredLocalTPMTPHeadForVerifier() const
    {
        if (!graph_builder_)
            return false;

        const auto &config = graph_builder_->config();
        return config.mtp.enabled &&
               config.mtp.mirror_full_head_for_local_tp &&
               config.lm_head_column_parallel &&
               config.tp_ctx &&
               config.tp_ctx->isLocal();
    }

    bool DeviceGraphOrchestrator::supportsMTPSidecarSampleFusion() const
    {
        return state_.device_id.is_gpu();
    }

    bool DeviceGraphOrchestrator::supportsMTPSidecarLogitsStreamHandoff() const
    {
        return graph_builder_ &&
               graph_builder_->config().mtp.enabled &&
               state_.device_id.is_gpu() &&
               debugEnv().execution.gpu_graphs;
    }

    bool DeviceGraphOrchestrator::supportsMTPDeviceDraftTokenInput() const
    {
        return supportsMTPSidecarLogitsStreamHandoff() &&
               mtp_sidecar_condition_token_dev_ &&
               mtp_sidecar_position_ids_dev_ &&
               stochastic_target_sample_tokens_dev_ &&
               stochastic_draft_sample_tokens_dev_;
    }

    bool DeviceGraphOrchestrator::supportsMTPSidecarPreservesMainState() const
    {
        if (!graph_builder_ ||
            !graph_builder_->config().mtp.enabled ||
            !state_.kv_cache ||
            state_.mtp_kv_caches.empty())
        {
            return false;
        }

        const auto &config = graph_builder_->config();
        /*
         * Treat either the parsed graph config or the architecture name as
         * authoritative evidence of MoE.  Some Qwen3.6 MoE fixtures share the
         * qwen35 graph family and can arrive here before every per-graph MoE
         * field is populated; advertising dense sidecar semantics for those
         * models lets the verifier skip a required base restore.
         */
        const bool model_is_moe =
            config.isMoE() || isPrefixCacheMoEModel();
        if (!model_is_moe)
        {
            /*
             * Dense Qwen MTP sidecars are graph-native fragments that write
             * only to MTP-prefixed scratch buffers plus the request-local
             * shifted MTP KV cache. They do not advance main KV, GDN recurrence,
             * terminal hidden, positions, or sampler bookkeeping.
             */
            return true;
        }

        /*
         * Full-owner GPU MoE sidecars use MTP-owned activation buffers and
         * depth-scoped router/expert metadata.  The
         * MTPSidecarPreservesMainRuntimeState parity gate runs the real sidecar
         * path with KV payload and GDN device-state probes enabled, proving that
         * main KV, GDN/short-conv state, positions, and sequence lengths match the
         * verifier base after sidecar execution.  Keep this GPU-only and tied to
         * resident logical-state publication so CPU and multi-participant MoE
         * domains cannot skip their verifier-base restore without their own proof.
         */
        return state_.device_id.is_gpu() &&
               supportsDeviceResidentLogicalSequenceStatePublication();
    }

    bool DeviceGraphOrchestrator::supportsMTPShiftedRowReuseFromSidecar() const
    {
        if (!supportsMTPSidecarPreservesMainState() || !graph_builder_)
        {
            return false;
        }

        /*
         * Dense sidecars append a shifted row that is equivalent to the first
         * accepted target-row commit. MoE sidecars keep verifier-base state
         * isolated, but the accepted shifted row must come from the target
         * verifier publication path so routed expert state and shifted MTP KV are
         * committed from the same accepted row.
         */
        const auto &config = graph_builder_->config();
        const bool model_is_moe =
            config.isMoE() || isPrefixCacheMoEModel();
        return !model_is_moe;
    }

    IGlobalTPContext *DeviceGraphOrchestrator::globalTPContextForMTPCoordination() const
    {
        if (global_tp_ctx_)
        {
            return global_tp_ctx_.get();
        }
        if (!graph_builder_)
        {
            return nullptr;
        }

        ITPContext *tp_ctx = graph_builder_->config().tp_ctx;
        if (!tp_ctx || tp_ctx->isLocal())
        {
            return nullptr;
        }

        auto *global_ctx = dynamic_cast<IGlobalTPContext *>(tp_ctx);
        return global_ctx && global_ctx->degree() > 1 ? global_ctx : nullptr;
    }

    int DeviceGraphOrchestrator::sampleGreedyFromMTPLogitsOnDevice()
    {
        auto it = state_.extension_buffers.find(BufferId::MTP_LOGITS);
        if (it == state_.extension_buffers.end() || !it->second)
        {
            return -1;
        }

        const int token_offset = mtpSidecarLogitsAreColumnParallel() && graph_builder_
                                     ? vocabOffsetForTPConfig(graph_builder_->config())
                                     : 0;
        void *pending_stream = consumePendingLogitsStream(
            PendingLogitsStreamRole::MTPSidecar,
            "sampleGreedyFromMTPLogitsOnDevice");
        TensorBase *mtp_logits = it->second.get();
        if (!pending_stream && mtp_logits)
        {
            auto device_opt = mtp_logits->current_device();
            if (device_opt.has_value() && device_opt->is_gpu())
            {
                pending_stream = explicitGPUStreamForOperation("sampleGreedyOnMTPLogits");
                if (!pending_stream)
                {
                    return -1;
                }
            }
        }
        return coordinateGreedyCandidate(
            sampleGreedyCandidateFromTensor(mtp_logits, 0, token_offset,
                                            argmax_partial_vals_dev_,
                                            argmax_partial_idxs_dev_,
                                            argmax_partial_capacity_,
                                            pending_stream,
                                            "mtp_logits"),
            globalTPContextForMTPCoordination());
    }

    std::vector<MTPMirroredTensorDigest>
    DeviceGraphOrchestrator::captureFailedMirroredMTPDigests()
    {
        std::vector<MTPMirroredTensorDigest> digests;
        if (!state_.device_id.is_gpu())
            return digests;

        IBackend *backend = getBackendFor(state_.device_id);
        void *stream = explicitGPUStreamForOperation(
            "captureFailedMirroredMTPDigests");
        if (!backend || !stream)
            return digests;

        constexpr uint64_t kFnvOffsetBasis = 1469598103934665603ULL;
        constexpr uint64_t kFnvPrime = 1099511628211ULL;
        auto hash_bytes = [](const uint8_t *bytes, size_t byte_count)
        {
            uint64_t hash = kFnvOffsetBasis;
            for (size_t i = 0; i < byte_count; ++i)
            {
                hash ^= static_cast<uint64_t>(bytes[i]);
                hash *= kFnvPrime;
            }
            return hash;
        };

        /*
         * Proposal sidecars are one-row graphs.  Hashing one logical row keeps
         * preallocated capacity and stale tail rows out of the comparison.
         * Direct backend copies intentionally bypass TensorBase::ensureOnHost:
         * diagnostics observe device truth without changing tensor authority.
         */
        auto append_tensor_row =
            [&](const char *name, const TensorBase *tensor)
        {
            MTPMirroredTensorDigest digest;
            digest.name = name ? name : "(unnamed)";
            if (!tensor || !tensor->gpu_data_ptr() || !tensor->deviceValid())
            {
                digests.push_back(std::move(digest));
                return;
            }

            const size_t rows = std::max<size_t>(1, tensor->rows());
            const size_t total_bytes = tensor->size_bytes();
            if (total_bytes == 0 || total_bytes % rows != 0)
            {
                digests.push_back(std::move(digest));
                return;
            }

            digest.byte_count = total_bytes / rows;
            std::vector<uint8_t> host_bytes(digest.byte_count);
            if (backend->deviceToHostFast(
                    host_bytes.data(),
                    tensor->gpu_data_ptr(),
                    digest.byte_count,
                    state_.device_id.gpu_ordinal(),
                    stream))
            {
                digest.hash = hash_bytes(
                    host_bytes.data(),
                    host_bytes.size());
                digest.available = true;
            }
            digests.push_back(std::move(digest));
        };

        auto append_device_bytes =
            [&](const char *name, const void *device_ptr, size_t byte_count)
        {
            MTPMirroredTensorDigest digest;
            digest.name = name ? name : "(unnamed)";
            digest.byte_count = byte_count;
            if (!device_ptr || byte_count == 0)
            {
                digests.push_back(std::move(digest));
                return;
            }

            std::vector<uint8_t> host_bytes(byte_count);
            if (backend->deviceToHostFast(
                    host_bytes.data(),
                    const_cast<void *>(device_ptr),
                    byte_count,
                    state_.device_id.gpu_ordinal(),
                    stream))
            {
                digest.hash = hash_bytes(
                    host_bytes.data(),
                    host_bytes.size());
                digest.available = true;
            }
            digests.push_back(std::move(digest));
        };

        auto append_prehashed_bytes =
            [&](std::string name,
                uint64_t hash,
                size_t byte_count,
                bool available)
        {
            MTPMirroredTensorDigest digest;
            digest.name = std::move(name);
            digest.hash = hash;
            digest.byte_count = byte_count;
            digest.available = available;
            digests.push_back(std::move(digest));
        };

        auto extension = [&](BufferId id) -> const TensorBase *
        {
            const auto it = state_.extension_buffers.find(id);
            return it == state_.extension_buffers.end()
                       ? nullptr
                       : it->second.get();
        };

        /*
         * Optional graph-captured checkpoints preserve only one terminal row
         * at each main-model layer boundary. Select the graph regime that
         * produced the currently published terminal hidden row; other cached
         * prefill and verifier variants may have valid but intentionally stale
         * checkpoint banks from earlier requests.
         */
        if (const auto *qwen_moe =
                dynamic_cast<const Qwen35MoEGraph *>(graph_builder_.get()))
        {
            const auto checkpoints =
                qwen_moe->mirroredLayerCheckpoints();
            if (DebugEnv::isTruthyEnv(
                    "LLAMINAR_MTP_MIRROR_LAYER_DIAGNOSTICS"))
            {
                size_t selected_matches = 0;
                std::map<std::string, size_t> bank_counts;
                for (const auto &checkpoint : checkpoints)
                {
                    if (!last_mirrored_layer_checkpoint_prefix_.empty() &&
                        checkpoint.name.starts_with(
                            last_mirrored_layer_checkpoint_prefix_))
                    {
                        ++selected_matches;
                    }
                    const size_t layer_marker =
                        checkpoint.name.find("_layer");
                    const std::string bank =
                        layer_marker == std::string::npos
                            ? checkpoint.name
                            : checkpoint.name.substr(0, layer_marker + 1);
                    ++bank_counts[bank];
                }
                std::ostringstream bank_summary;
                bool first_bank = true;
                for (const auto &[bank, count] : bank_counts)
                {
                    if (!first_bank)
                        bank_summary << ',';
                    first_bank = false;
                    bank_summary << bank << ':' << count;
                }
                LOG_ERROR(
                    "[MirroredLayerDiagnostics] device="
                    << state_.device_id.toString()
                    << " builder=" << qwen_moe->architectureName()
                    << " selected_bank="
                    << (last_mirrored_layer_checkpoint_prefix_.empty()
                            ? "(none)"
                            : last_mirrored_layer_checkpoint_prefix_)
                    << " retained_checkpoints=" << checkpoints.size()
                    << " selected_matches=" << selected_matches
                    << " banks={" << bank_summary.str() << '}'
                    << " first="
                    << (checkpoints.empty()
                            ? "(none)"
                            : checkpoints.front().name)
                    << " last="
                    << (checkpoints.empty()
                            ? "(none)"
                            : checkpoints.back().name));
            }
            for (const auto &checkpoint : checkpoints)
            {
                if (last_mirrored_layer_checkpoint_prefix_.empty() ||
                    !checkpoint.name.starts_with(
                        last_mirrored_layer_checkpoint_prefix_))
                    continue;
                append_tensor_row(
                    ("main_checkpoint_" + checkpoint.name).c_str(),
                    checkpoint.tensor);
            }
        }
        else if (DebugEnv::isTruthyEnv(
                     "LLAMINAR_MTP_MIRROR_LAYER_DIAGNOSTICS"))
        {
            LOG_ERROR(
                "[MirroredLayerDiagnostics] device="
                << state_.device_id.toString()
                << " builder="
                << (graph_builder_
                        ? graph_builder_->architectureName()
                        : "(null)")
                << " selected_bank="
                << (last_mirrored_layer_checkpoint_prefix_.empty()
                        ? "(none)"
                        : last_mirrored_layer_checkpoint_prefix_)
                << " retained_checkpoints=unavailable "
                   "(builder is not Qwen35MoEGraph)");
        }

        append_tensor_row(
            "terminal_hidden",
            state_.prefix_terminal_hidden.get());

        /*
         * The sidecar's first operation normalizes the terminal hidden row.
         * Include the immutable sidecar weights in the failed-participant
         * snapshot so an expert-overlay write that escapes its allocation can
         * be distinguished from an activation-lifetime or launch-order bug.
         * Matrix tensors contribute one logical row, which is enough to expose
         * participant-specific placement or collateral corruption without
         * copying a complete projection matrix on the error path.
         */
        const FrozenModelWeightSet *mtp_weight_set =
            selectMTPDecodeWeightSet("failed mirrored MTP digest");
        if (mtp_weight_set)
        {
            const ModelWeightBindings bindings =
                makeModelWeightBindings(*mtp_weight_set);
            if (!bindings.mtp.empty() && !bindings.mtp.depths.empty())
            {
                const MTPDepthWeightBindings &depth =
                    bindings.mtp.depths.front();
                append_tensor_row(
                    "mtp_weight_norm_hidden",
                    legacyTensor(depth.pre_fc_norm_hidden));
                append_tensor_row(
                    "mtp_weight_norm_embedding",
                    legacyTensor(depth.pre_fc_norm_embedding));
                append_tensor_row(
                    "mtp_weight_fc",
                    legacyTensor(depth.fc));
                append_tensor_row(
                    "mtp_weight_final_norm",
                    legacyTensor(depth.final_norm));
            }
        }

        append_tensor_row("mtp_embedding", extension(BufferId::MTP_EMBEDDING));
        append_tensor_row("mtp_norm_hidden", extension(BufferId::MTP_NORM_HIDDEN));
        append_tensor_row(
            "mtp_norm_embedding",
            extension(BufferId::MTP_NORM_EMBEDDING));
        append_tensor_row("mtp_concat", extension(BufferId::MTP_CONCAT));
        append_tensor_row("mtp_projected", extension(BufferId::MTP_PROJECTED));
        append_tensor_row("mtp_q", extension(BufferId::MTP_Q_PROJ));
        append_tensor_row("mtp_k", extension(BufferId::MTP_K_PROJ));
        append_tensor_row("mtp_v", extension(BufferId::MTP_V_PROJ));
        append_tensor_row(
            "mtp_attention_output",
            extension(BufferId::MTP_ATTN_OUTPUT));
        append_tensor_row(
            "mtp_attention_projection",
            extension(BufferId::MTP_ATTN_PROJ));
        append_tensor_row(
            "mtp_moe_expert_indices",
            extension(BufferId::MOE_EXPERT_INDICES));
        append_tensor_row(
            "mtp_moe_expert_weights",
            extension(BufferId::MOE_EXPERT_WEIGHTS));
        append_tensor_row(
            "mtp_moe_routed_output",
            extension(BufferId::MOE_COMBINED_OUTPUT));
        append_tensor_row(
            "mtp_moe_shared_output",
            extension(BufferId::MOE_SHARED_EXPERT_OUTPUT));
        append_tensor_row("mtp_hidden", extension(BufferId::MTP_HIDDEN));
        append_tensor_row("mtp_logits", extension(BufferId::MTP_LOGITS));

        /*
         * Stateful attention is the only main-graph operation whose result can
         * differ across mirrored participants despite equal incoming hidden
         * rows and immutable weights.  Capture a bounded logical K/V tail plus
         * both GDN bank geometries after a failed proposal.  The policy is
         * invocation-scoped and deliberately omits complete long-context KV
         * payloads, keeping this already-exceptional diagnostic proportional
         * to layer count rather than sequence length.
         */
        if (state_.kv_cache)
        {
            PrefixProbeCapturePolicy capture_policy;
            capture_policy.trailing_kv_tokens = 4;
            capture_policy.hash_gdn_device_state = true;

            const PrefixKVCacheProbe kv_probe =
                inspectKVCacheForPrefixProbe(
                    *state_.kv_cache,
                    "failed_mirrored_mtp",
                    state_.device_id,
                    /*sequence_count=*/1,
                    stream,
                    capture_policy);
            for (const PrefixKVLayerProbe &layer : kv_probe.layers)
            {
                const auto segment_it = std::find_if(
                    layer.segments.begin(),
                    layer.segments.end(),
                    [](const PrefixKVSegmentProbe &segment)
                    {
                        return segment.name == "diagnostic_tail";
                    });
                const bool available =
                    segment_it != layer.segments.end() &&
                    segment_it->hash_available;
                const std::string suffix =
                    "_layer" + std::to_string(layer.global_layer) +
                    "_seq" + std::to_string(layer.seq_idx);
                append_prehashed_bytes(
                    "main_live_kv_k" + suffix,
                    available ? segment_it->k_payload_hash : 0,
                    available ? segment_it->k_payload_bytes : 0,
                    available);
                append_prehashed_bytes(
                    "main_live_kv_v" + suffix,
                    available ? segment_it->v_payload_hash : 0,
                    available ? segment_it->v_payload_bytes : 0,
                    available);
            }

            const std::vector<PrefixGDNLayerProbe> gdn_probes =
                inspectHybridGDNForPrefixProbe(
                    *state_.kv_cache,
                    stream,
                    capture_policy);
            for (const PrefixGDNLayerProbe &layer : gdn_probes)
            {
                const std::string suffix =
                    "_layer" + std::to_string(layer.global_layer);
                append_prehashed_bytes(
                    "main_live_gdn_full_conv" + suffix,
                    layer.conv_device_hash,
                    layer.conv_device_bytes,
                    layer.device_state_hash_available);
                append_prehashed_bytes(
                    "main_live_gdn_full_recurrence" + suffix,
                    layer.recurrence_device_hash,
                    layer.recurrence_device_bytes,
                    layer.device_state_hash_available);
                append_prehashed_bytes(
                    "main_live_gdn_local_conv" + suffix,
                    layer.conv_local_device_hash,
                    layer.conv_local_device_bytes,
                    layer.local_device_state_hash_available);
                append_prehashed_bytes(
                    "main_live_gdn_local_recurrence" + suffix,
                    layer.recurrence_local_device_hash,
                    layer.recurrence_local_device_bytes,
                    layer.local_device_state_hash_available);
            }
        }

        append_device_bytes(
            "main_live_position",
            state_.kv_cache
                ? state_.kv_cache->deviceSequenceCachedTokenCountPtr(0)
                : nullptr,
            sizeof(int32_t));
        append_device_bytes(
            "mtp_live_position",
            !state_.mtp_kv_caches.empty() && state_.mtp_kv_caches[0]
                ? state_.mtp_kv_caches[0]->deviceSequenceCachedTokenCountPtr(0)
                : nullptr,
            sizeof(int32_t));
        append_device_bytes(
            "resident_draft_slots",
            stochastic_draft_sample_tokens_dev_,
            static_cast<size_t>(
                std::max(0, stochastic_draft_row_capacity_)) *
                sizeof(int32_t));
        append_device_bytes(
            "resident_target_slots",
            stochastic_target_sample_tokens_dev_,
            static_cast<size_t>(
                std::max(0, stochastic_target_row_capacity_)) *
                sizeof(int32_t));
        return digests;
    }

    bool DeviceGraphOrchestrator::sampleGreedyFromMTPLogitsToDeviceDraftSlot(
        int draft_sample_slot,
        int32_t *out_token)
    {
        if (out_token)
            *out_token = -1;
        if (globalTPContextForMTPCoordination())
        {
            /*
             * Multi-rank vocab-sharded MTP logits need a coordinated winner
             * before a single participant can write the verifier draft slot.
             * Keep those lanes on the existing host-visible coordinated path
             * until the TP device-slot contract is implemented domain-wide.
             */
            return false;
        }

        SamplingParams greedy_params;
        greedy_params.temperature = 0.0f;
        const int vocab = vocab_size();
        return sampleStochasticDraftProposalOnDeviceImpl(
            DeviceLogitsSource::MTP,
            /*row=*/0,
            draft_sample_slot,
            greedy_params,
            vocab,
            /*threshold=*/0.0f,
            out_token,
            /*verifier_consumer_pending=*/true);
    }

    bool DeviceGraphOrchestrator::sampleGreedyFromMainLogitsToDeviceTargetSlot(
        int target_sample_slot,
        int32_t *out_token)
    {
        if (!supportsDeviceStochasticMTPVerification() ||
            globalTPContextForMTPCoordination() ||
            !state_.logits ||
            !state_.logits->deviceValid() ||
            !state_.logits->gpu_data_ptr() ||
            target_sample_slot < 0 ||
            target_sample_slot >= stochastic_target_row_capacity_ ||
            !stochastic_target_sample_tokens_dev_ ||
            !stochastic_verify_accept_probs_dev_ ||
            !argmax_partial_vals_dev_ ||
            !argmax_partial_idxs_dev_ ||
            argmax_partial_capacity_ <= 0)
        {
            return false;
        }

        /*
         * The first target-token slot is the device-resident owner for this
         * token until the compact verifier summary returns.  Clear any stale
         * readiness marker before enqueueing a new argmax into the slot.
         */
        stochastic_target_top_k_[static_cast<size_t>(target_sample_slot)] = 0;
        stochastic_target_row_formats_[static_cast<size_t>(target_sample_slot)] =
            StochasticRowFormat::Empty;
        stochastic_target_distribution_streams_[static_cast<size_t>(target_sample_slot)] = nullptr;
        clearStochasticTargetSampleReadySlot(
            target_sample_slot,
            StochasticSampleReadyClearMode::Force);

        const auto &shape = state_.logits->shape();
        if (shape.empty())
            return false;
        const size_t rows = shape.size() >= 2 ? shape[0] : 1;
        const size_t cols = shape.size() >= 2 ? shape[1] : shape[0];
        if (cols == 0 ||
            rows == 0 ||
            cols > static_cast<size_t>(std::numeric_limits<int>::max()))
        {
            return false;
        }

        void *stream = consumePendingLogitsStream(
            PendingLogitsStreamRole::MainDecode,
            "sampleGreedyFromMainLogitsToDeviceTargetSlot");
        if (!stream)
            stream = explicitGPUStreamForOperation(
                "sampleGreedyFromMainLogitsToDeviceTargetSlot");
        if (!stream)
            return false;

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        const float *row_ptr = static_cast<const float *>(state_.logits->gpu_data_ptr());
        auto *out_token_dev =
            static_cast<int *>(stochastic_target_sample_tokens_dev_) +
            target_sample_slot;
        auto *out_value_dev =
            static_cast<float *>(stochastic_verify_accept_probs_dev_) +
            target_sample_slot;
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "first_token_greedy_device_target_slot_enqueue",
                "decode",
                state_.device_id.toString(),
                {{"slot", std::to_string(target_sample_slot)},
                 {"vocab", std::to_string(cols)}});
            if (!backend->enqueueArgmaxF32BatchedRowsDevice(
                    row_ptr,
                    /*rows=*/1,
                    static_cast<int>(cols),
                    state_.device_id.gpu_ordinal(),
                    stream,
                    out_value_dev,
                    out_token_dev,
                    argmax_partial_vals_dev_,
                    argmax_partial_idxs_dev_,
                    argmax_partial_capacity_))
            {
                return false;
            }
        }

        if (!recordStochasticTargetSampleReady(
                target_sample_slot,
                stream,
                /*verifier_consumer_pending=*/out_token == nullptr))
            return false;

        if (!out_token)
        {
            PerfStatsCollector::addCounter(
                "mtp",
                "first_token_greedy_deferred_host_reads",
                1.0,
                "decode",
                state_.device_id.toString(),
                {{"slot", std::to_string(target_sample_slot)}});
            return true;
        }

        int32_t token = -1;
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "first_token_greedy_device_target_slot_d2h_sync",
                "decode",
                state_.device_id.toString(),
                {{"slot", std::to_string(target_sample_slot)}});
            if (!backend->deviceToHostFast(&token,
                                           out_token_dev,
                                           sizeof(int),
                                           state_.device_id.gpu_ordinal(),
                                           stream))
            {
                return false;
            }
        }
        *out_token = token;
        return token >= 0;
    }

    int DeviceGraphOrchestrator::sampleGreedyFromAllPositionLogitsOnDevice(int row)
    {
        if (row < 0)
        {
            return -1;
        }

        if (state_.all_position_logits)
        {
            void *stream = nullptr;
            auto device_opt = state_.all_position_logits->current_device();
            if (device_opt.has_value() && device_opt->is_gpu())
            {
                stream = peekPendingLogitsStream(
                    PendingLogitsStreamRole::AllPositionVerifier);
                if (!stream)
                    stream = explicitGPUStreamForOperation("sampleGreedyFromAllPositionLogitsOnDevice");
                if (!stream)
                {
                    return -1;
                }
            }
            return coordinateGreedyCandidate(
                sampleGreedyCandidateFromTensor(state_.all_position_logits.get(), row, 0,
                                                argmax_partial_vals_dev_,
                                                argmax_partial_idxs_dev_,
                                                argmax_partial_capacity_,
                                                stream,
                                                "all_position_logits"),
                globalTPContextForMTPCoordination());
        }

        if (state_.all_position_logits_local)
        {
            const int token_offset = graph_builder_
                                         ? vocabOffsetForTPConfig(graph_builder_->config())
                                         : 0;
            void *stream = nullptr;
            auto device_opt = state_.all_position_logits_local->current_device();
            if (device_opt.has_value() && device_opt->is_gpu())
            {
                stream = peekPendingLogitsStream(
                    PendingLogitsStreamRole::AllPositionVerifier);
                if (!stream)
                    stream = explicitGPUStreamForOperation("sampleGreedyFromAllPositionLogitsLocalOnDevice");
                if (!stream)
                {
                    return -1;
                }
            }
            return coordinateGreedyCandidate(
                sampleGreedyCandidateFromTensor(state_.all_position_logits_local.get(), row, token_offset,
                                                argmax_partial_vals_dev_,
                                                argmax_partial_idxs_dev_,
                                                argmax_partial_capacity_,
                                                stream,
                                                "all_position_logits_local"),
                globalTPContextForMTPCoordination());
        }

        return -1;
    }

    bool DeviceGraphOrchestrator::sampleGreedyFromAllPositionLogitsOnDeviceRows(
        int start_row,
        int row_count,
        int32_t *out_tokens)
    {
        if (start_row < 0 || row_count <= 0 || !out_tokens)
            return false;

        const IGlobalTPContext *global_ctx = globalTPContextForMTPCoordination();
        if (global_ctx && global_ctx->degree() > 1)
        {
            return IInferenceRunner::sampleGreedyFromAllPositionLogitsOnDeviceRows(
                start_row, row_count, out_tokens);
        }

        TensorBase *tensor = nullptr;
        int token_offset = 0;
        const char *sample_source = "all_position_logits_rows";
        if (state_.all_position_logits)
        {
            tensor = state_.all_position_logits.get();
        }
        else if (state_.all_position_logits_local)
        {
            tensor = state_.all_position_logits_local.get();
            sample_source = "all_position_logits_local_rows";
            token_offset = graph_builder_
                               ? vocabOffsetForTPConfig(graph_builder_->config())
                               : 0;
        }
        if (!tensor)
            return false;

        constexpr int kMaxStackVerifierRows = 16;
        if (row_count > kMaxStackVerifierRows)
        {
            if (peekPendingLogitsStream(PendingLogitsStreamRole::AllPositionVerifier))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Deferred all-position verifier sampling exceeds stack row capacity");
                clearPendingLogitsStream(
                    PendingLogitsStreamRole::AllPositionVerifier,
                    "sampleGreedyFromAllPositionLogitsOnDeviceRows_over_capacity");
                return false;
            }
            return IInferenceRunner::sampleGreedyFromAllPositionLogitsOnDeviceRows(
                start_row, row_count, out_tokens);
        }

        const auto &shape = tensor->shape();
        if (shape.empty())
            return false;
        const size_t rows = shape.size() >= 2 ? shape[0] : 1;
        const size_t cols = shape.size() >= 2 ? shape[1] : shape[0];
        if (cols == 0 ||
            static_cast<size_t>(start_row) >= rows ||
            static_cast<size_t>(start_row + row_count) > rows ||
            cols > static_cast<size_t>(std::numeric_limits<int>::max()))
        {
            return false;
        }

        auto device_opt = tensor->current_device();
        if (device_opt.has_value() && device_opt->is_gpu() && tensor->deviceValid())
        {
            IBackend *backend = getBackendFor(*device_opt);
            const void *gpu_ptr = tensor->gpu_data_ptr();
            if (!backend || !gpu_ptr)
                return false;

            void *stream = peekPendingLogitsStream(
                PendingLogitsStreamRole::AllPositionVerifier);
            const bool using_deferred_stream = stream != nullptr;
            if (!stream)
                stream = explicitGPUStreamForOperation("sampleGreedyFromAllPositionLogitsOnDeviceRows");
            if (!stream)
            {
                return false;
            }

            const auto *base = static_cast<const float *>(gpu_ptr);
            const void *first_row =
                base + static_cast<size_t>(start_row) * static_cast<size_t>(cols);
            std::array<float, kMaxStackVerifierRows> values{};
            std::array<int, kMaxStackVerifierRows> indices{};
            const bool ok = backend->argmaxF32BatchedRows(
                first_row,
                row_count,
                static_cast<int>(cols),
                device_opt->gpu_ordinal(),
                values.data(),
                indices.data(),
                stream,
                argmax_partial_vals_dev_,
                argmax_partial_idxs_dev_,
                argmax_partial_capacity_);
            if (!ok)
            {
                if (using_deferred_stream)
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Batched verifier argmax failed after deferred verifier replay");
                    return false;
                }
                if (backend->backendDeviceType() == DeviceType::ROCm)
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] ROCm batched verifier argmax failed");
                    return false;
                }
                return IInferenceRunner::sampleGreedyFromAllPositionLogitsOnDeviceRows(
                    start_row, row_count, out_tokens);
            }

            for (int i = 0; i < row_count; ++i)
            {
                if (indices[static_cast<size_t>(i)] < 0)
                    return false;
                out_tokens[i] = static_cast<int32_t>(
                    token_offset + indices[static_cast<size_t>(i)]);
            }
            if (greedyMarginStatsEnabled())
            {
                for (int i = 0; i < row_count; ++i)
                {
                    const void *row_ptr =
                        base + static_cast<size_t>(start_row + i) * static_cast<size_t>(cols);
                    float top_values[2] = {};
                    int top_indices[2] = {};
                    if (backend->topKF32(row_ptr,
                                         static_cast<int>(cols),
                                         2,
                                         device_opt->gpu_ordinal(),
                                         top_values,
                                         top_indices,
                                         stream))
                    {
                        recordGreedyMarginStats(
                            sample_source,
                            *device_opt,
                            start_row + i,
                            top_values[0],
                            top_values[1]);
                    }
                    else
                    {
                        recordGreedyMarginUnavailable(sample_source, *device_opt, start_row + i);
                    }
                }
            }
            PerfStatsCollector::addCounter(
                "mtp",
                "verifier_token_device_batch_samples",
                static_cast<double>(row_count),
                "decode",
                state_.device_id.toString(),
                {{"rows", std::to_string(row_count)}});
            return true;
        }

        return IInferenceRunner::sampleGreedyFromAllPositionLogitsOnDeviceRows(
            start_row, row_count, out_tokens);
    }

    bool DeviceGraphOrchestrator::prepareGreedyAllPositionBatchOutcomeGraph(
        int verifier_token_count,
        const int32_t *stop_tokens,
        int stop_token_count,
        const MTPGreedyPenaltyPolicy &penalty_policy)
    {
        using namespace sampling_math;

        if (!state_.device_id.is_gpu() ||
            verifier_token_count <= 0 ||
            verifier_token_count > mtp_max_verifier_rows_ ||
            stop_token_count < 0 ||
            stop_token_count > kSpeculativeBatchMaxStopTokens ||
            (stop_token_count > 0 && !stop_tokens) ||
            !mtp_verifier_stop_tokens_dev_ ||
            !mtp_greedy_penalty_policy_dev_ ||
            !mtp_generated_token_counts_dev_ ||
            mtp_generated_token_count_capacity_ != state_.vocab_size ||
            !mtp_verifier_input_tokens_dev_ ||
            !stochastic_verify_tokens_dev_ ||
            !stochastic_verify_accept_probs_dev_ ||
            !stochastic_batch_output_tokens_dev_ ||
            !stochastic_batch_output_meta_dev_)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Invalid graph-owned greedy outcome preparation"
                      << " device=" << state_.device_id.toString()
                      << " verifier_tokens=" << verifier_token_count
                      << " stop_tokens=" << stop_token_count);
            return false;
        }
        if (mtp_verifier_outcome_graph_mode_ !=
                MTPVerifierOutcomeGraphMode::Disabled ||
            greedy_verifier_outcome_graph_transaction_.state !=
                GreedyVerifierOutcomeGraphState::Idle)
        {
            throw std::logic_error(
                "Cannot arm a graph-owned greedy MTP outcome while another "
                "outcome transaction is active");
        }

        GreedyVerifierOutcomeGraphTransaction transaction;
        transaction.state = GreedyVerifierOutcomeGraphState::Armed;
        transaction.verifier_token_count = verifier_token_count;
        transaction.stop_token_count = stop_token_count;
        for (int i = 0; i < stop_token_count; ++i)
        {
            transaction.stop_tokens[static_cast<size_t>(i)] =
                stop_tokens[i];
        }
        transaction.penalty_policy = penalty_policy;
        transaction.penalty_policy.first_token_already_in_history =
            penalty_policy.first_token_already_in_history != 0 ? 1 : 0;
        transaction.penalty_policy.enabled =
            penalty_policy.presence_penalty != 0.0f ||
                    penalty_policy.frequency_penalty != 0.0f
                ? 1
                : 0;

        greedy_verifier_outcome_graph_transaction_ = transaction;
        mtp_verifier_outcome_graph_mode_ =
            MTPVerifierOutcomeGraphMode::Greedy;
        PerfStatsCollector::addCounter(
            "mtp",
            "graph_owned_greedy_outcome_transactions_armed",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"rows", std::to_string(verifier_token_count)},
             {"stop_tokens", std::to_string(stop_token_count)}});
        return true;
    }

    bool DeviceGraphOrchestrator::verifyGreedyAllPositionBatchOutcomeOnDeviceResident(
        const int32_t *draft_tokens,
        int draft_token_count,
        const int32_t *stop_tokens,
        int stop_token_count,
        DeviceSpeculativeOutcomeHandle *out_handle)
    {
        using namespace sampling_math;
        if (out_handle)
            *out_handle = DeviceSpeculativeOutcomeHandle{};

        if (!out_handle)
            return false;

        if (!draft_tokens ||
            draft_token_count <= 0 ||
            draft_token_count > mtp_max_verifier_rows_ ||
            stop_token_count < 0 ||
            stop_token_count > kSpeculativeBatchMaxStopTokens ||
            (stop_token_count > 0 && !stop_tokens))
        {
            return false;
        }

        const auto &transaction =
            greedy_verifier_outcome_graph_transaction_;
        if (mtp_verifier_outcome_graph_mode_ !=
                MTPVerifierOutcomeGraphMode::Greedy ||
            transaction.state !=
                GreedyVerifierOutcomeGraphState::Produced ||
            transaction.verifier_token_count != draft_token_count ||
            transaction.stop_token_count != stop_token_count)
        {
            throw std::logic_error(
                "Greedy resident outcome consumption does not match a "
                "produced graph-owned transaction");
        }
        for (int i = 0; i < stop_token_count; ++i)
        {
            if (transaction.stop_tokens[static_cast<size_t>(i)] !=
                stop_tokens[i])
            {
                throw std::logic_error(
                    "Greedy resident outcome stop controls differ from the "
                    "controls captured for graph replay");
            }
        }

        void *stream = consumePendingLogitsStream(
            PendingLogitsStreamRole::AllPositionVerifier,
            "consumeGraphOwnedGreedyAllPositionBatchOutcome");
        if (!stream)
        {
            throw std::logic_error(
                "Graph-owned greedy outcome has no verifier stream handoff");
        }
        if (!forward_graph_output_ready_.valid ||
            !forward_graph_output_ready_.event ||
            !forward_graph_output_ready_.all_position_logits)
        {
            throw std::logic_error(
                "Graph-owned greedy outcome has no durable grouped-forward "
                "completion publication");
        }

        const bool materialized_first_token_from_device =
            materialized_mtp_verifier_device_token_row_.first_token_from_device;
        const int materialized_first_target_sample_slot =
            materialized_mtp_verifier_device_token_row_.first_target_sample_slot;

        if (materialized_first_token_from_device)
        {
            clearStochasticTargetSampleReadySlot(
                materialized_first_target_sample_slot,
                StochasticSampleReadyClearMode::Force);
        }
        materialized_mtp_verifier_device_token_row_ = {};
        materialized_mtp_verifier_device_token_batch_ = {};

        if (!recordDeviceResidentMTPTransactionMutation(
                /*request_count=*/1,
                stream,
                "graph_owned_greedy_device_outcome"))
        {
            return false;
        }

        out_handle->output_tokens_device =
            static_cast<const int32_t *>(stochastic_batch_output_tokens_dev_);
        out_handle->meta_device =
            static_cast<const int *>(stochastic_batch_output_meta_dev_);
        out_handle->request_count = 1;
        out_handle->output_token_stride =
            stochastic_batch_output_token_stride_;
        out_handle->meta_stride = kSpeculativeBatchMetaCount;
        out_handle->device = state_.device_id;
        out_handle->stream = stream;
        out_handle->response_ready_event =
            forward_graph_output_ready_.event;
        out_handle->mtp_transaction =
            currentDeviceResidentMTPTransactionLease();
        out_handle->mirrored_local_tp_published_in_graph =
            usesMirroredLocalTPMTPHeadForVerifier() &&
            graph_builder_ &&
            graph_builder_->config().tp_ctx &&
            graph_builder_->config().tp_ctx->degree() > 1;

        greedy_verifier_outcome_graph_transaction_ = {};
        mtp_verifier_outcome_graph_mode_ =
            MTPVerifierOutcomeGraphMode::Disabled;

        PerfStatsCollector::addCounter(
            "mtp",
            "all_position_greedy_device_resident_outcomes",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"compare_rows", std::to_string(draft_token_count - 1)},
             {"implementation", "graph_owned_outcome"}});
        PerfStatsCollector::addCounter(
            "mtp",
            "graph_owned_greedy_outcome_consumptions",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"rows", std::to_string(draft_token_count)}});
        return out_handle->valid();
    }

    bool DeviceGraphOrchestrator::verifyGreedyAllPositionRequestBatchOutcomesOnDeviceResident(
        const DeviceGreedyBatchOutcomeRequest *requests,
        int request_count,
        DeviceSpeculativeOutcomeHandle *out_handle)
    {
        using namespace sampling_math;
        if (out_handle)
            *out_handle = DeviceSpeculativeOutcomeHandle{};
        if (!out_handle ||
            !requests ||
            request_count <= 0 ||
            request_count > stochastic_batch_output_request_capacity_ ||
            !state_.all_position_logits ||
            !state_.device_id.is_gpu() ||
            !materialized_mtp_verifier_device_token_batch_.valid ||
            materialized_mtp_verifier_device_token_batch_.request_count !=
                request_count ||
            !mtp_verifier_input_tokens_dev_ ||
            !stochastic_verify_tokens_dev_ ||
            !stochastic_verify_accept_probs_dev_ ||
            !stochastic_batch_output_tokens_dev_ ||
            !stochastic_batch_output_meta_dev_)
        {
            return false;
        }

        int max_target_row = 0;
        for (int i = 0; i < request_count; ++i)
        {
            const DeviceGreedyBatchOutcomeRequest &request = requests[i];
            if (request.first_target_row < 0 ||
                request.verifier_token_count <= 0 ||
                request.verifier_token_count > mtp_max_verifier_rows_ ||
                request.token_row_offset < 0 ||
                request.token_row_stride <= 0 ||
                request.token_row_stride !=
                    materialized_mtp_verifier_device_token_batch_
                        .padded_seq_len ||
                request.stop_token_count < 0 ||
                request.stop_token_count >
                    static_cast<int>(kSpeculativeBatchMaxStopTokens) ||
                request.token_row_offset + request.verifier_token_count >
                    materialized_mtp_verifier_device_token_batch_
                        .total_token_capacity)
            {
                return false;
            }
            max_target_row = std::max(
                max_target_row,
                request.first_target_row + request.verifier_token_count);
        }
        if (max_target_row <= 0 ||
            max_target_row > stochastic_target_row_capacity_ ||
            activeAllPositionLogitsAreColumnParallel(max_target_row))
        {
            return false;
        }

        const IGlobalTPContext *global_ctx =
            globalTPContextForMTPCoordination();
        if (global_ctx && global_ctx->degree() > 1)
            return false;

        TensorBase *tensor = state_.all_position_logits.get();
        const auto &shape = tensor->shape();
        if (shape.empty())
            return false;
        const size_t rows = shape.size() >= 2 ? shape[0] : 1;
        const size_t cols = shape.size() >= 2 ? shape[1] : shape[0];
        if (cols == 0 ||
            static_cast<size_t>(max_target_row) > rows ||
            cols > static_cast<size_t>(std::numeric_limits<int>::max()) ||
            !state_.all_position_logits->deviceValid())
        {
            return false;
        }

        auto device_opt = tensor->current_device();
        if (!device_opt.has_value() || !device_opt->is_gpu())
            return false;

        IBackend *backend = getBackendFor(*device_opt);
        const void *gpu_ptr = tensor->gpu_data_ptr();
        if (!backend || !gpu_ptr)
            return false;

        void *stream = consumePendingLogitsStream(
            PendingLogitsStreamRole::AllPositionVerifier,
            "verifyGreedyAllPositionRequestBatchOutcomesOnDeviceResident");
        if (!stream)
        {
            stream = explicitGPUStreamForOperation(
                "verifyGreedyAllPositionRequestBatchOutcomesOnDeviceResident");
        }
        if (!stream)
            return false;

        std::shared_ptr<void> producer_start_timing_event;
        std::shared_ptr<void> producer_stop_timing_event;
        const bool collect_producer_gpu_timing =
            PerfStatsCollector::isEnabled() && state_.device_id.is_gpu();
        if (collect_producer_gpu_timing)
        {
            const int device_ordinal = device_opt->gpu_ordinal();
            if (!acquirePersistentMTPGpuTimingEvents(
                    "greedy_request_batch_compact_outcome_summary",
                    &producer_start_timing_event,
                    &producer_stop_timing_event))
            {
                return false;
            }
            if (!backend->recordEvent(
                    producer_start_timing_event.get(),
                    device_ordinal,
                    stream))
            {
                PerfStatsCollector::addCounter(
                    "mtp",
                    "greedy_request_batch_summary_gpu_timing_record_failures",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {{"event", "start"}});
                return false;
            }
        }

        const auto *base = static_cast<const float *>(gpu_ptr);
        if (!backend->enqueueArgmaxF32BatchedRowsDevice(
                base,
                max_target_row,
                static_cast<int>(cols),
                device_opt->gpu_ordinal(),
                stream,
                stochastic_verify_accept_probs_dev_,
                stochastic_verify_tokens_dev_,
                argmax_partial_vals_dev_,
                argmax_partial_idxs_dev_,
                argmax_partial_capacity_))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Greedy request-batch verifier device argmax failed on "
                      << device_opt->toString());
            return false;
        }

        auto *prepared_tokens =
            static_cast<const int32_t *>(mtp_verifier_input_tokens_dev_);
        auto *verify_tokens =
            static_cast<const int32_t *>(stochastic_verify_tokens_dev_);
        auto *output_tokens =
            static_cast<int32_t *>(stochastic_batch_output_tokens_dev_);
        auto *output_meta =
            static_cast<int *>(stochastic_batch_output_meta_dev_);
        for (int request_index = 0;
             request_index < request_count;
             ++request_index)
        {
            const DeviceGreedyBatchOutcomeRequest &request =
                requests[request_index];
            std::array<int, kSpeculativeBatchMaxStopTokens>
                packed_stop_tokens = {-1, -1, -1, -1, -1, -1, -1, -1};
            for (int stop_index = 0;
                 stop_index < request.stop_token_count;
                 ++stop_index)
            {
                packed_stop_tokens[static_cast<size_t>(stop_index)] =
                    request.stop_tokens[static_cast<size_t>(stop_index)];
            }

            if (!backend->enqueueSummarizeGreedySpeculativeVerifyBatch(
                    verify_tokens + request.first_target_row,
                    prepared_tokens + request.token_row_offset,
                    request.verifier_token_count - 1,
                    request.first_token,
                    packed_stop_tokens.data(),
                    request.stop_token_count,
                    device_opt->gpu_ordinal(),
                    stream,
                    stochastic_batch_output_token_stride_,
                    output_tokens +
                        static_cast<size_t>(request_index) *
                            static_cast<size_t>(
                                stochastic_batch_output_token_stride_),
                    output_meta +
                        static_cast<size_t>(request_index) *
                            static_cast<size_t>(kSpeculativeBatchMetaCount)))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Greedy request-batch verifier summary failed on "
                          << device_opt->toString()
                          << " request_index=" << request_index);
                return false;
            }
        }

        if (producer_stop_timing_event)
        {
            if (!backend->recordEvent(
                    producer_stop_timing_event.get(),
                    device_opt->gpu_ordinal(),
                    stream))
            {
                PerfStatsCollector::addCounter(
                    "mtp",
                    "greedy_request_batch_summary_gpu_timing_record_failures",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {{"event", "stop"}});
                return false;
            }
        }

        std::shared_ptr<void> response_ready_event =
            acquirePersistentMTPOutcomeReadyEvent(
                "greedy_request_batch_compact_outcome");
        if (!response_ready_event)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Greedy request-batch outcome has no available preallocated response-ready event");
            return false;
        }
        if (!DeviceEventEdge::at(
                 DeviceTimelinePoint::CompactSpeculativeResponseReady)
                 .from(DeviceTimelineRole::VerifierSummary)
                 .publish(
                     *backend,
                     state_.device_id,
                     response_ready_event.get(),
                     stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to record greedy request-batch outcome response-ready event");
            return false;
        }

        materialized_mtp_verifier_device_token_batch_ = {};
        if (!recordDeviceResidentMTPTransactionMutation(
                request_count,
                stream,
                "greedy_request_batch_device_outcome"))
        {
            return false;
        }
        out_handle->output_tokens_device =
            static_cast<const int32_t *>(stochastic_batch_output_tokens_dev_);
        out_handle->meta_device =
            static_cast<const int *>(stochastic_batch_output_meta_dev_);
        out_handle->request_count = request_count;
        out_handle->output_token_stride =
            stochastic_batch_output_token_stride_;
        out_handle->meta_stride = kSpeculativeBatchMetaCount;
        out_handle->device = state_.device_id;
        out_handle->stream = stream;
        out_handle->response_ready_event = std::move(response_ready_event);
        out_handle->mtp_transaction =
            currentDeviceResidentMTPTransactionLease();
        out_handle->producer_start_timing_event =
            std::move(producer_start_timing_event);
        out_handle->producer_stop_timing_event =
            std::move(producer_stop_timing_event);

        PerfStatsCollector::addCounter(
            "mtp",
            "request_batch_greedy_device_resident_outcomes",
            static_cast<double>(request_count),
            "decode",
            state_.device_id.toString(),
            {{"rows", std::to_string(max_target_row)}});
        return out_handle->valid();
    }

    bool DeviceGraphOrchestrator::verifyGreedyAllPositionBatchOutcomeOnDevice(
        const int32_t *draft_tokens,
        int draft_token_count,
        const int32_t *stop_tokens,
        int stop_token_count,
        DeviceSpeculativeVerifyBatchOutcome *out)
    {
        using namespace sampling_math;
        if (!out)
            return false;
        *out = DeviceSpeculativeVerifyBatchOutcome{};

        const int compare_rows = draft_token_count - 1;
        if (!draft_tokens ||
            draft_token_count <= 0 ||
            draft_token_count > mtp_max_verifier_rows_ ||
            compare_rows < 0 ||
            compare_rows > mtp_max_draft_depth_ ||
            stop_token_count < 0 ||
            stop_token_count > kSpeculativeBatchMaxStopTokens ||
            (stop_token_count > 0 && !stop_tokens) ||
            !state_.all_position_logits)
        {
            return false;
        }

        /*
         * See the resident counterpart above: only true local-shard verifier
         * logits are excluded. Mirrored LocalTP MTP heads keep full-vocab rows
         * despite the model's ordinary column-parallel LM-head setting.
         */
        if (activeAllPositionLogitsAreColumnParallel(draft_token_count))
            return false;

        const IGlobalTPContext *global_ctx = globalTPContextForMTPCoordination();
        if (global_ctx && global_ctx->degree() > 1)
            return false;

        TensorBase *tensor = state_.all_position_logits.get();
        const auto &shape = tensor->shape();
        if (shape.empty())
            return false;
        const size_t rows = shape.size() >= 2 ? shape[0] : 1;
        const size_t cols = shape.size() >= 2 ? shape[1] : shape[0];
        if (cols == 0 ||
            static_cast<size_t>(draft_token_count) > rows ||
            cols > static_cast<size_t>(std::numeric_limits<int>::max()))
        {
            return false;
        }

        std::array<int, kSpeculativeBatchMaxStopTokens> packed_stop_tokens =
            {-1, -1, -1, -1, -1, -1, -1, -1};
        for (int i = 0; i < stop_token_count; ++i)
            packed_stop_tokens[static_cast<size_t>(i)] = stop_tokens[i];

        if (state_.device_id.is_cpu())
        {
            /*
             * CPU runners keep verifier logits host-visible already, so the
             * compact vLLM-style greedy outcome can use the same shared summary
             * math without pretending to have a GPU-side reducer. This keeps
             * the SingleDevice CPU correctness gate symmetric with CUDA/ROCm
             * while still excluding sharded TP logits above.
             */
            const float *logits = tensor->fp32_data();
            if (!logits)
                return false;

            std::vector<int> verifier_tokens(
                static_cast<size_t>(draft_token_count));
            for (int row = 0; row < draft_token_count; ++row)
            {
                const float *row_logits =
                    logits + static_cast<size_t>(row) * static_cast<size_t>(cols);
                int best = 0;
                float best_value = row_logits[0];
                for (int col = 1; col < static_cast<int>(cols); ++col)
                {
                    if (row_logits[col] > best_value)
                    {
                        best = col;
                        best_value = row_logits[col];
                    }
                }
                verifier_tokens[static_cast<size_t>(row)] = best;
            }

            std::vector<int> packed_draft_tokens(
                static_cast<size_t>(draft_token_count));
            for (int i = 0; i < draft_token_count; ++i)
                packed_draft_tokens[static_cast<size_t>(i)] = draft_tokens[i];

            std::vector<int> output_tokens_int(
                static_cast<size_t>(draft_token_count));
            std::array<int, kSpeculativeBatchMetaCount> meta{};
            summarize_greedy_speculative_verify_batch(
                draft_tokens[0],
                verifier_tokens.data(),
                packed_draft_tokens.data(),
                compare_rows,
                packed_stop_tokens.data(),
                stop_token_count,
                output_tokens_int.data(),
                static_cast<int>(output_tokens_int.size()),
                meta.data());

            std::vector<int32_t> output_tokens(
                static_cast<size_t>(draft_token_count));
            for (size_t i = 0; i < output_tokens.size(); ++i)
                output_tokens[i] = static_cast<int32_t>(output_tokens_int[i]);

            if (!fillSpeculativeVerifyOutcomeFromMeta(
                    output_tokens.data(),
                    draft_token_count,
                    meta.data(),
                    out))
                return false;

            PerfStatsCollector::addCounter(
                "mtp",
                "all_position_greedy_device_batched_rows",
                static_cast<double>(draft_token_count),
                "decode",
                state_.device_id.toString(),
                {{"compare_rows", std::to_string(compare_rows)},
                 {"implementation", "cpu_compact_outcome"}});
            return true;
        }

        DeviceSpeculativeOutcomeHandle handle;
        if (!verifyGreedyAllPositionBatchOutcomeOnDeviceResident(
                draft_tokens,
                draft_token_count,
                stop_tokens,
                stop_token_count,
                &handle))
        {
            return false;
        }

        if (!copyDeviceSpeculativeOutcomesToHost(handle, out))
            return false;

        PerfStatsCollector::addCounter(
            "mtp",
            "all_position_greedy_device_batched_rows",
            static_cast<double>(draft_token_count),
            "decode",
            state_.device_id.toString(),
            {{"compare_rows", std::to_string(compare_rows)},
             {"implementation", "device_batch_outcome"}});
        return true;
    }

    bool DeviceGraphOrchestrator::supportsGreedyAllPositionBatchOutcomeOnDevice() const
    {
        /*
         * The compact reducer consumes one device's all-position logits tensor.
         * SingleDevice CPU can execute the same reducer contract over
         * host-visible logits. Rank-level sharded TP still needs a domain-wide
         * reduction contract, so only concrete CPU/GPU device runners advertise
         * this path.
         */
        return state_.device_id.is_cpu() || state_.device_id.is_gpu();
    }

    PrefixRuntimeStateSnapshot DeviceGraphOrchestrator::prefixStateProbe() const
    {
        void *probe_stream = explicitGPUStreamForOperation("prefixStateProbe");
        if (state_.device_id.is_gpu() &&
            (!probe_stream ||
             !waitForLiveInferenceStateReadyForObservation(
                 probe_stream,
                 "prefix_state_probe",
                 DeviceTimelineRole::Diagnostics)))
        {
            return {};
        }

        PrefixRuntimeStateSnapshot snapshot;
        snapshot.initialized = state_.isInitialized();
        snapshot.has_hidden = static_cast<bool>(state_.hidden);
        snapshot.has_logits = static_cast<bool>(state_.logits);
        snapshot.architecture = architecture();
        snapshot.execution_path = "graph";
        snapshot.primary_device = state_.device_id;
        snapshot.current_position = getPosition(0);
        snapshot.session_epoch = session_epoch_;
        snapshot.moe_runtime_movement_epoch = moeRuntimeMovementEpoch();
        snapshot.live_state_epoch = live_replay_state_epoch_;
        snapshot.live_state_mutations = live_state_mutation_count_;
        snapshot.last_live_state_mutation_reason =
            livePrefixMutationReasonName(last_live_state_mutation_reason_);
        snapshot.last_live_state_mutation_operation =
            last_live_state_mutation_operation_;
        snapshot.live_state_accepted_publications =
            live_state_accepted_publications_;
        snapshot.live_state_rejected_corrections =
            live_state_rejected_corrections_;
        snapshot.live_state_prefix_restores = live_state_prefix_restores_;
        snapshot.live_state_prefix_truncates = live_state_prefix_truncates_;
        snapshot.live_state_session_resets = live_state_session_resets_;
        snapshot.prefix_cache_config_enabled =
            graph_builder_ && graph_builder_->config().prefix_cache.enabled;
        snapshot.prefix_cache_bypassed =
            snapshot.prefix_cache_config_enabled && prefix_cache_bypassed_;
        snapshot.prefix_cache_bypass_reason =
            snapshot.prefix_cache_bypassed ? prefix_cache_bypass_reason_ : "";
        snapshot.prefix_cache_ready =
            static_cast<bool>(prefix_cache_) && !snapshot.prefix_cache_bypassed;
        if (prefix_cache_)
        {
            const auto &stats = prefix_cache_->stats();
            snapshot.prefix_cache_lookups = stats.lookups;
            snapshot.prefix_cache_hits = stats.hits;
            snapshot.prefix_cache_partial_hits = stats.partial_hits;
            snapshot.prefix_cache_misses = stats.misses;
            snapshot.prefix_cache_matched_blocks = stats.matched_blocks;
            snapshot.prefix_cache_matched_tokens = stats.matched_tokens;
            snapshot.prefix_cache_stores = stats.stores;
            snapshot.prefix_cache_inserts = stats.inserts;
            snapshot.prefix_cache_evictions = stats.evictions;
            snapshot.prefix_cache_promotions = stats.promotions;
            snapshot.prefix_cache_ram_to_disk_demotions =
                stats.ram_to_disk_demotions;
            snapshot.prefix_cache_device_hot_promotions =
                stats.device_hot_promotions;
            snapshot.prefix_cache_device_hot_repromotions =
                stats.device_hot_repromotions;
            snapshot.prefix_cache_device_hot_evictions =
                stats.device_hot_evictions;
            snapshot.prefix_cache_disk_evictions = stats.disk_evictions;
            snapshot.prefix_cache_device_hot_direct_hits =
                stats.device_hot_direct_hits;
            snapshot.prefix_cache_disk_hydrations = stats.disk_hydrations;
            snapshot.prefix_cache_terminal_state_hits = stats.terminal_state_hits;
            snapshot.prefix_cache_ram_bytes = stats.ram_bytes;
            snapshot.prefix_cache_device_bytes = stats.device_bytes;
            snapshot.prefix_cache_disk_bytes = stats.disk_bytes;
            snapshot.prefix_cache_hybrid_state_bytes = stats.hybrid_state_bytes;
            snapshot.prefix_cache_mtp_state_bytes = stats.mtp_state_bytes;
        }
        snapshot.prefix_cache_bypasses = prefix_cache_stats_.bypasses;
        snapshot.prefix_cache_unsupported_backend_bypasses =
            prefix_cache_stats_.unsupported_backend_bypasses;
        snapshot.prefix_cache_fingerprint_bypasses =
            prefix_cache_stats_.fingerprint_bypasses;
        snapshot.prefix_cache_terminal_state_bypasses =
            prefix_cache_stats_.terminal_state_bypasses;
        snapshot.mtp_config_enabled =
            graph_builder_ && graph_builder_->config().mtp.enabled;
        snapshot.positions = state_.positions;
        snapshot.sequence_lengths = state_.sequence_lengths;
        const DeviceResidentLogicalSequenceStateHandle logical_state =
            deviceResidentLogicalSequenceState();
        if (logical_state.valid())
        {
            /*
             * A diagnostic snapshot is a host-visible result boundary, so it
             * may materialize the small logical metadata row.  Read the entire
             * row from the authoritative mailbox in one operation rather than
             * mixing request zero with stale host vectors for later requests.
             * Any failed observation is fatal: returning the host mirror would
             * make a coherence defect look like a valid runtime state.
             */
            if (!waitForDeviceResidentLogicalSequenceStateMailboxForObservation(
                    probe_stream,
                    "prefix_state_probe_logical_state"))
            {
                throw std::runtime_error(
                    "Prefix-state diagnostics could not wait for the "
                    "device-resident logical-state mailbox");
            }
            IBackend *backend = getBackendFor(state_.device_id);
            if (!backend)
            {
                throw std::runtime_error(
                    "Prefix-state diagnostics could not resolve the GPU backend");
            }

            const size_t request_count =
                static_cast<size_t>(logical_state.request_count);
            std::vector<int32_t> resident_positions(request_count, -1);
            std::vector<int32_t> resident_sequence_lengths(request_count, -1);
            const size_t row_bytes = sizeof(int32_t) * request_count;
            if (!backend->deviceToHostFast(
                    resident_positions.data(),
                    logical_state.target_positions_device,
                    row_bytes,
                    state_.device_id.gpu_ordinal(),
                    probe_stream) ||
                !backend->deviceToHostFast(
                    resident_sequence_lengths.data(),
                    logical_state.target_sequence_lengths_device,
                    row_bytes,
                    state_.device_id.gpu_ordinal(),
                    probe_stream))
            {
                throw std::runtime_error(
                    "Prefix-state diagnostics could not materialize the "
                    "device-resident logical-state row");
            }
            if (std::any_of(
                    resident_positions.begin(),
                    resident_positions.end(),
                    [](int32_t value) { return value < 0; }) ||
                std::any_of(
                    resident_sequence_lengths.begin(),
                    resident_sequence_lengths.end(),
                    [](int32_t value) { return value < 0; }))
            {
                throw std::runtime_error(
                    "Prefix-state diagnostics observed invalid negative "
                    "device-resident logical metadata");
            }

            snapshot.current_position = resident_positions.front();
            snapshot.positions.assign(
                resident_positions.begin(),
                resident_positions.end());
            snapshot.sequence_lengths.assign(
                resident_sequence_lengths.begin(),
                resident_sequence_lengths.end());
        }

        const int sequence_count = state_.batch_size > 0 ? state_.batch_size : 1;
        if (state_.kv_cache)
        {
            auto cache_probe = inspectKVCacheForPrefixProbe(
                *state_.kv_cache,
                "primary",
                state_.device_id,
                sequence_count,
                probe_stream);
            auto gdn_probes = inspectHybridGDNForPrefixProbe(*state_.kv_cache, probe_stream);
            snapshot.gdn_layers.insert(snapshot.gdn_layers.end(),
                                       gdn_probes.begin(), gdn_probes.end());
            snapshot.kv_caches.push_back(std::move(cache_probe));
        }

        for (const auto &[device, cache] : state_.pp_kv_caches)
        {
            if (!cache)
            {
                continue;
            }
            auto cache_probe = inspectKVCacheForPrefixProbe(
                *cache,
                "pp:" + device.to_string(),
                device,
                sequence_count,
                probe_stream);
            auto gdn_probes = inspectHybridGDNForPrefixProbe(*cache, probe_stream);
            snapshot.gdn_layers.insert(snapshot.gdn_layers.end(),
                                       gdn_probes.begin(), gdn_probes.end());
            snapshot.kv_caches.push_back(std::move(cache_probe));
        }

        for (size_t depth = 0; depth < state_.mtp_kv_caches.size(); ++depth)
        {
            const auto &cache = state_.mtp_kv_caches[depth];
            if (!cache)
            {
                continue;
            }
            auto cache_probe = inspectKVCacheForPrefixProbe(
                *cache,
                "mtp:" + std::to_string(depth),
                state_.device_id,
                sequence_count,
                probe_stream);
            if (auto resident_mtp_tokens =
                    deviceResidentShiftedMTPKVTokenCountForObservation(
                        static_cast<int>(depth),
                        /*request_index=*/0,
                        probe_stream,
                        "prefix_state_probe_shifted_mtp"))
            {
                for (auto &layer_probe : cache_probe.layers)
                {
                    if (layer_probe.seq_idx == 0)
                    {
                        layer_probe.cached_tokens = *resident_mtp_tokens;
                        layer_probe.ring_head = *resident_mtp_tokens;
                    }
                }
            }
            snapshot.mtp_kv_caches.push_back(std::move(cache_probe));
        }

        if (forward_engine_)
        {
            auto phase_name = [](PrefillGraphPhase phase) -> const char *
            {
                switch (phase)
                {
                case PrefillGraphPhase::Disabled:
                    return "disabled";
                case PrefillGraphPhase::Cold:
                    return "cold";
                case PrefillGraphPhase::Initialized:
                    return "initialized";
                case PrefillGraphPhase::Warmup:
                    return "warmup";
                case PrefillGraphPhase::Capturing:
                    return "capturing";
                case PrefillGraphPhase::Ready:
                    return "ready";
                }
                return "unknown";
            };

            const auto prefill_snapshots = forward_engine_->prefillGraphCacheSnapshots();
            snapshot.prefill_graphs.reserve(prefill_snapshots.size());
            for (const auto &entry : prefill_snapshots)
            {
                PrefillGraphRuntimeProbe probe;
                probe.forward_cache_valid = entry.forward_cache_valid;
                probe.prefill_cache_initialized = entry.prefill_cache_initialized;
                probe.phase = phase_name(entry.phase);
                probe.cache_size = entry.cache_size;
                probe.node_count = entry.node_count;
                probe.replay_count = entry.replay_count;
                probe.warmup_count = entry.warmup_count;
                probe.initialized_count = entry.initialized_count;
                probe.capture_count = entry.capture_count;
                probe.eviction_count = entry.eviction_count;
                probe.observation_valid = entry.observation_valid;
                probe.chunk_index = entry.chunk_index;
                probe.bucket_seq_len = entry.bucket_seq_len;
                probe.real_token_start = entry.real_token_start;
                probe.real_token_count = entry.real_token_count;
                probe.real_token_end = entry.real_token_end;
                probe.domain_id = entry.domain_id;
                probe.participant_id = entry.participant_id;
                probe.placement_epoch = entry.placement_epoch;
                probe.topology_signature = entry.topology_signature;
                probe.capture_phase = entry.capture_phase;
                probe.recapture_reason = entry.recapture_reason;
                probe.reject_stage_name = entry.reject_stage_name;
                probe.reject_stage_type = entry.reject_stage_type;
                snapshot.prefill_graphs.push_back(std::move(probe));
            }
        }

        return snapshot;
    }

    void DeviceGraphOrchestrator::disablePrefixCacheForRunner(const std::string &reason)
    {
        const bool should_record =
            !prefix_cache_bypassed_ &&
            graph_builder_ &&
            graph_builder_->config().prefix_cache.enabled &&
            reason != "feature disabled";

        if (should_record)
        {
            ++prefix_cache_stats_.bypasses;
            const std::string normalized_reason = lowerASCII(reason);
            if (containsAny(normalized_reason, {"fingerprint", "moe placement policy"}))
            {
                ++prefix_cache_stats_.fingerprint_bypasses;
            }
            else if (containsAny(normalized_reason, {"terminal"}))
            {
                ++prefix_cache_stats_.terminal_state_bypasses;
            }
            else if (containsAny(normalized_reason,
                                 {"unavailable",
                                  "not implemented",
                                  "does not expose",
                                  "without an initialized",
                                  "graph builder unavailable"}))
            {
                ++prefix_cache_stats_.unsupported_backend_bypasses;
            }
        }
        prefix_cache_bypassed_ = true;
        prefix_cache_bypass_reason_ = reason;
        if (!reason.empty())
        {
            LOG_DEBUG("[DeviceGraphOrchestrator] Prefix cache bypassed: " << reason);
        }
    }

    bool DeviceGraphOrchestrator::isPrefixCacheMoEModel() const
    {
        if (!graph_builder_)
            return false;
        const std::string architecture = graph_builder_->architectureName();
        return architecture.find("moe") != std::string::npos ||
               architecture.find("MoE") != std::string::npos;
    }

    void *DeviceGraphOrchestrator::explicitGPUStreamForOperation(const char *operation) const
    {
        if (!state_.device_id.is_gpu())
        {
            return nullptr;
        }

        try
        {
            void *stream = GPUDeviceContextPool::instance()
                               .getContext(state_.device_id)
                               .defaultStream();
            if (!stream)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] "
                          << (operation ? operation : "gpu_operation")
                          << " requires an explicit non-null GPU stream on "
                          << state_.device_id.toString());
            }
            return stream;
        }
        catch (const std::exception &e)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] "
                      << (operation ? operation : "gpu_operation")
                      << " could not acquire an explicit GPU stream on "
                      << state_.device_id.toString() << ": " << e.what());
            return nullptr;
        }
    }

    const char *DeviceGraphOrchestrator::livePrefixMutationReasonName(
        LivePrefixMutationReason reason)
    {
        switch (reason)
        {
        case LivePrefixMutationReason::AcceptedSpecPublication:
            return "accepted_publication";
        case LivePrefixMutationReason::RejectedCorrection:
            return "rejected_correction";
        case LivePrefixMutationReason::PrefixRestore:
            return "prefix_restore";
        case LivePrefixMutationReason::PrefixTruncate:
            return "prefix_truncate";
        case LivePrefixMutationReason::ShiftedMTPKVUpdate:
            return "shifted_mtp_kv_update";
        case LivePrefixMutationReason::SessionReset:
            return "session_reset";
        case LivePrefixMutationReason::Unknown:
        default:
            return "unknown";
        }
    }

    DeviceGraphOrchestrator::LivePrefixMutationRecord
    DeviceGraphOrchestrator::recordLivePrefixMutation(
        LivePrefixMutationReason reason,
        const char *operation)
    {
        const uint64_t previous_epoch = live_replay_state_epoch_;
        ++live_replay_state_epoch_;
        ++live_state_mutation_count_;
        last_live_state_mutation_reason_ = reason;
        last_live_state_mutation_operation_ =
            operation ? operation : "unknown";

        switch (reason)
        {
        case LivePrefixMutationReason::AcceptedSpecPublication:
            ++live_state_accepted_publications_;
            break;
        case LivePrefixMutationReason::RejectedCorrection:
            ++live_state_rejected_corrections_;
            break;
        case LivePrefixMutationReason::PrefixRestore:
            ++live_state_prefix_restores_;
            break;
        case LivePrefixMutationReason::PrefixTruncate:
            ++live_state_prefix_truncates_;
            break;
        case LivePrefixMutationReason::ShiftedMTPKVUpdate:
            ++live_state_shifted_mtp_kv_updates_;
            break;
        case LivePrefixMutationReason::SessionReset:
            ++live_state_session_resets_;
            break;
        case LivePrefixMutationReason::Unknown:
        default:
            break;
        }

        return LivePrefixMutationRecord{
            previous_epoch,
            live_replay_state_epoch_,
            livePrefixMutationReasonName(reason)};
    }

    void DeviceGraphOrchestrator::recordLivePrefixSessionReset(
        const char *operation,
        bool preserve_gpu_replay_state)
    {
        clearPendingAllPositionVerifierStateReady();
        clearPendingAcceptedSpecPublicationReady();
        PerfStatsCollector::Tags tags{{"operation", operation ? operation : "unknown"}};
        const LivePrefixMutationRecord mutation =
            recordLivePrefixMutation(
                LivePrefixMutationReason::SessionReset,
                operation);
        tags["mutation_reason"] = mutation.reason_name;
        tags["previous_live_state_epoch"] =
            std::to_string(mutation.previous_epoch);
        tags["live_state_epoch"] = std::to_string(mutation.live_state_epoch);
        tags["live_state_mutation_count"] =
            std::to_string(live_state_mutation_count_);
        if (isPrefixCacheMoEModel())
        {
            tags["model"] = "moe";
            tags["moe_placement_epoch"] = std::to_string(moePlacementEpoch());
            tags["moe_runtime_movement_epoch"] =
                std::to_string(moeRuntimeMovementEpoch());
        }
        if (preserve_gpu_replay_state)
        {
            tags["forward_replay_reset_scope"] = "request_boundary_preserve";
            tags["replay_state"] = "preserved";
            tags["sidecar_replay_state"] = "preserved";
            tags["kernel_dynamic_state"] = "preserved";
            tags["gpu_replay_preserve_reason"] =
                operation ? operation : "session_reset";
        }
        else
        {
            tags["forward_replay_reset_scope"] = "session";
            tags["replay_state"] = "reset";
            tags["sidecar_replay_state"] = "reset";
            tags["kernel_dynamic_state"] = "reset";
        }
        PerfStatsCollector::addCounter("mtp",
                                       "live_prefix_replay_state_after_mutation",
                                       1.0,
                                       "decode",
                                       state_.device_id.toString(),
                                       std::move(tags));
    }

    void DeviceGraphOrchestrator::invalidateMTPSidecarDepth0GraphState(const char *reason)
    {
        mtp_sidecar_depth0_cache_.invalidate();
        mtp_sidecar_depth0_device_token_cache_.invalidate();
        mtp_sidecar_depth0_chained_cache_.invalidate();
        mtp_sidecar_depth0_chained_device_token_cache_.invalidate();
        mtp_sidecar_depth0_kv_only_cache_.invalidate();
        mtp_sidecar_depth0_kv_only_device_token_cache_.invalidate();
        for (auto &cache : mtp_sidecar_depth0_kv_only_batch_caches_)
        {
            cache->invalidate();
        }

        PerfStatsCollector::Tags tags;
        tags["reason"] = reason ? reason : "unknown";
        tags["state_epoch"] = std::to_string(session_epoch_);
        tags["moe_placement_epoch"] = std::to_string(moePlacementEpoch());
        PerfStatsCollector::addCounter("mtp",
                                       "sidecar_graph_invalidations",
                                       1.0,
                                       "decode",
                                       state_.device_id.toString(),
                                       std::move(tags));
    }

    void DeviceGraphOrchestrator::resetMTPSidecarDepth0ReplayState()
    {
        mtp_sidecar_depth0_cache_.resetReplayState();
        mtp_sidecar_depth0_device_token_cache_.resetReplayState();
        mtp_sidecar_depth0_chained_cache_.resetReplayState();
        mtp_sidecar_depth0_chained_device_token_cache_.resetReplayState();
        mtp_sidecar_depth0_kv_only_cache_.resetReplayState();
        mtp_sidecar_depth0_kv_only_device_token_cache_.resetReplayState();
        for (auto &cache : mtp_sidecar_depth0_kv_only_batch_caches_)
        {
            cache->resetReplayState();
        }
    }

    /**
     * @brief Publish a shifted-MTP-KV mutation without invalidating GPU graphs.
     *
     * A shifted row changes the contents and logical count of the MTP sidecar
     * cache, but it does not change any buffer address captured by the main
     * verifier or by a sidecar graph. Dense sidecars own persistent dynamic
     * token/position storage. MoE sidecars additionally own depth-scoped
     * `MoERuntimeTable` instances and MTP-scoped activation scratch, so their
     * routed metadata cannot alias the main graph or another MTP depth.
     *
     * The producer records `shifted_mtp_kv_ready_` before reaching this method.
     * Every later sidecar/verifier launch waits on that event from its explicit
     * stream. The event is therefore the complete ordering contract: advancing
     * the logical live-state epoch here must not destroy graph executables,
     * reset kernel dynamic objects, or clear the verifier publication event.
     *
     * @param operation Stable diagnostic name for the shifted-row producer.
     */
    void DeviceGraphOrchestrator::recordShiftedMTPKVReplayStateMutation(
        const char *operation)
    {
        if (!state_.device_id.is_gpu())
            return;

        /*
         * This is deliberately narrower than
         * handleLivePrefixReplayStateAfterMutation(): shifted MTP KV is sidecar
         * input state for the next draft, not live main-verifier state.  The
         * verifier launch still consumes the shifted-KV readiness event in
         * prepareAllPositionVerifierGraphMetadata(), so the GPU ordering edge
         * remains explicit without destroying the captured main-verifier graph
         * on every accepted row.
         *
         * Do not clear all_position_verifier_state_ready_ here.  The accepted
         * state publisher may run after a shifted-row commit and still needs
         * the verifier event to order recurrent/KV row-snapshot restores after
         * the all-position verifier graph.  Reset and prefix-restore paths own
         * abandoned verifier handoff cleanup explicitly.
         */
        PerfStatsCollector::Tags tags{
            {"operation", operation ? operation : "shifted_mtp_kv_update"}};
        const LivePrefixMutationRecord mutation =
            recordLivePrefixMutation(
                LivePrefixMutationReason::ShiftedMTPKVUpdate,
                operation);
        tags["mutation_reason"] = mutation.reason_name;
        tags["previous_live_state_epoch"] =
            std::to_string(mutation.previous_epoch);
        tags["live_state_epoch"] = std::to_string(mutation.live_state_epoch);
        tags["live_state_mutation_count"] =
            std::to_string(live_state_mutation_count_);
        tags["shifted_mtp_kv_update_count"] =
            std::to_string(live_state_shifted_mtp_kv_updates_);
        tags["forward_replay_reset_scope"] = "shifted_mtp_kv_sidecar_only";
        tags["replay_state"] = "preserved";
        tags["sidecar_replay_state"] = "preserved";
        tags["kernel_dynamic_state"] = "preserved";
        if (isPrefixCacheMoEModel())
        {
            tags["model"] = "moe";
            tags["moe_placement_epoch"] = std::to_string(moePlacementEpoch());
        }
        PerfStatsCollector::addCounter(
            "mtp",
            "live_prefix_replay_state_after_mutation",
            1.0,
            "decode",
            state_.device_id.toString(),
            std::move(tags));
    }

    void DeviceGraphOrchestrator::handleLivePrefixReplayStateAfterMutation(
        LivePrefixMutationReason reason,
        const char *operation,
        bool preserve_gpu_replay_state)
    {
        if (reason == LivePrefixMutationReason::PrefixRestore)
        {
            /*
             * Prefix restore is a full live-state replacement.  Clearing every
             * transient handoff here makes the next forward depend only on the
             * freshly imported snapshot plus the mutation-ready event recorded by
             * the caller, not on any stream/mailbox token from the discarded
             * timeline.
             */
            clearLivePrefixRestoreTransientHandoffs(operation);
        }
        else
        {
            clearPendingAllPositionVerifierStateReady();
        }
        if (reason != LivePrefixMutationReason::AcceptedSpecPublication &&
            reason != LivePrefixMutationReason::RejectedCorrection)
        {
            clearPendingAcceptedSpecPublicationReady();
        }

        PerfStatsCollector::Tags tags{{"operation", operation ? operation : "unknown"}};
        const LivePrefixMutationRecord mutation =
            recordLivePrefixMutation(reason, operation);
        tags["mutation_reason"] = mutation.reason_name;
        tags["previous_live_state_epoch"] =
            std::to_string(mutation.previous_epoch);
        tags["live_state_epoch"] = std::to_string(mutation.live_state_epoch);
        tags["live_state_mutation_count"] =
            std::to_string(live_state_mutation_count_);
        if (isPrefixCacheMoEModel())
        {
            tags["model"] = "moe";
            tags["moe_placement_epoch"] = std::to_string(moePlacementEpoch());
        }
        bool preserves_correction_graph_replay = false;
        if (forward_engine_ && !preserve_gpu_replay_state)
        {
            const bool correction_replay_boundary =
                reason == LivePrefixMutationReason::AcceptedSpecPublication ||
                reason == LivePrefixMutationReason::RejectedCorrection;
            if (correction_replay_boundary)
            {
                /*
                 * Accepted/rejected MTP publication is a live-state boundary:
                 * KV, GDN, short-conv, terminal hidden, and shifted sidecar
                 * caches have just been advanced to a compact verifier row.
                 * The capture lifetime is determined by the graph signature,
                 * not by the backend alone. Single-token ordinary decode reads
                 * backend-owned live buffers at stable addresses, while GDN and
                 * short-conv verifier work lives in separate speculative slots.
                 * CUDA and ROCm integration regressions capture the ordinary
                 * graph once, publish every accepted row at M=2/3/4, and prove
                 * the replayed continuation plus full recurrent state byte-equal
                 * to serial M=1 decode. All-position verifier graphs similarly
                 * refresh their stage-owned row metadata before every launch.
                 *
                 * Multi-row ordinary decode remains live-state-versioned: its
                 * captured executable encodes progression across several live
                 * rows, so publication invalidates that replay state. Delegate
                 * this distinction to the typed cache policy and retain every
                 * executable whose device-state ownership contract is proven.
                 */
                const bool preserve_single_token_decode_replay =
                    state_.device_id.is_gpu();
                const ForwardExecutionEngine::ReplayStateResetSummary summary =
                    forward_engine_->resetCapturedReplayStateForCorrectionReplay(
                        live_replay_state_epoch_,
                        preserve_single_token_decode_replay);
                preserves_correction_graph_replay =
                    summary.preserved_for_stream_rebind > 0;
                tags["forward_replay_reset_scope"] =
                    "correction_replay_typed_live_state";
                tags["forward_replay_single_token_decode_replay"] =
                    preserve_single_token_decode_replay
                        ? "preserved_byte_proven_device_state"
                        : "reset_for_publication_boundary";
                tags["forward_replay_reset_cache_count"] =
                    std::to_string(summary.reset_replay_state);
                tags["forward_replay_stream_rebind_cache_count"] =
                    std::to_string(summary.preserved_for_stream_rebind);
                tags["forward_replay_ordinary_decode_reset_count"] =
                    std::to_string(summary.ordinary_decode_reset);
                tags["forward_replay_all_position_verifier_rebind_count"] =
                    std::to_string(summary.all_position_verifier_preserved);
                tags["forward_replay_other_rebind_count"] =
                    std::to_string(summary.other_preserved);
            }
            else
            {
                if (reason == LivePrefixMutationReason::PrefixRestore)
                {
                    /*
                     * Prefix restore is a complete replacement of the live
                     * request state: main KV, hybrid recurrent buffers,
                     * terminal hidden/logits, MTP KV, positions, and sequence
                     * lengths all move to a previously captured point. A cached
                     * ComputeGraph may still own stage objects with
                     * request-scoped metadata or stable host/device buffer
                     * bindings from the pre-restore timeline. Rebuilding the
                     * forward graph on the next token is a small cost at a
                     * prefix-hit boundary and gives restore the same atomic
                     * semantics as a fresh continuation.
                     */
                    forward_engine_->discardAllCachedGraphs();
                    tags["forward_replay_reset_scope"] =
                        "prefix_restore_discard_cached_graphs";
                }
                else
                {
                    forward_engine_->resetCapturedReplayState();
                    tags["forward_replay_reset_scope"] = "all";
                }
            }

            /*
             * GPU sidecar graph replay is a mandatory device-ownership
             * contract, not an advertised optional capability. Dense and MoE
             * sidecars own stable dynamic buffers; MoE routed metadata is
             * depth-scoped as part of graph construction. Accepted/rejected
             * publication therefore changes buffer contents behind stable
             * addresses and is ordered by explicit events without recapture.
             */
            const bool preserve_sidecar_replay =
                state_.device_id.is_gpu() && correction_replay_boundary;
            if (!preserve_sidecar_replay)
            {
                /*
                 * Resetting sidecar graph replay tears down captured segments.
                 * GraphSegmentCache::reset() synchronizes the explicit capture
                 * stream before resources are discarded, so this timer makes
                 * the real recapture/synchronization tax visible in Phase 10
                 * tuning runs instead of hiding it inside publication latency.
                 */
                PerfStatsCollector::ScopedTimer reset_timer(
                    "mtp",
                    "sidecar_replay_reset",
                    "decode",
                    state_.device_id.toString(),
                    {{"operation", operation ? operation : "unknown"},
                     {"mutation_reason", tags["mutation_reason"]},
                     {"correction_replay_boundary",
                      boolTag(correction_replay_boundary)},
                     {"reset_scope",
                      correction_replay_boundary
                          ? "after_spec_publication"
                          : "all"}});
                resetMTPSidecarDepth0ReplayState();
                tags["sidecar_replay_state"] =
                    correction_replay_boundary
                        ? "reset_after_spec_publication"
                        : "reset";
            }
            else
            {
                tags["sidecar_replay_state"] = "preserved_for_spec_publication";
                preserves_correction_graph_replay = true;
            }
            tags["replay_state"] = "reset";
        }
        else
        {
            tags["replay_state"] = "preserved";
            tags["sidecar_replay_state"] = "preserved";
            if (state_.device_id.is_gpu() && preserve_gpu_replay_state)
            {
                tags["gpu_replay_preserve_reason"] =
                    operation ? operation : "live_prefix_mutation";
            }
        }
        /*
         * KernelFactory::resetAllDynamicState() clears per-kernel dynamic
         * device-param validity and stream bindings.  That is correct for a
         * hard graph reset, but unsafe when this boundary deliberately keeps
         * graph executables alive: CUDA/HIP graphs capture kernel argument
         * pointer identity, while updateDynamicParams() only restamps the
         * already-captured dynamic buffers before replay.  Preserve kernel
         * dynamic objects for accepted/rejected MTP publication boundaries and
         * rely on the explicit stream rebind plus per-stage dynamic updates.
         */
        if (!preserve_gpu_replay_state && preserves_correction_graph_replay)
        {
            tags["kernel_dynamic_state"] =
                "preserved_for_correction_graph_replay";
        }
        else if (!preserve_gpu_replay_state)
        {
            resetKernelDynamicState();
            tags["kernel_dynamic_state"] = "reset";
        }
        else
        {
            tags["kernel_dynamic_state"] = "preserved";
        }
        PerfStatsCollector::addCounter("mtp",
                                       "live_prefix_replay_state_after_mutation",
                                       1.0,
                                       "decode",
                                       state_.device_id.toString(),
                                       std::move(tags));
    }

    PrefixCacheFingerprintResult DeviceGraphOrchestrator::buildCurrentPrefixFingerprint(
        const PrefixCacheRuntimeConfig &prefix_config) const
    {
        const auto &config = graph_builder_->config();
        PrefixFingerprintMaterial material;
        material.model = {
            {"architecture", graph_builder_->architectureName()},
            {"n_layers", std::to_string(config.n_layers)},
            {"d_model", std::to_string(config.d_model)},
            {"n_heads", std::to_string(config.n_heads)},
            {"n_kv_heads", std::to_string(config.n_kv_heads)},
            {"vocab_size", std::to_string(config.vocab_size)},
        };
        material.runtime = {
            {"activation_precision", activationPrecisionToString(config.activation_precision)},
            {"kv_cache_precision", kvCachePrecisionToString(config.kv_cache_precision)},
            {"k_precision", activationPrecisionToString(prefix_layout_.k_precision)},
            {"v_precision", activationPrecisionToString(prefix_layout_.v_precision)},
            {"kv_layout", std::to_string(static_cast<int>(prefix_layout_.kv_layout))},
            {"block_size", std::to_string(prefix_layout_.block_size)},
            {"terminal_state", prefixCacheTerminalStateModeToString(prefix_config.terminal_state)},
        };
        material.topology = {
            {"first_layer_index", std::to_string(prefix_layout_.first_layer_index)},
            {"total_layers", std::to_string(prefix_layout_.total_layers)},
            {"head_dim", std::to_string(prefix_layout_.head_dim)},
        };
        if (config.tp_config && config.tp_config->worldSize() > 1)
        {
            material.topology.push_back({"scope", "tp-domain"});
            material.topology.push_back({"tp_world_size", std::to_string(config.tp_config->worldSize())});
            material.topology.push_back({"tp_total_heads", std::to_string(config.tp_config->totalHeads())});
            material.topology.push_back({"tp_total_kv_heads", std::to_string(config.tp_config->totalKVHeads())});
            material.topology.push_back({"tp_total_d_ff", std::to_string(config.tp_config->totalDFF())});
            material.topology.push_back({"tp_total_vocab", std::to_string(config.tp_config->totalVocab())});
            material.topology.push_back({"tp_proportional", config.tp_config->isProportional() ? "true" : "false"});
            material.topology.push_back({"qkv_column_parallel", config.qkv_column_parallel ? "true" : "false"});
            material.topology.push_back({"lm_head_column_parallel", config.lm_head_column_parallel ? "true" : "false"});
        }
        else
        {
            material.topology.push_back({"scope", "single-participant"});
            material.topology.push_back({"device", state_.device_id.toString()});
            material.topology.push_back({"local_kv_heads", std::to_string(prefix_layout_.local_kv_heads)});
            material.topology.push_back({"kv_head_start", std::to_string(prefix_layout_.kv_head_start)});
        }
        material.hybrid = prefix_layout_.includes_hybrid_state
                              ? std::vector<PrefixFingerprintField>{
                                    {"enabled", "true"},
                                    {"gdn_layers", std::to_string(prefix_layout_.gdn_layers)},
                                    {"hybrid_host_state_bytes", std::to_string(prefix_layout_.hybrid_host_state_bytes)},
                                    {"hybrid_device_state_bytes", std::to_string(prefix_layout_.hybrid_device_state_bytes)},
                                    {"hybrid_state_bytes", std::to_string(prefix_layout_.hybrid_state_bytes)},
                                }
                              : std::vector<PrefixFingerprintField>{{"enabled", "false"}};
        material.mtp = config.mtp.enabled
                           ? std::vector<PrefixFingerprintField>{
                                 {"enabled", "true"},
                                 {"draft_tokens", std::to_string(config.mtp.draft_tokens)},
                                 {"verify_mode", mtpVerifyModeToString(config.mtp.verify_mode)},
                                 {"require_terminal_hidden_for_full_hit",
                                  config.mtp.require_terminal_hidden_for_full_hit ? "true" : "false"},
                                 {"terminal_hidden_bytes", std::to_string(prefix_layout_.terminal_hidden_bytes)},
                             }
                           : std::vector<PrefixFingerprintField>{{"enabled", "false"}};

        const bool model_is_moe = isPrefixCacheMoEModel();
        if (model_is_moe)
        {
            const bool invalidate_on_rebalance =
                prefix_config.moe_policy == PrefixCacheMoEPolicy::InvalidateOnRebalance;
            material.moe.push_back({"policy", prefixCacheMoEPolicyToString(prefix_config.moe_policy)});
            material.moe.push_back({"model_is_moe", "true"});
            if (invalidate_on_rebalance)
            {
                material.moe.push_back({"runtime_movement_epoch", std::to_string(moeRuntimeMovementEpoch())});
                material.moe.push_back({"graph_placement_epoch", std::to_string(moePlacementEpoch())});
            }
            if (moe_rebalance_controller_)
            {
                const auto *controller = moe_rebalance_controller_.get();
                material.moe.push_back({"controller.num_layers", std::to_string(controller->numLayers())});
                material.moe.push_back({"controller.num_experts", std::to_string(controller->numExperts())});
                material.moe.push_back({"controller.top_k", std::to_string(controller->topK())});
                if (invalidate_on_rebalance)
                {
                    material.moe.push_back({"controller.placement_epoch", std::to_string(controller->placementEpoch())});
                    material.moe.push_back({"controller.total_rebalances", std::to_string(controller->totalRebalances())});
                }

                const auto &placement = controller->currentPlacement();
                if (invalidate_on_rebalance)
                {
                    for (size_t expert = 0; expert < placement.size(); ++expert)
                    {
                        material.moe.push_back({"controller.expert." + std::to_string(expert) + ".owner_participant",
                                                std::to_string(placement[expert])});
                    }
                }

                const auto &replicas = controller->currentReplicas();
                if (invalidate_on_rebalance)
                {
                    material.moe.push_back({"controller.replicas.count", std::to_string(replicas.num_replicated)});
                    for (size_t expert = 0; expert < replicas.is_replicated.size(); ++expert)
                    {
                        const std::string prefix = "controller.replica." + std::to_string(expert);
                        material.moe.push_back({prefix + ".enabled", replicas.is_replicated[expert] ? "1" : "0"});
                        if (expert < replicas.owner_socket.size())
                        {
                            material.moe.push_back({prefix + ".owner_participant",
                                                    std::to_string(replicas.owner_socket[expert])});
                        }
                    }
                    for (size_t layer = 0; layer < replicas.replica_participants_by_layer.size(); ++layer)
                    {
                        const auto &layer_replicas = replicas.replica_participants_by_layer[layer];
                        for (size_t expert = 0; expert < layer_replicas.size(); ++expert)
                        {
                            const auto &participants = layer_replicas[expert];
                            for (size_t participant = 0; participant < participants.size(); ++participant)
                            {
                                if (!participants[participant])
                                    continue;
                                material.moe.push_back({"controller.replica.layer." + std::to_string(layer) +
                                                            ".expert." + std::to_string(expert) +
                                                            ".participant." + std::to_string(participant),
                                                        "1"});
                            }
                        }
                    }
                }
            }
        }

        if (graph_builder_)
            graph_builder_->appendPrefixCacheFingerprintMaterial(material);

        return buildPrefixCacheFingerprint(
            material,
            model_is_moe,
            prefix_config.moe_policy);
    }

    bool DeviceGraphOrchestrator::ensurePrefixArchiveDeviceStaging()
    {
        if (!state_.device_id.is_gpu())
        {
            prefix_archive_device_staging_.reset();
            return true;
        }
        if (!arena_)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Prefix archive staging requires an initialized BufferArena");
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Prefix archive staging cannot resolve backend for "
                      << state_.device_id.toString());
            return false;
        }
        if (!prefix_archive_device_staging_ ||
            prefix_archive_device_staging_->device != state_.device_id)
        {
            prefix_archive_device_staging_ =
                std::make_unique<PrefixArchiveDeviceStaging>(
                    backend,
                    state_.device_id);
        }

        struct Requirement
        {
            BufferId id;
            size_t bytes;
        };
        const std::array<Requirement, 5> requirements = {{
            {BufferId::PREFIX_K_STAGING, prefix_layout_.bytes_per_fa_layer_k},
            {BufferId::PREFIX_V_STAGING, prefix_layout_.bytes_per_fa_layer_v},
            {BufferId::PREFIX_HYBRID_STATE_STAGING, prefix_layout_.hybrid_device_state_bytes},
            {BufferId::PREFIX_MTP_K_STAGING, prefix_layout_.bytes_per_mtp_layer_k},
            {BufferId::PREFIX_MTP_V_STAGING, prefix_layout_.bytes_per_mtp_layer_v},
        }};

        for (const Requirement &requirement : requirements)
        {
            if (requirement.bytes == 0)
                continue;

            auto *slot = prefix_archive_device_staging_->slot(requirement.id);
            if (!slot ||
                !prefix_archive_device_staging_->ensure(*slot, requirement.bytes) ||
                !slot->view)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to allocate "
                          << bufferIdName(requirement.id)
                          << " capacity=" << requirement.bytes);
                return false;
            }

            const bool registered = arena_->isRegistered(requirement.id);
            const bool bound =
                registered
                    ? arena_->bindExternalBuffer(requirement.id, slot->view.get())
                    : arena_->registerExternalBuffer(requirement.id, slot->view.get());
            if (!bound)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to "
                          << (registered ? "bind " : "register ")
                          << bufferIdName(requirement.id)
                          << " with BufferArena");
                return false;
            }
        }

        PerfStatsCollector::addCounter(
            "prefix_cache",
            "device_archive_staging_ready",
            1.0,
            "initialization",
            state_.device_id.toString(),
            {
                {"k_bytes", std::to_string(prefix_layout_.bytes_per_fa_layer_k)},
                {"v_bytes", std::to_string(prefix_layout_.bytes_per_fa_layer_v)},
                {"mtp_k_bytes", std::to_string(prefix_layout_.bytes_per_mtp_layer_k)},
                {"mtp_v_bytes", std::to_string(prefix_layout_.bytes_per_mtp_layer_v)},
                {"hybrid_bytes", std::to_string(prefix_layout_.hybrid_device_state_bytes)},
            });
        return true;
    }

    bool DeviceGraphOrchestrator::preparePrefixArchivePayloadReady(
        PrefixBlockHandle *handle,
        void *producer_stream,
        const char *producer_name) const
    {
        if (!state_.device_id.is_gpu())
            return true;
        if (!handle || !handle->payload_readiness || !producer_stream)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Prefix archive readiness requires a GPU RAM handle and explicit stream");
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;
        const int ordinal = state_.device_id.gpu_ordinal();
        void *raw_event = backend->createEvent(ordinal);
        if (!raw_event)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to create prefix archive readiness event");
            return false;
        }
        std::shared_ptr<void> event(
            raw_event,
            [backend, ordinal](void *value)
            {
                if (value)
                    backend->destroyEvent(value, ordinal);
            });

        if (!handle->payload_readiness->prepare(
                std::move(event),
                state_.device_id,
                producer_stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to prepare prefix archive readiness event"
                      << " producer="
                      << (producer_name && producer_name[0] != '\0'
                              ? producer_name
                              : "unknown"));
            return false;
        }
        return true;
    }

    bool DeviceGraphOrchestrator::recordPrefixArchivePayloadReady(
        PrefixBlockHandle *handle,
        void *producer_stream,
        const char *producer_name) const
    {
        if (!state_.device_id.is_gpu())
            return true;
        if (!handle ||
            !handle->payload_readiness ||
            !handle->payload_readiness->prepared() ||
            !handle->payload_readiness->event() ||
            handle->payload_readiness->producerDevice() != state_.device_id ||
            handle->payload_readiness->producerStream() != producer_stream)
        {
            LOG_ERROR(
                "[DeviceGraphOrchestrator] Prefix archive completion reached "
                "commit without its exact preflighted event and stream");
            std::terminate();
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
        {
            LOG_ERROR(
                "[DeviceGraphOrchestrator] Prefix archive completion lost its "
                "GPU backend after asynchronous copies were submitted");
            std::terminate();
        }
        const int ordinal = state_.device_id.gpu_ordinal();
        if (!backend->recordEvent(
                handle->payload_readiness->event(),
                ordinal,
                producer_stream))
        {
            LOG_ERROR(
                "[DeviceGraphOrchestrator] Failed to record the preflighted "
                "prefix archive readiness event after asynchronous copies");
            std::terminate();
        }
        if (!handle->payload_readiness->publishRecorded())
        {
            LOG_ERROR(
                "[DeviceGraphOrchestrator] Failed to publish the recorded "
                "prefix archive readiness event");
            std::terminate();
        }

        PerfStatsCollector::addCounter(
            "prefix_cache",
            "archive_ready_events",
            1.0,
            "harvest",
            state_.device_id.toString(),
            {{"producer", producer_name && producer_name[0] != '\0'
                              ? producer_name
                              : "unknown"}});
        return true;
    }

    bool DeviceGraphOrchestrator::promotePrefixBlockToDeviceHotForRestore(
        const PrefixBlockHandle &lower_tier_handle,
        void *producer_stream,
        PrefixBlockHandle *promoted_handle)
    {
        auto fail = [&](const std::string &reason,
                        PrefixBlockHandle *prepared = nullptr) -> bool
        {
            if (prepared && prepared->valid() && prefix_device_hot_backend_)
            {
                /*
                 * release() retires backend budget accounting. The handle's
                 * shared allocation owners remain alive until their queued
                 * readiness event is complete, so exceptional cleanup cannot
                 * free storage still referenced by an asynchronous transfer.
                 */
                (void)prefix_device_hot_backend_->release(*prepared);
            }
            LOG_ERROR("[DeviceGraphOrchestrator] Device-hot prefix promotion failed: "
                      << reason
                      << " key=" << lower_tier_handle.key.toHex()
                      << " bytes=" << lower_tier_handle.total_bytes);
            return false;
        };

        if (!promoted_handle ||
            !state_.device_id.is_gpu() ||
            !producer_stream ||
            !prefix_cache_ ||
            !prefix_device_hot_backend_)
        {
            return fail("promotion dependencies are unavailable");
        }
        if (!lower_tier_handle.valid() ||
            lower_tier_handle.tier != PrefixStorageTier::Ram ||
            !prefix_cache_->deviceHotCapacityEligible(
                lower_tier_handle.total_bytes))
        {
            return fail("lower-tier handle is not eligible for the hot tier");
        }
        if (!lower_tier_handle.waitForPayloadOnStream(producer_stream))
        {
            return fail("lower-tier payload readiness wait failed");
        }

        PrefixBlockHandle prepared;
        if (!prefix_cache_->prepareDeviceHotCopy(
                lower_tier_handle,
                &prepared))
        {
            return fail("VRAM allocation or hot-tier LRU reservation failed");
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
        {
            return fail("GPU backend is unavailable", &prepared);
        }
        if (!preparePrefixArchivePayloadReady(
                &prepared,
                producer_stream,
                "restore_prefix_device_hot_promotion"))
        {
            return fail(
                "promotion readiness event preflight failed",
                &prepared);
        }
        const int ordinal = state_.device_id.gpu_ordinal();
        const auto upload_section =
            [&](const char *section,
                void *destination,
                const void *source,
                size_t bytes) -> bool
        {
            if (bytes == 0)
                return true;
            if (!destination || !source)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Device-hot promotion section "
                          << section << " has a null "
                          << (!destination ? "destination" : "source"));
                return false;
            }
            if (!backend->hostToDeviceOnStream(
                    destination,
                    source,
                    bytes,
                    ordinal,
                    producer_stream))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Device-hot promotion H2D failed "
                          "for section=" << section
                          << " bytes=" << bytes);
                return false;
            }
            return true;
        };

        /*
         * The RAM archive stores K followed by V in one allocation, and shifted
         * MTP K followed by V in another. Uploading each contiguous allocation
         * once avoids the old per-layer staging loop and leaves the promoted
         * handle immediately usable by every logical import operation.
         */
        bool uploaded =
            upload_section(
                "kv",
                prepared.deviceKVKData(),
                lower_tier_handle.kv_payload,
                lower_tier_handle.kvBytes()) &&
            upload_section(
                "mtp",
                prepared.deviceMTPKData(),
                lower_tier_handle.mtp_payload,
                lower_tier_handle.layout.mtpKVBytes());

        if (uploaded && lower_tier_handle.has_hybrid_state)
        {
            uploaded = upload_section(
                "hybrid",
                prepared.deviceHybridData(),
                lower_tier_handle.hybrid_payload,
                lower_tier_handle.hybridBytes());
        }
        if (uploaded && lower_tier_handle.has_terminal_hidden)
        {
            uploaded = upload_section(
                "terminal_hidden",
                prepared.deviceTerminalHiddenData(),
                lower_tier_handle.terminal_hidden,
                lower_tier_handle.terminalHiddenBytes());
        }
        if (uploaded && lower_tier_handle.has_terminal_logits)
        {
            uploaded = upload_section(
                "terminal_logits",
                prepared.deviceTerminalLogitsData(),
                lower_tier_handle.terminal_logits,
                lower_tier_handle.terminalLogitsBytes());
        }
        if (!uploaded)
        {
            return fail("one or more archive sections could not be uploaded",
                        &prepared);
        }

        if (!recordPrefixArchivePayloadReady(
                &prepared,
                producer_stream,
                "restore_prefix_device_hot_promotion"))
        {
            return fail("promotion readiness publication failed", &prepared);
        }
        if (!prefix_cache_->installDeviceHotCopy(
                prepared,
                /*repromotion=*/true))
        {
            return fail("completed replica could not enter the hot LRU",
                        &prepared);
        }

        PerfStatsCollector::addCounter(
            "prefix_cache",
            "device_hot_repromotions",
            1.0,
            "promotion",
            state_.device_id.toString(),
            {
                {"block", std::to_string(lower_tier_handle.key.block_index)},
                {"tokens", std::to_string(lower_tier_handle.key.token_count)},
                {"bytes", std::to_string(lower_tier_handle.total_bytes)},
                {"source", "ram_or_disk_hydration"},
            });
        *promoted_handle = std::move(prepared);
        return true;
    }

    bool DeviceGraphOrchestrator::ensurePrefixCacheReady()
    {
        if (!graph_builder_)
        {
            disablePrefixCacheForRunner("graph builder unavailable");
            return false;
        }

        const auto &config = graph_builder_->config();
        const auto &prefix_config = config.prefix_cache;
        if (prefix_cache_bypassed_)
        {
            return false;
        }
        if (prefix_cache_)
        {
            auto fingerprint = buildCurrentPrefixFingerprint(prefix_config);
            if (fingerprint.bypass || fingerprint.key == 0)
            {
                disablePrefixCacheForRunner(
                    fingerprint.bypass_reason.empty() ? "fingerprint refresh requested bypass"
                                                      : fingerprint.bypass_reason);
                return false;
            }
            if (fingerprint.key != prefix_fingerprint_)
            {
                LOG_DEBUG("[DeviceGraphOrchestrator] Prefix cache fingerprint refreshed for "
                          << graph_builder_->architectureName());
                prefix_fingerprint_ = fingerprint.key;
            }
            return true;
        }
        if (!prefix_config.enabled ||
            prefix_config.storage_mode == PrefixCacheStorageMode::Disabled)
        {
            disablePrefixCacheForRunner("feature disabled");
            return false;
        }
        if (prefix_config.storage_mode == PrefixCacheStorageMode::Device)
        {
            disablePrefixCacheForRunner("device-only prefix cache tier is not implemented yet");
            return false;
        }
        if (!state_.isInitialized() || !state_.kv_cache)
        {
            disablePrefixCacheForRunner("inference state or KV cache unavailable");
            return false;
        }
        if (!state_.pp_kv_caches.empty())
        {
            disablePrefixCacheForRunner("pipeline-parallel KV cache restore is not implemented yet");
            return false;
        }
        const int block_size = prefix_config.block_size > 0 ? prefix_config.block_size : 64;
        const bool terminal_state_enabled =
            prefix_config.terminal_state != PrefixCacheTerminalStateMode::Off;
        const bool owns_terminal_state =
            !pp_stage_config_.has_value() || pp_stage_config_->has_lm_head;
        const bool use_local_terminal_logits = activeMainLogitsAreColumnParallel();
        const auto *terminal_logits_tensor =
            use_local_terminal_logits ? state_.logits_local.get() : state_.logits.get();
        const size_t terminal_hidden_bytes =
            owns_terminal_state && config.mtp.enabled && terminal_state_enabled && state_.d_model > 0
                ? static_cast<size_t>(state_.d_model) * sizeof(float)
                : 0;
        const size_t terminal_logits_bytes =
            !terminal_state_enabled || !owns_terminal_state
                ? 0
                : fp32LogitsRowBytes(terminal_logits_tensor);

        prefix_layout_ = buildDensePrefixPayloadLayout(
            *state_.kv_cache,
            state_.device_id,
            block_size,
            terminal_hidden_bytes,
            terminal_logits_bytes);

        if (config.mtp.enabled)
        {
            if (state_.mtp_kv_caches.empty() || !state_.mtp_kv_caches[0])
            {
                disablePrefixCacheForRunner("MTP prefix cache requested without an initialized MTP KV cache");
                return false;
            }
            if (!attachMTPPayloadLayout(prefix_layout_, *state_.mtp_kv_caches[0]))
            {
                disablePrefixCacheForRunner("MTP KV cache does not expose a logical payload layout");
                return false;
            }
        }

        if (prefix_layout_.fa_layers <= 0 || prefix_layout_.faKVBytes() == 0)
        {
            disablePrefixCacheForRunner("KV cache does not expose a dense logical payload layout");
            return false;
        }
        if (!ensurePrefixArchiveDeviceStaging())
        {
            disablePrefixCacheForRunner("GPU prefix archive staging allocation failed");
            return false;
        }
        const size_t block_bytes = prefix_layout_.totalBytes();
        if (block_bytes == 0 || prefix_config.ram_budget_bytes < block_bytes)
        {
            disablePrefixCacheForRunner("RAM budget cannot hold one complete prefix block");
            return false;
        }

        auto fingerprint = buildCurrentPrefixFingerprint(prefix_config);
        if (fingerprint.bypass || fingerprint.key == 0)
        {
            disablePrefixCacheForRunner(
                fingerprint.bypass_reason.empty() ? "fingerprint build requested bypass"
                                                  : fingerprint.bypass_reason);
            return false;
        }

        prefix_fingerprint_ = fingerprint.key;
        prefix_ram_backend_ = std::make_shared<RamPrefixStorageBackend>(
            state_.device_id,
            prefix_config.ram_budget_bytes);
        prefix_device_hot_backend_.reset();
        if (prefix_config.storage_mode == PrefixCacheStorageMode::Tiered &&
            state_.device_id.is_gpu() &&
            prefix_config.device_budget_bytes >= block_bytes)
        {
            prefix_device_hot_backend_ = std::make_shared<DeviceHotPrefixStorageBackend>(
                state_.device_id,
                prefix_config.device_budget_bytes);
        }
        prefix_disk_backend_.reset();
        if (prefix_config.storage_mode == PrefixCacheStorageMode::Tiered &&
            prefix_config.disk_budget_bytes > 0)
        {
            if (prefix_config.disk_dir.empty())
            {
                disablePrefixCacheForRunner(
                    "disk prefix cache requested but HOME/default disk directory is unavailable");
                return false;
            }
            if (!injected_model_ctx_ || injected_model_ctx_->path().empty())
            {
                disablePrefixCacheForRunner(
                    "disk prefix cache requires a file-backed model context");
                return false;
            }

            std::string digest_error;
            const auto model_sha256 =
                sha256FileHex(injected_model_ctx_->path(), &digest_error);
            if (!model_sha256)
            {
                disablePrefixCacheForRunner(
                    "failed to content-address disk prefix cache: " +
                    digest_error);
                return false;
            }

            const std::filesystem::path archive_path =
                std::filesystem::path(prefix_config.disk_dir) /
                (*model_sha256 + ".kvcache");
            std::string archive_error;
            prefix_disk_backend_ = DiskPrefixStorageBackend::openShared(
                archive_path,
                prefix_config.disk_budget_bytes,
                *model_sha256,
                &archive_error);
            if (!prefix_disk_backend_)
            {
                disablePrefixCacheForRunner(
                    "failed to open disk prefix archive: " + archive_error);
                return false;
            }
        }
        prefix_cache_ = std::make_shared<PrefixStateCache>(
            prefix_config.ram_budget_bytes,
            prefix_ram_backend_,
            prefix_disk_backend_,
            prefix_device_hot_backend_);
        if (prefix_disk_backend_)
        {
            std::string discovery_error;
            if (!prefix_cache_->installDiscoveredDiskEntries(
                    prefix_fingerprint_,
                    prefix_layout_,
                    &discovery_error))
            {
                disablePrefixCacheForRunner(
                    "failed to index disk prefix archive: " +
                    discovery_error);
                return false;
            }
        }
        prefix_cache_bypassed_ = false;
        prefix_cache_bypass_reason_.clear();
        LOG_INFO("[DeviceGraphOrchestrator] Prefix cache enabled: block_size="
                 << prefix_layout_.block_size
                 << " block_bytes=" << block_bytes
                 << " ram_budget_bytes=" << prefix_config.ram_budget_bytes
                 << " device_hot_budget_bytes=" << (prefix_device_hot_backend_ ? prefix_config.device_budget_bytes : 0)
                 << " disk_budget_bytes=" << (prefix_disk_backend_ ? prefix_config.disk_budget_bytes : 0)
                 << " disk_archive="
                 << (prefix_disk_backend_
                         ? prefix_disk_backend_->archivePath().string()
                         : ""));
        return true;
    }

    bool DeviceGraphOrchestrator::refreshPrefixPayloadLayoutForLiveHybridState(const char *operation)
    {
        if (!prefix_cache_ || !state_.kv_cache)
        {
            return false;
        }
        if (!dynamic_cast<const IHybridKVCache *>(state_.kv_cache.get()))
        {
            return true;
        }

        const auto &graph_config = graph_builder_->config();
        PrefixPayloadLayout live_layout = buildDensePrefixPayloadLayout(
            *state_.kv_cache,
            state_.device_id,
            prefix_layout_.block_size,
            prefix_layout_.terminal_hidden_bytes,
            prefix_layout_.terminal_logits_bytes);
        copyMTPPayloadLayoutFields(prefix_layout_, live_layout);

        if (samePrefixPayloadShape(live_layout, prefix_layout_))
        {
            return true;
        }
        if (live_layout.fa_layers <= 0 || live_layout.faKVBytes() == 0)
        {
            disablePrefixCacheForRunner("live hybrid prefix layout does not expose restorable KV payloads");
            return false;
        }

        const auto &prefix_config = graph_config.prefix_cache;
        const size_t live_block_bytes = live_layout.totalBytes();
        if (live_block_bytes == 0 || prefix_config.ram_budget_bytes < live_block_bytes)
        {
            disablePrefixCacheForRunner("RAM budget cannot hold one live hybrid prefix block");
            return false;
        }

        const auto stats = prefix_cache_->stats();
        const bool has_cached_entries =
            prefix_cache_->size() > 0 ||
            stats.device_hot_bytes > 0 ||
            stats.disk_bytes > 0;
        if (has_cached_entries && !prefix_cache_->clear())
        {
            disablePrefixCacheForRunner("live hybrid prefix layout changed while entries were retained");
            return false;
        }

        LOG_INFO("[DeviceGraphOrchestrator] Prefix cache live hybrid layout refreshed"
                 << " operation=" << (operation ? operation : "<unknown>")
                 << " old_hybrid_host_bytes=" << prefix_layout_.hybrid_host_state_bytes
                 << " old_hybrid_device_bytes=" << prefix_layout_.hybrid_device_state_bytes
                 << " new_hybrid_host_bytes=" << live_layout.hybrid_host_state_bytes
                 << " new_hybrid_device_bytes=" << live_layout.hybrid_device_state_bytes
                 << " block_bytes=" << live_block_bytes
                 << " invalidated_entries=" << (has_cached_entries ? "yes" : "no"));
        prefix_layout_ = live_layout;
        if (!ensurePrefixArchiveDeviceStaging())
        {
            disablePrefixCacheForRunner("live hybrid GPU prefix archive staging resize failed");
            return false;
        }
        auto fingerprint = buildCurrentPrefixFingerprint(prefix_config);
        if (fingerprint.bypass || fingerprint.key == 0)
        {
            disablePrefixCacheForRunner(
                fingerprint.bypass_reason.empty() ? "live hybrid fingerprint refresh requested bypass"
                                                  : fingerprint.bypass_reason);
            return false;
        }
        if (fingerprint.key != prefix_fingerprint_)
        {
            LOG_DEBUG("[DeviceGraphOrchestrator] Prefix cache fingerprint refreshed after live hybrid layout update for "
                      << graph_builder_->architectureName()
                      << " fingerprint=" << prefixHashHex(fingerprint.key));
            prefix_fingerprint_ = fingerprint.key;
        }
        return true;
    }

    PrefixCacheKey DeviceGraphOrchestrator::makePrefixKeyForBlock(
        const std::vector<int32_t> &tokens,
        int block_index,
        uint64_t parent_hash) const
    {
        const int start = block_index * prefix_layout_.block_size;
        const int end = std::min<int>(start + prefix_layout_.block_size, tokens.size());
        std::vector<int32_t> block_tokens(tokens.begin() + start, tokens.begin() + end);
        return makePrefixCacheKey(prefix_fingerprint_, parent_hash, block_index, start, block_tokens);
    }

    PrefixLookupResult DeviceGraphOrchestrator::lookupPrefix(const std::vector<int32_t> &tokens)
    {
        PrefixLookupResult result;
        result.cache_enabled = graph_builder_ && graph_builder_->config().prefix_cache.enabled;

        if (!ensurePrefixCacheReady())
        {
            result.bypass_reason = prefix_cache_bypass_reason_;
            return result;
        }

        result.supported = true;
        result.block_size = prefix_layout_.block_size;
        result.fingerprint_key = prefix_fingerprint_;
        result.placement_epoch = moeRuntimeMovementEpoch();
        result.requires_terminal_logits = prefix_layout_.includes_terminal_logits;
        result.requires_terminal_hidden = prefix_layout_.includes_terminal_hidden;
        if (tokens.empty() || prefix_layout_.block_size <= 0)
        {
            return result;
        }

        const int complete_blocks =
            (static_cast<int>(tokens.size()) + prefix_layout_.block_size - 1) /
            prefix_layout_.block_size;
        uint64_t parent_hash = 0;
        for (int block = 0; block < complete_blocks; ++block)
        {
            PrefixCacheKey key = makePrefixKeyForBlock(tokens, block, parent_hash);
            auto handle = prefix_cache_->find(key);
            if (!handle || !handle->layout.compatiblePayloadShape(prefix_layout_))
            {
                PerfStatsCollector::addCounter(
                    "prefix_cache",
                    "block_misses",
                    1.0,
                    "lookup",
                    state_.device_id.toString(),
                    {
                        {"block", std::to_string(block)},
                        {"prompt_tokens", std::to_string(tokens.size())},
                        {"handle_present", handle ? "true" : "false"},
                        {"shape_compatible", (handle && handle->layout.compatiblePayloadShape(prefix_layout_)) ? "true" : "false"},
                    });
                if (prefixCacheTraceEnabled())
                {
                    LOG_INFO("[PREFIX_TRACE] lookup miss device=" << state_.device_id.toString()
                                                                  << " block=" << block
                                                                  << " key=" << key.toHex()
                                                                  << " fingerprint="
                                                                  << prefixHashHex(prefix_fingerprint_)
                                                                  << " handle="
                                                                  << (handle ? "present" : "absent")
                                                                  << " shape_compatible="
                                                                  << (handle && handle->layout.compatiblePayloadShape(prefix_layout_) ? "yes" : "no"));
                }
                break;
            }

            PerfStatsCollector::addCounter(
                "prefix_cache",
                "block_hits",
                1.0,
                "lookup",
                state_.device_id.toString(),
                {
                    {"block", std::to_string(block)},
                    {"prompt_tokens", std::to_string(tokens.size())},
                    {"token_count", std::to_string(handle->key.token_count)},
                    {"terminal_logits", handle->has_terminal_logits ? "true" : "false"},
                    {"terminal_hidden", handle->has_terminal_hidden ? "true" : "false"},
                    {"includes_mtp_state", handle->layout.includes_mtp_state ? "true" : "false"},
                    {"model_runtime_state", handle->has_model_runtime_state ? "true" : "false"},
                });
            if (prefixCacheTraceEnabled())
            {
                LOG_INFO("[PREFIX_TRACE] lookup hit device=" << state_.device_id.toString()
                                                             << " block=" << block
                                                             << " key=" << key.toHex()
                                                             << " token_count=" << handle->key.token_count
                                                             << " terminal_logits="
                                                             << (handle->has_terminal_logits ? "yes" : "no")
                                                             << " terminal_hidden="
                                                             << (handle->has_terminal_hidden ? "yes" : "no")
                                                             << " mtp_state="
                                                             << (handle->layout.includes_mtp_state ? "yes" : "no")
                                                             << " model_runtime_state="
                                                             << (handle->has_model_runtime_state ? "yes" : "no")
                                                             << " model_runtime_state_bytes="
                                                             << (handle->model_runtime_state_storage
                                                                     ? handle->model_runtime_state_storage->size()
                                                                     : 0u));
            }
            result.blocks.push_back(*handle);
            result.cached_tokens += handle->key.token_count;
            result.has_terminal_hidden = handle->has_terminal_hidden;
            result.has_terminal_logits = handle->has_terminal_logits;
            parent_hash = key.stableHash();
        }

        while (!result.blocks.empty() &&
               prefix_layout_.includes_hybrid_state &&
               !result.blocks.back().has_hybrid_state)
        {
            result.blocks.pop_back();
            result.cached_tokens = result.blocks.empty()
                                       ? 0
                                       : result.blocks.back().key.token_start +
                                             result.blocks.back().key.token_count;
            result.has_terminal_hidden =
                !result.blocks.empty() && result.blocks.back().has_terminal_hidden;
            result.has_terminal_logits =
                !result.blocks.empty() && result.blocks.back().has_terminal_logits;
        }

        prefix_cache_->recordRequestLookup(
            static_cast<int>(tokens.size()),
            result.cached_tokens,
            static_cast<int>(result.blocks.size()));
        PerfStatsCollector::addCounter(
            "prefix_cache",
            "lookup_results",
            1.0,
            "lookup",
            state_.device_id.toString(),
            {
                {"prompt_tokens", std::to_string(tokens.size())},
                {"cached_tokens", std::to_string(result.cached_tokens)},
                {"blocks", std::to_string(result.blocks.size())},
                {"hit_type", result.cached_tokens <= 0
                                 ? "miss"
                                 : (result.cached_tokens >= static_cast<int>(tokens.size()) ? "full" : "partial")},
                {"terminal_logits", result.has_terminal_logits ? "true" : "false"},
                {"terminal_hidden", result.has_terminal_hidden ? "true" : "false"},
            });

        if (prefixCacheTraceEnabled())
        {
            LOG_INFO("[PREFIX_TRACE] lookup result device=" << state_.device_id.toString()
                                                            << " cached_tokens=" << result.cached_tokens
                                                            << " blocks=" << result.blocks.size()
                                                            << " terminal_logits="
                                                            << (result.has_terminal_logits ? "yes" : "no")
                                                            << " terminal_hidden="
                                                            << (result.has_terminal_hidden ? "yes" : "no")
                                                            << " fingerprint="
                                                            << prefixHashHex(prefix_fingerprint_));
        }

        return result;
    }

    bool DeviceGraphOrchestrator::populatePrefix(const PrefixLookupResult &hit, int seq_idx)
    {
        auto fail = [](const std::string &reason) -> bool
        {
            LOG_ERROR("[DeviceGraphOrchestrator] populatePrefix failed: " << reason);
            return false;
        };

        if (hit.cached_tokens <= 0)
        {
            return true;
        }
        if (!ensurePrefixCacheReady() || !state_.kv_cache)
        {
            return fail("prefix cache or KV cache is not ready");
        }
        if (seq_idx < 0 || seq_idx >= state_.batch_size)
        {
            return fail("sequence index out of range");
        }
        if (hit.blocks.empty())
        {
            return fail("prefix hit has no blocks");
        }

        void *stream = explicitGPUStreamForOperation("populatePrefix");
        if (state_.device_id.is_gpu() && !stream)
        {
            return fail("missing explicit GPU stream");
        }
        if (!waitForPendingLivePrefixMutationReady(
                stream,
                "populate_prefix_previous_mutation"))
        {
            return fail("pending live prefix mutation wait failed");
        }
        if (!waitForPendingLiveGraphProducersBeforePrefixMutation(
                stream,
                "populate_prefix"))
        {
            return fail("pending live graph producer wait failed");
        }

        const auto &terminal_block = hit.blocks.back();
        const bool restore_model_runtime_state =
            hit.restore_model_runtime_state &&
            terminal_block.has_model_runtime_state &&
            terminal_block.model_runtime_state_storage &&
            !terminal_block.model_runtime_state_storage->empty();
        /*
         * A prefix restore is not an overlay on top of the current request; it is
         * a complete replacement of live sequence state.  Decode may have warmed
         * graph replay, kernel dynamic buffers, token mailboxes, sampled-logit
         * streams, or model-local scratch that remains valid for ordinary
         * request resets but is stale for a restored prefix followed by suffix
         * prefill.  Reset inference-owned state after ordering earlier
         * producers, then import the snapshot into a clean live-state
         * transaction.  If a model-runtime snapshot is present, the typed
         * reset deliberately leaves the graph-owned model-runtime owner for
         * the restore call below; otherwise it resets that owner here so a
         * missing snapshot cannot silently reuse stale MoE placement state.
         */
        try
        {
            resetInferenceState(
                InferenceStateResetRequest::prefixRestoreBoundary(
                    "populate_prefix_cache",
                    /*reset_model_runtime_owner=*/!restore_model_runtime_state));
        }
        catch (const std::exception &ex)
        {
            return fail(std::string("prefix restore state reset failed: ") + ex.what());
        }
        stream = explicitGPUStreamForOperation("populatePrefix");
        if (state_.device_id.is_gpu() && !stream)
        {
            return fail("missing explicit GPU stream after prefix restore reset");
        }
        if (!waitForPendingRequestStateReset(
                stream,
                DeviceTimelineRole::PrefixRestoreMutation,
                "populate_prefix_request_state_reset"))
        {
            return fail("prefix restore could not consume request-state reset");
        }
        IBackend *prefix_backend =
            state_.device_id.is_gpu() ? getBackendFor(state_.device_id) : nullptr;
        if (state_.device_id.is_gpu() &&
            (!prefix_backend || !prefix_archive_device_staging_))
        {
            return fail("GPU prefix archive staging is unavailable");
        }
        if (!prepareLivePrefixMutationReadyEvent(
                stream,
                "populate_prefix_cache"))
        {
            return fail("could not preflight live-state readiness event");
        }

        /*
         * A lookup result owns the tier that was resident when lookup ran. Cold
         * GPU hits are promoted before live-state import so every subsequent
         * operation in this transaction consumes the same device-owned bytes.
         * Blocks larger than the entire configured hot tier are intentionally
         * restored from RAM; an eligible promotion failure is never hidden.
         */
        std::vector<PrefixBlockHandle> restore_blocks = hit.blocks;
        if (state_.device_id.is_gpu())
        {
            for (PrefixBlockHandle &handle : restore_blocks)
            {
                if (handle.tier == PrefixStorageTier::DeviceHot ||
                    !prefix_cache_->deviceHotCapacityEligible(
                        handle.total_bytes))
                {
                    continue;
                }

                PrefixBlockHandle promoted;
                if (!promotePrefixBlockToDeviceHotForRestore(
                        handle,
                        stream,
                        &promoted))
                {
                    return fail("eligible lower-tier block could not be promoted");
                }
                handle = std::move(promoted);
            }
        }

        if (restore_model_runtime_state)
        {
            if (prefixCacheTraceEnabled())
            {
                LOG_INFO("[PREFIX_TRACE] restore model-runtime-state device="
                         << state_.device_id.toString()
                         << " cached_tokens=" << hit.cached_tokens
                         << " bytes=" << terminal_block.model_runtime_state_storage->size());
            }
            if (!graph_builder_ ||
                !graph_builder_->restorePrefixCacheRuntimeState(
                    *terminal_block.model_runtime_state_storage,
                    stream))
            {
                return fail("model runtime state restore failed");
            }
            const bool device_rehydration_pending =
                graph_builder_->
                    prefixCacheRuntimeStateRequiresDeviceRehydration();
            LOG_INFO("[DeviceGraphOrchestrator] Adopted prefix-runtime restore "
                     "transaction"
                     << " device=" << state_.device_id.toString()
                     << " cached_tokens=" << hit.cached_tokens
                     << " device_payload_rehydration="
                     << (device_rehydration_pending
                             ? "pending"
                             : "not_required"));
            ++moe_runtime_movement_epoch_;
            PerfStatsCollector::addCounter(
                "prefix_cache",
                "model_runtime_state_restores",
                1.0,
                "prefix_cache",
                state_.device_id.toString(),
                {{"cached_tokens", std::to_string(hit.cached_tokens)}});
        }

        for (const auto &handle : restore_blocks)
        {
            const bool device_hot =
                handle.tier == PrefixStorageTier::DeviceHot;
            if (!handle.valid() || !handle.layout.compatiblePayloadShape(prefix_layout_) ||
                (device_hot
                     ? (!handle.deviceKVKData() ||
                        !handle.deviceKVVData())
                     : (!handle.kvKData() || !handle.kvVData())))
            {
                return fail("prefix block handle is invalid or layout-incompatible");
            }
            if (state_.device_id.is_gpu() &&
                !handle.waitForPayloadOnStream(stream))
            {
                return fail("prefix block archive readiness wait failed");
            }

            for (int local_layer = 0; local_layer < prefix_layout_.fa_layers; ++local_layer)
            {
                const int global_layer = prefixFALayerForIndex(*state_.kv_cache, local_layer);
                if (global_layer < 0)
                {
                    return fail("prefix full-attention layer index is invalid");
                }
                const auto block_payload_layout =
                    state_.kv_cache->logicalBlockLayout(global_layer, handle.key.token_count);
                if (block_payload_layout.k_bytes > prefix_layout_.bytes_per_fa_layer_k ||
                    block_payload_layout.v_bytes > prefix_layout_.bytes_per_fa_layer_v)
                {
                    return fail("prefix block payload layout exceeds per-layer storage stride");
                }
                const uint8_t *k_src =
                    (device_hot ? handle.deviceKVKData()
                                : handle.kvKData()) +
                    static_cast<size_t>(local_layer) *
                        prefix_layout_.bytes_per_fa_layer_k;
                const uint8_t *v_src =
                    (device_hot ? handle.deviceKVVData()
                                : handle.kvVData()) +
                    static_cast<size_t>(local_layer) *
                        prefix_layout_.bytes_per_fa_layer_v;
                IKVCache::KVCacheLogicalBlockDescriptor desc;
                desc.layer = global_layer;
                desc.seq_idx = seq_idx;
                desc.logical_token_start = handle.key.token_start;
                desc.token_count = handle.key.token_count;
                desc.stream = stream;
                const bool trace_payload_hash =
                    shouldTracePrefixPayloadHash(handle.key, global_layer);
                if (trace_payload_hash && !device_hot)
                {
                    logPrefixPayloadHashTrace(
                        "populate_import_payload",
                        state_.device_id,
                        handle.key,
                        global_layer,
                        local_layer,
                        k_src,
                        block_payload_layout.k_bytes,
                        v_src,
                        block_payload_layout.v_bytes);
                }
                bool imported = false;
                if (state_.device_id.is_gpu())
                {
                    desc.payload_domain =
                        IKVCache::KVCacheLogicalBlockPayloadDomain::Device;
                    if (device_hot)
                    {
                        imported =
                            state_.kv_cache->importLogicalBlock(
                                desc,
                                k_src,
                                v_src);
                    }
                    else
                    {
                        void *k_staging =
                            prefix_archive_device_staging_->k.devicePtr();
                        void *v_staging =
                            prefix_archive_device_staging_->v.devicePtr();
                        if (!k_staging || !v_staging ||
                            !prefix_backend->hostToDeviceOnStream(
                                k_staging,
                                k_src,
                                block_payload_layout.k_bytes,
                                state_.device_id.gpu_ordinal(),
                                stream) ||
                            !prefix_backend->hostToDeviceOnStream(
                                v_staging,
                                v_src,
                                block_payload_layout.v_bytes,
                                state_.device_id.gpu_ordinal(),
                                stream))
                        {
                            return fail("main KV logical block H2D staging failed");
                        }
                        imported =
                            state_.kv_cache->importLogicalBlock(
                                desc,
                                k_staging,
                                v_staging);
                    }
                }
                else
                {
                    imported =
                        state_.kv_cache->importLogicalBlock(desc, k_src, v_src);
                }
                if (!imported)
                {
                    return fail("main KV logical block import failed");
                }
                if (trace_payload_hash && !device_hot)
                {
                    std::vector<uint8_t> live_k(block_payload_layout.k_bytes, 0);
                    std::vector<uint8_t> live_v(block_payload_layout.v_bytes, 0);
                    auto trace_desc = desc;
                    trace_desc.payload_domain =
                        IKVCache::KVCacheLogicalBlockPayloadDomain::Host;
                    if (!state_.kv_cache->exportLogicalBlock(
                            trace_desc,
                            live_k.empty() ? nullptr : live_k.data(),
                            live_v.empty() ? nullptr : live_v.data()))
                    {
                        return fail("main KV logical block post-import export failed");
                    }
                    logPrefixPayloadHashTrace(
                        "populate_import_live",
                        state_.device_id,
                        handle.key,
                        global_layer,
                        local_layer,
                        live_k.empty() ? nullptr : live_k.data(),
                        live_k.size(),
                        live_v.empty() ? nullptr : live_v.data(),
                        live_v.size());
                }
            }

            if (device_hot)
            {
                PerfStatsCollector::addCounter(
                    "prefix_cache",
                    "device_hot_direct_kv_restores",
                    1.0,
                    "restore",
                    state_.device_id.toString(),
                    {
                        {"block", std::to_string(handle.key.block_index)},
                        {"tokens", std::to_string(handle.key.token_count)},
                        {"layers", std::to_string(prefix_layout_.fa_layers)},
                    });
            }

            if (prefix_layout_.includes_mtp_state)
            {
                if (state_.mtp_kv_caches.empty() || !state_.mtp_kv_caches[0])
                {
                    return fail("prefix hit contains MTP state but runner has no MTP KV cache");
                }
                if (!importMTPPrefixPayload(
                        *state_.mtp_kv_caches[0],
                        seq_idx,
                        handle,
                        stream,
                        state_.device_id.is_gpu()
                            ? prefix_archive_device_staging_->mtp_k.devicePtr()
                            : nullptr,
                        state_.device_id.is_gpu()
                            ? prefix_archive_device_staging_->mtp_v.devicePtr()
                            : nullptr,
                        prefix_backend,
                        state_.device_id))
                {
                    return fail("MTP prefix payload import failed");
                }
                if (device_hot)
                {
                    PerfStatsCollector::addCounter(
                        "prefix_cache",
                        "device_hot_direct_mtp_restores",
                        1.0,
                        "restore",
                        state_.device_id.toString(),
                        {
                            {"block", std::to_string(handle.key.block_index)},
                            {"tokens", std::to_string(handle.key.token_count)},
                        });
                }
            }
        }

        bool hybrid_imported = true;
        if (prefix_layout_.includes_hybrid_state)
        {
            const PrefixBlockHandle &terminal_handle = restore_blocks.back();
            if (state_.device_id.is_gpu())
            {
                auto *hybrid =
                    dynamic_cast<IHybridKVCache *>(state_.kv_cache.get());
                const bool terminal_device_hot =
                    terminal_handle.tier == PrefixStorageTier::DeviceHot;
                void *hybrid_staging =
                    terminal_device_hot
                        ? const_cast<void *>(
                              terminal_handle.deviceHybridData())
                        : prefix_archive_device_staging_->hybrid.devicePtr();
                if (!hybrid || !terminal_handle.has_hybrid_state ||
                    terminal_handle.layout.hybrid_host_state_bytes != 0 ||
                    terminal_handle.layout.hybrid_device_state_bytes == 0 ||
                    !hybrid_staging ||
                    (!terminal_device_hot &&
                     (!terminal_handle.hybrid_payload ||
                      !prefix_backend->hostToDeviceOnStream(
                          hybrid_staging,
                          terminal_handle.hybrid_payload,
                          terminal_handle.layout.hybrid_device_state_bytes,
                          state_.device_id.gpu_ordinal(),
                          stream))))
                {
                    hybrid_imported = false;
                }
                else
                {
                    HybridPrefixStateDescriptor desc;
                    desc.seq_idx = seq_idx;
                    desc.logical_token_count =
                        terminal_handle.key.token_start +
                        terminal_handle.key.token_count;
                    desc.stream = stream;
                    desc.synchronize = false;
                    desc.include_host_state = false;
                    desc.include_device_state = true;
                    hybrid_imported = hybrid->importHybridPrefixState(
                        desc,
                        nullptr,
                        hybrid_staging);
                }
            }
            else
            {
                hybrid_imported = importHybridPrefixPayload(
                    *state_.kv_cache,
                    terminal_handle,
                    seq_idx,
                    hit.restore_hybrid_state_for_suffix_prefill,
                    /*synchronize=*/true,
                    stream);
            }
        }
        if (!hybrid_imported)
        {
            return fail("hybrid prefix payload import failed");
        }
        if (prefix_layout_.includes_hybrid_state &&
            restore_blocks.back().tier == PrefixStorageTier::DeviceHot)
        {
            PerfStatsCollector::addCounter(
                "prefix_cache",
                "device_hot_direct_hybrid_restores",
                1.0,
                "restore",
                state_.device_id.toString(),
                {{"bytes", std::to_string(
                               restore_blocks.back().layout.hybrid_device_state_bytes)}});
        }

        if (graph_builder_ && graph_builder_->config().mtp.enabled &&
            hit.has_terminal_hidden &&
            restore_blocks.back().has_terminal_hidden &&
            (restore_blocks.back().terminal_hidden ||
             restore_blocks.back().deviceTerminalHiddenData()))
        {
            if (!ensureMTPTerminalHiddenBuffer())
                return fail("terminal hidden buffer allocation failed");
            if (!state_.prefix_terminal_hidden ||
                prefix_layout_.terminal_hidden_bytes == 0)
                return fail("terminal hidden destination is unavailable");
            if (state_.device_id.is_gpu())
            {
                if (!state_.prefix_terminal_hidden->gpu_data_ptr() &&
                    !state_.prefix_terminal_hidden->allocateOnDevice(
                        state_.device_id,
                        stream))
                {
                    return fail("terminal hidden device allocation failed");
                }
                void *hidden_device =
                    state_.prefix_terminal_hidden->gpu_data_ptr();
                const bool terminal_device_hot =
                    restore_blocks.back().tier ==
                    PrefixStorageTier::DeviceHot;
                const void *hidden_source =
                    terminal_device_hot
                        ? restore_blocks.back().deviceTerminalHiddenData()
                        : restore_blocks.back().terminal_hidden;
                if (!hidden_device || !hidden_source ||
                    !(terminal_device_hot
                          ? prefix_backend->deviceCopyAsync(
                                hidden_device,
                                hidden_source,
                                prefix_layout_.terminal_hidden_bytes,
                                state_.device_id.gpu_ordinal(),
                                stream)
                          : prefix_backend->hostToDeviceOnStream(
                                hidden_device,
                                hidden_source,
                                prefix_layout_.terminal_hidden_bytes,
                                state_.device_id.gpu_ordinal(),
                                stream)))
                {
                    return fail("terminal hidden device restore failed");
                }
                TransferEngine::publishDeviceWrite(
                    state_.prefix_terminal_hidden.get(),
                    state_.device_id,
                    stream);
            }
            else
            {
                void *hidden_host =
                    state_.prefix_terminal_hidden->raw_mutable_data();
                if (!hidden_host)
                    return fail("terminal hidden host destination is unavailable");
                std::memcpy(
                    hidden_host,
                    restore_blocks.back().terminal_hidden,
                    prefix_layout_.terminal_hidden_bytes);
                TransferEngine::publishHostWrite(
                    state_.prefix_terminal_hidden.get());
            }
            state_.mtp_terminal_hidden_current = true;
            if (arena_ && arena_->isRegistered(BufferId::PREFIX_TERMINAL_HIDDEN))
            {
                arena_->markWrittenFlagsOnly(
                    BufferId::PREFIX_TERMINAL_HIDDEN,
                    state_.device_id.is_gpu() ? state_.device_id : DeviceId::cpu());
            }
            if (restore_blocks.back().tier == PrefixStorageTier::DeviceHot)
            {
                PerfStatsCollector::addCounter(
                    "prefix_cache",
                    "device_hot_direct_terminal_hidden_restores",
                    1.0,
                    "restore",
                    state_.device_id.toString(),
                    {{"bytes", std::to_string(
                                   prefix_layout_.terminal_hidden_bytes)}});
            }
        }

        state_.positions[seq_idx] = hit.cached_tokens;
        state_.sequence_lengths[seq_idx] = hit.cached_tokens;
        handleLivePrefixReplayStateAfterMutation(
            LivePrefixMutationReason::PrefixRestore,
            "populate_prefix_cache");

        /*
         * Every GPU import above is asynchronous. Transfer the copied handles
         * into the mutation event instead of leasing cache metadata: eviction
         * may proceed immediately, while the underlying RAM/VRAM allocations
         * remain alive until the final restore operation completes.
         */
        std::vector<PrefixBlockHandle> retained_restore_sources;
        if (state_.device_id.is_gpu())
        {
            /*
             * The immutable lookup handles own lower-tier sources used while a
             * block is promoted. The working handles own the promoted sources
             * used by the final restore. Retain both sets through one event;
             * duplicate shared owners are cheap and keep this transaction
             * correct whether each block was promoted or restored in place.
             */
            retained_restore_sources = hit.blocks;
            for (auto &source : restore_blocks)
                retained_restore_sources.push_back(std::move(source));
        }
        if (!recordLivePrefixMutationReady(
                stream,
                "populate_prefix_cache",
                std::move(retained_restore_sources)))
        {
            return fail("could not record live-state readiness");
        }
        PerfStatsCollector::addCounter(
            "prefix_cache",
            "populate_restores",
            1.0,
            "restore",
            state_.device_id.toString(),
            {
                {"cached_tokens", std::to_string(hit.cached_tokens)},
                {"blocks", std::to_string(hit.blocks.size())},
                {"includes_hybrid_state", prefix_layout_.includes_hybrid_state ? "true" : "false"},
                {"includes_mtp_state", prefix_layout_.includes_mtp_state ? "true" : "false"},
                {"terminal_logits", hit.has_terminal_logits ? "true" : "false"},
                {"terminal_hidden", hit.has_terminal_hidden ? "true" : "false"},
                {"model_runtime_state", restore_model_runtime_state ? "true" : "false"},
            });
        return true;
    }

    bool DeviceGraphOrchestrator::restorePrefixTerminalState(const PrefixLookupResult &hit)
    {
        void *terminal_restore_stream = nullptr;
        TensorBase *terminal_logits_tensor =
            activeMainLogitsAreColumnParallel() ? state_.logits_local.get() : state_.logits.get();
        const BufferId terminal_logits_buffer_id =
            terminal_logits_tensor == state_.logits_local.get() ? BufferId::LOGITS_LOCAL : BufferId::LOGITS;

        if (!prefix_layout_.includes_terminal_logits ||
            prefix_layout_.terminal_logits_bytes == 0)
        {
            return true;
        }
        if (!hit.has_terminal_logits || hit.blocks.empty() || !terminal_logits_tensor)
        {
            return false;
        }

        PrefixBlockHandle terminal = hit.blocks.back();
        if (state_.device_id.is_gpu() &&
            prefix_cache_ &&
            terminal.tier != PrefixStorageTier::DeviceHot)
        {
            /*
             * populatePrefix() may have promoted this lower-tier block after
             * the immutable lookup result was assembled. Resolve the installed
             * hot owner so terminal logits and hidden state reuse the same VRAM
             * archive instead of issuing a second H2D transfer.
             */
            if (auto promoted =
                    prefix_cache_->deviceHotCopy(terminal.key))
            {
                terminal = std::move(*promoted);
            }
        }
        if (!terminal.has_terminal_logits ||
            (!terminal.terminal_logits &&
             !terminal.deviceTerminalLogitsData()))
        {
            return false;
        }

        if (fp32LogitsRowBytes(terminal_logits_tensor) < prefix_layout_.terminal_logits_bytes)
        {
            return false;
        }

        if (state_.device_id.is_gpu())
        {
            terminal_restore_stream =
                explicitGPUStreamForOperation("restorePrefixTerminalState");
            if (!terminal_restore_stream)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to upload restored prefix terminal logits: "
                          "missing explicit GPU stream");
                return false;
            }
            if (!prepareLivePrefixMutationReadyEvent(
                    terminal_restore_stream,
                    "restore_prefix_terminal_state"))
            {
                LOG_ERROR(
                    "[DeviceGraphOrchestrator] Failed to preflight restored "
                    "prefix terminal-state completion event");
                return false;
            }
            if (!terminal.waitForPayloadOnStream(terminal_restore_stream))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to upload restored prefix terminal logits: "
                          "archive readiness wait failed");
                return false;
            }
            if (!terminal_logits_tensor->gpu_data_ptr() &&
                !terminal_logits_tensor->allocateOnDevice(
                    state_.device_id,
                    terminal_restore_stream))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to allocate restored prefix terminal logits");
                return false;
            }
            IBackend *backend = getBackendFor(state_.device_id);
            const bool device_hot =
                terminal.tier == PrefixStorageTier::DeviceHot;
            const void *logits_source =
                device_hot
                    ? terminal.deviceTerminalLogitsData()
                    : terminal.terminal_logits;
            if (!backend || !logits_source ||
                !(device_hot
                      ? backend->deviceCopyAsync(
                            terminal_logits_tensor->gpu_data_ptr(),
                            logits_source,
                            prefix_layout_.terminal_logits_bytes,
                            state_.device_id.gpu_ordinal(),
                            terminal_restore_stream)
                      : backend->hostToDeviceOnStream(
                            terminal_logits_tensor->gpu_data_ptr(),
                            logits_source,
                            prefix_layout_.terminal_logits_bytes,
                            state_.device_id.gpu_ordinal(),
                            terminal_restore_stream)))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to submit restored prefix terminal logits device copy");
                return false;
            }
            TransferEngine::publishDeviceWrite(
                terminal_logits_tensor,
                state_.device_id,
                terminal_restore_stream);
            if (device_hot)
            {
                PerfStatsCollector::addCounter(
                    "prefix_cache",
                    "device_hot_direct_terminal_logits_restores",
                    1.0,
                    "restore",
                    state_.device_id.toString(),
                    {{"bytes", std::to_string(
                                   prefix_layout_.terminal_logits_bytes)}});
            }
        }
        else
        {
            void *dst = terminal_logits_tensor->raw_mutable_data();
            if (!dst)
            {
                return false;
            }
            std::memcpy(
                dst,
                terminal.terminal_logits,
                prefix_layout_.terminal_logits_bytes);
            TransferEngine::publishHostWrite(terminal_logits_tensor);
        }
        if (arena_ && arena_->isRegistered(terminal_logits_buffer_id))
        {
            arena_->markWrittenFlagsOnly(
                terminal_logits_buffer_id,
                state_.device_id.is_gpu() ? state_.device_id : DeviceId::cpu());
        }

        if (terminal_logits_tensor == state_.logits_local.get() &&
            state_.device_id.is_cpu() &&
            state_.logits &&
            mpi_ctx_ &&
            mpi_ctx_->world_size() > 1)
        {
            /*
             * Global/NodeLocal TP stores the authoritative terminal prefix row
             * as one column-parallel LOGITS_LOCAL shard per MPI participant.
             * The normal forward graph immediately follows LM_HEAD_LOCAL with
             * `lm_head_allgather`, so CPU stochastic sampling reads the complete
             * row from LOGITS. A prefix restore must reproduce that same graph
             * boundary before advertising terminal logits as ready.
             *
             * Without this compact one-row collective, LOGITS retains the last
             * decode row from the previous request. The restored KV, hidden,
             * and local logit shard are all correct, but the first MTP target
             * sample is taken from stale full-vocabulary bytes. Execute the
             * existing AllGatherStage contract for exactly one row; this is the
             * same grouped collective used by production forward, not serial
             * row replay and not an ad hoc host reconstruction.
             *
             * GPU restores intentionally do not enter this host-visible path.
             * GPU LocalTP uses mirrored device-owned heads, while supported GPU
             * GlobalTP sampling coordinates resident shard candidates.
             */
            AllGatherStage::Params gather_params;
            gather_params.device_id = DeviceId::cpu();
            gather_params.mpi_ctx = mpi_ctx_.get();
            gather_params.local_input = state_.logits_local.get();
            gather_params.full_output = state_.logits.get();
            gather_params.actual_seq_len = 1;
            gather_params.input_buffer_id = BufferId::LOGITS_LOCAL;
            gather_params.output_buffer_id = BufferId::LOGITS;

            AllGatherStage gather_stage(std::move(gather_params));
            if (!gather_stage.execute(/*ctx=*/nullptr))
            {
                LOG_ERROR(
                    "[DeviceGraphOrchestrator] Failed to rebuild the CPU "
                    "GlobalTP full-vocabulary terminal row after prefix restore");
                return false;
            }
            TransferEngine::publishHostWrite(state_.logits.get());
            if (arena_ && arena_->isRegistered(BufferId::LOGITS))
            {
                arena_->markWrittenFlagsOnly(
                    BufferId::LOGITS,
                    DeviceId::cpu());
            }
            PerfStatsCollector::addCounter(
                "prefix_cache",
                "cpu_global_tp_terminal_logits_allgathers",
                1.0,
                "restore",
                state_.device_id.toString(),
                {{"cached_tokens", std::to_string(hit.cached_tokens)},
                 {"rows", "1"},
                 {"participants", std::to_string(mpi_ctx_->world_size())},
                 {"source", "restored_logits_local"},
                 {"destination", "logits"}});
        }
        if (prefix_cache_)
        {
            prefix_cache_->recordTerminalStateHit();
        }

        if (graph_builder_ && graph_builder_->config().mtp.enabled &&
            terminal.has_terminal_hidden &&
            (terminal.terminal_hidden ||
             terminal.deviceTerminalHiddenData()))
        {
            if (!ensureMTPTerminalHiddenBuffer())
                return false;
            if (!state_.prefix_terminal_hidden ||
                prefix_layout_.terminal_hidden_bytes == 0)
                return false;
            if (state_.device_id.is_gpu())
            {
                if (!terminal_restore_stream)
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Failed to upload restored prefix terminal hidden: "
                              "missing explicit GPU stream");
                    return false;
                }
                if (!terminal.waitForPayloadOnStream(terminal_restore_stream))
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Failed to upload restored prefix terminal hidden: "
                              "archive readiness wait failed");
                    return false;
                }
                if (!state_.prefix_terminal_hidden->gpu_data_ptr() &&
                    !state_.prefix_terminal_hidden->allocateOnDevice(
                        state_.device_id,
                        terminal_restore_stream))
                {
                    return false;
                }
                IBackend *backend = getBackendFor(state_.device_id);
                const bool device_hot =
                    terminal.tier == PrefixStorageTier::DeviceHot;
                const void *hidden_source =
                    device_hot
                        ? terminal.deviceTerminalHiddenData()
                        : terminal.terminal_hidden;
                if (!backend || !hidden_source ||
                    !(device_hot
                          ? backend->deviceCopyAsync(
                                state_.prefix_terminal_hidden->gpu_data_ptr(),
                                hidden_source,
                                prefix_layout_.terminal_hidden_bytes,
                                state_.device_id.gpu_ordinal(),
                                terminal_restore_stream)
                          : backend->hostToDeviceOnStream(
                                state_.prefix_terminal_hidden->gpu_data_ptr(),
                                hidden_source,
                                prefix_layout_.terminal_hidden_bytes,
                                state_.device_id.gpu_ordinal(),
                                terminal_restore_stream)))
                {
                    return false;
                }
                TransferEngine::publishDeviceWrite(
                    state_.prefix_terminal_hidden.get(),
                    state_.device_id,
                    terminal_restore_stream);
            }
            else
            {
                void *hidden_dst =
                    state_.prefix_terminal_hidden->raw_mutable_data();
                if (!hidden_dst || !terminal.terminal_hidden)
                    return false;
                std::memcpy(
                    hidden_dst,
                    terminal.terminal_hidden,
                    prefix_layout_.terminal_hidden_bytes);
                TransferEngine::publishHostWrite(
                    state_.prefix_terminal_hidden.get());
            }
            state_.mtp_terminal_hidden_current = true;
            if (arena_ && arena_->isRegistered(BufferId::PREFIX_TERMINAL_HIDDEN))
            {
                arena_->markWrittenFlagsOnly(
                    BufferId::PREFIX_TERMINAL_HIDDEN,
                    state_.device_id.is_gpu() ? state_.device_id : DeviceId::cpu());
            }
        }

        if (state_.device_id.is_gpu())
        {
            std::vector<PrefixBlockHandle> retained_terminal_sources;
            retained_terminal_sources.push_back(std::move(terminal));
            if (!recordLivePrefixMutationReady(
                    terminal_restore_stream,
                    "restore_prefix_terminal_state",
                    std::move(retained_terminal_sources)))
            {
                LOG_ERROR(
                    "[DeviceGraphOrchestrator] Failed to publish terminal "
                    "prefix restore source ownership");
                return false;
            }
        }

        return true;
    }

    bool DeviceGraphOrchestrator::harvestPrefix(
        const std::vector<int32_t> &tokens,
        int prompt_token_count)
    {
        if (prompt_token_count <= 0 || prompt_token_count > static_cast<int>(tokens.size()))
        {
            LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest skipped: invalid prompt_token_count="
                      << prompt_token_count << " token_count=" << tokens.size());
            return false;
        }
        if (!ensurePrefixCacheReady() || !state_.kv_cache || !prefix_ram_backend_)
        {
            LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest skipped: cache_ready="
                      << (prefix_cache_ ? "yes" : "no")
                      << " kv_cache=" << (state_.kv_cache ? "yes" : "no")
                      << " ram_backend=" << (prefix_ram_backend_ ? "yes" : "no")
                      << " bypass_reason=" << prefix_cache_bypass_reason_);
            return false;
        }

        void *stream = explicitGPUStreamForOperation("harvestPrefix");
        if (state_.device_id.is_gpu() && !stream)
        {
            return false;
        }
        if (!waitForLiveInferenceStateReadyForObservation(
                stream,
                "harvest_prefix",
                DeviceTimelineRole::PrefixCheckpointArchive))
        {
            return false;
        }

        if (!refreshPrefixPayloadLayoutForLiveHybridState("harvestPrefix"))
        {
            return false;
        }
        IBackend *prefix_backend =
            state_.device_id.is_gpu() ? getBackendFor(state_.device_id) : nullptr;
        if (state_.device_id.is_gpu() &&
            (!prefix_backend || !prefix_archive_device_staging_))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Prefix harvest GPU staging is unavailable");
            return false;
        }

        const int complete_blocks =
            (prompt_token_count + prefix_layout_.block_size - 1) /
            prefix_layout_.block_size;

        uint64_t parent_hash = 0;
        for (int block = 0; block < complete_blocks; ++block)
        {
            PrefixCacheKey key = makePrefixKeyForBlock(tokens, block, parent_hash);
            parent_hash = key.stableHash();
            if (prefix_cache_->contains(key))
            {
                if (prefixCacheTraceEnabled())
                {
                    LOG_INFO("[PREFIX_TRACE] harvest skip-existing device=" << state_.device_id.toString()
                                                                            << " block=" << block
                                                                            << " key=" << key.toHex());
                }
                continue;
            }

            const bool terminal_block =
                (key.token_start + key.token_count) == prompt_token_count;
            PrefixPayloadLayout block_layout = prefix_layout_;
            if (!terminal_block)
            {
                block_layout.includes_hybrid_state = false;
                block_layout.includes_terminal_hidden = false;
                block_layout.includes_terminal_logits = false;
            }

            std::shared_ptr<std::vector<uint8_t>> model_runtime_state;
            if (terminal_block && graph_builder_)
            {
                auto captured = std::make_shared<std::vector<uint8_t>>();
                if (!graph_builder_->capturePrefixCacheRuntimeState(*captured, stream))
                {
                    LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: model runtime state capture failed");
                    return false;
                }
                if (!captured->empty())
                    model_runtime_state = std::move(captured);
            }

            const size_t model_runtime_state_bytes =
                model_runtime_state ? model_runtime_state->size() : 0u;
            const size_t total_block_bytes =
                block_layout.totalBytes() + model_runtime_state_bytes;

            if (!prefix_cache_->reserveRam(total_block_bytes))
            {
                LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: RAM reserve rejected block_bytes="
                          << total_block_bytes);
                return false;
            }

            PrefixBlockHandle handle = prefix_ram_backend_->allocate(key, block_layout);
            if (!handle.valid())
            {
                LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: RAM allocate rejected key="
                          << key.toHex()
                          << " block_bytes=" << block_layout.totalBytes());
                return false;
            }
            handle.total_bytes = total_block_bytes;
            handle.model_runtime_state_storage = std::move(model_runtime_state);
            handle.has_model_runtime_state =
                handle.model_runtime_state_storage && !handle.model_runtime_state_storage->empty();

            PrefixBlockHandle device_hot_handle;
            const bool prepare_device_hot =
                prefix_device_hot_backend_ &&
                total_block_bytes <= prefix_device_hot_backend_->budgetBytes();
            if (prepare_device_hot &&
                !prefix_cache_->prepareDeviceHotCopy(
                    handle,
                    &device_hot_handle))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Prefix harvest failed: "
                          "device-hot allocation rejected key="
                          << key.toHex()
                          << " block_bytes=" << total_block_bytes);
                prefix_ram_backend_->release(handle);
                return false;
            }

            /*
             * Event allocation must precede the first asynchronous payload
             * operation. Once a D2H or D2D copy is accepted, both handles own
             * in-flight storage and completion-record failure is fatal.
             */
            if (state_.device_id.is_gpu() &&
                (!preparePrefixArchivePayloadReady(
                     &handle,
                     stream,
                     "harvest_prefix_block") ||
                 (device_hot_handle.valid() &&
                  !preparePrefixArchivePayloadReady(
                      &device_hot_handle,
                      stream,
                      "harvest_prefix_device_hot_block"))))
            {
                if (device_hot_handle.valid() && prefix_device_hot_backend_)
                    (void)prefix_device_hot_backend_->release(device_hot_handle);
                (void)prefix_ram_backend_->release(handle);
                return false;
            }

            bool ok = true;
            bool terminal_hidden_archival_refresh = false;
            for (int local_layer = 0; local_layer < prefix_layout_.fa_layers && ok; ++local_layer)
            {
                const int global_layer = prefixFALayerForIndex(*state_.kv_cache, local_layer);
                if (global_layer < 0)
                {
                    LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: no FA layer for local index "
                              << local_layer);
                    ok = false;
                    break;
                }
                const auto block_payload_layout =
                    state_.kv_cache->logicalBlockLayout(global_layer, key.token_count);
                if (block_payload_layout.k_bytes > block_layout.bytes_per_fa_layer_k ||
                    block_payload_layout.v_bytes > block_layout.bytes_per_fa_layer_v)
                {
                    LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: logical block payload layout "
                              "exceeds per-layer storage stride for layer="
                              << global_layer
                              << " token_start=" << key.token_start
                              << " token_count=" << key.token_count
                              << " k_bytes=" << block_payload_layout.k_bytes
                              << " k_stride=" << block_layout.bytes_per_fa_layer_k
                              << " v_bytes=" << block_payload_layout.v_bytes
                              << " v_stride=" << block_layout.bytes_per_fa_layer_v);
                    ok = false;
                    break;
                }
                uint8_t *k_dst = handle.kvKData() +
                                 static_cast<size_t>(local_layer) * prefix_layout_.bytes_per_fa_layer_k;
                uint8_t *v_dst = handle.kvVData() +
                                 static_cast<size_t>(local_layer) * prefix_layout_.bytes_per_fa_layer_v;
                IKVCache::KVCacheLogicalBlockDescriptor desc;
                desc.layer = global_layer;
                desc.seq_idx = 0;
                desc.logical_token_start = key.token_start;
                desc.token_count = key.token_count;
                desc.stream = stream;
                if (state_.device_id.is_gpu())
                {
                    void *k_staging =
                        prefix_archive_device_staging_->k.devicePtr();
                    void *v_staging =
                        prefix_archive_device_staging_->v.devicePtr();
                    desc.payload_domain =
                        IKVCache::KVCacheLogicalBlockPayloadDomain::Device;
                    ok = k_staging && v_staging &&
                         state_.kv_cache->exportLogicalBlock(
                             desc,
                             k_staging,
                             v_staging) &&
                         prefix_backend->deviceToHostOnStream(
                             k_dst,
                             k_staging,
                             block_payload_layout.k_bytes,
                             state_.device_id.gpu_ordinal(),
                             stream) &&
                         prefix_backend->deviceToHostOnStream(
                             v_dst,
                             v_staging,
                             block_payload_layout.v_bytes,
                             state_.device_id.gpu_ordinal(),
                             stream) &&
                         (!device_hot_handle.valid() ||
                          (device_hot_handle.deviceKVKData() &&
                           device_hot_handle.deviceKVVData() &&
                           prefix_backend->deviceCopyAsync(
                               device_hot_handle.deviceKVKData() +
                                   static_cast<size_t>(local_layer) *
                                       prefix_layout_.bytes_per_fa_layer_k,
                               k_staging,
                               block_payload_layout.k_bytes,
                               state_.device_id.gpu_ordinal(),
                               stream) &&
                           prefix_backend->deviceCopyAsync(
                               device_hot_handle.deviceKVVData() +
                                   static_cast<size_t>(local_layer) *
                                       prefix_layout_.bytes_per_fa_layer_v,
                               v_staging,
                               block_payload_layout.v_bytes,
                               state_.device_id.gpu_ordinal(),
                               stream)));
                }
                else
                {
                    ok = state_.kv_cache->exportLogicalBlock(
                        desc,
                        k_dst,
                        v_dst);
                }
                if (ok && shouldTracePrefixPayloadHash(key, global_layer))
                {
                    /*
                     * GPU archive bytes are still being filled asynchronously.
                     * The deferred block-ready event remains the authority; a
                     * host hash here would race DMA or force a synchronization.
                     */
                    if (!state_.device_id.is_gpu())
                    {
                        logPrefixPayloadHashTrace(
                            "harvest_export",
                            state_.device_id,
                            key,
                            global_layer,
                            local_layer,
                            k_dst,
                            block_payload_layout.k_bytes,
                            v_dst,
                            block_payload_layout.v_bytes);
                    }
                }
                if (!ok)
                {
                    const auto seq_state = state_.kv_cache->sequenceState(global_layer, desc.seq_idx);
                    LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: exportLogicalBlock layer="
                              << global_layer
                              << " token_start=" << desc.logical_token_start
                              << " token_count=" << desc.token_count
                              << " cached_tokens=" << seq_state.cached_tokens
                              << " first_layer_index=" << state_.kv_cache->first_layer_index()
                              << " total_layers=" << state_.kv_cache->n_layers());
                }
            }

            if (ok && prefix_layout_.includes_mtp_state)
            {
                if (state_.mtp_kv_caches.empty() || !state_.mtp_kv_caches[0])
                {
                    LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: missing MTP KV cache");
                    ok = false;
                }
                else
                {
                    ok = exportMTPPrefixPayload(
                        *state_.mtp_kv_caches[0],
                        0,
                        key,
                        &handle,
                        device_hot_handle.valid()
                            ? &device_hot_handle
                            : nullptr,
                        stream,
                        state_.device_id.is_gpu()
                            ? prefix_archive_device_staging_->mtp_k.devicePtr()
                            : nullptr,
                        state_.device_id.is_gpu()
                            ? prefix_archive_device_staging_->mtp_v.devicePtr()
                            : nullptr,
                        prefix_backend,
                        state_.device_id);
                    if (!ok)
                    {
                        LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: MTP payload export failed");
                    }
                }
            }

            if (ok && terminal_block && prefix_layout_.includes_hybrid_state)
            {
                if (state_.device_id.is_gpu())
                {
                    const auto *hybrid =
                        dynamic_cast<const IHybridKVCache *>(state_.kv_cache.get());
                    void *hybrid_staging =
                        prefix_archive_device_staging_->hybrid.devicePtr();
                    if (!hybrid ||
                        block_layout.hybrid_host_state_bytes != 0 ||
                        block_layout.hybrid_device_state_bytes == 0 ||
                        !handle.hybrid_payload ||
                        !hybrid_staging)
                    {
                        ok = false;
                    }
                    else
                    {
                        HybridPrefixStateDescriptor desc;
                        desc.seq_idx = 0;
                        desc.logical_token_count =
                            key.token_start + key.token_count;
                        desc.stream = stream;
                        desc.synchronize = false;
                        desc.include_host_state = false;
                        desc.include_device_state = true;
                        ok = hybrid->exportHybridPrefixState(
                                 desc,
                                 nullptr,
                                 hybrid_staging) &&
                             prefix_backend->deviceToHostOnStream(
                                 handle.hybrid_payload,
                                 hybrid_staging,
                                 block_layout.hybrid_device_state_bytes,
                                 state_.device_id.gpu_ordinal(),
                                 stream) &&
                             (!device_hot_handle.valid() ||
                              (device_hot_handle.deviceHybridData() &&
                               prefix_backend->deviceCopyAsync(
                                   device_hot_handle.deviceHybridData(),
                                   hybrid_staging,
                                   block_layout.hybrid_device_state_bytes,
                                   state_.device_id.gpu_ordinal(),
                                   stream)));
                        handle.has_hybrid_state = ok;
                        device_hot_handle.has_hybrid_state =
                            device_hot_handle.valid() && ok;
                    }
                }
                else
                {
                    ok = exportHybridPrefixPayload(
                        *state_.kv_cache,
                        0,
                        key.token_start + key.token_count,
                        &handle,
                        /*synchronize=*/true,
                        stream);
                }
                if (!ok)
                {
                    LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: hybrid payload export failed");
                }
            }

            if (ok && terminal_block && prefix_layout_.includes_terminal_hidden &&
                !state_.mtp_terminal_hidden_current)
            {
                /*
                 * Prefix full hits with MTP need the terminal hidden row from
                 * the prompt prefill before the first draft sidecar can run.
                 * MTP sidecar execution lazily refreshes this row too, but
                 * prefix harvest happens immediately after prefill and before
                 * decode.  Refresh it here so a stored terminal block never
                 * advertises MTP state while silently lacking terminal hidden.
                 *
                 * This refresh is an archival read for the prefix-cache block,
                 * not a decode-state publication.  Leave the real sidecar
                 * input contract untouched after the block copies the row so
                 * the following MTP decode step refreshes terminal hidden at
                 * the same transaction boundary as the no-prefix path.
                 */
                ok = refreshMTPTerminalHiddenState(prompt_token_count, 1);
                if (!ok)
                {
                    LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: terminal hidden refresh failed");
                }
                else
                {
                    terminal_hidden_archival_refresh = true;
                    PerfStatsCollector::addCounter(
                        "prefix_cache",
                        "harvest_terminal_hidden_archival_refreshes",
                        1.0,
                        "harvest",
                        state_.device_id.toString(),
                        {{"prompt_token_count", std::to_string(prompt_token_count)}});
                }
            }

            TensorBase *terminal_logits_tensor =
                activeMainLogitsAreColumnParallel() ? state_.logits_local.get() : state_.logits.get();
            if (ok && terminal_block && prefix_layout_.includes_terminal_logits &&
                terminal_logits_tensor && handle.terminal_logits)
            {
                if (fp32LogitsRowBytes(terminal_logits_tensor) < prefix_layout_.terminal_logits_bytes)
                {
                    ok = false;
                }
                if (state_.device_id.is_gpu())
                {
                    const void *logits_device =
                        terminal_logits_tensor->gpu_data_ptr();
                    if (!logits_device ||
                        !prefix_backend->deviceToHostOnStream(
                            handle.terminal_logits,
                            logits_device,
                            prefix_layout_.terminal_logits_bytes,
                            state_.device_id.gpu_ordinal(),
                            stream) ||
                        (device_hot_handle.valid() &&
                         (!device_hot_handle.deviceTerminalLogitsData() ||
                          !prefix_backend->deviceCopyAsync(
                              device_hot_handle.deviceTerminalLogitsData(),
                              logits_device,
                              prefix_layout_.terminal_logits_bytes,
                              state_.device_id.gpu_ordinal(),
                              stream))))
                    {
                        LOG_ERROR("[DeviceGraphOrchestrator] Failed to submit prefix terminal logits D2H");
                        ok = false;
                    }
                    handle.has_terminal_logits = ok;
                    device_hot_handle.has_terminal_logits =
                        device_hot_handle.valid() && ok;
                }
                else
                {
                    const float *logits =
                        ok ? terminal_logits_tensor->fp32_data() : nullptr;
                    if (ok && logits)
                    {
                        std::memcpy(
                            handle.terminal_logits,
                            logits,
                            prefix_layout_.terminal_logits_bytes);
                        handle.has_terminal_logits = true;
                    }
                    else if (ok)
                    {
                        LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: terminal logits host pointer unavailable");
                        ok = false;
                    }
                }
            }

            if (ok && terminal_block && prefix_layout_.includes_terminal_hidden &&
                state_.prefix_terminal_hidden &&
                state_.mtp_terminal_hidden_current &&
                handle.terminal_hidden)
            {
                if (state_.device_id.is_gpu())
                {
                    const void *hidden_device =
                        state_.prefix_terminal_hidden->gpu_data_ptr();
                    if (!hidden_device ||
                        !prefix_backend->deviceToHostOnStream(
                            handle.terminal_hidden,
                            hidden_device,
                            prefix_layout_.terminal_hidden_bytes,
                            state_.device_id.gpu_ordinal(),
                            stream) ||
                        (device_hot_handle.valid() &&
                         (!device_hot_handle.deviceTerminalHiddenData() ||
                          !prefix_backend->deviceCopyAsync(
                              device_hot_handle.deviceTerminalHiddenData(),
                              hidden_device,
                              prefix_layout_.terminal_hidden_bytes,
                              state_.device_id.gpu_ordinal(),
                              stream))))
                    {
                        LOG_ERROR("[DeviceGraphOrchestrator] Failed to submit prefix terminal hidden D2H");
                        ok = false;
                    }
                    handle.has_terminal_hidden = ok;
                    device_hot_handle.has_terminal_hidden =
                        device_hot_handle.valid() && ok;
                }
                else
                {
                    const void *hidden =
                        ok ? state_.prefix_terminal_hidden->raw_data() : nullptr;
                    if (ok && hidden)
                    {
                        std::memcpy(
                            handle.terminal_hidden,
                            hidden,
                            prefix_layout_.terminal_hidden_bytes);
                        handle.has_terminal_hidden = true;
                    }
                    else if (ok)
                    {
                        LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: terminal hidden host pointer unavailable");
                        ok = false;
                    }
                }
            }

            if (terminal_hidden_archival_refresh &&
                terminal_block &&
                prefix_layout_.includes_terminal_hidden &&
                handle.has_terminal_hidden)
            {
                /*
                 * `PREFIX_TERMINAL_HIDDEN` now has a durable copy in the
                 * prefix-cache handle.  If harvest was the operation that made
                 * the sidecar input look current, clear only the live-current
                 * bit.  The buffer contents remain valid for the archive, but
                 * MTP decode must not skip its own terminal-hidden refresh
                 * because a cache-miss observer happened to run first.
                 */
                state_.mtp_terminal_hidden_current = false;
                PerfStatsCollector::addCounter(
                    "prefix_cache",
                    "harvest_terminal_hidden_live_current_clears",
                    1.0,
                    "harvest",
                    state_.device_id.toString(),
                    {{"prompt_token_count", std::to_string(prompt_token_count)}});
            }

            if (state_.device_id.is_gpu())
            {
                /*
                 * Record both preflighted events even after a partial copy
                 * submission failure. Their allocation owners may otherwise
                 * retire while an earlier accepted copy is still in flight.
                 * The record helper hard-fails if the backend cannot preserve
                 * this ownership edge; it never substitutes a stream sync.
                 */
                const bool ram_ready =
                    recordPrefixArchivePayloadReady(
                        &handle,
                        stream,
                        "harvest_prefix_block");
                const bool device_hot_ready =
                    !device_hot_handle.valid() ||
                    recordPrefixArchivePayloadReady(
                        &device_hot_handle,
                        stream,
                        "harvest_prefix_device_hot_block");
                ok = ok && ram_ready && device_hot_ready;
            }

            if (!ok ||
                !prefix_cache_->insert(
                    handle,
                    device_hot_handle))
            {
                if (ok)
                {
                    LOG_DEBUG("[DeviceGraphOrchestrator] Prefix harvest failed: cache insert rejected key="
                              << key.toHex());
                }
                if (prefixCacheTraceEnabled())
                {
                    LOG_INFO("[PREFIX_TRACE] harvest failed device=" << state_.device_id.toString()
                                                                     << " block=" << block
                                                                     << " key=" << key.toHex()
                                                                     << " ok_before_insert="
                                                                     << (ok ? "yes" : "no")
                                                                     << " terminal_block="
                                                                     << (terminal_block ? "yes" : "no")
                                                                     << " terminal_logits="
                                                                     << (handle.has_terminal_logits ? "yes" : "no")
                                                                     << " terminal_hidden="
                                                                     << (handle.has_terminal_hidden ? "yes" : "no")
                                                                     << " mtp_state="
                                                                     << (handle.layout.includes_mtp_state ? "yes" : "no")
                                                                     << " model_runtime_state="
                                                                     << (handle.has_model_runtime_state ? "yes" : "no")
                                                                     << " model_runtime_state_bytes="
                                                                     << (handle.model_runtime_state_storage
                                                                             ? handle.model_runtime_state_storage->size()
                                                                             : 0u)
                                                                     << " total_bytes=" << handle.total_bytes);
                }
                if (device_hot_handle.valid() &&
                    prefix_device_hot_backend_)
                {
                    prefix_device_hot_backend_->release(device_hot_handle);
                }
                prefix_ram_backend_->release(handle);
                return false;
            }

            if (device_hot_handle.valid())
            {
                PerfStatsCollector::addCounter(
                    "prefix_cache",
                    "harvest_device_hot_d2d_publications",
                    1.0,
                    "harvest",
                    state_.device_id.toString(),
                    {
                        {"block", std::to_string(block)},
                        {"bytes", std::to_string(device_hot_handle.total_bytes)},
                    });
            }

            PerfStatsCollector::addCounter(
                "prefix_cache",
                "harvest_inserts",
                1.0,
                "harvest",
                state_.device_id.toString(),
                {
                    {"block", std::to_string(block)},
                    {"token_start", std::to_string(key.token_start)},
                    {"token_count", std::to_string(key.token_count)},
                    {"terminal_block", terminal_block ? "true" : "false"},
                    {"terminal_logits", handle.has_terminal_logits ? "true" : "false"},
                    {"terminal_hidden", handle.has_terminal_hidden ? "true" : "false"},
                    {"includes_mtp_state", handle.layout.includes_mtp_state ? "true" : "false"},
                    {"model_runtime_state", handle.has_model_runtime_state ? "true" : "false"},
                    {"total_bytes", std::to_string(handle.total_bytes)},
                });

            if (prefixCacheTraceEnabled())
            {
                LOG_INFO("[PREFIX_TRACE] harvest insert device=" << state_.device_id.toString()
                                                                 << " block=" << block
                                                                 << " key=" << key.toHex()
                                                                 << " token_count=" << key.token_count
                                                                 << " terminal_logits="
                                                                 << (handle.has_terminal_logits ? "yes" : "no")
                                                                 << " terminal_hidden="
                                                                 << (handle.has_terminal_hidden ? "yes" : "no")
                                                                 << " mtp_state="
                                                                 << (handle.layout.includes_mtp_state ? "yes" : "no")
                                                                 << " model_runtime_state="
                                                                 << (handle.has_model_runtime_state ? "yes" : "no")
                                                                 << " model_runtime_state_bytes="
                                                                 << (handle.model_runtime_state_storage
                                                                         ? handle.model_runtime_state_storage->size()
                                                                         : 0u)
                                                                 << " total_bytes=" << handle.total_bytes);
            }
        }

        return true;
    }

    PrefixStateSnapshot DeviceGraphOrchestrator::captureLivePrefixState(int seq_idx) const
    {
        PrefixStateSnapshot snapshot;
        auto fail = [&](const std::string &reason) -> PrefixStateSnapshot
        {
            PerfStatsCollector::addCounter(
                "mtp",
                "live_prefix_payload_capture_failures",
                1.0,
                "decode",
                state_.device_id.toString(),
                {{"reason", reason},
                 {"seq_idx", std::to_string(seq_idx)}});
            LOG_WARN("[DeviceGraphOrchestrator] captureLivePrefixState failed on "
                     << state_.device_id.toString()
                     << " seq_idx=" << seq_idx
                     << " reason=" << reason);
            return {};
        };

        if (!state_.kv_cache || seq_idx < 0 || seq_idx >= state_.batch_size)
        {
            return fail("missing_kv_cache_or_sequence_index_out_of_range");
        }

        void *stream = explicitGPUStreamForOperation("captureLivePrefixState");
        if (state_.device_id.is_gpu() && !stream)
        {
            return fail("missing_explicit_gpu_stream");
        }
        if (!waitForLiveInferenceStateReadyForObservation(
                stream,
                "capture_live_prefix_state",
                DeviceTimelineRole::PrefixCheckpointArchive))
        {
            return fail("live_state_observation_wait_failed");
        }

        int cached_tokens = restorablePrefixCachedTokens(*state_.kv_cache, seq_idx);
        if (auto resident_tokens =
                deviceResidentLogicalTokenCountForObservation(
                    seq_idx,
                    stream,
                    "capture_live_prefix_state_logical_tokens"))
        {
            cached_tokens = *resident_tokens;
        }
        if (cached_tokens < 0 || cached_tokens > state_.kv_cache->max_seq_len())
        {
            return fail("cached_token_count_out_of_range");
        }

        snapshot.valid = true;
        snapshot.provenance = PrefixStateProvenance::PayloadCheckpoint;
        snapshot.cached_tokens = cached_tokens;
        bool queued_async_device_checkpoint_payload = false;
        if (cached_tokens > 0)
        {
            size_t live_terminal_hidden_bytes = 0;
            if (graph_builder_ &&
                graph_builder_->config().mtp.enabled &&
                state_.prefix_terminal_hidden &&
                state_.mtp_terminal_hidden_current &&
                state_.d_model > 0)
            {
                live_terminal_hidden_bytes =
                    static_cast<size_t>(state_.d_model) * sizeof(float);
            }

            PrefixPayloadLayout layout = buildDensePrefixPayloadLayout(
                *state_.kv_cache,
                state_.device_id,
                cached_tokens,
                live_terminal_hidden_bytes);
            PrefixBlockHandle handle;
            handle.key.fingerprint = prefix_fingerprint_ != 0 ? prefix_fingerprint_ : 1;
            handle.key.block_index = 0;
            handle.key.token_start = 0;
            handle.key.token_count = cached_tokens;
            handle.layout = layout;
            if (state_.device_id.is_gpu() &&
                handle.layout.hybrid_device_state_bytes > 0)
            {
                handle.layout.hybrid_host_state_bytes = 0;
                handle.layout.hybrid_state_bytes =
                    handle.layout.hybrid_device_state_bytes;
            }
            handle.total_bytes = handle.layout.totalBytes();

            const size_t kv_bytes = layout.faKVBytes();
            if (kv_bytes == 0)
            {
                return fail("main_kv_layout_empty");
            }
            handle.kv_storage = std::make_shared<std::vector<uint8_t>>(kv_bytes, 0);
            handle.kv_payload = handle.kv_storage->data();
            if (!ensureLiveCheckpointStorage(handle))
            {
                return fail("main_checkpoint_storage_unavailable");
            }

            for (int local_layer = 0; local_layer < layout.fa_layers; ++local_layer)
            {
                const int global_layer = prefixFALayerForIndex(*state_.kv_cache, local_layer);
                if (global_layer < 0)
                {
                    return fail("main_kv_global_layer_unavailable");
                }
                uint8_t *k_dst = handle.kvKData() +
                                 static_cast<size_t>(local_layer) * layout.bytes_per_fa_layer_k;
                uint8_t *v_dst = handle.kvVData() +
                                 static_cast<size_t>(local_layer) * layout.bytes_per_fa_layer_v;

                IKVCache::KVCacheLogicalBlockDescriptor desc;
                desc.layer = global_layer;
                desc.seq_idx = seq_idx;
                desc.logical_token_start = 0;
                desc.token_count = cached_tokens;
                desc.stream = stream;
                if (!state_.kv_cache->exportLogicalBlock(desc, k_dst, v_dst))
                {
                    return fail(
                        "main_kv_export_failed_layer_" +
                        std::to_string(global_layer) +
                        "_tokens_" + std::to_string(cached_tokens));
                }
            }

            if (!exportHybridPrefixPayload(
                    *state_.kv_cache,
                    seq_idx,
                    cached_tokens,
                    &handle,
                    /*synchronize=*/true,
                    stream))
            {
                return fail("main_hybrid_payload_export_failed");
            }

            if (live_terminal_hidden_bytes > 0)
            {
                if (state_.device_id.is_gpu())
                {
                    IBackend *backend = getBackendFor(state_.device_id);
                    const void *source =
                        state_.prefix_terminal_hidden
                            ? state_.prefix_terminal_hidden->gpu_data_ptr()
                            : nullptr;
                    void *destination =
                        handle.deviceTerminalHiddenData();
                    if (!backend ||
                        !source ||
                        !destination ||
                        !backend->deviceCopyAsync(
                            destination,
                            source,
                            live_terminal_hidden_bytes,
                            state_.device_id.gpu_ordinal(),
                            stream))
                    {
                        return fail(
                            "terminal_hidden_device_copy_failed");
                    }
                    queued_async_device_checkpoint_payload = true;
                }
                else
                {
                    const void *source =
                        state_.prefix_terminal_hidden->raw_data();
                    if (!source || !handle.terminal_hidden)
                    {
                        return fail(
                            "terminal_hidden_host_storage_unavailable");
                    }
                    std::memcpy(
                        handle.terminal_hidden,
                        source,
                        live_terminal_hidden_bytes);
                }
                handle.has_terminal_hidden = true;
            }

            snapshot.blocks.push_back(std::move(handle));
        }

        for (size_t depth = 0; depth < state_.mtp_kv_caches.size(); ++depth)
        {
            const auto &cache = state_.mtp_kv_caches[depth];
            if (!cache)
            {
                continue;
            }

            int mtp_cached_tokens = restorablePrefixCachedTokens(*cache, seq_idx);
            if (auto resident_mtp_tokens =
                    deviceResidentShiftedMTPKVTokenCountForObservation(
                        static_cast<int>(depth),
                        seq_idx,
                        stream,
                        "capture_live_prefix_state_shifted_mtp"))
            {
                mtp_cached_tokens = *resident_mtp_tokens;
            }
            if (mtp_cached_tokens < 0 || mtp_cached_tokens > cache->max_seq_len())
            {
                return fail(
                    "mtp_cached_token_count_out_of_range_depth_" +
                    std::to_string(depth));
            }
            if (mtp_cached_tokens == 0)
            {
                continue;
            }

            PrefixPayloadLayout layout = buildDensePrefixPayloadLayout(
                *cache,
                state_.device_id,
                mtp_cached_tokens);

            PrefixBlockHandle handle;
            handle.key.fingerprint = prefix_fingerprint_ != 0 ? prefix_fingerprint_ : 1;
            handle.key.block_index = static_cast<int>(depth);
            handle.key.token_start = 0;
            handle.key.token_count = mtp_cached_tokens;
            handle.layout = layout;
            handle.total_bytes = layout.totalBytes();

            const size_t kv_bytes = layout.faKVBytes();
            if (kv_bytes == 0)
            {
                return fail(
                    "mtp_kv_layout_empty_depth_" +
                    std::to_string(depth));
            }
            handle.kv_storage = std::make_shared<std::vector<uint8_t>>(kv_bytes, 0);
            handle.kv_payload = handle.kv_storage->data();

            for (int local_layer = 0; local_layer < layout.fa_layers; ++local_layer)
            {
                const int global_layer = prefixFALayerForIndex(*cache, local_layer);
                if (global_layer < 0)
                {
                    return fail(
                        "mtp_kv_global_layer_unavailable_depth_" +
                        std::to_string(depth));
                }
                uint8_t *k_dst = handle.kvKData() +
                                 static_cast<size_t>(local_layer) * layout.bytes_per_fa_layer_k;
                uint8_t *v_dst = handle.kvVData() +
                                 static_cast<size_t>(local_layer) * layout.bytes_per_fa_layer_v;

                IKVCache::KVCacheLogicalBlockDescriptor desc;
                desc.layer = global_layer;
                desc.seq_idx = seq_idx;
                desc.logical_token_start = 0;
                desc.token_count = mtp_cached_tokens;
                desc.stream = stream;
                if (!cache->exportLogicalBlock(desc, k_dst, v_dst))
                {
                    return fail(
                        "mtp_kv_export_failed_depth_" +
                        std::to_string(depth) +
                        "_layer_" + std::to_string(global_layer) +
                        "_tokens_" + std::to_string(mtp_cached_tokens));
                }
            }

            snapshot.mtp_blocks.push_back(std::move(handle));
        }

        if (queued_async_device_checkpoint_payload &&
            !recordLivePrefixCheckpointReady(
                &snapshot,
                stream,
                "capture_live_prefix_state"))
        {
            return fail("checkpoint_ready_event_record_failed");
        }
        return snapshot;
    }

    bool DeviceGraphOrchestrator::ensureLiveCheckpointStorage(PrefixBlockHandle &handle) const
    {
        return acquireLiveCheckpointStorage(handle);
    }

    bool DeviceGraphOrchestrator::initializeLiveCheckpointStoragePool()
    {
        if (!graph_builder_ || !graph_builder_->config().mtp.enabled)
            return true;
        if (!state_.kv_cache || state_.d_model <= 0)
            return false;

        live_checkpoint_storage_pool_initialized_ = false;
        live_checkpoint_storage_pool_.clear();
        live_device_sequence_state_storage_pool_.clear();

        constexpr size_t kConcurrentCheckpointSlots = 4;
        PrefixPayloadLayout layout = buildDensePrefixPayloadLayout(
            *state_.kv_cache,
            state_.device_id,
            /*cached_tokens=*/1);
        layout = liveHybridCheckpointLayout(
            layout,
            /*device_only=*/state_.device_id.is_gpu());
        size_t checkpoint_handles_per_snapshot = 1;
        for (const auto &cache : state_.mtp_kv_caches)
        {
            if (!cache)
                continue;

            ++checkpoint_handles_per_snapshot;
            const PrefixPayloadLayout shifted_layout =
                liveHybridCheckpointLayout(
                    buildDensePrefixPayloadLayout(
                        *cache,
                        state_.device_id,
                        /*block_size=*/1),
                    /*device_only=*/state_.device_id.is_gpu());
            layout.hybrid_host_state_bytes = std::max(
                layout.hybrid_host_state_bytes,
                shifted_layout.hybrid_host_state_bytes);
            layout.hybrid_device_state_bytes = std::max(
                layout.hybrid_device_state_bytes,
                shifted_layout.hybrid_device_state_bytes);
        }
        layout.hybrid_state_bytes =
            layout.hybrid_host_state_bytes +
            layout.hybrid_device_state_bytes;
        layout.includes_hybrid_state = layout.hybrid_state_bytes > 0;
        layout.terminal_hidden_bytes =
            static_cast<size_t>(state_.d_model) * sizeof(float);
        layout.includes_terminal_hidden = true;
        const size_t total_storage_slots =
            kConcurrentCheckpointSlots * checkpoint_handles_per_snapshot;

        /*
         * One logical checkpoint may own a main-cache handle plus one hybrid
         * handle for every shifted MTP cache. Keep every acquired handle alive
         * until the complete pool is reserved. Shared ownership makes
         * acquireLiveCheckpointStorage skip earlier slots, so this loop creates
         * four complete checkpoint sets without a mutable "reserved" flag or a
         * hot-path allocation branch.
         */
        std::vector<PrefixBlockHandle> reservations;
        reservations.reserve(total_storage_slots);
        for (size_t slot_index = 0;
             slot_index < total_storage_slots;
             ++slot_index)
        {
            PrefixBlockHandle handle;
            handle.layout = layout;
            handle.total_bytes = layout.totalBytes();
            if (!acquireLiveCheckpointStorage(handle))
                return false;
            reservations.push_back(std::move(handle));
        }

        /*
         * Sequence metadata is required for every GPU cache, even when a cache
         * has no recurrent payload and therefore consumes no PrefixBlockHandle
         * during a live checkpoint. Reserve complete main-plus-shifted sets so
         * capture never allocates or creates events in decode.
         */
        std::vector<DeviceKVSequenceStateCheckpoint>
            sequence_state_reservations;
        if (state_.device_id.is_gpu())
        {
            sequence_state_reservations.reserve(total_storage_slots);
            for (size_t checkpoint_index = 0;
                 checkpoint_index < kConcurrentCheckpointSlots;
                 ++checkpoint_index)
            {
                DeviceKVSequenceStateCheckpoint checkpoint;
                if (!acquireLiveDeviceSequenceStateStorage(
                        /*cache_depth=*/-1,
                        /*sequence_index=*/0,
                        *state_.kv_cache,
                        &checkpoint))
                {
                    return false;
                }
                sequence_state_reservations.push_back(
                    std::move(checkpoint));

                for (size_t depth = 0;
                     depth < state_.mtp_kv_caches.size();
                     ++depth)
                {
                    const auto &cache = state_.mtp_kv_caches[depth];
                    if (!cache)
                        continue;
                    DeviceKVSequenceStateCheckpoint shifted_checkpoint;
                    if (!acquireLiveDeviceSequenceStateStorage(
                            static_cast<int>(depth),
                            /*sequence_index=*/0,
                            *cache,
                            &shifted_checkpoint))
                    {
                        return false;
                    }
                    sequence_state_reservations.push_back(
                        std::move(shifted_checkpoint));
                }
            }
        }
        live_checkpoint_storage_pool_initialized_ = true;

        PerfStatsCollector::addCounter(
            "mtp",
            "live_checkpoint_storage_slots_preallocated",
            static_cast<double>(total_storage_slots),
            "setup",
            state_.device_id.toString(),
            {{"concurrent_checkpoint_count",
              std::to_string(kConcurrentCheckpointSlots)},
             {"handles_per_checkpoint",
              std::to_string(checkpoint_handles_per_snapshot)},
             {"terminal_hidden_bytes",
              std::to_string(layout.terminal_hidden_bytes)},
             {"hybrid_host_bytes",
              std::to_string(layout.hybrid_host_state_bytes)},
             {"hybrid_device_bytes",
              std::to_string(layout.hybrid_device_state_bytes)},
             {"device_sequence_state_slots",
              std::to_string(
                  live_device_sequence_state_storage_pool_.size())}});
        return true;
    }

    bool DeviceGraphOrchestrator::acquireLiveDeviceSequenceStateStorage(
        int cache_depth,
        int sequence_index,
        const IKVCache &cache,
        DeviceKVSequenceStateCheckpoint *checkpoint) const
    {
        if (!checkpoint ||
            !state_.device_id.is_gpu() ||
            sequence_index < 0 ||
            cache_depth < -1)
        {
            return false;
        }

        const size_t required_bytes =
            cache.deviceSequenceStateCheckpointBytes();
        if (required_bytes == 0 ||
            required_bytes % (sizeof(int32_t) * 2u) != 0)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] GPU KV cache does not expose a valid device sequence-state checkpoint layout"
                      << " cache_depth=" << cache_depth
                      << " bytes=" << required_bytes);
            return false;
        }

        auto assign_slot =
            [&](LiveDeviceSequenceStateStorageSlot &slot)
        {
            *checkpoint = DeviceKVSequenceStateCheckpoint{
                .cache_depth = cache_depth,
                .sequence_index = sequence_index,
                .metadata_layer_count = static_cast<int>(
                    required_bytes / (sizeof(int32_t) * 2u)),
                .bytes = required_bytes,
                .device = state_.device_id,
                .storage = slot.storage,
                .ready_event = slot.ready_event,
            };
        };

        for (auto &slot : live_device_sequence_state_storage_pool_)
        {
            const bool free =
                slot.storage &&
                slot.storage.use_count() == 1 &&
                slot.ready_event &&
                slot.ready_event.use_count() == 1;
            if (!free ||
                slot.device != state_.device_id ||
                slot.capacity_bytes < required_bytes)
            {
                continue;
            }

            assign_slot(slot);
            PerfStatsCollector::addCounter(
                "mtp",
                "live_prefix_checkpoint_device_sequence_state_pool_hits",
                1.0,
                "decode",
                state_.device_id.toString(),
                {{"cache_depth", std::to_string(cache_depth)},
                 {"bytes", std::to_string(required_bytes)}});
            return true;
        }

        if (live_checkpoint_storage_pool_initialized_)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Device sequence-state checkpoint pool exhausted after initialization"
                      << " cache_depth=" << cache_depth
                      << " bytes=" << required_bytes);
            return false;
        }

        LiveDeviceSequenceStateStorageSlot slot;
        slot.capacity_bytes = required_bytes;
        slot.device = state_.device_id;
        slot.storage =
            allocatePureDeviceStorage(required_bytes, state_.device_id);
        slot.ready_event =
            allocatePersistentDeviceEvent(state_.device_id);
        if (!slot.storage || !slot.ready_event)
        {
            return false;
        }
        live_device_sequence_state_storage_pool_.push_back(std::move(slot));
        assign_slot(live_device_sequence_state_storage_pool_.back());
        PerfStatsCollector::addCounter(
            "mtp",
            "live_prefix_checkpoint_device_sequence_state_pool_misses",
            1.0,
            "setup",
            state_.device_id.toString(),
            {{"cache_depth", std::to_string(cache_depth)},
             {"bytes", std::to_string(required_bytes)},
             {"pool_size",
              std::to_string(
                  live_device_sequence_state_storage_pool_.size())}});
        return true;
    }

    bool DeviceGraphOrchestrator::acquireLiveCheckpointStorage(PrefixBlockHandle &handle) const
    {
        const size_t hybrid_host_bytes =
            handle.layout.includes_hybrid_state
                ? handle.layout.hybrid_host_state_bytes
                : 0;
        const size_t hybrid_device_bytes =
            handle.layout.includes_hybrid_state
                ? handle.layout.hybrid_device_state_bytes
                : 0;
        const size_t terminal_hidden_bytes =
            handle.layout.includes_terminal_hidden
                ? handle.layout.terminal_hidden_bytes
                : 0;
        const bool gpu_checkpoint = state_.device_id.is_gpu();
        const bool needs_hybrid_host = hybrid_host_bytes > 0;
        const bool needs_hybrid_device = hybrid_device_bytes > 0;
        const bool needs_terminal_hidden_host =
            !gpu_checkpoint && terminal_hidden_bytes > 0;
        const bool needs_terminal_hidden_device =
            gpu_checkpoint && terminal_hidden_bytes > 0;
        if (!needs_hybrid_host &&
            !needs_hybrid_device &&
            !needs_terminal_hidden_host &&
            !needs_terminal_hidden_device)
        {
            return true;
        }

        auto assign_slot = [&](LiveCheckpointStorageSlot &slot)
        {
            handle.live_checkpoint_ready_event =
                state_.device_id.is_gpu() ? slot.ready_event : nullptr;
            if (needs_hybrid_host)
            {
                slot.hybrid_host_storage->resize(hybrid_host_bytes);
                handle.hybrid_storage = slot.hybrid_host_storage;
                handle.hybrid_payload = slot.hybrid_host_storage->data();
            }
            else
            {
                handle.hybrid_storage.reset();
                handle.hybrid_payload = nullptr;
            }

            if (needs_hybrid_device)
            {
                handle.device_hybrid_storage.reset();
                handle.device_hybrid_allocation =
                    slot.hybrid_device_storage;
            }
            else
            {
                handle.device_hybrid_storage.reset();
                handle.device_hybrid_allocation.reset();
            }

            if (needs_terminal_hidden_host)
            {
                slot.terminal_hidden_host_storage->resize(terminal_hidden_bytes);
                handle.terminal_hidden_storage =
                    slot.terminal_hidden_host_storage;
                handle.terminal_hidden =
                    slot.terminal_hidden_host_storage->data();
            }
            else
            {
                handle.terminal_hidden_storage.reset();
                handle.terminal_hidden = nullptr;
            }

            if (needs_terminal_hidden_device)
            {
                handle.device_terminal_hidden_storage.reset();
                handle.device_terminal_hidden_allocation =
                    slot.terminal_hidden_device_storage;
            }
            else
            {
                handle.device_terminal_hidden_storage.reset();
                handle.device_terminal_hidden_allocation.reset();
            }
        };

        for (auto &slot : live_checkpoint_storage_pool_)
        {
            const bool slot_free =
                (!slot.hybrid_host_storage ||
                 slot.hybrid_host_storage.use_count() == 1) &&
                (!slot.hybrid_device_storage ||
                 slot.hybrid_device_storage.use_count() == 1) &&
                (!slot.terminal_hidden_host_storage ||
                 slot.terminal_hidden_host_storage.use_count() == 1) &&
                (!slot.terminal_hidden_device_storage ||
                 slot.terminal_hidden_device_storage.use_count() == 1) &&
                (!slot.ready_event ||
                 slot.ready_event.use_count() == 1);
            const bool hybrid_host_ok =
                !needs_hybrid_host ||
                (slot.hybrid_host_storage &&
                 slot.hybrid_host_capacity_bytes >= hybrid_host_bytes);
            const bool hybrid_device_ok =
                !needs_hybrid_device ||
                (slot.hybrid_device_storage &&
                 slot.hybrid_device_capacity_bytes >= hybrid_device_bytes &&
                 slot.device == state_.device_id);
            const bool terminal_hidden_host_ok =
                !needs_terminal_hidden_host ||
                (slot.terminal_hidden_host_storage &&
                 slot.terminal_hidden_host_capacity_bytes >=
                     terminal_hidden_bytes);
            const bool terminal_hidden_device_ok =
                !needs_terminal_hidden_device ||
                (slot.terminal_hidden_device_storage &&
                 slot.terminal_hidden_device_capacity_bytes >=
                     terminal_hidden_bytes &&
                 slot.device == state_.device_id);
            if (!slot_free ||
                !hybrid_host_ok ||
                !hybrid_device_ok ||
                !terminal_hidden_host_ok ||
                !terminal_hidden_device_ok)
            {
                continue;
            }

            assign_slot(slot);
            PerfStatsCollector::addCounter(
                "mtp",
                "live_prefix_checkpoint_storage_pool_hits",
                1.0,
                "decode",
                state_.device_id.toString(),
                {{"hybrid_host_bytes", std::to_string(hybrid_host_bytes)},
                 {"hybrid_device_bytes", std::to_string(hybrid_device_bytes)},
                 {"terminal_hidden_bytes", std::to_string(terminal_hidden_bytes)}});
            return true;
        }

        if (live_checkpoint_storage_pool_initialized_)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Transient MTP checkpoint storage pool exhausted after initialization");
            return false;
        }

        LiveCheckpointStorageSlot slot;
        slot.device = state_.device_id;
        if (state_.device_id.is_gpu())
        {
            slot.ready_event =
                allocatePersistentDeviceEvent(state_.device_id);
            if (!slot.ready_event)
                return false;
        }

        if (needs_hybrid_host)
        {
            slot.hybrid_host_storage =
                std::make_shared<std::vector<uint8_t>>(hybrid_host_bytes);
            slot.hybrid_host_capacity_bytes =
                slot.hybrid_host_storage->capacity();
        }

        if (needs_hybrid_device)
        {
            slot.hybrid_device_storage =
                allocatePureDeviceStorage(
                    hybrid_device_bytes,
                    state_.device_id);
            if (!slot.hybrid_device_storage)
            {
                return false;
            }
            slot.hybrid_device_capacity_bytes = hybrid_device_bytes;
        }

        if (needs_terminal_hidden_host)
        {
            slot.terminal_hidden_host_storage =
                std::make_shared<std::vector<uint8_t>>(terminal_hidden_bytes);
            slot.terminal_hidden_host_capacity_bytes =
                slot.terminal_hidden_host_storage->capacity();
        }

        if (needs_terminal_hidden_device)
        {
            slot.terminal_hidden_device_storage =
                allocatePureDeviceStorage(
                    terminal_hidden_bytes,
                    state_.device_id);
            if (!slot.terminal_hidden_device_storage)
            {
                return false;
            }
            slot.terminal_hidden_device_capacity_bytes =
                terminal_hidden_bytes;
        }

        live_checkpoint_storage_pool_.push_back(std::move(slot));
        assign_slot(live_checkpoint_storage_pool_.back());
        PerfStatsCollector::addCounter(
            "mtp",
            "live_prefix_checkpoint_storage_pool_misses",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"hybrid_host_bytes", std::to_string(hybrid_host_bytes)},
             {"hybrid_device_bytes", std::to_string(hybrid_device_bytes)},
             {"terminal_hidden_bytes", std::to_string(terminal_hidden_bytes)},
             {"pool_size", std::to_string(live_checkpoint_storage_pool_.size())}});
        return true;
    }

    PrefixStateSnapshot DeviceGraphOrchestrator::captureLivePrefixCheckpoint(int seq_idx) const
    {
        PrefixStateSnapshot snapshot;
        bool submitted_async_device_work = false;
        auto fail = [&](const std::string &reason) -> PrefixStateSnapshot
        {
            if (state_.device_id.is_gpu() &&
                submitted_async_device_work)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Live prefix checkpoint failed after submitting device work"
                          << " device=" << state_.device_id.toString()
                          << " seq_idx=" << seq_idx
                          << " reason=" << reason);
                /*
                 * A failed transaction has no completion event to retain its
                 * pooled destination. Returning would permit immediate slot
                 * reuse while a capture kernel or D2D copy still references
                 * that storage. This is an unrecoverable ownership violation.
                 */
                std::terminate();
            }
            /*
             * This path is the first safety gate for MTP transactions: before a
             * sidecar mutates speculative KV/GDN state, the runner captures a
             * rollback checkpoint for the live serial-decode state.  Returning
             * an empty snapshot is correct when the state is not safely
             * restorable, but the caller only sees a generic failure.  Keep a
             * structured reason here so multi-device tests can identify which
             * child and which checkpoint invariant failed.
             */
            PerfStatsCollector::addCounter(
                "mtp",
                "live_prefix_checkpoint_capture_failures",
                1.0,
                "decode",
                state_.device_id.toString(),
                {{"reason", reason},
                 {"seq_idx", std::to_string(seq_idx)}});
            LOG_WARN("[DeviceGraphOrchestrator] captureLivePrefixCheckpoint failed on "
                     << state_.device_id.toString()
                     << " seq_idx=" << seq_idx
                     << " reason=" << reason);
            return {};
        };

        if (!state_.kv_cache || seq_idx < 0 || seq_idx >= state_.batch_size)
        {
            return fail("missing_kv_cache_or_sequence_index_out_of_range");
        }

        void *stream = explicitGPUStreamForOperation("captureLivePrefixCheckpoint");
        if (state_.device_id.is_gpu() && !stream)
        {
            return fail("missing_explicit_gpu_stream");
        }
        if (!waitForLiveInferenceStateReadyForObservation(
                stream,
                "capture_live_prefix_checkpoint",
                DeviceTimelineRole::PrefixCheckpointArchive))
        {
            return fail("live_state_observation_wait_failed");
        }

        int cached_tokens = -1;
        if (state_.device_id.is_gpu())
        {
            /*
             * The host-side position is request planning input already known
             * at admission/publication. It sizes optional recurrent payloads
             * and performs a conservative headroom check; it is never adopted
             * as GPU cache truth. Exact canonical heads/counts are checkpointed
             * below and restored without a D2H observation.
             */
            if (seq_idx >= static_cast<int>(state_.positions.size()))
            {
                return fail("missing_request_planning_position");
            }
            cached_tokens = state_.positions[static_cast<size_t>(seq_idx)];
        }
        else
        {
            cached_tokens =
                restorablePrefixCachedTokens(*state_.kv_cache, seq_idx);
        }
        if (cached_tokens < 0 || cached_tokens > state_.kv_cache->max_seq_len())
        {
            return fail("cached_token_count_out_of_range");
        }

        const int draft_tokens =
            graph_builder_ ? std::max(1, graph_builder_->config().mtp.draft_tokens) : 1;
        const int main_headroom = draft_tokens + 2;
        if (liveCheckpointLacksHeadroom(*state_.kv_cache, cached_tokens, main_headroom))
        {
            return fail(
                "main_cache_lacks_speculative_headroom_cached_" +
                std::to_string(cached_tokens) +
                "_required_" + std::to_string(main_headroom) +
                "_capacity_" + std::to_string(state_.kv_cache->max_seq_len()));
        }

        /*
         * Plan every shifted-cache checkpoint before submitting the first
         * asynchronous copy. The former implementation discovered shifted GDN
         * state after copying the main cache, then abandoned the logical
         * checkpoint for a host payload snapshot. Besides making ordinary GPU
         * MTP host-owned, that could release a pool slot while its D2D copy was
         * still in flight. A complete preflight makes the transaction shape
         * immutable before any producer work reaches the stream.
         */
        struct ShiftedCheckpointPlan
        {
            int cached_tokens = -1;
            PrefixPayloadLayout hybrid_layout;
            bool captures_hybrid_state = false;
        };
        std::vector<ShiftedCheckpointPlan> shifted_checkpoint_plans(
            state_.mtp_kv_caches.size());
        for (size_t depth = 0; depth < state_.mtp_kv_caches.size(); ++depth)
        {
            const auto &cache = state_.mtp_kv_caches[depth];
            if (!cache)
                continue;

            const int mtp_cached_tokens =
                state_.device_id.is_gpu()
                    ? std::max(
                          0,
                          cached_tokens -
                              static_cast<int>(depth) - 1)
                    : restorablePrefixCachedTokens(*cache, seq_idx);
            if (mtp_cached_tokens < 0 ||
                mtp_cached_tokens > cache->max_seq_len())
            {
                return fail(
                    "mtp_cached_token_count_out_of_range_depth_" +
                    std::to_string(depth));
            }
            if (liveCheckpointLacksHeadroom(
                    *cache,
                    mtp_cached_tokens,
                    draft_tokens))
            {
                return fail(
                    "mtp_cache_lacks_speculative_headroom_depth_" +
                    std::to_string(depth) +
                    "_cached_" + std::to_string(mtp_cached_tokens) +
                    "_required_" + std::to_string(draft_tokens) +
                    "_capacity_" + std::to_string(cache->max_seq_len()));
            }

            ShiftedCheckpointPlan &plan = shifted_checkpoint_plans[depth];
            plan.cached_tokens = mtp_cached_tokens;
            if (mtp_cached_tokens > 0)
            {
                plan.hybrid_layout = liveHybridCheckpointLayout(
                    buildDensePrefixPayloadLayout(
                        *cache,
                        state_.device_id,
                        mtp_cached_tokens),
                    /*device_only=*/state_.device_id.is_gpu());
                plan.captures_hybrid_state =
                    plan.hybrid_layout.includes_hybrid_state &&
                    plan.hybrid_layout.hybrid_state_bytes > 0;
            }
        }

        snapshot.valid = true;
        snapshot.logical_checkpoint = true;
        snapshot.provenance = PrefixStateProvenance::LogicalCheckpoint;
        snapshot.cached_tokens = cached_tokens;
        snapshot.mtp_cached_tokens.assign(state_.mtp_kv_caches.size(), -1);
        for (size_t depth = 0; depth < shifted_checkpoint_plans.size(); ++depth)
        {
            snapshot.mtp_cached_tokens[depth] =
                shifted_checkpoint_plans[depth].cached_tokens;
        }
        bool queued_async_device_checkpoint_payload = false;

        if (state_.device_id.is_gpu())
        {
            auto capture_sequence_state =
                [&](int cache_depth,
                    const IKVCache &cache) -> bool
            {
                DeviceKVSequenceStateCheckpoint checkpoint;
                if (!acquireLiveDeviceSequenceStateStorage(
                        cache_depth,
                        seq_idx,
                        cache,
                        &checkpoint))
                {
                    return false;
                }

                std::string checkpoint_error;
                /*
                 * Treat the call as submitted before invoking the backend.
                 * A backend may discover a launch error only after partially
                 * accepting work; failure must therefore retain no pretense
                 * that the pooled destination can safely be reused.
                 */
                submitted_async_device_work = true;
                if (!cache.captureDeviceSequenceStateCheckpoint(
                        seq_idx,
                        checkpoint.data(),
                        checkpoint.bytes,
                        stream,
                        &checkpoint_error))
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Device sequence-state checkpoint capture failed"
                              << " cache_depth=" << cache_depth
                              << " error=" << checkpoint_error);
                    return false;
                }

                PerfStatsCollector::addCounter(
                    "mtp",
                    "live_prefix_checkpoint_device_sequence_state_captures",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {{"cache",
                      cache_depth < 0 ? "main" : "shifted"},
                     {"depth", std::to_string(cache_depth)},
                     {"bytes", std::to_string(checkpoint.bytes)},
                     {"implementation", "device_kernel"}});
                snapshot.device_sequence_state_checkpoints.push_back(
                    std::move(checkpoint));
                return true;
            };

            if (!capture_sequence_state(-1, *state_.kv_cache))
            {
                return fail("main_device_sequence_state_capture_failed");
            }
            for (size_t depth = 0;
                 depth < state_.mtp_kv_caches.size();
                 ++depth)
            {
                const auto &cache = state_.mtp_kv_caches[depth];
                if (!cache)
                    continue;
                if (!capture_sequence_state(
                        static_cast<int>(depth),
                        *cache))
                {
                    return fail(
                        "shifted_device_sequence_state_capture_failed_depth_" +
                        std::to_string(depth));
                }
            }
            queued_async_device_checkpoint_payload = true;
        }

        PrefixPayloadLayout main_layout;
        if (cached_tokens > 0)
        {
            PerfStatsCollector::ScopedTimer timer("mtp",
                                                  "live_prefix_checkpoint_layout",
                                                  "decode",
                                                  state_.device_id.toString(),
                                                  {{"cache", "main"}});
            main_layout = buildDensePrefixPayloadLayout(
                *state_.kv_cache,
                state_.device_id,
                cached_tokens);
        }

        size_t live_terminal_hidden_bytes = 0;
        const float *live_terminal_hidden_source = nullptr;
        const bool mtp_terminal_hidden_checkpoint_enabled =
            graph_builder_ &&
            graph_builder_->config().mtp.enabled &&
            cached_tokens > 0 &&
            state_.d_model > 0;
        if (graph_builder_ &&
            graph_builder_->config().mtp.enabled &&
            state_.prefix_terminal_hidden &&
            state_.mtp_terminal_hidden_current &&
            cached_tokens > 0 &&
            state_.d_model > 0)
        {
            live_terminal_hidden_bytes =
                static_cast<size_t>(state_.d_model) * sizeof(float);
        }
        else if (mtp_terminal_hidden_checkpoint_enabled &&
                 !state_.device_id.is_gpu() &&
                 state_.last_forward_batch_size == 1 &&
                 state_.last_forward_seq_len > 0 &&
                 state_.hidden)
        {
            /*
             * CPU logical checkpoints do not need to materialize the compact
             * PREFIX_TERMINAL_HIDDEN tensor just to publish accepted MTP state.
             * If the main forward produced a multi-row hidden tensor, copy the
             * terminal row directly from HIDDEN_STATE.  GPU keeps using the
             * explicit row-select path so stream ownership remains visible.
             */
            const auto &hidden_shape = state_.hidden->shape();
            const size_t hidden_rows = hidden_shape.empty() ? 0 : hidden_shape[0];
            const size_t terminal_row =
                static_cast<size_t>(std::max(0, state_.last_forward_seq_len - 1));
            const float *hidden_rows_fp32 = state_.hidden->fp32_data();
            if (hidden_rows_fp32 &&
                hidden_rows > terminal_row &&
                hidden_shape.size() >= 2 &&
                hidden_shape[1] >= static_cast<size_t>(state_.d_model))
            {
                live_terminal_hidden_source =
                    hidden_rows_fp32 + terminal_row * static_cast<size_t>(state_.d_model);
                live_terminal_hidden_bytes =
                    static_cast<size_t>(state_.d_model) * sizeof(float);
            }
        }

        if ((main_layout.includes_hybrid_state && main_layout.hybrid_state_bytes > 0) ||
            live_terminal_hidden_bytes > 0)
        {
            PrefixBlockHandle handle;
            handle.key.fingerprint = prefix_fingerprint_ != 0 ? prefix_fingerprint_ : 1;
            handle.key.block_index = 0;
            handle.key.token_start = 0;
            handle.key.token_count = cached_tokens;
            const bool device_only_checkpoint = state_.device_id.is_gpu();
            handle.layout = liveHybridCheckpointLayout(
                main_layout,
                device_only_checkpoint);
            if (live_terminal_hidden_bytes > 0)
            {
                handle.layout.terminal_hidden_bytes = live_terminal_hidden_bytes;
                handle.layout.includes_terminal_hidden = true;
            }
            handle.total_bytes = handle.layout.totalBytes();
            PerfStatsCollector::addCounter("mtp",
                                           "live_prefix_checkpoint_hybrid_host_bytes",
                                           static_cast<double>(handle.layout.hybrid_host_state_bytes),
                                           "decode",
                                           state_.device_id.toString());
            PerfStatsCollector::addCounter("mtp",
                                           "live_prefix_checkpoint_hybrid_device_bytes",
                                           static_cast<double>(handle.layout.hybrid_device_state_bytes),
                                           "decode",
                                           state_.device_id.toString());
            if (device_only_checkpoint)
            {
                PerfStatsCollector::addCounter("mtp",
                                               "live_prefix_checkpoint_hybrid_device_only_captures",
                                               1.0,
                                               "decode",
                                               state_.device_id.toString());
            }
            {
                PerfStatsCollector::ScopedTimer timer("mtp",
                                                      "live_prefix_checkpoint_hybrid_storage",
                                                      "decode",
                                                      state_.device_id.toString());
                if (!ensureLiveCheckpointStorage(handle))
                    return fail("checkpoint_storage_unavailable");
            }
            if (state_.device_id.is_gpu() &&
                !handle.live_checkpoint_ready_event)
            {
                return fail(
                    "checkpoint_storage_missing_preallocated_ready_event");
            }
            if (handle.layout.includes_hybrid_state && handle.layout.hybrid_state_bytes > 0)
            {
                PerfStatsCollector::ScopedTimer timer("mtp",
                                                      "live_prefix_checkpoint_hybrid_export",
                                                      "decode",
                                                      state_.device_id.toString());
                if (!exportHybridPrefixPayload(
                        *state_.kv_cache,
                        seq_idx,
                        cached_tokens,
                        &handle,
                        /*synchronize=*/false,
                        stream))
                {
                    return fail("hybrid_checkpoint_export_failed");
                }
                if (!handle.has_hybrid_state)
                {
                    return fail("hybrid_checkpoint_export_missing_payload");
                }
                queued_async_device_checkpoint_payload =
                    state_.device_id.is_gpu() &&
                    handle.layout.hybrid_device_state_bytes > 0;
            }
            if (live_terminal_hidden_bytes > 0)
            {
                if (state_.device_id.is_gpu())
                {
                    IBackend *backend = getBackendFor(state_.device_id);
                    const void *hidden_source =
                        state_.prefix_terminal_hidden
                            ? state_.prefix_terminal_hidden->gpu_data_ptr()
                            : nullptr;
                    void *hidden_destination =
                        handle.deviceTerminalHiddenData();
                    if (!backend ||
                        !hidden_source ||
                        !hidden_destination ||
                        !backend->deviceCopyAsync(
                            hidden_destination,
                            hidden_source,
                            live_terminal_hidden_bytes,
                            state_.device_id.gpu_ordinal(),
                            stream))
                    {
                        return fail(
                            "terminal_hidden_checkpoint_device_copy_failed");
                    }
                    queued_async_device_checkpoint_payload = true;
                }
                else
                {
                    const void *hidden_source =
                        live_terminal_hidden_source
                            ? static_cast<const void *>(
                                  live_terminal_hidden_source)
                            : state_.prefix_terminal_hidden->raw_data();
                    if (!hidden_source || !handle.terminal_hidden)
                    {
                        return fail(
                            "terminal_hidden_checkpoint_host_storage_unavailable");
                    }
                    std::memcpy(
                        handle.terminal_hidden,
                        hidden_source,
                        live_terminal_hidden_bytes);
                }
                handle.has_terminal_hidden = true;
                PerfStatsCollector::addCounter(
                    "mtp",
                    "live_prefix_checkpoint_terminal_hidden_captures",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {{"bytes", std::to_string(live_terminal_hidden_bytes)},
                     {"implementation",
                      state_.device_id.is_gpu()
                          ? "device_to_device"
                          : "host_copy"}});
            }
            snapshot.blocks.push_back(std::move(handle));
            if (main_layout.includes_hybrid_state && main_layout.hybrid_state_bytes > 0)
            {
                PerfStatsCollector::addCounter("mtp", "live_prefix_checkpoint_hybrid_state_captures", 1.0, "decode",
                                               state_.device_id.toString());
            }
        }

        for (size_t depth = 0; depth < state_.mtp_kv_caches.size(); ++depth)
        {
            const auto &cache = state_.mtp_kv_caches[depth];
            const ShiftedCheckpointPlan &plan =
                shifted_checkpoint_plans[depth];
            if (!cache || !plan.captures_hybrid_state)
                continue;

            PrefixBlockHandle handle;
            handle.key.fingerprint =
                prefix_fingerprint_ != 0 ? prefix_fingerprint_ : 1;
            handle.key.block_index = static_cast<int>(depth);
            handle.key.token_start = 0;
            handle.key.token_count = plan.cached_tokens;
            handle.layout = plan.hybrid_layout;
            handle.total_bytes = handle.layout.totalBytes();

            if (!ensureLiveCheckpointStorage(handle))
            {
                return fail(
                    "shifted_hybrid_checkpoint_storage_unavailable_depth_" +
                    std::to_string(depth));
            }
            if (state_.device_id.is_gpu() &&
                !handle.live_checkpoint_ready_event)
            {
                return fail(
                    "shifted_hybrid_checkpoint_missing_preallocated_ready_event_depth_" +
                    std::to_string(depth));
            }
            if (!exportHybridPrefixPayload(
                    *cache,
                    seq_idx,
                    plan.cached_tokens,
                    &handle,
                    /*synchronize=*/false,
                    stream))
            {
                return fail(
                    "shifted_hybrid_checkpoint_export_failed_depth_" +
                    std::to_string(depth));
            }
            if (!handle.has_hybrid_state)
            {
                return fail(
                    "shifted_hybrid_checkpoint_payload_missing_depth_" +
                    std::to_string(depth));
            }

            queued_async_device_checkpoint_payload =
                queued_async_device_checkpoint_payload ||
                (state_.device_id.is_gpu() &&
                 handle.layout.hybrid_device_state_bytes > 0);
            snapshot.mtp_blocks.push_back(std::move(handle));
            PerfStatsCollector::addCounter(
                "mtp",
                "live_prefix_checkpoint_shifted_hybrid_state_captures",
                1.0,
                "decode",
                state_.device_id.toString(),
                {{"depth", std::to_string(depth)},
                 {"cached_tokens", std::to_string(plan.cached_tokens)},
                 {"implementation",
                  state_.device_id.is_gpu()
                      ? "device_to_device"
                      : "host_copy"}});
        }

        if (queued_async_device_checkpoint_payload &&
            !recordLivePrefixCheckpointReady(
                &snapshot,
                stream,
                "capture_live_prefix_checkpoint"))
        {
            return fail("checkpoint_ready_event_record_failed");
        }

        PerfStatsCollector::addCounter("mtp", "live_prefix_checkpoint_logical_captures", 1.0, "decode",
                                       state_.device_id.toString());
        return snapshot;
    }

    bool DeviceGraphOrchestrator::restoreLivePrefixState(const PrefixStateSnapshot &snapshot, int seq_idx)
    {
        bool submitted_async_device_mutation = false;
        auto fail = [&](const std::string &reason) -> bool
        {
            LOG_ERROR("[DeviceGraphOrchestrator] restoreLivePrefixState failed: " << reason);
            if (state_.device_id.is_gpu() &&
                submitted_async_device_mutation)
            {
                /*
                 * Once restore reads or writes are queued, returning would
                 * release snapshot-owned source allocations without a
                 * completion event. There is no legal synchronous cleanup or
                 * fallback path for that ownership violation.
                 */
                std::terminate();
            }
            return false;
        };

        if (!snapshot.valid || !state_.kv_cache || seq_idx < 0 || seq_idx >= state_.batch_size)
        {
            return fail("invalid snapshot, missing KV cache, or sequence index out of range");
        }
        if (snapshot.cached_tokens < 0 || snapshot.cached_tokens > state_.kv_cache->max_seq_len())
        {
            return fail("cached token count out of range: cached_tokens=" +
                        std::to_string(snapshot.cached_tokens) +
                        " max_seq_len=" + std::to_string(state_.kv_cache->max_seq_len()));
        }

        void *stream = explicitGPUStreamForOperation("restoreLivePrefixState");
        if (state_.device_id.is_gpu() && !stream)
        {
            return fail("missing explicit GPU stream");
        }
        if (!waitForPendingRequestStateReset(
                stream,
                DeviceTimelineRole::PrefixRestoreMutation,
                "restore_live_prefix_request_state_reset"))
        {
            return fail("request-state reset wait failed");
        }
        if (!waitForPendingLivePrefixCheckpointReady(
                stream,
                "restore_live_prefix_state_source"))
        {
            return fail("pending live prefix checkpoint source wait failed");
        }
        if (!waitForPendingLivePrefixMutationReady(
                stream,
                "restore_live_prefix_state_previous_mutation"))
        {
            return fail("pending live prefix mutation wait failed");
        }
        if (!waitForSnapshotReady(
                snapshot,
                stream,
                "restore_live_prefix_state_snapshot"))
        {
            return fail("prefix snapshot readiness wait failed");
        }
        if (!waitForPendingLiveGraphProducersBeforePrefixMutation(
                stream,
                "restore_live_prefix_state"))
        {
            return fail("pending live graph producer wait failed");
        }
        if (!prepareLivePrefixMutationReadyEvent(
                stream,
                "restore_live_prefix_state"))
        {
            return fail("could not preflight live-state readiness event");
        }

        /*
         * Restoring KV/GDN/position state invalidates any previously current
         * terminal-hidden sidecar input unless this snapshot explicitly
         * carries a matching terminal-hidden payload.  Leaving the flag set
         * after a hidden-less restore can combine fresh restored caches with an
         * old PREFIX_TERMINAL_HIDDEN row on the next MTP sidecar step.
         */
        if (graph_builder_ && graph_builder_->config().mtp.enabled)
        {
            state_.mtp_terminal_hidden_current = false;
        }

        if (snapshot.logical_checkpoint)
        {
            if (snapshot.blocks.size() > 1)
            {
                return fail("logical checkpoint contains more than one hybrid payload block");
            }
            const PrefixBlockHandle *hybrid_handle = nullptr;
            if (!snapshot.blocks.empty())
            {
                hybrid_handle = &snapshot.blocks.front();
                const bool includes_hybrid_state =
                    hybrid_handle->layout.includes_hybrid_state &&
                    hybrid_handle->layout.hybrid_state_bytes > 0;
                const bool includes_terminal_hidden =
                    hybrid_handle->layout.includes_terminal_hidden &&
                    hybrid_handle->layout.terminal_hidden_bytes > 0;
                const bool terminal_hidden_source_available =
                    state_.device_id.is_gpu()
                        ? hybrid_handle->deviceTerminalHiddenData() != nullptr
                        : hybrid_handle->terminal_hidden != nullptr;
                if ((!includes_hybrid_state && !includes_terminal_hidden) ||
                    (includes_hybrid_state &&
                     (!hybrid_handle->has_hybrid_state ||
                      (hybrid_handle->layout.hybrid_host_state_bytes > 0 && !hybrid_handle->hybrid_payload) ||
                      (hybrid_handle->layout.hybrid_device_state_bytes > 0 && !hybridPayloadDevicePtr(*hybrid_handle)))) ||
                    (includes_terminal_hidden &&
                     (!hybrid_handle->has_terminal_hidden ||
                      !terminal_hidden_source_available)) ||
                    hybrid_handle->key.token_start != 0 ||
                    hybrid_handle->key.token_count != snapshot.cached_tokens)
                {
                    return fail("logical checkpoint payload block is invalid");
                }
            }
            if (snapshot.mtp_cached_tokens.size() != state_.mtp_kv_caches.size())
            {
                return fail("logical checkpoint MTP cache count does not match runner state");
            }

            const DeviceKVSequenceStateCheckpoint *main_sequence_checkpoint =
                nullptr;
            std::vector<const DeviceKVSequenceStateCheckpoint *>
                shifted_sequence_checkpoints(
                    state_.mtp_kv_caches.size(),
                    nullptr);
            if (state_.device_id.is_gpu())
            {
                for (const DeviceKVSequenceStateCheckpoint &checkpoint :
                     snapshot.device_sequence_state_checkpoints)
                {
                    if (!checkpoint.valid() ||
                        checkpoint.device != state_.device_id ||
                        checkpoint.sequence_index != seq_idx)
                    {
                        return fail(
                            "logical checkpoint contains an invalid or foreign device sequence-state payload");
                    }

                    IKVCache *checkpoint_cache = nullptr;
                    if (checkpoint.cache_depth < 0)
                    {
                        if (main_sequence_checkpoint)
                        {
                            return fail(
                                "logical checkpoint contains duplicate main device sequence state");
                        }
                        main_sequence_checkpoint = &checkpoint;
                        checkpoint_cache = state_.kv_cache.get();
                    }
                    else
                    {
                        const int depth = checkpoint.cache_depth;
                        if (depth >= static_cast<int>(
                                         state_.mtp_kv_caches.size()) ||
                            shifted_sequence_checkpoints[
                                static_cast<size_t>(depth)])
                        {
                            return fail(
                                "logical checkpoint contains an invalid or duplicate shifted device sequence-state depth");
                        }
                        checkpoint_cache =
                            state_.mtp_kv_caches[
                                static_cast<size_t>(depth)]
                                .get();
                        shifted_sequence_checkpoints[
                            static_cast<size_t>(depth)] = &checkpoint;
                    }

                    if (!checkpoint_cache ||
                        checkpoint.bytes !=
                            checkpoint_cache
                                ->deviceSequenceStateCheckpointBytes())
                    {
                        return fail(
                            "logical checkpoint device sequence-state layout does not match its live cache");
                    }
                }

                if (!main_sequence_checkpoint)
                {
                    return fail(
                        "GPU logical checkpoint is missing main device sequence state");
                }
                for (size_t depth = 0;
                     depth < state_.mtp_kv_caches.size();
                     ++depth)
                {
                    if (state_.mtp_kv_caches[depth] &&
                        !shifted_sequence_checkpoints[depth])
                    {
                        return fail(
                            "GPU logical checkpoint is missing shifted device sequence state for depth=" +
                            std::to_string(depth));
                    }
                }
            }
            else if (!snapshot.device_sequence_state_checkpoints.empty())
            {
                return fail(
                    "CPU logical checkpoint unexpectedly carries GPU sequence state");
            }
            if (snapshot.cached_tokens == 0 &&
                state_.device_id.is_gpu() &&
                dynamic_cast<IHybridKVCache *>(state_.kv_cache.get()))
            {
                return fail(
                    "zero-token hybrid logical checkpoint restore requires a streamful recurrent-state reset");
            }

            /*
             * Shifted MTP caches have independent GDN/short-conv recurrent
             * banks. Truncating their logical token counts cannot reconstruct
             * those banks, so every non-empty hybrid shifted cache must carry
             * exactly one hybrid-only checkpoint handle. Validate the complete
             * map before mutating any live cache; a partial snapshot must never
             * leave half of the transaction restored.
             */
            std::vector<const PrefixBlockHandle *> shifted_hybrid_handles(
                state_.mtp_kv_caches.size(),
                nullptr);
            for (const PrefixBlockHandle &handle : snapshot.mtp_blocks)
            {
                const int depth = handle.key.block_index;
                if (depth < 0 ||
                    depth >= static_cast<int>(state_.mtp_kv_caches.size()))
                {
                    return fail(
                        "logical checkpoint shifted hybrid depth out of range: " +
                        std::to_string(depth));
                }
                const auto &cache =
                    state_.mtp_kv_caches[static_cast<size_t>(depth)];
                const int mtp_cached_tokens =
                    snapshot.mtp_cached_tokens[static_cast<size_t>(depth)];
                if (!cache || mtp_cached_tokens <= 0)
                {
                    return fail(
                        "logical checkpoint carries shifted hybrid state for an empty or missing cache at depth=" +
                        std::to_string(depth));
                }
                if (shifted_hybrid_handles[static_cast<size_t>(depth)])
                {
                    return fail(
                        "logical checkpoint contains duplicate shifted hybrid state at depth=" +
                        std::to_string(depth));
                }

                const PrefixPayloadLayout expected =
                    liveHybridCheckpointLayout(
                        buildDensePrefixPayloadLayout(
                            *cache,
                            state_.device_id,
                            mtp_cached_tokens),
                        /*device_only=*/state_.device_id.is_gpu());
                const bool source_available =
                    state_.device_id.is_gpu()
                        ? hybridPayloadDevicePtr(handle) != nullptr
                        : hybridPayloadHostPtr(handle) != nullptr;
                if (!handle.valid() ||
                    handle.key.token_start != 0 ||
                    handle.key.token_count != mtp_cached_tokens ||
                    !expected.includes_hybrid_state ||
                    expected.hybrid_state_bytes == 0 ||
                    !handle.layout.compatiblePayloadShape(expected) ||
                    !handle.has_hybrid_state ||
                    !source_available)
                {
                    return fail(
                        "logical checkpoint shifted hybrid payload is invalid at depth=" +
                        std::to_string(depth));
                }
                shifted_hybrid_handles[static_cast<size_t>(depth)] = &handle;
            }

            bool main_sequence_state_restored = false;
            if (state_.device_id.is_gpu())
            {
                std::string checkpoint_error;
                submitted_async_device_mutation = true;
                main_sequence_state_restored =
                    state_.kv_cache
                        ->restoreDeviceSequenceStateCheckpoint(
                            seq_idx,
                            main_sequence_checkpoint->data(),
                            main_sequence_checkpoint->bytes,
                            stream,
                            &checkpoint_error);
                if (!main_sequence_state_restored)
                {
                    return fail(
                        "main device sequence-state restore failed: " +
                        checkpoint_error);
                }
                PerfStatsCollector::addCounter(
                    "mtp",
                    "live_prefix_checkpoint_device_sequence_state_restores",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {{"cache", "main"},
                     {"depth", "-1"},
                     {"bytes",
                      std::to_string(main_sequence_checkpoint->bytes)},
                     {"implementation", "device_kernel"}});
            }
            else
            {
                main_sequence_state_restored =
                    state_.kv_cache->truncateSequence(
                        seq_idx,
                        snapshot.cached_tokens,
                        stream);
            }
            if (!main_sequence_state_restored)
            {
                return fail("main KV logical checkpoint truncate failed for tokens=" +
                            std::to_string(snapshot.cached_tokens));
            }
            if (snapshot.cached_tokens == 0)
            {
                if (!resetHybridPrefixPayloadState(
                        *state_.kv_cache,
                        IKVCache::StateResetContext{
                            .boundary =
                                IKVCache::StateResetBoundary::PrefixReplacement,
                            .execution_stream = stream,
                            .reason = "restore-logical-checkpoint-zero",
                        }))
                {
                    return fail(
                        "zero-token logical checkpoint GDN reset failed");
                }
            }
            else if (hybrid_handle)
            {
                if (hybrid_handle->layout.includes_hybrid_state &&
                    hybrid_handle->layout.hybrid_state_bytes > 0)
                {
                    PerfStatsCollector::ScopedTimer timer("mtp",
                                                          "restore_live_prefix_checkpoint_hybrid_import",
                                                          "decode",
                                                          state_.device_id.toString());
                    if (!importHybridPrefixPayload(
                            *state_.kv_cache,
                            *hybrid_handle,
                            seq_idx,
                            /*restore_for_suffix_prefill=*/false,
                            /*synchronize=*/false,
                            stream))
                    {
                        return fail("logical checkpoint hybrid payload import failed");
                    }
                }
                if (hybrid_handle->layout.includes_terminal_hidden &&
                    hybrid_handle->layout.terminal_hidden_bytes > 0)
                {
                    if (!restoreLiveCheckpointTerminalHidden(
                            *hybrid_handle,
                            stream,
                            "restore_logical_checkpoint",
                            /*publish_mailbox=*/false))
                    {
                        return fail(
                            "logical checkpoint terminal hidden restore failed");
                    }
                }
            }

            for (size_t depth = 0; depth < state_.mtp_kv_caches.size(); ++depth)
            {
                auto &cache = state_.mtp_kv_caches[depth];
                const int mtp_cached_tokens = snapshot.mtp_cached_tokens[depth];
                if (!cache)
                {
                    if (mtp_cached_tokens >= 0)
                    {
                        return fail("logical checkpoint contains MTP tokens for a missing cache");
                    }
                    continue;
                }
                if (mtp_cached_tokens < 0 || mtp_cached_tokens > cache->max_seq_len())
                {
                    return fail("logical checkpoint MTP token count out of range for depth=" +
                                std::to_string(depth) +
                                " tokens=" + std::to_string(mtp_cached_tokens));
                }
                bool shifted_sequence_state_restored = false;
                if (state_.device_id.is_gpu())
                {
                    const DeviceKVSequenceStateCheckpoint *checkpoint =
                        shifted_sequence_checkpoints[depth];
                    std::string checkpoint_error;
                    submitted_async_device_mutation = true;
                    shifted_sequence_state_restored =
                        cache->restoreDeviceSequenceStateCheckpoint(
                            seq_idx,
                            checkpoint->data(),
                            checkpoint->bytes,
                            stream,
                            &checkpoint_error);
                    if (!shifted_sequence_state_restored)
                    {
                        return fail(
                            "MTP device sequence-state restore failed for depth=" +
                            std::to_string(depth) +
                            ": " + checkpoint_error);
                    }
                    PerfStatsCollector::addCounter(
                        "mtp",
                        "live_prefix_checkpoint_device_sequence_state_restores",
                        1.0,
                        "decode",
                        state_.device_id.toString(),
                        {{"cache", "shifted"},
                         {"depth", std::to_string(depth)},
                         {"bytes", std::to_string(checkpoint->bytes)},
                         {"implementation", "device_kernel"}});
                }
                else
                {
                    shifted_sequence_state_restored =
                        cache->truncateSequence(
                            seq_idx,
                            mtp_cached_tokens,
                            stream);
                }
                if (!shifted_sequence_state_restored)
                {
                    return fail("MTP KV logical checkpoint truncate failed for depth=" +
                                std::to_string(depth) +
                                " tokens=" + std::to_string(mtp_cached_tokens));
                }

                const bool expects_hybrid_checkpoint =
                    liveCheckpointHasHybridState(
                        *cache,
                        state_.device_id,
                        mtp_cached_tokens);
                const PrefixBlockHandle *shifted_hybrid_handle =
                    shifted_hybrid_handles[depth];
                if (expects_hybrid_checkpoint && !shifted_hybrid_handle)
                {
                    return fail(
                        "logical checkpoint is missing shifted hybrid state for depth=" +
                        std::to_string(depth));
                }
                if (!expects_hybrid_checkpoint && shifted_hybrid_handle)
                {
                    return fail(
                        "logical checkpoint has unexpected shifted hybrid state for depth=" +
                        std::to_string(depth));
                }
                if (shifted_hybrid_handle &&
                    !importHybridPrefixPayload(
                        *cache,
                        *shifted_hybrid_handle,
                        seq_idx,
                        /*restore_for_suffix_prefill=*/false,
                        /*synchronize=*/false,
                        stream))
                {
                    return fail(
                        "logical checkpoint shifted hybrid payload import failed for depth=" +
                        std::to_string(depth));
                }
            }

            state_.positions[seq_idx] = snapshot.cached_tokens;
            state_.sequence_lengths[seq_idx] = snapshot.cached_tokens;
            handleLivePrefixReplayStateAfterMutation(
                LivePrefixMutationReason::PrefixRestore,
                "restore_logical_checkpoint");
            std::vector<PrefixBlockHandle> retained_snapshot_sources;
            std::vector<std::shared_ptr<void>>
                retained_device_sequence_sources;
            if (state_.device_id.is_gpu())
            {
                retained_snapshot_sources = snapshot.blocks;
                retained_snapshot_sources.insert(
                    retained_snapshot_sources.end(),
                    snapshot.mtp_blocks.begin(),
                    snapshot.mtp_blocks.end());
                retained_device_sequence_sources.reserve(
                    snapshot.device_sequence_state_checkpoints.size());
                for (const DeviceKVSequenceStateCheckpoint &checkpoint :
                     snapshot.device_sequence_state_checkpoints)
                {
                    retained_device_sequence_sources.push_back(
                        checkpoint.storage);
                }
            }
            if (!recordLivePrefixMutationReady(
                    stream,
                    "restore_logical_checkpoint",
                    std::move(retained_snapshot_sources),
                    std::move(retained_device_sequence_sources)))
            {
                return fail("logical checkpoint restore could not record live-state readiness");
            }
            submitted_async_device_mutation = false;
            if (!recordRestoredDeviceResidentMTPTransaction(
                    stream,
                    "restore_logical_checkpoint_shifted_kv"))
            {
                return fail("logical checkpoint restore could not publish restored shifted-MTP KV ownership");
            }
            return true;
        }

        if (state_.device_id.is_gpu())
        {
            submitted_async_device_mutation = true;
        }
        if (!state_.kv_cache->truncateSequence(seq_idx, 0, stream))
        {
            return fail("main KV payload checkpoint clear failed");
        }
        for (auto &cache : state_.mtp_kv_caches)
        {
            if (cache)
            {
                if (!cache->truncateSequence(seq_idx, 0, stream))
                {
                    return fail("MTP KV payload checkpoint clear failed");
                }
            }
        }

        if (snapshot.cached_tokens == 0)
        {
            if (!snapshot.mtp_blocks.empty())
            {
                return fail("zero-token snapshot unexpectedly contains MTP blocks");
            }
            if (state_.device_id.is_gpu() &&
                dynamic_cast<IHybridKVCache *>(state_.kv_cache.get()))
            {
                return fail("zero-token hybrid payload checkpoint restore requires streamful GDN reset");
            }
            if (!resetHybridPrefixPayloadState(
                    *state_.kv_cache,
                    IKVCache::StateResetContext{
                        .boundary =
                            IKVCache::StateResetBoundary::PrefixReplacement,
                        .execution_stream = stream,
                        .reason = "restore-payload-checkpoint-zero",
                    }))
            {
                return fail("zero-token payload checkpoint GDN reset failed");
            }
            state_.positions[seq_idx] = 0;
            state_.sequence_lengths[seq_idx] = 0;
            handleLivePrefixReplayStateAfterMutation(
                LivePrefixMutationReason::PrefixRestore,
                "restore_payload_checkpoint_zero");
            if (!recordLivePrefixMutationReady(
                    stream,
                    "restore_payload_checkpoint_zero"))
            {
                return fail("zero-token payload checkpoint restore could not record live-state readiness");
            }
            submitted_async_device_mutation = false;
            if (!recordRestoredDeviceResidentMTPTransaction(
                    stream,
                    "restore_payload_checkpoint_zero_shifted_kv"))
            {
                return fail("zero-token payload checkpoint restore could not publish restored shifted-MTP KV ownership");
            }
            return true;
        }

        for (const auto &handle : snapshot.blocks)
        {
            if (!handle.valid() || !handle.kvKData() || !handle.kvVData())
            {
                return fail("main KV block handle is invalid");
            }

            PrefixPayloadLayout expected = buildDensePrefixPayloadLayout(
                *state_.kv_cache,
                state_.device_id,
                handle.key.token_count,
                handle.layout.terminal_hidden_bytes,
                handle.layout.terminal_logits_bytes);
            if (!handle.layout.compatiblePayloadShape(expected))
            {
                return fail("main KV block layout is incompatible");
            }

            for (int local_layer = 0; local_layer < handle.layout.fa_layers; ++local_layer)
            {
                const int global_layer = prefixFALayerForIndex(*state_.kv_cache, local_layer);
                if (global_layer < 0)
                {
                    return fail("main KV block layer index is invalid");
                }
                const uint8_t *k_src = handle.kvKData() +
                                       static_cast<size_t>(local_layer) * handle.layout.bytes_per_fa_layer_k;
                const uint8_t *v_src = handle.kvVData() +
                                       static_cast<size_t>(local_layer) * handle.layout.bytes_per_fa_layer_v;

                IKVCache::KVCacheLogicalBlockDescriptor desc;
                desc.layer = global_layer;
                desc.seq_idx = seq_idx;
                desc.logical_token_start = handle.key.token_start;
                desc.token_count = handle.key.token_count;
                desc.stream = stream;
                if (!state_.kv_cache->importLogicalBlock(desc, k_src, v_src))
                {
                    return fail("main KV logical block import failed for layer=" +
                                std::to_string(global_layer) +
                                " tokens=" + std::to_string(handle.key.token_count));
                }
            }
        }

        if (!snapshot.blocks.empty() &&
            !importHybridPrefixPayload(
                *state_.kv_cache,
                snapshot.blocks.back(),
                seq_idx,
                /*restore_for_suffix_prefill=*/false,
                /*synchronize=*/true,
                stream))
        {
            return fail("hybrid payload import failed");
        }

        if (!snapshot.blocks.empty())
        {
            const PrefixBlockHandle &terminal_handle = snapshot.blocks.back();
            if (terminal_handle.layout.includes_terminal_hidden &&
                terminal_handle.layout.terminal_hidden_bytes > 0)
            {
                if (!restoreLiveCheckpointTerminalHidden(
                        terminal_handle,
                        stream,
                        "restore_payload_checkpoint",
                        /*publish_mailbox=*/false))
                {
                    return fail(
                        "payload checkpoint terminal hidden restore failed");
                }
            }
        }

        for (const auto &handle : snapshot.mtp_blocks)
        {
            if (!handle.valid() || !handle.kvKData() || !handle.kvVData())
            {
                return fail("MTP KV block handle is invalid");
            }

            const int depth = handle.key.block_index;
            if (depth < 0 || depth >= static_cast<int>(state_.mtp_kv_caches.size()))
            {
                return fail("MTP KV block depth out of range: depth=" +
                            std::to_string(depth) +
                            " caches=" + std::to_string(state_.mtp_kv_caches.size()));
            }
            auto &cache = state_.mtp_kv_caches[static_cast<size_t>(depth)];
            if (!cache || handle.key.token_count < 0 || handle.key.token_count > cache->max_seq_len())
            {
                return fail("MTP KV block token count out of range: tokens=" +
                            std::to_string(handle.key.token_count));
            }

            PrefixPayloadLayout expected = buildDensePrefixPayloadLayout(
                *cache,
                state_.device_id,
                handle.key.token_count);
            if (!handle.layout.compatiblePayloadShape(expected))
            {
                return fail("MTP KV block layout is incompatible");
            }

            for (int local_layer = 0; local_layer < handle.layout.fa_layers; ++local_layer)
            {
                const int global_layer = prefixFALayerForIndex(*cache, local_layer);
                if (global_layer < 0)
                {
                    return fail("MTP KV block layer index is invalid");
                }
                const uint8_t *k_src = handle.kvKData() +
                                       static_cast<size_t>(local_layer) * handle.layout.bytes_per_fa_layer_k;
                const uint8_t *v_src = handle.kvVData() +
                                       static_cast<size_t>(local_layer) * handle.layout.bytes_per_fa_layer_v;

                IKVCache::KVCacheLogicalBlockDescriptor desc;
                desc.layer = global_layer;
                desc.seq_idx = seq_idx;
                desc.logical_token_start = handle.key.token_start;
                desc.token_count = handle.key.token_count;
                desc.stream = stream;
                if (!cache->importLogicalBlock(desc, k_src, v_src))
                {
                    return fail("MTP KV logical block import failed for layer=" +
                                std::to_string(global_layer) +
                                " tokens=" + std::to_string(handle.key.token_count));
                }
            }
        }

        state_.positions[seq_idx] = snapshot.cached_tokens;
        state_.sequence_lengths[seq_idx] = snapshot.cached_tokens;
        handleLivePrefixReplayStateAfterMutation(
            LivePrefixMutationReason::PrefixRestore,
            "restore_payload_checkpoint");
        std::vector<PrefixBlockHandle> retained_snapshot_sources;
        if (state_.device_id.is_gpu())
        {
            retained_snapshot_sources = snapshot.blocks;
            retained_snapshot_sources.insert(
                retained_snapshot_sources.end(),
                snapshot.mtp_blocks.begin(),
                snapshot.mtp_blocks.end());
        }
        if (!recordLivePrefixMutationReady(
                stream,
                "restore_payload_checkpoint",
                std::move(retained_snapshot_sources)))
        {
            return fail("payload checkpoint restore could not record live-state readiness");
        }
        submitted_async_device_mutation = false;
        if (!recordRestoredDeviceResidentMTPTransaction(
                stream,
                "restore_payload_checkpoint_shifted_kv"))
        {
            return fail("payload checkpoint restore could not publish restored shifted-MTP KV ownership");
        }
        return true;
    }

    bool DeviceGraphOrchestrator::truncateLivePrefixState(int cached_tokens, int seq_idx)
    {
        if (!state_.kv_cache || seq_idx < 0 || seq_idx >= state_.batch_size)
        {
            return false;
        }
        void *stream = explicitGPUStreamForOperation("truncateLivePrefixState");
        if (state_.device_id.is_gpu() && !stream)
        {
            return false;
        }
        if (!waitForPendingRequestStateReset(
                stream,
                DeviceTimelineRole::PrefixRestoreMutation,
                "truncate_live_prefix_request_state_reset"))
        {
            return false;
        }
        if (!waitForPendingLivePrefixCheckpointReady(
                stream,
                "truncate_live_prefix_source"))
        {
            return false;
        }
        if (!waitForPendingLivePrefixMutationReady(
                stream,
                "truncate_live_prefix_previous_mutation"))
        {
            return false;
        }
        if (!waitForPendingLiveGraphProducersBeforePrefixMutation(
                stream,
                "truncate_live_prefix"))
        {
            return false;
        }
        if (!prepareLivePrefixMutationReadyEvent(
                stream,
                "truncate_live_prefix"))
        {
            return false;
        }
        if (!state_.kv_cache->truncateSequence(seq_idx, cached_tokens, stream))
        {
            return false;
        }
        for (size_t depth = 0; depth < state_.mtp_kv_caches.size(); ++depth)
        {
            auto &cache = state_.mtp_kv_caches[depth];
            if (!cache)
            {
                continue;
            }
            const int shifted_count = std::max(
                0,
                cached_tokens - static_cast<int>(depth) - 1);
            const int bounded_count = std::min(shifted_count, cache->max_seq_len());
            if (!cache->truncateSequence(seq_idx, bounded_count, stream))
            {
                return false;
            }
        }
        state_.positions[seq_idx] = cached_tokens;
        state_.sequence_lengths[seq_idx] = cached_tokens;
        handleLivePrefixReplayStateAfterMutation(
            LivePrefixMutationReason::PrefixTruncate,
            "truncate_live_prefix");
        if (!recordLivePrefixMutationReady(
                stream,
                "truncate_live_prefix"))
        {
            return false;
        }
        return true;
    }

    bool DeviceGraphOrchestrator::mtpSpecStatePublicationRequiresCapturedStage() const
    {
        if (!graph_builder_ || !graph_builder_->config().mtp.enabled || !state_.kv_cache)
        {
            return false;
        }

        auto *hybrid = dynamic_cast<IHybridKVCache *>(state_.kv_cache.get());
        if (!hybrid)
        {
            return false;
        }

        for (int layer = 0; layer < state_.kv_cache->n_layers(); ++layer)
        {
            if (hybrid->isGDNLayer(layer))
            {
                return true;
            }
        }
        return false;
    }

    bool DeviceGraphOrchestrator::requiresMTPDecodeEquivalentVerifierReplay() const
    {
        return mtpSpecStatePublicationRequiresCapturedStage() &&
               !supportsMTPSpecStatePublication();
    }

    int DeviceGraphOrchestrator::sampleGreedyOnDevice()
    {
        // LmHeadStage always writes the last-token logits to row 0 for both
        // prefill and decode.  In GlobalTP/NodeLocalTP, the terminal restore path
        // repopulates logits_local, so greedy sampling must use the shard-local
        // tensor and coordinate the winning candidate across ranks.
        if (activeMainLogitsAreColumnParallel())
        {
            const int token_offset = vocabOffsetForTPConfig(graph_builder_->config());
            void *stream = nullptr;
            auto device_opt = state_.logits_local->current_device();
            if (device_opt.has_value() && device_opt->is_gpu())
            {
                stream = consumePendingLogitsStream(
                    PendingLogitsStreamRole::MainDecode,
                    "sampleGreedyOnDeviceLocal");
                if (!stream)
                    stream = explicitGPUStreamForOperation("sampleGreedyOnDeviceLocal");
                if (!stream)
                {
                    return -1;
                }
            }
            return coordinateGreedyCandidate(
                sampleGreedyCandidateFromTensor(state_.logits_local.get(),
                                                0,
                                                token_offset,
                                                argmax_partial_vals_dev_,
                                                argmax_partial_idxs_dev_,
                                                argmax_partial_capacity_,
                                                stream,
                                                "logits_local"),
                globalTPContextForMTPCoordination());
        }

        if (!state_.logits)
            return -1;

        void *stream = nullptr;
        auto device_opt = state_.logits->current_device();
        if (device_opt.has_value() && device_opt->is_gpu())
        {
            stream = consumePendingLogitsStream(
                PendingLogitsStreamRole::MainDecode,
                "sampleGreedyOnDevice");
            if (!stream)
                stream = explicitGPUStreamForOperation("sampleGreedyOnDevice");
            if (!stream)
            {
                return -1;
            }
        }
        return coordinateGreedyCandidate(
            sampleGreedyCandidateFromTensor(state_.logits.get(),
                                            0,
                                            0,
                                            argmax_partial_vals_dev_,
                                            argmax_partial_idxs_dev_,
                                            argmax_partial_capacity_,
                                            stream,
                                            "logits"),
            globalTPContextForMTPCoordination());
    }

    int DeviceGraphOrchestrator::sampleOnDevice(const SamplingParams &params)
    {
        return sampleOnDeviceAtLogicalPosition(params, get_position());
    }

    int DeviceGraphOrchestrator::sampleOnDeviceAtLogicalPosition(
        const SamplingParams &params,
        int logical_position)
    {
        if (params.is_greedy())
        {
            return sampleGreedyOnDevice();
        }
        if (!state_.device_id.is_gpu() || !state_.logits)
        {
            return -1;
        }
        if (activeMainLogitsAreColumnParallel())
        {
            return -1;
        }
        if (params.top_k <= 0 || params.top_k > 256)
        {
            LOG_DEBUG("[DeviceGraphOrchestrator] GPU stochastic sampling requires 1 <= top_k <= 256; got top_k="
                      << params.top_k);
            return -1;
        }
        if (!state_.logits->deviceValid())
        {
            return -1;
        }

        void *gpu_ptr = state_.logits->gpu_data_ptr();
        if (!gpu_ptr)
        {
            return -1;
        }

        const auto &shape = state_.logits->shape();
        if (shape.empty())
        {
            return -1;
        }
        const size_t rows = shape.size() >= 2 ? shape[0] : 1;
        const size_t cols = shape.size() >= 2 ? shape[1] : shape[0];
        if (rows < 1 || cols == 0 || cols > static_cast<size_t>(std::numeric_limits<int>::max()))
        {
            return -1;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
        {
            return -1;
        }
        void *stream = consumePendingLogitsStream(
            PendingLogitsStreamRole::MainDecode,
            "sampleOnDevice");
        if (!stream)
            stream = explicitGPUStreamForOperation("sampleOnDevice");
        if (!stream)
        {
            return -1;
        }

        int token = -1;
        const bool seeded = params.seed != 0;
        const uint64_t seed =
            seeded ? static_cast<uint64_t>(params.seed)
                   : (0xD1B54A32D192ED03ull ^
                      (session_epoch_ * 0x9E3779B97F4A7C15ull));
        const uint64_t offset =
            seeded
                ? static_cast<uint64_t>(std::max(0, logical_position)) *
                      sampling_math::kMTPSpecDrawPurposesPerToken
                : device_sampling_counter_++;
        const bool ok = backend->sampleTopKTopPF32(
            static_cast<const float *>(gpu_ptr),
            static_cast<int>(cols),
            params.top_k,
            params.top_p,
            params.temperature,
            seed,
            offset,
            state_.device_id.gpu_ordinal(),
            &token,
            stream);
        if (!ok)
        {
            LOG_DEBUG("[DeviceGraphOrchestrator] GPU stochastic sampling failed on "
                      << state_.device_id.toString());
            return -1;
        }
        return token;
    }

    bool DeviceGraphOrchestrator::requiresMPICoordinatedDecodeSampling(
        const SamplingParams &params) const
    {
        /*
         * Greedy sampling on a vocab-sharded GlobalTP LM head allgathers the
         * local winning candidate from every MPI rank.  Worker ranks must enter
         * that same sampling method or rank 0 blocks in candidate coordination.
         * CPU GlobalTP already materializes gathered logits through the graph
         * allgather stage, so rank 0 can sample the authoritative row without a
         * second sampling-time collective.  Keeping CPU out of this hook also
         * prevents divergent root/worker fallback paths when a worker has only
         * a local logits shard.
         * Penalty and non-greedy column-parallel sampling currently can fall
         * back to root-local host logic, so advertising participation there
         * would create the exact command-stream deadlock this hook is meant to
         * avoid.
         */
        if (!state_.device_id.is_gpu())
        {
            return false;
        }
        if (!params.is_greedy() || params.has_penalties())
        {
            return false;
        }
        if (!activeMainLogitsAreColumnParallel())
        {
            return false;
        }
        IGlobalTPContext *global_ctx = globalTPContextForMTPCoordination();
        return global_ctx && global_ctx->degree() > 1;
    }

    bool DeviceGraphOrchestrator::joinPriorDeviceWorkForRequestStateReset(
        void *reset_stream,
        const char *consumer_name)
    {
        if (!state_.device_id.is_gpu())
            return true;

        /*
         * Server initialization and request admission may establish adjacent
         * reset boundaries before any forward graph consumes the first
         * publication.  Treat the newer reset as the explicit consumer of the
         * prior reset generation.  This queues the dependency onto the exact
         * reset stream and retires the old publication before the same
         * lifecycle-owned event is recorded for the new generation.
         */
        if (!reset_stream)
        {
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "request_state_reset",
                "ExplicitResetStream",
                consumer_name);
        }
        if (!waitForPendingRequestStateReset(
                reset_stream,
                DeviceTimelineRole::RequestStateReset,
                consumer_name))
        {
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "request_state_reset",
                "RequestStateResetReady",
                consumer_name);
        }
        if (!waitForLiveInferenceStateReadyForObservation(
                reset_stream,
                consumer_name,
                DeviceTimelineRole::RequestStateReset))
        {
            return reportDeviceTimelineJoinFailure(
                state_.device_id,
                "request_state_reset",
                "LiveInferenceStateReady",
                consumer_name);
        }
        PerfStatsCollector::addCounter(
            "request_reset",
            "device_prior_work_joins",
            1.0,
            "request_reset",
            state_.device_id.toString(),
            {{"consumer",
              consumer_name && consumer_name[0] != '\0'
                  ? consumer_name
                  : "unknown"},
             {"ordering", "event_wait"}});
        return true;
    }

    void DeviceGraphOrchestrator::publishRequestStateResetReady(
        void *producer_stream,
        const char *producer_name)
    {
        if (!state_.device_id.is_gpu())
            return;

        auto &ready = request_state_reset_ready_;
        if (!ready.event || ready.valid)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Request-state reset publication has invalid lifecycle ownership"
                      << " producer="
                      << (producer_name && producer_name[0] != '\0'
                              ? producer_name
                              : "unknown")
                      << " event=" << static_cast<bool>(ready.event)
                      << " already_valid=" << ready.valid);
            std::terminate();
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!producer_stream || !backend ||
            !DeviceEventEdge::at(DeviceTimelinePoint::RequestStateResetReady)
                 .from(DeviceTimelineRole::RequestStateReset)
                 .publish(
                     *backend,
                     state_.device_id,
                     ready.event.get(),
                     producer_stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to publish request-state reset readiness");
            std::terminate();
        }

        ready.producer_stream = producer_stream;
        ready.valid = true;
        PerfStatsCollector::addCounter(
            "request_reset",
            "device_state_ready_events",
            1.0,
            "request_reset",
            state_.device_id.toString(),
            {{"producer",
              producer_name && producer_name[0] != '\0'
                  ? producer_name
                  : "unknown"},
             {"ordering", "event_wait"}});
    }

    bool DeviceGraphOrchestrator::waitForPendingRequestStateReset(
        void *consumer_stream,
        DeviceTimelineRole consumer_role,
        const char *consumer_name)
    {
        if (!state_.device_id.is_gpu())
            return true;

        auto &ready = request_state_reset_ready_;
        if (!ready.valid)
            return true;
        if (!consumer_stream ||
            !ready.event ||
            !ready.producer_stream ||
            (consumer_role != DeviceTimelineRole::RequestStateReset &&
             consumer_role != DeviceTimelineRole::MainForwardGraph &&
             consumer_role != DeviceTimelineRole::MTPSidecarGraph &&
             consumer_role != DeviceTimelineRole::PrefixRestoreMutation))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Request-state reset dependency has incomplete or invalid ownership"
                      << " consumer="
                      << (consumer_name && consumer_name[0] != '\0'
                              ? consumer_name
                              : "unknown"));
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend ||
            !DeviceEventEdge::at(DeviceTimelinePoint::RequestStateResetReady)
                 .from(DeviceTimelineRole::RequestStateReset)
                 .to(consumer_role)
                 .enqueueWait(
                     *backend,
                     state_.device_id,
                     ready.event.get(),
                     ready.producer_stream,
                     consumer_stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to order graph execution after request-state reset"
                      << " consumer="
                      << (consumer_name && consumer_name[0] != '\0'
                              ? consumer_name
                              : "unknown"));
            return false;
        }

        /*
         * Observe cache-owned recurrent banks only after the consumer stream
         * has inherited RequestStateResetReady. This diagnostic distinguishes
         * an incomplete reset from a captured graph that later addresses the
         * wrong persistent bank. It is opt-in and synchronizes only this
         * consumer stream; production request reset remains event-only.
         */
        const auto diagnostic_gdn_layer =
            mtpGraphReuseDiagnosticGDNLayer();
        if (consumer_role == DeviceTimelineRole::MainForwardGraph &&
            diagnostic_gdn_layer &&
            mtpGraphReuseDiagnosticsEnabledForContext(
                "request_state_reset_gdn"))
        {
            auto *hybrid_cache =
                dynamic_cast<IHybridKVCache *>(state_.kv_cache.get());
            const HybridGDNLayerState *gdn_state =
                hybrid_cache
                    ? hybrid_cache->getGDNState(*diagnostic_gdn_layer)
                    : nullptr;
            if (!gdn_state)
            {
                LOG_ERROR("[MTPGraphReuseDiagnostics] selected reset diagnostic layer is not GDN"
                          << " layer=" << *diagnostic_gdn_layer
                          << " device=" << state_.device_id.toString());
                return false;
            }

            std::vector<MTPGraphReuseDiagnosticSource> sources;
            const auto append_binding =
                [&](const char *owner,
                    const GDNDeviceStateBinding &binding)
            {
                const std::string prefix =
                    std::string{"layer"} +
                    std::to_string(*diagnostic_gdn_layer) +
                    "_" + owner;
                if (binding.primary_state &&
                    binding.primary_state_floats > 0)
                {
                    sources.push_back({
                        prefix + "_primary",
                        binding.primary_state,
                        static_cast<size_t>(
                            binding.primary_state_floats) *
                            sizeof(float),
                    });
                }
                if (binding.secondary_state &&
                    binding.secondary_state_floats > 0)
                {
                    sources.push_back({
                        prefix + "_secondary",
                        binding.secondary_state,
                        static_cast<size_t>(
                            binding.secondary_state_floats) *
                            sizeof(float),
                    });
                }
                if (binding.request_state_bank &&
                    binding.request_state_bank_floats > 0)
                {
                    sources.push_back({
                        prefix + "_requests",
                        binding.request_state_bank,
                        binding.request_state_bank_floats *
                            sizeof(float),
                    });
                }
            };
            append_binding("conv", gdn_state->conv_device_state);
            append_binding(
                "recurrence",
                gdn_state->recurrence_device_state);
            if (sources.empty() ||
                !logMTPGraphReuseBoundaryDiagnostics(
                    "after_reset_wait",
                    "request_state_reset_gdn",
                    session_epoch_,
                    /*graph_rebuilt=*/false,
                    /*graph_replayed=*/false,
                    *backend,
                    state_.device_id,
                    consumer_stream,
                    sources))
            {
                return false;
            }
        }

        PerfStatsCollector::addCounter(
            "request_reset",
            "device_state_ready_waits",
            1.0,
            perfPhaseName(),
            state_.device_id.toString(),
            {{"consumer",
              consumer_name && consumer_name[0] != '\0'
                  ? consumer_name
                  : "unknown"},
             {"same_stream",
              boolTag(consumer_stream == ready.producer_stream)}});
        ready.valid = false;
        ready.producer_stream = nullptr;
        return true;
    }

    bool DeviceGraphOrchestrator::admitRequestInputsOnDevice(
        const int *tokens,
        const int *position_ids,
        int total_tokens,
        int request_count,
        int padded_seq_len)
    {
        static_assert(
            sizeof(int) == sizeof(int32_t),
            "GPU request admission requires 32-bit host ints");

        if (!state_.device_id.is_gpu() ||
            !tokens ||
            !position_ids ||
            total_tokens <= 0 ||
            request_count <= 0 ||
            padded_seq_len <= 0 ||
            total_tokens != request_count * padded_seq_len ||
            total_tokens > request_input_row_capacity_ ||
            request_count > request_sequence_lengths_capacity_ ||
            static_cast<int>(state_.sequence_lengths.size()) < request_count ||
            !request_token_ids_dev_ ||
            !request_position_ids_dev_ ||
            !request_sequence_lengths_dev_ ||
            !request_input_admission_ready_.event ||
            !request_input_reuse_ready_.event)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Request-input admission received invalid geometry or ownership"
                      << " device=" << state_.device_id.toString()
                      << " tokens=" << total_tokens
                      << " requests=" << request_count
                      << " padded_seq_len=" << padded_seq_len
                      << " token_capacity=" << request_input_row_capacity_
                      << " request_capacity=" << request_sequence_lengths_capacity_);
            return false;
        }
        if (request_input_admission_ready_.valid)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] A new request attempted to overwrite unconsumed GPU admission state");
            return false;
        }
        for (int request = 0; request < request_count; ++request)
        {
            const int real_tokens =
                request_count == 1
                    ? padded_seq_len
                    : state_.sequence_lengths[static_cast<size_t>(request)];
            if (real_tokens <= 0 || real_tokens > padded_seq_len)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Request-input admission received an invalid real row count"
                          << " request=" << request
                          << " real_tokens=" << real_tokens
                          << " padded_seq_len=" << padded_seq_len);
                return false;
            }
        }

        void *stream =
            explicitGPUStreamForOperation("admitRequestInputsOnDevice");
        IBackend *backend = getBackendFor(state_.device_id);
        if (!stream || !backend)
            return false;

        auto &reuse = request_input_reuse_ready_;
        if (reuse.consumers_started)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Request-input admission reached an input bank whose prior readers never published reuse readiness");
            std::terminate();
        }
        if (reuse.valid)
        {
            if (!reuse.event || !reuse.producer_stream ||
                !DeviceEventEdge::at(
                     DeviceTimelinePoint::RequestInputReuseReady)
                     .from(DeviceTimelineRole::MainForwardGraph)
                     .to(DeviceTimelineRole::RequestAdmissionTransfer)
                     .enqueueWait(
                         *backend,
                         state_.device_id,
                         reuse.event.get(),
                         reuse.producer_stream,
                         stream))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to order request-input admission after prior consumers");
                std::terminate();
            }

            PerfStatsCollector::addCounter(
                "request_admission",
                "device_input_reuse_waits",
                1.0,
                "prefill",
                state_.device_id.toString(),
                {{"same_stream", boolTag(reuse.producer_stream == stream)},
                 {"ordering", "consumer_release_event"}});
            reuse.valid = false;
            reuse.producer_stream = nullptr;
        }

        const size_t row_bytes =
            sizeof(int32_t) * static_cast<size_t>(total_tokens);
        const size_t padding_tokens =
            static_cast<size_t>(request_input_row_capacity_ - total_tokens);
        const size_t padding_bytes =
            sizeof(int32_t) * padding_tokens;
        const size_t length_bytes =
            sizeof(int32_t) * static_cast<size_t>(request_count);
        std::array<int32_t, 1> single_request_length{
            static_cast<int32_t>(padded_seq_len)};
        const int32_t *lengths =
            request_count == 1
                ? single_request_length.data()
                : reinterpret_cast<const int32_t *>(
                      state_.sequence_lengths.data());

        /*
         * The forward engine may widen this real row to a larger captured graph
         * bucket after admission. Materialize every potentially visible token ID
         * now so embedding can never observe allocator residue in that padding
         * tail. The immutable source vector was allocated during initialization
         * and remains alive until the exact request-reuse event retires.
         */
        const bool padding_enqueued =
            padding_tokens == 0 ||
            backend->hostToDeviceOnStream(
                static_cast<int32_t *>(request_token_ids_dev_) + total_tokens,
                request_padding_token_ids_host_.data(),
                padding_bytes,
                state_.device_id.gpu_ordinal(),
                stream);
        if (!padding_enqueued ||
            !backend->hostToDeviceOnStream(
                request_token_ids_dev_,
                tokens,
                row_bytes,
                state_.device_id.gpu_ordinal(),
                stream) ||
            !backend->hostToDeviceOnStream(
                request_position_ids_dev_,
                position_ids,
                row_bytes,
                state_.device_id.gpu_ordinal(),
                stream) ||
            !backend->hostToDeviceOnStream(
                request_sequence_lengths_dev_,
                lengths,
                length_bytes,
                state_.device_id.gpu_ordinal(),
                stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to enqueue the complete GPU request-input admission");
            return false;
        }
        if (!DeviceEventEdge::at(DeviceTimelinePoint::RequestInputAdmission)
                 .from(DeviceTimelineRole::RequestAdmissionTransfer)
                 .publish(
                     *backend,
                     state_.device_id,
                     request_input_admission_ready_.event.get(),
                     stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to publish GPU request-input admission readiness");
            std::terminate();
        }

        request_input_admission_ready_.producer_stream = stream;
        request_input_admission_ready_.valid = true;
        request_input_admission_ready_.token_count = total_tokens;
        request_input_admission_ready_.request_count = request_count;
        request_sequence_lengths_active_count_ = request_count;
        PerfStatsCollector::addCounter(
            "request_admission",
            "device_owned_input_rows",
            static_cast<double>(total_tokens),
            "prefill",
            state_.device_id.toString(),
            {{"requests", std::to_string(request_count)},
             {"owner", "arena_request_inputs"},
             {"ordering", "event_wait"}});
        return true;
    }

    bool DeviceGraphOrchestrator::waitForPendingRequestInputAdmission(
        void *consumer_stream,
        const char *consumer_name)
    {
        if (!state_.device_id.is_gpu())
            return true;
        auto &ready = request_input_admission_ready_;
        if (!ready.valid)
            return true;
        if (!consumer_stream || !ready.event || !ready.producer_stream)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] GPU request-input admission has incomplete stream/event ownership");
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;
        const bool same_stream = consumer_stream == ready.producer_stream;
        if (!DeviceEventEdge::at(DeviceTimelinePoint::RequestInputAdmission)
                 .from(DeviceTimelineRole::RequestAdmissionTransfer)
                 .to(DeviceTimelineRole::MainForwardGraph)
                 .enqueueWait(
                     *backend,
                     state_.device_id,
                     ready.event.get(),
                     ready.producer_stream,
                     consumer_stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to order graph execution after request admission for consumer="
                      << (consumer_name && consumer_name[0] != '\0'
                              ? consumer_name
                              : "unknown"));
            return false;
        }

        PerfStatsCollector::addCounter(
            "request_admission",
            "device_input_event_waits",
            1.0,
            "prefill",
            state_.device_id.toString(),
            {{"same_stream", boolTag(same_stream)},
             {"tokens", std::to_string(ready.token_count)},
             {"requests", std::to_string(ready.request_count)}});
        ready.valid = false;
        ready.producer_stream = nullptr;
        ready.token_count = 0;
        ready.request_count = 0;
        request_input_reuse_ready_.consumers_started = true;
        return true;
    }

    void DeviceGraphOrchestrator::publishRequestInputReuseReady(
        void *consumer_completion_stream,
        const char *producer_name)
    {
        if (!state_.device_id.is_gpu())
            return;

        auto &reuse = request_input_reuse_ready_;
        if (!consumer_completion_stream ||
            !reuse.event ||
            !reuse.consumers_started ||
            reuse.valid)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Request-input reuse publication violated the reusable-bank lifecycle"
                      << " stream=" << consumer_completion_stream
                      << " event=" << reuse.event.get()
                      << " consumers_started=" << boolTag(reuse.consumers_started)
                      << " prior_release_valid=" << boolTag(reuse.valid));
            std::terminate();
        }

        /*
         * Request-batched shifted prefill does not archive one terminal row after
         * its final sidecar. Join that side stream here without consuming its
         * live-state publication. For the single-request path the final terminal
         * archive already consumed the shifted-KV edge on this same stream, so
         * this observation is a no-op.
         */
        if (!waitForPendingShiftedMTPKVReadyForObservation(
                consumer_completion_stream,
                "request_input_reuse"))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Could not order request-input release after shifted MTP readers");
            std::terminate();
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend ||
            !DeviceEventEdge::at(DeviceTimelinePoint::RequestInputReuseReady)
                 .from(DeviceTimelineRole::MainForwardGraph)
                 .publish(
                     *backend,
                     state_.device_id,
                     reuse.event.get(),
                     consumer_completion_stream))
        {
            /*
             * GPU readers have already launched. Without a completion event the
             * reusable bank has no legal next writer, so continuing inference
             * would turn a backend publication failure into silent stale input.
             */
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to publish request-input reuse readiness");
            std::terminate();
        }

        reuse.producer_stream = consumer_completion_stream;
        reuse.valid = true;
        reuse.consumers_started = false;
        PerfStatsCollector::addCounter(
            "request_admission",
            "device_input_reuse_publications",
            1.0,
            "prefill",
            state_.device_id.toString(),
            {{"producer", producer_name && producer_name[0] != '\0'
                              ? producer_name
                              : "unknown"},
             {"ordering", "transitive_last_reader"}});
    }

    /**
     * @brief Seed the first device-owned request-batch publication after prefill.
     *
     * This is deliberately a device-to-device publication operation. Prompt
     * positions already live in the persistent request-length arena row, sampled
     * token identities live in target-sample arena slots, and every logical-state
     * field is completed before the mailbox event is recorded.
     */
    bool DeviceGraphOrchestrator::initializeDeviceResidentLogicalSequenceStateFromMainBatchSamples(
        int request_count,
        void *producer_stream)
    {
        if (!state_.device_id.is_gpu() ||
            request_count <= 0 ||
            request_count > stochastic_batch_output_request_capacity_ ||
            !producer_stream ||
            !stochastic_target_sample_tokens_dev_)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Initial MTP device logical-state publication received invalid request geometry or scratch");
            return false;
        }

        const MTPSpecDecodeMetadataShape metadata_shape =
            mtp_spec_decode_metadata_binding_.shape();
        if (!mtp_spec_decode_metadata_binding_.hasWorkspace() ||
            metadata_shape.max_requests < request_count)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Initial MTP device logical-state publication requires a pre-bound request-batch metadata workspace");
            return false;
        }

        const MTPSpecDecodeMetadataDevicePointers &workspace_ptrs =
            mtp_spec_decode_metadata_binding_.devicePointers();
        MTPSpecDecodeMetadataDevicePointers publication_ptrs = workspace_ptrs;
        if (!workspace_ptrs.base_cached_tokens ||
            !device_resident_logical_sequence_state_storage_
                 .bindPublicationOutputs(
                     &publication_ptrs,
                     request_count))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Initial MTP device logical-state publication has no complete arena-owned output storage");
            return false;
        }
        if (!request_sequence_lengths_dev_ ||
            request_sequence_lengths_active_count_ < request_count)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Initial MTP device logical-state publication is missing admitted request lengths");
            return false;
        }

        for (int request = 0; request < request_count; ++request)
        {
            if (!waitForRequiredStochasticTargetSampleReady(
                    request,
                    producer_stream,
                    "initialize_mtp_logical_state_after_prefill"))
            {
                return false;
            }
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "request_batch_prefill_device_logical_state_enqueue",
                "decode",
                state_.device_id.toString(),
                {{"requests", std::to_string(request_count)}});
            if (!backend->enqueueInitializeMTPDeviceLogicalState(
                    stochastic_target_sample_tokens_dev_,
                    static_cast<const int32_t *>(request_sequence_lengths_dev_),
                    request_count,
                    state_.device_id.gpu_ordinal(),
                    producer_stream,
                    workspace_ptrs.base_cached_tokens,
                    publication_ptrs.target_cached_tokens,
                    publication_ptrs.accepted_state_counts,
                    publication_ptrs.next_condition_tokens,
                    publication_ptrs.all_drafts_accepted_flags,
                    publication_ptrs.stopped_flags,
                    publication_ptrs.publication_ok_flags))
            {
                return false;
            }
        }

        /*
         * Shifted-prefill graph work may be emitted as several economical
         * request-local kernel groups, but the serving transaction that follows
         * owns the complete logical request batch. Promote that earlier fence to
         * the canonical request count before exposing the logical-state mailbox.
         * Waiting on the prior shared transaction first preserves cross-stream
         * ordering; recordDeviceResidentMTPTransactionMutation() can then retain
         * the same shared identity on every subsequent grouped sidecar mutation.
         */
        const DeviceResidentMTPTransactionLease prior_transaction =
            currentDeviceResidentMTPTransactionLease();
        if (prior_transaction.valid() &&
            !waitForDeviceResidentMTPTransaction(
                prior_transaction,
                producer_stream,
                "request_batch_prefill_logical_state_transaction_promotion"))
        {
            return false;
        }
        if (!recordDeviceResidentMTPTransactionMutation(
                request_count,
                producer_stream,
                "request_batch_prefill_logical_state_transaction"))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Initial MTP device logical-state publication could not establish the canonical request-batch transaction");
            return false;
        }

        std::string mailbox_error;
        if (!recordDeviceResidentLogicalSequenceStateMailbox(
                request_count,
                producer_stream,
                &mailbox_error))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Initial MTP device logical-state mailbox publication failed: "
                      << mailbox_error);
            return false;
        }

        PerfStatsCollector::addCounter(
            "mtp",
            "request_batch_prefill_device_mtp_transaction_publications",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"requests", std::to_string(request_count)},
             {"transaction_owner", "canonical_shifted_kv_counts"},
             {"logical_state_owner", "arena_persistent"}});

        PerfStatsCollector::addCounter(
            "mtp",
            "request_batch_prefill_device_logical_state_publications",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"requests", std::to_string(request_count)},
             {"logical_state_owner", "arena_persistent"},
             {"position_owner", "arena_persistent"}});
        return true;
    }

    bool DeviceGraphOrchestrator::sampleMainLogitsBatchRowsOnDevice(
        int request_count,
        const SamplingParams &params,
        int32_t *out_tokens,
        const uint64_t *stochastic_position_seeds)
    {
        if (request_count <= 0 || !out_tokens)
        {
            return false;
        }
        if (!state_.device_id.is_gpu())
        {
            return false;
        }
        if (activeMainLogitsAreColumnParallel())
        {
            LOG_DEBUG("[DeviceGraphOrchestrator] Request-batched main-logits "
                      "sampling is not enabled for column-parallel LM heads");
            return false;
        }

        TensorBase *logits_tensor = nullptr;
        if (request_batched_prefill_logits_row_count_ >= request_count &&
            state_.all_position_logits)
        {
            logits_tensor = state_.all_position_logits.get();
        }
        else
        {
            logits_tensor = state_.logits.get();
        }

        if (!logits_tensor || !logits_tensor->deviceValid())
        {
            return false;
        }

        void *gpu_ptr = logits_tensor->gpu_data_ptr();
        if (!gpu_ptr)
        {
            return false;
        }

        const auto &shape = logits_tensor->shape();
        if (shape.empty())
        {
            return false;
        }

        /*
         * Batched prefill stores exactly one terminal logits row per request.
         * This differs from the all-position verifier tensor: there is no
         * padded sequence dimension to skip here.
         */
        const size_t rows = shape.size() >= 2 ? shape[0] : 1;
        const size_t cols = shape.size() >= 2 ? shape[1] : shape[0];
        if (rows < static_cast<size_t>(request_count) ||
            cols == 0 ||
            cols > static_cast<size_t>(std::numeric_limits<int>::max()))
        {
            LOG_DEBUG("[DeviceGraphOrchestrator] Request-batched logits shape "
                      "cannot satisfy sampling request: rows=" << rows
                      << " cols=" << cols
                      << " request_count=" << request_count);
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
        {
            return false;
        }

        const PendingLogitsStreamRole stream_role =
            logits_tensor == state_.all_position_logits.get()
                ? PendingLogitsStreamRole::AllPositionVerifier
                : PendingLogitsStreamRole::MainDecode;
        void *stream = peekPendingLogitsStream(stream_role);
        if (!stream)
            stream = explicitGPUStreamForOperation(
                "sampleMainLogitsBatchRowsOnDevice");
        if (!stream)
        {
            return false;
        }

        auto *base = static_cast<const float *>(gpu_ptr);
        const int vocab_cols = static_cast<int>(cols);
        if (!stochastic_target_sample_tokens_dev_ ||
            !stochastic_verify_accept_probs_dev_ ||
            !argmax_partial_vals_dev_ ||
            !argmax_partial_idxs_dev_ ||
            argmax_partial_capacity_ <= 0 ||
            request_count > stochastic_target_row_capacity_)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Request-batched prefill sampling is missing persistent device scratch");
            return false;
        }

        if (params.is_greedy())
        {
            for (int row = 0; row < request_count; ++row)
            {
                clearStochasticTargetSampleReadySlot(
                    row,
                    StochasticSampleReadyClearMode::Force);
            }

            {
                PerfStatsCollector::ScopedTimer timer(
                    "mtp",
                    "request_batch_prefill_argmax_enqueue",
                    "decode",
                    state_.device_id.toString(),
                    {{"requests", std::to_string(request_count)},
                     {"vocab", std::to_string(vocab_cols)}});
                if (!backend->enqueueArgmaxF32BatchedRowsDevice(
                        base,
                        request_count,
                        vocab_cols,
                        state_.device_id.gpu_ordinal(),
                        stream,
                        stochastic_verify_accept_probs_dev_,
                        stochastic_target_sample_tokens_dev_,
                        argmax_partial_vals_dev_,
                        argmax_partial_idxs_dev_,
                        argmax_partial_capacity_))
                {
                    return false;
                }
            }

            for (int row = 0; row < request_count; ++row)
            {
                if (!recordStochasticTargetSampleReady(
                        row,
                        stream,
                        /*verifier_consumer_pending=*/false))
                {
                    return false;
                }
            }
        }
        else
        {
            if (params.top_k <= 0 || params.top_k > 256)
            {
                LOG_DEBUG("[DeviceGraphOrchestrator] GPU stochastic batch-row "
                          "sampling requires 1 <= top_k <= 256; got top_k="
                          << params.top_k);
                return false;
            }
            if (!stochastic_position_seeds)
            {
                LOG_DEBUG("[DeviceGraphOrchestrator] GPU stochastic batch-row "
                          "sampling requires immutable per-request position seeds");
                return false;
            }
            if (logits_tensor != state_.all_position_logits.get() ||
                request_batched_prefill_logits_row_count_ < request_count)
            {
                LOG_DEBUG("[DeviceGraphOrchestrator] GPU stochastic batch-row "
                          "sampling requires compact request-batched prefill logits");
                return false;
            }
            if (!supportsDeviceStochasticMTPVerification())
            {
                LOG_DEBUG("[DeviceGraphOrchestrator] GPU stochastic batch-row "
                          "sampling requires compact device distribution support");
                return false;
            }

            if (!request_sequence_lengths_dev_ ||
                request_sequence_lengths_active_count_ < request_count)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] GPU stochastic prefill sampling is missing resident logical positions");
                return false;
            }
            for (int row = 0; row < request_count; ++row)
            {
                if (stochastic_position_seeds[row] == 0)
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] GPU stochastic prefill sampling received an unresolved zero seed");
                    return false;
                }
            }

            /*
             * Build all request distributions in one launch, then leave every
             * sampled token in its target slot. A single batched D2H below is the
             * response observation; it is not part of MTP planning or publication.
             */
            if (!buildStochasticDistributionsOnDevice(
                    DeviceLogitsSource::AllPosition,
                    /*first_row=*/0,
                    DeviceDistributionBuffer::Target,
                    /*first_slot=*/0,
                    request_count,
                    params,
                    vocab_cols))
            {
                return false;
            }
            for (int row = 0; row < request_count; ++row)
            {
                if (!sampleStochasticDistributionOnDeviceImpl(
                        DeviceDistributionBuffer::Target,
                        row,
                        /*threshold=*/0.0f,
                        /*out_token_host=*/nullptr,
                        stochastic_position_seeds[row],
                        static_cast<const int32_t *>(request_sequence_lengths_dev_) + row,
                        /*threshold_position_offset=*/0))
                {
                    return false;
                }
            }
            PerfStatsCollector::addCounter(
                "mtp",
                "request_batch_prefill_resident_position_threshold_rows",
                static_cast<double>(request_count),
                "decode",
                state_.device_id.toString(),
                {{"position_owner", "arena_request_sequence_lengths"}});
        }

        if (!initializeDeviceResidentLogicalSequenceStateFromMainBatchSamples(
                request_count,
                stream))
        {
            return false;
        }

        /*
         * The serving API must return sampled token identities to the CPU, but
         * this one contiguous response read occurs only after the device mailbox
         * has become authoritative. No later grouped MTP operation consumes
         * `out_tokens` or any host shadow derived from it.
         */
        if (!backend->deviceToHostFast(
                out_tokens,
                stochastic_target_sample_tokens_dev_,
                sizeof(int32_t) * static_cast<size_t>(request_count),
                state_.device_id.gpu_ordinal(),
                stream))
        {
            return false;
        }
        for (int row = 0; row < request_count; ++row)
        {
            if (out_tokens[row] < 0)
                return false;
            clearStochasticTargetSampleReadySlot(
                row,
                StochasticSampleReadyClearMode::Force);
        }
        drainPendingGpuTimingMeasurements(backend);
        (void)consumePendingLogitsStream(
            stream_role,
            "sampleMainLogitsBatchRowsOnDeviceComplete");
        request_batched_prefill_logits_row_count_ = 0;
        return true;
    }

    /**
     * @brief Apply sparse penalties to the current main logits on the logits stream.
     *
     * GPU graph replay can leave logits pending on a capture stream. Penalty
     * application is an in-place mutation of those logits, so it is also a
     * logits producer. Keep the same stream in pending_main_decode_logits_stream_
     * for the next sampler/distribution consumer; otherwise a penalty kernel on
     * one stream can race a top-k kernel on another stream.
     */
    bool DeviceGraphOrchestrator::applyPenaltiesOnDevice(const std::vector<LogitPenalty> &penalties,
                                                         int vocab_size)
    {
        if (penalties.empty())
            return true; // Nothing to apply, success

        if (!state_.device_id.is_gpu())
        {
            TensorBase *tensor = nullptr;
            int token_offset = 0;
            if (activeMainLogitsAreColumnParallel())
            {
                tensor = state_.logits_local.get();
                token_offset = vocabOffsetForTPConfig(graph_builder_->config());
            }
            else
            {
                tensor = state_.logits.get();
            }
            return applyPenaltiesToTensorRowOnHost(
                tensor,
                penalties,
                vocab_size,
                0,
                token_offset,
                "applyPenaltiesOnDeviceHost");
        }

        void *stream = peekPendingLogitsStream(PendingLogitsStreamRole::MainDecode);
        if (!stream)
            stream = explicitGPUStreamForOperation("applyPenaltiesOnDevice");
        if (!stream)
            return false;

        bool ok = false;
        if (activeMainLogitsAreColumnParallel())
        {
            const int token_offset = vocabOffsetForTPConfig(graph_builder_->config());
            ok = applyPenaltiesToTensorRowOnDevice(
                state_.logits_local.get(),
                state_.device_id,
                penalties,
                vocab_size,
                0,
                token_offset,
                stream,
                "applyPenaltiesOnDeviceLocal");
        }
        else
        {
            ok = applyPenaltiesToTensorRowOnDevice(
                state_.logits.get(),
                state_.device_id,
                penalties,
                vocab_size,
                0,
                0,
                stream,
                "applyPenaltiesOnDevice");
        }

        if (ok)
        {
            /*
             * The sampler owns clearing this pending stream. We intentionally
             * leave it set even if it came from explicitGPUStreamForOperation()
             * because the penalty kernel is now the newest logits writer.
             */
            publishPendingLogitsStream(
                PendingLogitsStreamRole::MainDecode,
                stream,
                "applyPenaltiesOnDevice");
        }
        return ok;
    }

    /**
     * @brief Apply sparse penalties to MTP sidecar logits on the logits stream.
     *
     * Sidecar logits often come from a captured MTP graph. The penalty kernel
     * must stay ordered with that graph replay and with the following draft
     * sampler, so this method republishes the stream for the next MTP logits
     * consumer instead of switching to an unrelated operation stream.
     */
    bool DeviceGraphOrchestrator::applyPenaltiesToMTPLogitsOnDevice(
        const std::vector<LogitPenalty> &penalties,
        int vocab_size)
    {
        if (penalties.empty())
            return true;

        auto it = state_.extension_buffers.find(BufferId::MTP_LOGITS);
        if (it == state_.extension_buffers.end() || !it->second)
            return false;

        const int token_offset = mtpSidecarLogitsAreColumnParallel() && graph_builder_
                                     ? vocabOffsetForTPConfig(graph_builder_->config())
                                     : 0;
        if (!state_.device_id.is_gpu())
        {
            return applyPenaltiesToTensorRowOnHost(
                it->second.get(),
                penalties,
                vocab_size,
                0,
                token_offset,
                "applyPenaltiesToMTPLogitsOnDeviceHost");
        }

        void *stream = peekPendingLogitsStream(PendingLogitsStreamRole::MTPSidecar);
        if (!stream)
        {
            stream = explicitGPUStreamForOperation("applyPenaltiesToMTPLogitsOnDevice");
        }
        if (!stream)
            return false;

        const bool ok = applyPenaltiesToTensorRowOnDevice(
            it->second.get(),
            state_.device_id,
            penalties,
            vocab_size,
            0,
            token_offset,
            stream,
            "applyPenaltiesToMTPLogitsOnDevice");
        if (ok)
        {
            publishPendingLogitsStream(
                PendingLogitsStreamRole::MTPSidecar,
                stream,
                "applyPenaltiesToMTPLogitsOnDevice");
        }
        return ok;
    }

    /**
     * @brief Apply sparse penalties to one all-position verifier logits row.
     *
     * All-position verifier replay may build several target distributions from
     * one captured logits buffer. Penalties are row-local mutations of that
     * buffer, so they must be enqueued on the all-position producer stream and
     * leave that stream available for the next distribution build.
     */
    bool DeviceGraphOrchestrator::applyPenaltiesToAllPositionLogitsOnDeviceRow(
        int row,
        const std::vector<LogitPenalty> &penalties,
        int vocab_size)
    {
        if (penalties.empty())
            return true;
        if (row < 0)
            return false;

        TensorBase *tensor = nullptr;
        int token_offset = 0;
        if (activeAllPositionLogitsAreColumnParallel())
        {
            /*
             * Column-parallel LocalTP keeps two useful all-position views:
             * a local LM-head shard for cross-shard sampling, and sometimes a
             * gathered full-vocab tensor for diagnostics or host consumers.
             *
             * Penalties are part of the sampled distribution, so they must be
             * applied to the same producer buffer that LogitsLocalInfo exposes
             * to RankOrchestrator::sampleGreedyFromAllPositionLogitsOnDeviceRows().
             * Mutating the gathered tensor here would leave the local shard
             * unchanged and let the verifier sample stale row logits.
             */
            tensor = state_.all_position_logits_local.get();
            token_offset = localLogitsVocabOffset();
        }
        else if (state_.all_position_logits)
        {
            tensor = state_.all_position_logits.get();
        }
        if (!tensor)
            return false;

        if (!state_.device_id.is_gpu())
        {
            return applyPenaltiesToTensorRowOnHost(
                tensor,
                penalties,
                vocab_size,
                row,
                token_offset,
                "applyPenaltiesToAllPositionLogitsOnDeviceRowHost");
        }

        void *stream = peekPendingLogitsStream(PendingLogitsStreamRole::AllPositionVerifier);
        if (!stream)
        {
            stream = explicitGPUStreamForOperation(
                "applyPenaltiesToAllPositionLogitsOnDeviceRow");
        }
        if (!stream)
            return false;

        const bool ok = applyPenaltiesToTensorRowOnDevice(
            tensor,
            state_.device_id,
            penalties,
            vocab_size,
            row,
            token_offset,
            stream,
            "applyPenaltiesToAllPositionLogitsOnDeviceRow");
        if (ok)
        {
            publishPendingLogitsStream(
                PendingLogitsStreamRole::AllPositionVerifier,
                stream,
                "applyPenaltiesToAllPositionLogitsOnDeviceRow");
            if (!recordAllPositionVerifierStateReady(
                    stream,
                    "applyPenaltiesToAllPositionLogitsOnDeviceRow"))
            {
                throw std::runtime_error(
                    "Failed to publish all-position logits penalty readiness");
            }
        }
        return ok;
    }

    bool DeviceGraphOrchestrator::supportsRowLocalAllPositionPenaltyApplication() const
    {
        /*
         * CPU all-position rows are native host tensors, and the method above
         * applies the same sparse row-local penalty map directly to that row.
         * GPU rows use the explicit-stream sparse penalty kernel.  Both are
         * grouped-verifier implementations: the caller mutates each verifier
         * row in place, then samples/reduces the grouped outcome without
         * replaying rows through the serial decode loop.
         */
        return state_.device_id.is_cpu() || state_.device_id.is_gpu();
    }

    bool DeviceGraphOrchestrator::supportsDeviceStochasticMTPVerification() const
    {
        if (!state_.device_id.is_gpu())
            return false;
        /*
         * Ordinary column-parallel logits do not contain a full distribution on
         * one participant, so the single-device stochastic verifier kernels
         * must not consume them.  Mirrored LocalTP MTP heads are the explicit
         * exception: each child binds a replicated full-vocabulary MTP head for
         * verifier/proposal rows, while other TP projections remain sharded.
         */
        if (graph_builder_ &&
            graph_builder_->config().lm_head_column_parallel &&
            !usesMirroredLocalTPMTPHeadForVerifier())
        {
            return false;
        }
        return stochastic_target_token_ids_dev_ &&
               stochastic_target_probs_dev_ &&
               stochastic_draft_token_ids_dev_ &&
               stochastic_draft_probs_dev_ &&
               stochastic_processed_logits_dev_ &&
               stochastic_inverse_rejection_samples_dev_ &&
               stochastic_target_sample_tokens_dev_ &&
               stochastic_draft_sample_tokens_dev_ &&
               stochastic_draft_sample_probs_dev_ &&
               stochastic_topk_partial_vals_dev_ &&
               stochastic_topk_partial_idxs_dev_ &&
               stochastic_topk_partial_capacity_ > 0 &&
               stochastic_draft_topk_partial_vals_dev_ &&
               stochastic_draft_topk_partial_idxs_dev_ &&
               stochastic_draft_topk_partial_capacity_ > 0 &&
               argmax_partial_vals_dev_ &&
               argmax_partial_idxs_dev_ &&
               argmax_partial_capacity_ > 0 &&
               mtp_verifier_input_tokens_dev_ &&
               stochastic_verify_tokens_dev_ &&
               stochastic_verify_accepted_dev_ &&
               stochastic_verify_accept_probs_dev_ &&
               stochastic_verify_thresholds_dev_ &&
               stochastic_batch_output_tokens_dev_ &&
               stochastic_batch_output_meta_dev_;
    }

    bool DeviceGraphOrchestrator::buildStochasticProcessedLogitRowsOnDevice(
        DeviceLogitsSource source,
        int first_row,
        DeviceDistributionBuffer buffer,
        int first_slot,
        int row_count,
        const SamplingParams &params,
        int vocab_size,
        void *stream,
        const char *operation_name)
    {
        if (!supportsDeviceStochasticMTPVerification() ||
            !stochastic_processed_logits_dev_ ||
            first_row < 0 || first_slot < 0 || row_count <= 0 ||
            vocab_size <= 0 || params.top_k <= 0 ||
            stream == nullptr)
        {
            return false;
        }

        const int max_slots =
            buffer == DeviceDistributionBuffer::Target
                ? stochastic_target_row_capacity_
                : stochastic_draft_row_capacity_;
        if (first_slot + row_count > max_slots ||
            row_count > stochastic_target_row_capacity_)
        {
            return false;
        }

        TensorBase *tensor = nullptr;
        switch (source)
        {
        case DeviceLogitsSource::Main:
            tensor = state_.logits.get();
            break;
        case DeviceLogitsSource::MTP:
        {
            auto it = state_.extension_buffers.find(BufferId::MTP_LOGITS);
            tensor = it == state_.extension_buffers.end() ? nullptr : it->second.get();
            break;
        }
        case DeviceLogitsSource::AllPosition:
            tensor = state_.all_position_logits.get();
            break;
        case DeviceLogitsSource::MainRequestBatch:
            tensor = state_.all_position_logits.get();
            break;
        }

        if (!tensor || !tensor->deviceValid() || !tensor->gpu_data_ptr())
            return false;

        const auto &shape = tensor->shape();
        if (shape.empty())
            return false;
        const size_t rows = shape.size() >= 2 ? shape[0] : 1;
        const size_t cols = shape.size() >= 2 ? shape[1] : shape[0];
        if (cols == 0 ||
            cols > static_cast<size_t>(std::numeric_limits<int>::max()) ||
            static_cast<size_t>(first_row + row_count) > rows ||
            static_cast<int>(cols) != vocab_size)
        {
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        const float *row_ptr =
            static_cast<const float *>(tensor->gpu_data_ptr()) +
            static_cast<size_t>(first_row) * cols;
        auto *processed_rows =
            static_cast<float *>(stochastic_processed_logits_dev_) +
            static_cast<size_t>(first_slot) * cols;
        /*
         * Target/verifier distributions and MTP draft distributions may be
         * produced on different explicit streams.  Keep their partial top-k
         * workspaces disjoint so graph-captured stochastic verification cannot
         * race through a shared scratch buffer.
         */
        void *partial_vals =
            buffer == DeviceDistributionBuffer::Target
                ? stochastic_topk_partial_vals_dev_
                : stochastic_draft_topk_partial_vals_dev_;
        void *partial_idxs =
            buffer == DeviceDistributionBuffer::Target
                ? stochastic_topk_partial_idxs_dev_
                : stochastic_draft_topk_partial_idxs_dev_;
        const int partial_capacity =
            buffer == DeviceDistributionBuffer::Target
                ? stochastic_topk_partial_capacity_
                : stochastic_draft_topk_partial_capacity_;
        if (!partial_vals || !partial_idxs || partial_capacity <= 0)
            return false;

        const std::map<std::string, std::string> processed_tags = {
            {"operation", operation_name ? operation_name : "unknown"},
            {"rows", std::to_string(row_count)},
            {"top_k", std::to_string(params.top_k)}};
        std::shared_ptr<void> gpu_timing_start;
        std::shared_ptr<void> gpu_timing_stop;
        if (!beginPendingGpuTimingMeasurement(
                "stochastic_processed_rows_build_gpu",
                stream,
                &gpu_timing_start,
                &gpu_timing_stop))
        {
            return false;
        }
        bool ok = false;
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "stochastic_processed_rows_build_enqueue",
                "decode",
                state_.device_id.toString(),
                processed_tags);
            ok = backend->enqueueBuildTopKTopPProcessedLogitsF32Device(
                    row_ptr,
                    row_count,
                    static_cast<int>(cols),
                    static_cast<int>(cols),
                    params.top_k,
                    params.top_p,
                    params.temperature,
                    state_.device_id.gpu_ordinal(),
                    stream,
                    processed_rows,
                    static_cast<int>(cols),
                    partial_vals,
                    partial_idxs,
                    partial_capacity);
        }
        if (!ok)
            return false;
        finishPendingGpuTimingMeasurement(
            "stochastic_processed_rows_build_gpu",
            stream,
            processed_tags,
            std::move(gpu_timing_start),
            std::move(gpu_timing_stop));

        PerfStatsCollector::addCounter(
            "mtp",
            "stochastic_processed_rows",
            static_cast<double>(row_count),
            "decode",
            state_.device_id.toString(),
            {{"buffer", buffer == DeviceDistributionBuffer::Target ? "target" : "draft"}});
        for (int row = 0; row < row_count; ++row)
        {
            const int slot = first_slot + row;
            if (buffer == DeviceDistributionBuffer::Target)
            {
                stochastic_target_top_k_[static_cast<size_t>(slot)] = params.top_k;
                stochastic_target_row_formats_[static_cast<size_t>(slot)] =
                    StochasticRowFormat::ProcessedLogits;
                stochastic_target_distribution_streams_[static_cast<size_t>(slot)] = stream;
            }
            else
            {
                stochastic_draft_top_k_[static_cast<size_t>(slot)] = params.top_k;
                stochastic_draft_row_formats_[static_cast<size_t>(slot)] =
                    StochasticRowFormat::ProcessedLogits;
                stochastic_draft_distribution_streams_[static_cast<size_t>(slot)] = stream;
            }
        }
        return true;
    }

    bool DeviceGraphOrchestrator::buildStochasticProcessedLogitRowsOnDevice(
        DeviceLogitsSource source,
        int first_row,
        DeviceDistributionBuffer buffer,
        int first_slot,
        int row_count,
        const SamplingParams &params,
        int vocab_size)
    {
        void *stream = nullptr;
        switch (source)
        {
        case DeviceLogitsSource::Main:
        case DeviceLogitsSource::MainRequestBatch:
            stream = peekPendingLogitsStream(PendingLogitsStreamRole::MainDecode);
            break;
        case DeviceLogitsSource::MTP:
            stream = peekPendingLogitsStream(PendingLogitsStreamRole::MTPSidecar);
            break;
        case DeviceLogitsSource::AllPosition:
            stream = peekPendingLogitsStream(PendingLogitsStreamRole::AllPositionVerifier);
            break;
        }
        if (!stream)
        {
            stream = explicitGPUStreamForOperation("buildStochasticProcessedLogitRowsOnDevice");
        }
        if (!stream)
            return false;

        return buildStochasticProcessedLogitRowsOnDevice(
            source,
            first_row,
            buffer,
            first_slot,
            row_count,
            params,
            vocab_size,
            stream,
            "buildStochasticProcessedLogitRowsOnDevice");
    }

    bool DeviceGraphOrchestrator::buildStochasticDistributionOnDevice(
        DeviceLogitsSource source,
        int row,
        DeviceDistributionBuffer buffer,
        int slot,
        const SamplingParams &params,
        int vocab_size)
    {
        if (!supportsDeviceStochasticMTPVerification() ||
            row < 0 || slot < 0 || vocab_size <= 0 ||
            params.top_k <= 0 ||
            params.top_k > static_cast<int>(kStochasticDistributionMaxK))
        {
            return false;
        }

        TensorBase *tensor = nullptr;
        switch (source)
        {
        case DeviceLogitsSource::Main:
            tensor = state_.logits.get();
            break;
        case DeviceLogitsSource::MTP:
        {
            auto it = state_.extension_buffers.find(BufferId::MTP_LOGITS);
            tensor = it == state_.extension_buffers.end() ? nullptr : it->second.get();
            break;
        }
        case DeviceLogitsSource::AllPosition:
            tensor = state_.all_position_logits.get();
            break;
        case DeviceLogitsSource::MainRequestBatch:
            tensor = state_.all_position_logits.get();
            break;
        }

        if (!tensor || !tensor->deviceValid())
            return false;

        const auto &shape = tensor->shape();
        if (shape.empty())
            return false;
        const size_t rows = shape.size() >= 2 ? shape[0] : 1;
        const size_t cols = shape.size() >= 2 ? shape[1] : shape[0];
        if (cols == 0 ||
            cols > static_cast<size_t>(std::numeric_limits<int>::max()) ||
            static_cast<size_t>(row) >= rows ||
            static_cast<int>(cols) != vocab_size)
        {
            return false;
        }

        int *token_ids = nullptr;
        float *probs = nullptr;
        int max_slots = 0;
        if (buffer == DeviceDistributionBuffer::Target)
        {
            token_ids = static_cast<int *>(stochastic_target_token_ids_dev_);
            probs = static_cast<float *>(stochastic_target_probs_dev_);
            max_slots = stochastic_target_row_capacity_;
        }
        else
        {
            token_ids = static_cast<int *>(stochastic_draft_token_ids_dev_);
            probs = static_cast<float *>(stochastic_draft_probs_dev_);
            max_slots = stochastic_draft_row_capacity_;
        }
        if (!token_ids || !probs || slot >= max_slots)
            return false;

        if (buffer == DeviceDistributionBuffer::Target)
        {
            stochastic_target_top_k_[static_cast<size_t>(slot)] = 0;
            stochastic_target_row_formats_[static_cast<size_t>(slot)] =
                StochasticRowFormat::Empty;
            stochastic_target_distribution_streams_[static_cast<size_t>(slot)] = nullptr;
        }
        else
        {
            stochastic_draft_top_k_[static_cast<size_t>(slot)] = 0;
            stochastic_draft_row_formats_[static_cast<size_t>(slot)] =
                StochasticRowFormat::Empty;
            stochastic_draft_distribution_streams_[static_cast<size_t>(slot)] = nullptr;
            clearStochasticDraftSampleReadySlot(
                slot,
                StochasticSampleReadyClearMode::Force);
        }

        void *stream = nullptr;
        bool used_pending_main_stream = false;
        bool used_pending_mtp_stream = false;
        if (source == DeviceLogitsSource::Main ||
            source == DeviceLogitsSource::MainRequestBatch)
        {
            /*
             * MTP condition-forward replay may leave main logits pending on
             * the capture stream. Build the stochastic distribution on that
             * same stream so the CPU does not force a replay sync before the
             * sampler kernel has been queued.
             */
            stream = consumePendingLogitsStream(
                PendingLogitsStreamRole::MainDecode,
                "buildStochasticDistributionOnDevice(Main)");
            used_pending_main_stream = stream != nullptr;
        }
        else if (source == DeviceLogitsSource::MTP)
        {
            stream = consumePendingLogitsStream(
                PendingLogitsStreamRole::MTPSidecar,
                "buildStochasticDistributionOnDevice(MTP)");
            used_pending_mtp_stream = stream != nullptr;
        }
        else if (source == DeviceLogitsSource::AllPosition)
        {
            /*
             * A deferred all-position verifier replay leaves its capture stream
             * here for the next device-side consumer. Stochastic verification
             * may build several target/bonus distributions before the summary
             * kernel finally copies compact metadata to host, so the stream is
             * intentionally not cleared by individual distribution builds.
             */
            stream = peekPendingLogitsStream(PendingLogitsStreamRole::AllPositionVerifier);
        }
        if (!stream)
            stream = explicitGPUStreamForOperation("buildStochasticDistributionOnDevice");
        if (!stream)
            return false;

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        const void *gpu_ptr = tensor->gpu_data_ptr();
        if (!gpu_ptr)
            return false;
        const float *row_ptr =
            static_cast<const float *>(gpu_ptr) +
            static_cast<size_t>(row) * cols;

        const size_t slot_offset =
            static_cast<size_t>(slot) * kStochasticDistributionMaxK;
        void *partial_vals =
            buffer == DeviceDistributionBuffer::Target
                ? stochastic_topk_partial_vals_dev_
                : stochastic_draft_topk_partial_vals_dev_;
        void *partial_idxs =
            buffer == DeviceDistributionBuffer::Target
                ? stochastic_topk_partial_idxs_dev_
                : stochastic_draft_topk_partial_idxs_dev_;
        const int partial_capacity =
            buffer == DeviceDistributionBuffer::Target
                ? stochastic_topk_partial_capacity_
                : stochastic_draft_topk_partial_capacity_;
        if (!partial_vals || !partial_idxs || partial_capacity <= 0)
            return false;
        bool ok = false;
        const std::map<std::string, std::string> distribution_tags = {
            {"slot", std::to_string(slot)},
            {"source", source == DeviceLogitsSource::Main
                           ? "main"
                           : (source == DeviceLogitsSource::MainRequestBatch
                                  ? "main_request_batch"
                           : (source == DeviceLogitsSource::MTP
                                  ? "mtp"
                                  : "all_position"))},
            {"top_k", std::to_string(params.top_k)}};
        std::shared_ptr<void> gpu_timing_start;
        std::shared_ptr<void> gpu_timing_stop;
        if (!beginPendingGpuTimingMeasurement(
                "stochastic_distribution_build_gpu",
                stream,
                &gpu_timing_start,
                &gpu_timing_stop))
        {
            return false;
        }
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "stochastic_distribution_build_enqueue",
                "decode",
                state_.device_id.toString(),
                distribution_tags);
            ok = backend->enqueueBuildTopKTopPDistributionF32Device(
                row_ptr,
                static_cast<int>(cols),
                params.top_k,
                params.top_p,
                params.temperature,
                state_.device_id.gpu_ordinal(),
                stream,
                token_ids + slot_offset,
                probs + slot_offset,
                partial_vals,
                partial_idxs,
                partial_capacity);
        }
        if (ok)
        {
            finishPendingGpuTimingMeasurement(
                "stochastic_distribution_build_gpu",
                stream,
                distribution_tags,
                std::move(gpu_timing_start),
                std::move(gpu_timing_stop));
        }
        if (ok)
        {
            if (used_pending_main_stream)
            {
                PerfStatsCollector::addCounter(
                    "mtp",
                    "stochastic_main_distribution_stream_handoffs",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {{"slot", std::to_string(slot)}});
            }
            if (used_pending_mtp_stream)
            {
                PerfStatsCollector::addCounter(
                    "mtp",
                    "stochastic_mtp_distribution_stream_handoffs",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {{"slot", std::to_string(slot)}});
            }
            const int effective_top_k =
                std::min(params.top_k, static_cast<int>(cols));
            size_t partial_blocks =
                (cols + kStochasticTopKSmallKThreads - 1) /
                kStochasticTopKSmallKThreads;
            partial_blocks = std::max<size_t>(partial_blocks, 1);
            partial_blocks = std::min(partial_blocks, kStochasticTopKPartialBlocks);
            const bool used_gpu_smallk_scratch =
                state_.device_id.is_gpu() &&
                effective_top_k > 0 &&
                effective_top_k <= static_cast<int>(kStochasticTopKSmallKCap) &&
                partial_vals &&
                partial_idxs &&
                partial_capacity >=
                    static_cast<int>(partial_blocks * static_cast<size_t>(effective_top_k));
            if (used_gpu_smallk_scratch)
            {
                const char *source_name = "unknown";
                switch (source)
                {
                case DeviceLogitsSource::Main:
                    source_name = "main";
                    break;
                case DeviceLogitsSource::MTP:
                    source_name = "mtp";
                    break;
                case DeviceLogitsSource::AllPosition:
                    source_name = "all_position";
                    break;
                case DeviceLogitsSource::MainRequestBatch:
                    source_name = "main_request_batch";
                    break;
                }
                PerfStatsCollector::addCounter(
                    "mtp",
                    "stochastic_topk_smallk_scratch_distribution_builds",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {
                        {"source", source_name},
                        {"top_k", std::to_string(effective_top_k)},
                    });
            }
            if (buffer == DeviceDistributionBuffer::Target)
            {
                stochastic_target_top_k_[static_cast<size_t>(slot)] = params.top_k;
                stochastic_target_row_formats_[static_cast<size_t>(slot)] =
                    StochasticRowFormat::CompactDistribution;
                stochastic_target_distribution_streams_[static_cast<size_t>(slot)] = stream;
                /*
                 * Target distribution slots are reused for all-position
                 * verifier rows after the first target token has already been
                 * sampled.  Do not clear target sample readiness here: that
                 * readiness belongs to STOCHASTIC_TARGET_SAMPLE_TOKENS and is
                 * the event edge that lets the verifier summary read the
                 * deferred first token safely from another stream.
                 */
            }
            else
            {
                stochastic_draft_top_k_[static_cast<size_t>(slot)] = params.top_k;
                stochastic_draft_row_formats_[static_cast<size_t>(slot)] =
                    StochasticRowFormat::CompactDistribution;
                stochastic_draft_distribution_streams_[static_cast<size_t>(slot)] = stream;
                clearStochasticDraftSampleReadySlot(
                    slot,
                    StochasticSampleReadyClearMode::Force);
            }
        }
        return ok;
    }

    bool DeviceGraphOrchestrator::buildStochasticDistributionsOnDevice(
        DeviceLogitsSource source,
        int first_row,
        DeviceDistributionBuffer buffer,
        int first_slot,
        int row_count,
        const SamplingParams &params,
        int vocab_size)
    {
        if (!supportsDeviceStochasticMTPVerification() ||
            (source != DeviceLogitsSource::AllPosition &&
             source != DeviceLogitsSource::Main &&
             source != DeviceLogitsSource::MainRequestBatch) ||
            buffer != DeviceDistributionBuffer::Target ||
            first_row < 0 ||
            first_slot < 0 ||
            row_count <= 0 ||
            params.top_k <= 0 ||
            params.top_k > static_cast<int>(kStochasticDistributionMaxK))
        {
            return false;
        }

        if (first_slot + row_count > stochastic_target_row_capacity_)
            return false;

        auto *token_ids = static_cast<int *>(stochastic_target_token_ids_dev_);
        auto *probs = static_cast<float *>(stochastic_target_probs_dev_);
        if (!token_ids || !probs)
            return false;

        for (int row = 0; row < row_count; ++row)
        {
            const int slot = first_slot + row;
            stochastic_target_top_k_[static_cast<size_t>(slot)] = 0;
            stochastic_target_row_formats_[static_cast<size_t>(slot)] =
                StochasticRowFormat::Empty;
            stochastic_target_distribution_streams_[static_cast<size_t>(slot)] = nullptr;
        }

        /*
         * Batched all-position verifier distributions must stay ordered behind
         * the launch-only verifier replay. Individual rows do not consume the
         * pending stream; the final compact summary copy closes this handoff.
         */
        const PendingLogitsStreamRole stream_role =
            (source == DeviceLogitsSource::Main ||
             source == DeviceLogitsSource::MainRequestBatch)
                ? PendingLogitsStreamRole::MainDecode
                : PendingLogitsStreamRole::AllPositionVerifier;
        void *stream = peekPendingLogitsStream(stream_role);
        if (!stream)
            stream = explicitGPUStreamForOperation("buildStochasticDistributionsOnDevice");
        if (!stream)
            return false;

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        TensorBase *tensor =
            source == DeviceLogitsSource::Main
                ? state_.logits.get()
                : state_.all_position_logits.get();
        if (!tensor || !tensor->gpu_data_ptr())
            return false;
        const auto &shape = tensor->shape();
        if (shape.size() < 2)
            return false;
        const size_t rows = shape[0];
        const size_t cols = shape[1];
        if (first_row + row_count > static_cast<int>(rows) ||
            (vocab_size > 0 && static_cast<size_t>(vocab_size) != cols))
        {
            return false;
        }

        const float *row_ptr =
            static_cast<const float *>(tensor->gpu_data_ptr()) +
            static_cast<size_t>(first_row) * cols;
        const size_t slot_offset =
            static_cast<size_t>(first_slot) * kStochasticDistributionMaxK;

        bool ok = false;
        const char *source_name =
            source == DeviceLogitsSource::Main
                ? "main"
                : source == DeviceLogitsSource::MainRequestBatch
                      ? "main_request_batch"
                      : "all_position";
        const std::map<std::string, std::string> distribution_tags = {
            {"first_slot", std::to_string(first_slot)},
            {"rows", std::to_string(row_count)},
            {"source", source_name},
            {"top_k", std::to_string(params.top_k)}};
        std::shared_ptr<void> gpu_timing_start;
        std::shared_ptr<void> gpu_timing_stop;
        if (!beginPendingGpuTimingMeasurement(
                "stochastic_distribution_batch_build_gpu",
                stream,
                &gpu_timing_start,
                &gpu_timing_stop))
        {
            return false;
        }
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "stochastic_distribution_batch_build_enqueue",
                "decode",
                state_.device_id.toString(),
                distribution_tags);
            ok = backend->enqueueBuildTopKTopPDistributionsF32Device(
                row_ptr,
                row_count,
                static_cast<int>(cols),
                static_cast<int>(cols),
                params.top_k,
                params.top_p,
                params.temperature,
                state_.device_id.gpu_ordinal(),
                stream,
                token_ids + slot_offset,
                static_cast<int>(kStochasticDistributionMaxK),
                probs + slot_offset,
                stochastic_topk_partial_vals_dev_,
                stochastic_topk_partial_idxs_dev_,
                stochastic_topk_partial_capacity_);
        }
        if (ok)
        {
            finishPendingGpuTimingMeasurement(
                "stochastic_distribution_batch_build_gpu",
                stream,
                distribution_tags,
                std::move(gpu_timing_start),
                std::move(gpu_timing_stop));
        }

        if (!ok)
            return false;

        for (int row = 0; row < row_count; ++row)
        {
            const int slot = first_slot + row;
            stochastic_target_top_k_[static_cast<size_t>(slot)] = params.top_k;
            stochastic_target_row_formats_[static_cast<size_t>(slot)] =
                StochasticRowFormat::CompactDistribution;
            stochastic_target_distribution_streams_[static_cast<size_t>(slot)] = stream;
        }

        const int effective_top_k =
            std::min(params.top_k, static_cast<int>(cols));
        size_t partial_blocks =
            (cols + kStochasticTopKSmallKThreads - 1) /
            kStochasticTopKSmallKThreads;
        partial_blocks = std::max<size_t>(partial_blocks, 1);
        partial_blocks = std::min(partial_blocks, kStochasticTopKPartialBlocks);
        if (effective_top_k > 0 &&
            effective_top_k <= static_cast<int>(kStochasticTopKSmallKCap))
        {
            PerfStatsCollector::addCounter(
                "mtp",
                "stochastic_topk_smallk_scratch_distribution_builds",
                static_cast<double>(row_count),
                "decode",
                state_.device_id.toString(),
                {
                    {"source", std::string(source_name) + "_batched"},
                    {"top_k", std::to_string(effective_top_k)},
                    {"partial_blocks", std::to_string(partial_blocks)},
                });
        }

        return true;
    }

    bool DeviceGraphOrchestrator::sampleStochasticDistributionOnDeviceImpl(
        DeviceDistributionBuffer buffer,
        int slot,
        float threshold,
        int32_t *out_token_host,
        uint64_t threshold_seed,
        const int32_t *threshold_position_device,
        int threshold_position_offset)
    {
        if (!supportsDeviceStochasticMTPVerification() ||
            slot < 0 ||
            (threshold_position_device && threshold_seed == 0) ||
            (!threshold_position_device && threshold_seed != 0))
            return false;

        int *token_ids = nullptr;
        float *probs = nullptr;
        int max_slots = 0;
        if (buffer == DeviceDistributionBuffer::Target)
        {
            token_ids = static_cast<int *>(stochastic_target_token_ids_dev_);
            probs = static_cast<float *>(stochastic_target_probs_dev_);
            max_slots = stochastic_target_row_capacity_;
        }
        else
        {
            token_ids = static_cast<int *>(stochastic_draft_token_ids_dev_);
            probs = static_cast<float *>(stochastic_draft_probs_dev_);
            max_slots = stochastic_draft_row_capacity_;
        }
        if (!token_ids || !probs || slot >= max_slots)
            return false;
        const int active_top_k =
            buffer == DeviceDistributionBuffer::Target
                ? stochastic_target_top_k_[static_cast<size_t>(slot)]
                : stochastic_draft_top_k_[static_cast<size_t>(slot)];
        if (active_top_k <= 0 ||
            active_top_k > static_cast<int>(kStochasticDistributionMaxK))
        {
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;
        void *stream = nullptr;
        if (buffer == DeviceDistributionBuffer::Target)
        {
            stream = stochastic_target_distribution_streams_[static_cast<size_t>(slot)];
            stochastic_target_distribution_streams_[static_cast<size_t>(slot)] = nullptr;
        }
        else
        {
            stream = stochastic_draft_distribution_streams_[static_cast<size_t>(slot)];
            stochastic_draft_distribution_streams_[static_cast<size_t>(slot)] = nullptr;
        }
        if (!stream)
        {
            // A distribution constructed by a caller without a dedicated
            // producer stream is ordered on the orchestrator's explicit
            // operation stream. The device-default/null stream is never
            // acceptable here.
            stream = explicitGPUStreamForOperation("sampleStochasticDistributionOnDevice");
        }
        if (!stream)
            return false;

        const char *buffer_name =
            buffer == DeviceDistributionBuffer::Draft ? "draft" : "target";

        /*
         * Sampled target and draft tokens both outlive the sampler kernel.
         * Keep them out of STOCHASTIC_VERIFY_TOKENS because verifier rows reuse
         * that buffer for row-local accept/reject outputs later in the same
         * speculative step.
         */
        int *out_token_dev =
            (buffer == DeviceDistributionBuffer::Draft)
                ? static_cast<int *>(stochastic_draft_sample_tokens_dev_) + slot
                : static_cast<int *>(stochastic_target_sample_tokens_dev_) + slot;
        if (!out_token_dev)
            return false;

        /*
         * The selected draft probability is small but valuable metadata for the
         * vLLM-style fused verifier: the verifier can read q(draft_token)
         * directly instead of rebuilding or rescanning the draft distribution.
         * Target samples do not currently need the same metadata, so only draft
         * slots write this companion buffer.
         */
        float *out_probability_dev =
            (buffer == DeviceDistributionBuffer::Draft && stochastic_draft_sample_probs_dev_)
                ? static_cast<float *>(stochastic_draft_sample_probs_dev_) + slot
                : nullptr;
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "sample_stochastic_distribution_enqueue",
                "decode",
                state_.device_id.toString(),
                {{"buffer", buffer_name},
                 {"slot", std::to_string(slot)},
                 {"top_k", std::to_string(active_top_k)},
                 {"resident_position", boolTag(threshold_position_device != nullptr)}});
            if (!backend->enqueueSampleDistributionF32Device(
                    token_ids + static_cast<size_t>(slot) * kStochasticDistributionMaxK,
                    probs + static_cast<size_t>(slot) * kStochasticDistributionMaxK,
                    active_top_k,
                    threshold,
                    state_.device_id.gpu_ordinal(),
                    stream,
                    out_token_dev,
                    out_probability_dev,
                    threshold_seed,
                    threshold_position_device,
                    threshold_position_offset))
            {
                return false;
            }
        }

        if (buffer == DeviceDistributionBuffer::Draft)
        {
            if (!recordStochasticDraftSampleReady(
                    slot,
                    stream,
                    /*verifier_consumer_pending=*/out_token_host == nullptr))
                return false;
        }
        else
        {
            if (!recordStochasticTargetSampleReady(
                    slot,
                    stream,
                    /*verifier_consumer_pending=*/out_token_host == nullptr))
                return false;
        }

        if (!out_token_host)
        {
            PerfStatsCollector::addCounter(
                "mtp",
                "sample_stochastic_distribution_deferred_host_reads",
                1.0,
                "decode",
                state_.device_id.toString(),
                {{"buffer", buffer_name},
                 {"slot", std::to_string(slot)},
                 {"top_k", std::to_string(active_top_k)}});
            return true;
        }

        int32_t token = -1;
        /*
         * This read is the semantic point where the runner needs the sampled
         * draft token on the host. It drains all earlier distribution work on
         * `stream`, but the source is trusted arena scratch, so use the fast
         * D2H path and avoid per-token ROCm pointer-attribute validation.
         */
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "sample_stochastic_distribution_d2h_sync",
                "decode",
                state_.device_id.toString(),
                {{"buffer", buffer_name},
                 {"slot", std::to_string(slot)},
                 {"top_k", std::to_string(active_top_k)}});
            if (!backend->deviceToHostFast(&token, out_token_dev, sizeof(int),
                                           state_.device_id.gpu_ordinal(), stream))
            {
                return false;
            }
        }
        drainPendingGpuTimingMeasurements(backend);
        *out_token_host = token;
        return true;
    }

    bool DeviceGraphOrchestrator::sampleStochasticDraftProposalOnDeviceImpl(
        DeviceLogitsSource source,
        int row,
        int slot,
        const SamplingParams &params,
        int vocab_size,
        float threshold,
        int32_t *out_token_host,
        bool verifier_consumer_pending)
    {
        (void)params;
        (void)threshold;

        if (!supportsDeviceStochasticMTPVerification() ||
            source != DeviceLogitsSource::MTP ||
            row < 0 || slot < 0 ||
            slot >= stochastic_draft_row_capacity_ ||
            vocab_size <= 0 ||
            !stochastic_draft_sample_tokens_dev_ ||
            !stochastic_draft_sample_probs_dev_ ||
            !argmax_partial_vals_dev_ ||
            !argmax_partial_idxs_dev_ ||
            argmax_partial_capacity_ <= 0)
        {
            return false;
        }

        auto it = state_.extension_buffers.find(BufferId::MTP_LOGITS);
        TensorBase *tensor =
            it == state_.extension_buffers.end() ? nullptr : it->second.get();
        if (!tensor || !tensor->deviceValid() || !tensor->gpu_data_ptr())
            return false;

        const auto &shape = tensor->shape();
        if (shape.empty())
            return false;
        const size_t rows = shape.size() >= 2 ? shape[0] : 1;
        const size_t cols = shape.size() >= 2 ? shape[1] : shape[0];
        if (cols == 0 ||
            cols > static_cast<size_t>(std::numeric_limits<int>::max()) ||
            static_cast<size_t>(row) >= rows ||
            static_cast<int>(cols) != vocab_size)
        {
            return false;
        }

        void *stream = consumePendingLogitsStream(
            PendingLogitsStreamRole::MTPSidecar,
            "sampleStochasticDraftProposalOnDevice(MTP)");
        if (!stream)
            stream = explicitGPUStreamForOperation("sampleStochasticDraftProposalOnDevice");
        if (!stream)
            return false;

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        stochastic_draft_top_k_[static_cast<size_t>(slot)] = 0;
        stochastic_draft_row_formats_[static_cast<size_t>(slot)] =
            StochasticRowFormat::Empty;
        stochastic_draft_distribution_streams_[static_cast<size_t>(slot)] = nullptr;
        clearStochasticDraftSampleReadySlot(
            slot,
            StochasticSampleReadyClearMode::Force);

        const float *row_ptr =
            static_cast<const float *>(tensor->gpu_data_ptr()) +
            static_cast<size_t>(row) * cols;
        auto *out_token_dev =
            static_cast<int *>(stochastic_draft_sample_tokens_dev_) + slot;
        auto *out_value_dev =
            static_cast<float *>(stochastic_draft_sample_probs_dev_) + slot;

        /*
         * vLLM's default MTP proposal is greedy. The verifier receives the
         * sampled token and treats the draft distribution q as one-hot at that
         * token, avoiding full draft probability/logit rows in runner scratch.
         */
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "stochastic_draft_greedy_proposal_enqueue",
                "decode",
                state_.device_id.toString(),
                {{"slot", std::to_string(slot)},
                 {"vocab", std::to_string(vocab_size)}});
            if (!backend->enqueueArgmaxF32BatchedRowsDevice(
                    row_ptr,
                    /*rows=*/1,
                    static_cast<int>(cols),
                    state_.device_id.gpu_ordinal(),
                    stream,
                    out_value_dev,
                    out_token_dev,
                    argmax_partial_vals_dev_,
                    argmax_partial_idxs_dev_,
                    argmax_partial_capacity_))
            {
                return false;
            }
        }

        if (!recordStochasticDraftSampleReady(
                slot,
                stream,
                /*verifier_consumer_pending=*/
                verifier_consumer_pending || out_token_host == nullptr))
            return false;

        PerfStatsCollector::addCounter(
            "mtp",
            "stochastic_draft_greedy_proposals",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"slot", std::to_string(slot)}});

        if (!out_token_host)
        {
            if (!debugEnv().runtime_debug.mtp_publication_diagnostics)
                return true;

            /*
             * Keep scalar and request-batched diagnostics symmetric.  This
             * debug-only read observes the arena draft slot after the exact
             * production argmax and readiness-event publication, allowing a
             * parity failure to compare proposal bytes at the common boundary.
             */
            int32_t diagnostic_token = -1;
            if (!backend->deviceToHostFast(
                    &diagnostic_token,
                    out_token_dev,
                    sizeof(int32_t),
                    state_.device_id.gpu_ordinal(),
                    stream))
            {
                return false;
            }
            LOG_INFO(
                "[MTPPublicationDiagnostics] phase=scalar_sidecar_draft_publication"
                << " row=" << row
                << " slot=" << slot
                << " draft_token=" << diagnostic_token);
            return diagnostic_token >= 0;
        }

        int32_t token = -1;
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "stochastic_draft_greedy_proposal_d2h_sync",
                "decode",
                state_.device_id.toString(),
                {{"slot", std::to_string(slot)}});
            if (!backend->deviceToHostFast(&token,
                                           out_token_dev,
                                           sizeof(int),
                                           state_.device_id.gpu_ordinal(),
                                           stream))
            {
                return false;
            }
        }
        *out_token_host = token;
        return token >= 0;
    }

    int DeviceGraphOrchestrator::sampleStochasticDraftProposalOnDevice(
        DeviceLogitsSource source,
        int row,
        int slot,
        const SamplingParams &params,
        int vocab_size,
        float threshold)
    {
        int32_t token = -1;
        if (!sampleStochasticDraftProposalOnDeviceImpl(
                source,
                row,
                slot,
                params,
                vocab_size,
                threshold,
                &token,
                /*verifier_consumer_pending=*/true))
        {
            return -1;
        }
        return token;
    }

    bool DeviceGraphOrchestrator::sampleStochasticDraftProposalOnDeviceDeferred(
        DeviceLogitsSource source,
        int row,
        int slot,
        const SamplingParams &params,
        int vocab_size,
        float threshold)
    {
        return sampleStochasticDraftProposalOnDeviceImpl(
            source,
            row,
            slot,
            params,
            vocab_size,
            threshold,
            /*out_token_host=*/nullptr,
            /*verifier_consumer_pending=*/true);
    }

    DeviceStochasticDraftSampleSlotHandle
    DeviceGraphOrchestrator::deviceStochasticDraftSampleSlot(
        int slot,
        bool require_ready)
    {
        DeviceStochasticDraftSampleSlotHandle handle;
        handle.slot = slot;
        handle.device = state_.device_id;

        if (!state_.device_id.is_gpu() ||
            slot < 0 ||
            slot >= stochastic_draft_row_capacity_ ||
            slot >= static_cast<int>(stochastic_draft_sample_ready_.size()) ||
            !stochastic_draft_sample_tokens_dev_)
        {
            return {};
        }

        const auto &ready =
            stochastic_draft_sample_ready_[static_cast<size_t>(slot)];
        if (require_ready && (!ready.valid || !ready.event))
        {
            return {};
        }

        /*
         * A ready slot must keep using the producing stream so a rank-level
         * broadcast is naturally sequenced after the sampler kernel.  A not-yet
         * ready destination slot still needs a real runner stream; the broadcast
         * will become the new producer and will record a fresh event on that
         * stream before any sidecar/verifier consumer can proceed.
         */
        void *stream = ready.valid
                           ? ready.producer_stream
                           : explicitGPUStreamForOperation(
                                 "deviceStochasticDraftSampleSlot");
        if (!stream)
            return {};

        handle.token_device =
            static_cast<int32_t *>(stochastic_draft_sample_tokens_dev_) + slot;
        handle.stream = stream;
        return handle.valid() ? handle : DeviceStochasticDraftSampleSlotHandle{};
    }

    bool DeviceGraphOrchestrator::recordStochasticDraftSampleSlotReadyFromDevice(
        int slot,
        void *producer_stream,
        bool verifier_consumer_pending)
    {
        if (!state_.device_id.is_gpu() ||
            slot < 0 ||
            slot >= stochastic_draft_row_capacity_ ||
            !stochastic_draft_sample_tokens_dev_ ||
            !producer_stream)
        {
            return false;
        }

        return recordStochasticDraftSampleReady(
            slot,
            producer_stream,
            verifier_consumer_pending);
    }

    DeviceStochasticTargetSampleSlotHandle
    DeviceGraphOrchestrator::deviceStochasticTargetSampleSlot(
        int slot,
        bool require_ready)
    {
        DeviceStochasticTargetSampleSlotHandle handle;
        handle.slot = slot;
        handle.device = state_.device_id;

        if (!state_.device_id.is_gpu() ||
            slot < 0 ||
            slot >= stochastic_target_row_capacity_ ||
            slot >= static_cast<int>(stochastic_target_sample_ready_.size()) ||
            !stochastic_target_sample_tokens_dev_)
        {
            return {};
        }

        const auto &ready =
            stochastic_target_sample_ready_[static_cast<size_t>(slot)];
        if (require_ready && (!ready.valid || !ready.event))
            return {};

        /*
         * A ready primary slot remains ordered on its sampler stream. A peer
         * destination uses the runner's explicit operation stream until the
         * collective becomes its producer. The rank records a fresh event on
         * that same stream immediately after NCCL/RCCL writes the token.
         */
        void *stream = ready.valid
                           ? ready.producer_stream
                           : explicitGPUStreamForOperation(
                                 "deviceStochasticTargetSampleSlot");
        if (!stream)
            return {};

        handle.token_device =
            static_cast<int32_t *>(stochastic_target_sample_tokens_dev_) + slot;
        handle.stream = stream;
        return handle.valid() ? handle : DeviceStochasticTargetSampleSlotHandle{};
    }

    bool DeviceGraphOrchestrator::recordStochasticTargetSampleSlotReadyFromDevice(
        int slot,
        void *producer_stream,
        bool verifier_consumer_pending)
    {
        if (!state_.device_id.is_gpu() ||
            slot < 0 ||
            slot >= stochastic_target_row_capacity_ ||
            !stochastic_target_sample_tokens_dev_ ||
            !producer_stream)
        {
            return false;
        }

        return recordStochasticTargetSampleReady(
            slot,
            producer_stream,
            verifier_consumer_pending);
    }

    bool DeviceGraphOrchestrator::stageStochasticDraftTokensForDeviceVerification(
        const int32_t *draft_tokens,
        int draft_token_count,
        int first_draft_slot)
    {
        if (!state_.device_id.is_gpu() ||
            !draft_tokens ||
            first_draft_slot < 0 ||
            draft_token_count <= 0 ||
            first_draft_slot + draft_token_count > stochastic_draft_row_capacity_ ||
            !stochastic_draft_sample_tokens_dev_)
        {
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        void *stream = explicitGPUStreamForOperation(
            "stageStochasticDraftTokensForDeviceVerification");
        if (!backend || !stream)
            return false;

        for (int slot = 0; slot < draft_token_count; ++slot)
            clearStochasticDraftSampleReadySlot(
                first_draft_slot + slot,
                StochasticSampleReadyClearMode::Force);

        if (!backend->hostToDeviceOnStream(
                static_cast<int32_t *>(stochastic_draft_sample_tokens_dev_) +
                    first_draft_slot,
                draft_tokens,
                sizeof(int32_t) * static_cast<size_t>(draft_token_count),
                state_.device_id.gpu_ordinal(),
                stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to stage stochastic draft tokens for verifier");
            return false;
        }

        for (int slot = 0; slot < draft_token_count; ++slot)
        {
            if (!recordStochasticDraftSampleReady(
                    first_draft_slot + slot,
                    stream,
                    /*verifier_consumer_pending=*/true))
                return false;
        }

        PerfStatsCollector::addCounter(
            "mtp",
            "stochastic_request_batch_draft_token_stages",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"draft_tokens", std::to_string(draft_token_count)},
             {"first_slot", std::to_string(first_draft_slot)}});
        return true;
    }

    bool DeviceGraphOrchestrator::stageStochasticTargetTokenForDeviceSampling(
        int32_t target_token,
        int target_sample_slot)
    {
        if (!state_.device_id.is_gpu() ||
            target_token < 0 ||
            target_sample_slot < 0 ||
            target_sample_slot >= stochastic_target_row_capacity_ ||
            !stochastic_target_sample_tokens_dev_)
        {
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        void *stream = explicitGPUStreamForOperation(
            "stageStochasticTargetTokenForDeviceSampling");
        if (!backend || !stream)
            return false;

        clearStochasticTargetSampleReadySlot(
            target_sample_slot,
            StochasticSampleReadyClearMode::Force);
        if (!backend->hostToDeviceOnStream(
                static_cast<int32_t *>(stochastic_target_sample_tokens_dev_) +
                    target_sample_slot,
                &target_token,
                sizeof(int32_t),
                state_.device_id.gpu_ordinal(),
                stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to stage stochastic target token for device sampling");
            return false;
        }
        if (!recordStochasticTargetSampleReady(
                target_sample_slot,
                stream,
                /*verifier_consumer_pending=*/true))
        {
            return false;
        }

        PerfStatsCollector::addCounter(
            "mtp",
            "stochastic_target_token_device_stages",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"slot", std::to_string(target_sample_slot)},
             {"token", std::to_string(target_token)}});
        return true;
    }

    bool DeviceGraphOrchestrator::publishDeviceResidentConditionTokenToTargetSampleSlot(
        const DeviceResidentLogicalSequenceStateHandle &logical_state,
        int request_index,
        int target_sample_slot)
    {
        if (!state_.device_id.is_gpu() ||
            !logical_state.coversRequest(request_index) ||
            logical_state.device != state_.device_id ||
            target_sample_slot < 0 ||
            target_sample_slot >= stochastic_target_row_capacity_ ||
            !stochastic_target_sample_tokens_dev_)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Invalid resident condition-token target publication"
                      << " request=" << request_index
                      << " target_slot=" << target_sample_slot
                      << " runner=" << state_.device_id.toString());
            return false;
        }
        if (!device_resident_logical_sequence_state_mailbox_.ownsHandle(
                logical_state,
                live_replay_state_epoch_))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Resident condition-token target publication received a stale or foreign mailbox");
            return false;
        }

        const int32_t *condition_token_device =
            logical_state.nextConditionTokenDeviceForRequest(request_index);
        IBackend *backend = getBackendFor(state_.device_id);
        void *stream = explicitGPUStreamForOperation(
            "publishDeviceResidentConditionTokenToTargetSampleSlot");
        if (!condition_token_device || !backend || !stream)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Resident condition-token target publication requires a device token, backend, and explicit stream");
            return false;
        }

        /*
         * Snapshot the token before any shifted-cache consumer retargets the
         * logical-state transaction. The target sample arena is persistent, so
         * the later main graph can consume this exact token after the mailbox
         * itself has advanced to a new transaction epoch.
         */
        clearStochasticTargetSampleReadySlot(
            target_sample_slot,
            StochasticSampleReadyClearMode::Force);
        if (!waitForDeviceResidentLogicalSequenceStateMailbox(
                stream,
                "resident_condition_token_target_publication"))
        {
            return false;
        }
        if (!backend->deviceCopyAsync(
                static_cast<int32_t *>(stochastic_target_sample_tokens_dev_) +
                    target_sample_slot,
                condition_token_device,
                sizeof(int32_t),
                state_.device_id.gpu_ordinal(),
                stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to copy resident condition token into target sample slot");
            return false;
        }
        if (!recordStochasticTargetSampleReady(
                target_sample_slot,
                stream,
                /*verifier_consumer_pending=*/true))
        {
            return false;
        }

        PerfStatsCollector::addCounter(
            "mtp",
            "resident_condition_token_target_publications",
            1.0,
            "decode",
            state_.device_id.toString(),
            {{"request_index", std::to_string(request_index)},
             {"target_slot", std::to_string(target_sample_slot)},
             {"transfer", "d2d"}});
        return true;
    }

    int DeviceGraphOrchestrator::sampleStochasticDistributionOnDevice(
        DeviceDistributionBuffer buffer,
        int slot,
        float threshold)
    {
        int32_t token = -1;
        if (!sampleStochasticDistributionOnDeviceImpl(
                buffer,
                slot,
                threshold,
                &token))
        {
            return -1;
        }
        return token;
    }

    bool DeviceGraphOrchestrator::sampleStochasticDistributionOnDeviceDeferred(
        DeviceDistributionBuffer buffer,
        int slot,
        float threshold)
    {
        return sampleStochasticDistributionOnDeviceImpl(
            buffer,
            slot,
            threshold,
            /*out_token_host=*/nullptr);
    }

    bool DeviceGraphOrchestrator::verifyStochasticDistributionsOnDevice(
        int target_slot,
        int draft_slot,
        int draft_token,
        float accept_threshold,
        float residual_threshold,
        DeviceSpeculativeVerifyResult *out)
    {
        if (!supportsDeviceStochasticMTPVerification() || !out ||
            target_slot < 0 || draft_slot < 0 ||
            target_slot >= stochastic_target_row_capacity_ ||
            draft_slot >= stochastic_draft_row_capacity_)
        {
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;
        void *stream = explicitGPUStreamForOperation("verifyStochasticDistributionsOnDevice");
        if (!stream)
            return false;

        int *target_ids = static_cast<int *>(stochastic_target_token_ids_dev_) +
                          static_cast<size_t>(target_slot) * kStochasticDistributionMaxK;
        float *target_probs = static_cast<float *>(stochastic_target_probs_dev_) +
                              static_cast<size_t>(target_slot) * kStochasticDistributionMaxK;
        int *draft_ids = static_cast<int *>(stochastic_draft_token_ids_dev_) +
                         static_cast<size_t>(draft_slot) * kStochasticDistributionMaxK;
        float *draft_probs = static_cast<float *>(stochastic_draft_probs_dev_) +
                             static_cast<size_t>(draft_slot) * kStochasticDistributionMaxK;
        const int target_top_k = stochastic_target_top_k_[static_cast<size_t>(target_slot)];
        const int draft_top_k = stochastic_draft_top_k_[static_cast<size_t>(draft_slot)];
        if (target_top_k <= 0 ||
            draft_top_k <= 0 ||
            target_top_k != draft_top_k ||
            target_top_k > static_cast<int>(kStochasticDistributionMaxK))
        {
            return false;
        }

        int *out_token_dev = static_cast<int *>(stochastic_verify_tokens_dev_) + target_slot;
        int *out_accepted_dev = static_cast<int *>(stochastic_verify_accepted_dev_) + target_slot;
        float *out_accept_prob_dev =
            static_cast<float *>(stochastic_verify_accept_probs_dev_) + target_slot;
        float *out_threshold_dev =
            static_cast<float *>(stochastic_verify_thresholds_dev_) + target_slot;

        if (!backend->enqueueSpeculativeVerifyDistributionsF32DeviceThresholds(
                target_ids,
                target_probs,
                draft_ids,
                draft_probs,
                target_top_k,
                draft_token,
                accept_threshold,
                residual_threshold,
                state_.device_id.gpu_ordinal(),
                stream,
                out_token_dev,
                out_accepted_dev,
                out_accept_prob_dev,
                out_threshold_dev))
        {
            return false;
        }

        int token = -1;
        int accepted = 0;
        float accept_probability = 0.0f;
        float threshold = 0.0f;
        /*
         * These compact result buffers are written by the verifier kernel on
         * the same stream. Fast D2H preserves the synchronization point while
         * skipping backend pointer validation that dominates tiny ROCm copies.
         */
        if (!backend->deviceToHostFast(&token, out_token_dev, sizeof(int),
                                       state_.device_id.gpu_ordinal(), stream) ||
            !backend->deviceToHostFast(&accepted, out_accepted_dev, sizeof(int),
                                       state_.device_id.gpu_ordinal(), stream) ||
            !backend->deviceToHostFast(&accept_probability, out_accept_prob_dev, sizeof(float),
                                       state_.device_id.gpu_ordinal(), stream) ||
            !backend->deviceToHostFast(&threshold, out_threshold_dev, sizeof(float),
                                       state_.device_id.gpu_ordinal(), stream))
        {
            return false;
        }

        out->token = token;
        out->accepted = accepted != 0;
        out->accept_probability = accept_probability;
        out->accept_threshold = threshold;
        return token >= 0;
    }

    bool DeviceGraphOrchestrator::verifyStochasticDistributionsBatchOnDevice(
        int first_target_slot,
        int first_draft_slot,
        const int32_t *draft_tokens,
        const float *accept_thresholds,
        const float *residual_thresholds,
        int row_count,
        DeviceSpeculativeVerifyResult *out)
    {
        if (!supportsDeviceStochasticMTPVerification() ||
            first_target_slot < 0 || first_draft_slot < 0 ||
            row_count <= 0 ||
            row_count > mtp_max_draft_depth_ ||
            first_target_slot + row_count > stochastic_target_row_capacity_ ||
            first_draft_slot + row_count > stochastic_draft_row_capacity_ ||
            !draft_tokens || !accept_thresholds || !residual_thresholds || !out)
        {
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;
        /*
         * The verifier consumes compact target distributions built immediately
         * after the main decode row.  Prefer that producer stream so the verifier
         * is naturally ordered behind the distribution build without a host sync.
         * A null producer stream means the row was either rebuilt through a
         * synchronized path or is being exercised by a non-graph unit runner.
         */
        void *stream =
            stochastic_target_distribution_streams_[static_cast<size_t>(first_target_slot)];
        if (!stream)
        {
            stream = explicitGPUStreamForOperation(
                "verifyStochasticDistributionsBatchOnDevice");
        }
        if (!stream)
            return false;

        const int target_top_k =
            stochastic_target_top_k_[static_cast<size_t>(first_target_slot)];
        if (target_top_k <= 0 ||
            target_top_k > static_cast<int>(kStochasticDistributionMaxK))
        {
            return false;
        }
        bool uses_one_hot_draft_tokens = false;
        bool uses_draft_distribution_rows = false;
        for (int row = 0; row < row_count; ++row)
        {
            const int target_slot = first_target_slot + row;
            const int draft_slot = first_draft_slot + row;
            const int draft_top_k =
                stochastic_draft_top_k_[static_cast<size_t>(draft_slot)];
            if (stochastic_target_top_k_[static_cast<size_t>(target_slot)] != target_top_k)
            {
                return false;
            }
            if (draft_top_k == target_top_k)
            {
                uses_draft_distribution_rows = true;
            }
            else if (draft_top_k <= 0)
            {
                uses_one_hot_draft_tokens = true;
            }
            else
            {
                return false;
            }
        }

        if (uses_one_hot_draft_tokens == uses_draft_distribution_rows)
        {
            return false;
        }

        if (uses_one_hot_draft_tokens &&
            !waitForRequiredStochasticDraftSampleReadyRange(
                first_draft_slot,
                row_count,
                stream,
                "decode_equivalent_stochastic_verifier"))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to order decode-equivalent stochastic verifier after sampled draft tokens");
            return false;
        }

        auto *target_ids =
            static_cast<int *>(stochastic_target_token_ids_dev_) +
            static_cast<size_t>(first_target_slot) * kStochasticDistributionMaxK;
        auto *target_probs =
            static_cast<float *>(stochastic_target_probs_dev_) +
            static_cast<size_t>(first_target_slot) * kStochasticDistributionMaxK;
        auto *draft_ids =
            static_cast<int *>(stochastic_draft_token_ids_dev_) +
            static_cast<size_t>(first_draft_slot) * kStochasticDistributionMaxK;
        auto *draft_probs =
            static_cast<float *>(stochastic_draft_probs_dev_) +
            static_cast<size_t>(first_draft_slot) * kStochasticDistributionMaxK;
        auto *sampled_draft_tokens =
            stochastic_draft_sample_tokens_dev_
                ? static_cast<int *>(stochastic_draft_sample_tokens_dev_) +
                      first_draft_slot
                : nullptr;
        auto *out_token_dev =
            static_cast<int *>(stochastic_verify_tokens_dev_) + first_target_slot;
        auto *out_accepted_dev =
            static_cast<int *>(stochastic_verify_accepted_dev_) + first_target_slot;
        auto *out_accept_prob_dev =
            static_cast<float *>(stochastic_verify_accept_probs_dev_) + first_target_slot;
        auto *out_threshold_dev =
            static_cast<float *>(stochastic_verify_thresholds_dev_) + first_target_slot;

        bool verify_enqueued = false;
        if (uses_one_hot_draft_tokens)
        {
            if (!sampled_draft_tokens)
                return false;
            verify_enqueued =
                backend->enqueueSpeculativeVerifyDistributionsF32DeviceThresholdsBatchDeviceTokens(
                    target_ids,
                    target_probs,
                    /*draft_token_ids_device=*/nullptr,
                    /*draft_probs_device=*/nullptr,
                    target_top_k,
                    static_cast<int>(kStochasticDistributionMaxK),
                    sampled_draft_tokens,
                    accept_thresholds,
                    residual_thresholds,
                    row_count,
                    state_.device_id.gpu_ordinal(),
                    stream,
                    out_token_dev,
                    out_accepted_dev,
                    out_accept_prob_dev,
                    out_threshold_dev);
        }
        else
        {
            verify_enqueued =
                backend->enqueueSpeculativeVerifyDistributionsF32DeviceThresholdsBatch(
                    target_ids,
                    target_probs,
                    draft_ids,
                    draft_probs,
                    target_top_k,
                    static_cast<int>(kStochasticDistributionMaxK),
                    draft_tokens,
                    accept_thresholds,
                    residual_thresholds,
                    row_count,
                    state_.device_id.gpu_ordinal(),
                    stream,
                    out_token_dev,
                    out_accepted_dev,
                    out_accept_prob_dev,
                    out_threshold_dev);
        }
        if (!verify_enqueued)
        {
            return false;
        }

        std::vector<int> tokens(static_cast<size_t>(row_count));
        std::vector<int> accepted(static_cast<size_t>(row_count));
        std::vector<float> accept_probabilities(
            static_cast<size_t>(row_count));
        std::vector<float> thresholds(static_cast<size_t>(row_count));
        if (!backend->deviceToHostFast(tokens.data(), out_token_dev,
                                       sizeof(int) * static_cast<size_t>(row_count),
                                       state_.device_id.gpu_ordinal(), stream) ||
            !backend->deviceToHostFast(accepted.data(), out_accepted_dev,
                                       sizeof(int) * static_cast<size_t>(row_count),
                                       state_.device_id.gpu_ordinal(), stream) ||
            !backend->deviceToHostFast(accept_probabilities.data(), out_accept_prob_dev,
                                       sizeof(float) * static_cast<size_t>(row_count),
                                       state_.device_id.gpu_ordinal(), stream) ||
            !backend->deviceToHostFast(thresholds.data(), out_threshold_dev,
                                       sizeof(float) * static_cast<size_t>(row_count),
                                       state_.device_id.gpu_ordinal(), stream))
        {
            return false;
        }

        for (int row = 0; row < row_count; ++row)
        {
            out[row].accepted = accepted[static_cast<size_t>(row)] != 0;
            out[row].token = tokens[static_cast<size_t>(row)];
            out[row].accept_probability =
                accept_probabilities[static_cast<size_t>(row)];
            out[row].accept_threshold = thresholds[static_cast<size_t>(row)];
        }

        PerfStatsCollector::addCounter(
            "mtp",
            "stochastic_verify_batch_rows",
            static_cast<double>(row_count),
            "decode",
            state_.device_id.toString(),
            {{"top_k", std::to_string(target_top_k)},
             {"draft", uses_one_hot_draft_tokens ? "one_hot" : "distribution"}});
        return true;
    }

    bool DeviceGraphOrchestrator::verifyStochasticDistributionsBatchOutcomeOnDevice(
        int first_target_slot,
        int first_draft_slot,
        const int32_t *draft_tokens,
        const float *accept_thresholds,
        const float *residual_thresholds,
        int row_count,
        int32_t first_token,
        const int32_t *stop_tokens,
        int stop_token_count,
        int bonus_target_slot,
        float bonus_threshold,
        DeviceSpeculativeVerifyBatchOutcome *out,
        uint64_t inverse_sample_seed,
        int inverse_sample_first_logical_position,
        bool use_vllm_probability_rejection)
    {
        /*
         * Keep the old host-visible scalar API as a compatibility bridge over
         * the resident outcome contract.  This makes single-request decode and
         * request-batched decode use one ordering/stream path, and gives Phase
         * 10 publication work a single device-handle interface to consume.
         */
        DeviceSpeculativeOutcomeHandle handle;
        if (!verifyStochasticDistributionsBatchOutcomeOnDeviceResident(
                first_target_slot,
                first_draft_slot,
                draft_tokens,
                accept_thresholds,
                residual_thresholds,
                row_count,
                first_token,
                stop_tokens,
                stop_token_count,
                bonus_target_slot,
                bonus_threshold,
                &handle,
                inverse_sample_seed,
                inverse_sample_first_logical_position,
                use_vllm_probability_rejection))
        {
            return false;
        }
        return copyDeviceSpeculativeOutcomesToHost(handle, out);
    }

    bool DeviceGraphOrchestrator::verifyStochasticDistributionsBatchOutcomeOnDeviceFirstToken(
        int first_target_slot,
        int first_draft_slot,
        const int32_t *draft_tokens,
        const float *accept_thresholds,
        const float *residual_thresholds,
        int row_count,
        int first_target_sample_slot,
        const int32_t *stop_tokens,
        int stop_token_count,
        int bonus_target_slot,
        float bonus_threshold,
        DeviceSpeculativeVerifyBatchOutcome *out,
        uint64_t inverse_sample_seed,
        int inverse_sample_first_logical_position,
        bool use_vllm_probability_rejection)
    {
        DeviceSpeculativeOutcomeHandle handle;
        if (!verifyStochasticDistributionsBatchOutcomeOnDeviceFirstTokenResident(
                first_target_slot,
                first_draft_slot,
                draft_tokens,
                accept_thresholds,
                residual_thresholds,
                row_count,
                first_target_sample_slot,
                stop_tokens,
                stop_token_count,
                bonus_target_slot,
                bonus_threshold,
                &handle,
                inverse_sample_seed,
                inverse_sample_first_logical_position,
                use_vllm_probability_rejection))
        {
            return false;
        }
        return copyDeviceSpeculativeOutcomesToHost(handle, out);
    }

    bool DeviceGraphOrchestrator::verifyStochasticDistributionsRequestBatchOutcomesOnDevice(
        const DeviceStochasticBatchOutcomeRequest *requests,
        int request_count,
        DeviceSpeculativeVerifyBatchOutcome *outcomes)
    {
        DeviceSpeculativeOutcomeHandle handle;
        if (!verifyStochasticDistributionsRequestBatchOutcomesOnDeviceResident(
                requests,
                request_count,
                &handle))
        {
            return false;
        }
        return copyDeviceSpeculativeOutcomesToHost(handle, outcomes);
    }

    bool DeviceGraphOrchestrator::verifyStochasticDistributionsRequestBatchOutcomesOnDeviceResident(
        const DeviceStochasticBatchOutcomeRequest *requests,
        int request_count,
        DeviceSpeculativeOutcomeHandle *out_handle)
    {
        using namespace sampling_math;
        if (out_handle)
            *out_handle = DeviceSpeculativeOutcomeHandle{};
        if (!requests || !out_handle ||
            request_count <= 0 ||
            request_count > stochastic_batch_output_request_capacity_ ||
            !supportsDeviceStochasticMTPVerification() ||
            !stochastic_batch_output_tokens_dev_ ||
            !stochastic_batch_output_meta_dev_)
        {
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        /*
         * All target distributions for the scheduled request batch have already
         * been queued on the verifier stream.  Consume that stream once and keep
         * every per-request verify/bonus/summary launch ordered behind it, then
         * perform exactly one compact D2H copy for all request outcomes.
         */
        void *stream = consumePendingLogitsStream(
            PendingLogitsStreamRole::AllPositionVerifier,
            "verifyStochasticDistributionsRequestBatchOutcomesOnDevice");
        if (!stream)
        {
            stream = explicitGPUStreamForOperation(
                "verifyStochasticDistributionsRequestBatchOutcomesOnDevice");
        }
        if (!stream)
            return false;

        bool uses_resident_threshold_positions = false;
        bool uses_verifier_base_snapshot_positions = false;
        for (int request_idx = 0; request_idx < request_count; ++request_idx)
        {
            const DeviceStochasticDrawPositionSource source =
                requests[request_idx].draw_position_source;
            uses_resident_threshold_positions =
                uses_resident_threshold_positions ||
                source == DeviceStochasticDrawPositionSource::ResidentLogicalState;
            uses_verifier_base_snapshot_positions =
                uses_verifier_base_snapshot_positions ||
                source == DeviceStochasticDrawPositionSource::VerifierBaseSnapshot;
        }

        DeviceResidentLogicalSequenceStateHandle threshold_position_state;
        if (uses_resident_threshold_positions)
        {
            threshold_position_state = deviceResidentLogicalSequenceState();
            if (!threshold_position_state.valid() ||
                threshold_position_state.device != state_.device_id ||
                threshold_position_state.request_count < request_count ||
                !waitForDeviceResidentLogicalSequenceStateMailbox(
                    stream,
                    "stochastic_request_batch_threshold_positions"))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Stochastic request batch could not bind its resident threshold-position mailbox");
                return false;
            }
        }

        const MTPSpecDecodeMetadataDevicePointers &publication_metadata =
            mtp_spec_decode_metadata_binding_.devicePointers();
        if (uses_verifier_base_snapshot_positions &&
            (!mtp_publication_base_cache_snapshot_ready_ ||
             mtp_publication_base_cache_snapshot_request_count_ < request_count ||
             !publication_metadata.base_cached_tokens))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Seeded stochastic verifier could not bind the pre-verifier device base-count snapshot");
            return false;
        }

        std::shared_ptr<void> producer_start_timing_event;
        std::shared_ptr<void> producer_stop_timing_event;
        const bool collect_producer_gpu_timing =
            PerfStatsCollector::isEnabled() && state_.device_id.is_gpu();
        if (collect_producer_gpu_timing)
        {
            if (!acquirePersistentMTPGpuTimingEvents(
                    "stochastic_request_batch_compact_outcome_summary",
                    &producer_start_timing_event,
                    &producer_stop_timing_event))
            {
                return false;
            }
            if (!backend->recordEvent(
                    producer_start_timing_event.get(),
                    state_.device_id.gpu_ordinal(),
                    stream))
            {
                PerfStatsCollector::addCounter(
                    "mtp",
                    "stochastic_request_batch_summary_gpu_timing_record_failures",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {{"event", "start"}});
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to record the preallocated stochastic outcome timing start event");
                return false;
            }
        }

        for (int request_idx = 0; request_idx < request_count; ++request_idx)
        {
            const DeviceStochasticBatchOutcomeRequest &request =
                requests[request_idx];
            if (request.row_count <= 0 ||
                request.row_count > mtp_max_draft_depth_ ||
                request.stop_token_count < 0 ||
                request.stop_token_count > kSpeculativeBatchMaxStopTokens)
            {
                return false;
            }

            const int32_t *stop_tokens =
                request.stop_token_count > 0
                    ? request.stop_tokens.data()
                    : nullptr;
            const int32_t *draft_tokens = request.hostDraftTokensOrNull();
            const bool source_is_explicit =
                request.draw_position_source ==
                DeviceStochasticDrawPositionSource::ExplicitThresholds;
            const bool source_is_host_position =
                request.draw_position_source ==
                DeviceStochasticDrawPositionSource::HostLogicalPosition;
            const bool source_is_resident_state =
                request.draw_position_source ==
                DeviceStochasticDrawPositionSource::ResidentLogicalState;
            const bool source_is_verifier_snapshot =
                request.draw_position_source ==
                DeviceStochasticDrawPositionSource::VerifierBaseSnapshot;
            const bool derive_thresholds_from_seed =
                request.derive_thresholds_from_seed &&
                request.inverse_sample_seed != 0 &&
                (request.serial_sample_equivalent ||
                 request.use_vllm_probability_rejection) &&
                !source_is_explicit &&
                ((source_is_host_position &&
                  request.inverse_sample_first_logical_position >= 0) ||
                 ((source_is_resident_state || source_is_verifier_snapshot) &&
                  request.inverse_sample_first_logical_position < 0));
            if (request.derive_thresholds_from_seed !=
                    derive_thresholds_from_seed ||
                (!request.derive_thresholds_from_seed && !source_is_explicit))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Seeded stochastic descriptor has an inconsistent draw-position authority for request="
                          << request.request_id);
                return false;
            }
            const size_t required_rows =
                static_cast<size_t>(request.row_count);
            if ((!request.use_device_draft_tokens &&
                 request.draft_tokens.size() < required_rows) ||
                (source_is_explicit &&
                 request.serial_sample_equivalent &&
                 request.sample_thresholds.size() < required_rows) ||
                (source_is_explicit &&
                 !request.serial_sample_equivalent &&
                 (request.accept_thresholds.size() < required_rows ||
                  request.residual_thresholds.size() < required_rows)))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Stochastic descriptor host rows do not cover request="
                          << request.request_id
                          << " row_count=" << request.row_count);
                return false;
            }
            const int32_t *threshold_base_position_device = nullptr;
            if (source_is_resident_state)
            {
                if (!derive_thresholds_from_seed ||
                    !threshold_position_state.coversRequest(request.request_id))
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Resident stochastic threshold descriptor is malformed for request="
                              << request.request_id);
                    return false;
                }
                threshold_base_position_device =
                    threshold_position_state.targetPositionDeviceForRequest(
                        request.request_id);
            }
            else if (source_is_verifier_snapshot)
            {
                if (!derive_thresholds_from_seed ||
                    request.request_id < 0 ||
                    request.request_id >=
                        mtp_publication_base_cache_snapshot_request_count_)
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Verifier-snapshot stochastic threshold descriptor is malformed for request="
                              << request.request_id);
                    return false;
                }
                threshold_base_position_device =
                    publication_metadata.base_cached_tokens + request.request_id;
            }
            const float *accept_thresholds =
                derive_thresholds_from_seed || request.serial_sample_equivalent
                    ? nullptr
                    : request.accept_thresholds.data();
            const float *residual_thresholds =
                derive_thresholds_from_seed || request.serial_sample_equivalent
                    ? nullptr
                    : request.residual_thresholds.data();
            const float *sample_thresholds =
                request.serial_sample_equivalent
                    ? (derive_thresholds_from_seed
                           ? nullptr
                           : request.sample_thresholds.data())
                    : nullptr;
            DeviceSpeculativeVerifyBatchOutcome ignored_host_outcome;

            const bool ok =
                verifyStochasticDistributionsBatchOutcomeOnDeviceCommon(
                    request.first_target_slot,
                    request.first_draft_slot,
                    draft_tokens,
                    accept_thresholds,
                    residual_thresholds,
                    sample_thresholds,
                    request.row_count,
                    request.first_token,
                    request.first_target_sample_slot,
                    request.token_row_offset,
                    request.token_row_stride,
                    request.first_token_from_device,
                    stop_tokens,
                    request.stop_token_count,
                    request.bonus_target_slot,
                    request.bonus_threshold,
                    &ignored_host_outcome,
                    request.inverse_sample_seed,
                    request.inverse_sample_first_logical_position,
                    threshold_base_position_device,
                    /*threshold_position_offset=*/1,
                    request.use_vllm_probability_rejection,
                    request.serial_sample_equivalent,
                    /*output_request_slot=*/request_idx,
                    stream,
                    /*copy_summary_to_host=*/false);
            if (!ok)
                return false;
        }

        if (producer_stop_timing_event)
        {
            if (!backend->recordEvent(
                    producer_stop_timing_event.get(),
                    state_.device_id.gpu_ordinal(),
                    stream))
            {
                PerfStatsCollector::addCounter(
                    "mtp",
                    "stochastic_request_batch_summary_gpu_timing_record_failures",
                    1.0,
                    "decode",
                    state_.device_id.toString(),
                    {{"event", "stop"}});
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to record the preallocated stochastic outcome timing stop event");
                return false;
            }
        }

        std::shared_ptr<void> response_ready_event =
            acquirePersistentMTPOutcomeReadyEvent(
                "stochastic_request_batch_compact_outcome");
        if (!response_ready_event)
        {
            return false;
        }
        /*
         * Record before any caller enqueues state publication on this producer
         * stream.  The compact outcome rows are immutable after the verifier
         * summary kernels above, so the response bridge can wait only for this
         * event and avoid draining later live-state publication work.
         */
        if (!DeviceEventEdge::at(
                 DeviceTimelinePoint::CompactSpeculativeResponseReady)
                 .from(DeviceTimelineRole::VerifierSummary)
                 .publish(
                     *backend,
                     state_.device_id,
                     response_ready_event.get(),
                     stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to record stochastic outcome response-ready event");
            return false;
        }

        materialized_mtp_verifier_device_token_batch_ = {};
        if (!recordDeviceResidentMTPTransactionMutation(
                request_count,
                stream,
                "stochastic_request_batch_device_outcome"))
        {
            return false;
        }
        out_handle->output_tokens_device =
            static_cast<const int32_t *>(stochastic_batch_output_tokens_dev_);
        out_handle->meta_device =
            static_cast<const int *>(stochastic_batch_output_meta_dev_);
        out_handle->request_count = request_count;
        out_handle->output_token_stride =
            stochastic_batch_output_token_stride_;
        out_handle->meta_stride = kSpeculativeBatchMetaCount;
        out_handle->device = state_.device_id;
        out_handle->stream = stream;
        out_handle->response_ready_event = std::move(response_ready_event);
        out_handle->mtp_transaction =
            currentDeviceResidentMTPTransactionLease();
        out_handle->producer_start_timing_event =
            std::move(producer_start_timing_event);
        out_handle->producer_stop_timing_event =
            std::move(producer_stop_timing_event);
        return out_handle->valid();
    }

    bool DeviceGraphOrchestrator::publishRankCompactSpeculativeResponseReady(
        DeviceSpeculativeOutcomeHandle *handle)
    {
        if (!handle ||
            !handle->valid() ||
            handle->device != state_.device_id ||
            handle->stream == nullptr ||
            handle->response_ready_event == nullptr ||
            handle->response_ready_after_rank_collective)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Invalid compact outcome ownership while publishing rank readiness");
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend ||
            !DeviceEventEdge::at(
                 DeviceTimelinePoint::RankCompactSpeculativeResponseReady)
                 .from(DeviceTimelineRole::RankCollective)
                 .publish(
                     *backend,
                     state_.device_id,
                     handle->response_ready_event.get(),
                     handle->stream))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to publish rank compact-outcome readiness");
            return false;
        }

        handle->response_ready_after_rank_collective = true;
        return true;
    }

    bool DeviceGraphOrchestrator::copyDeviceSpeculativeOutcomesToHost(
        const DeviceSpeculativeOutcomeHandle &handle,
        DeviceSpeculativeVerifyBatchOutcome *outcomes)
    {
        using namespace sampling_math;
        if (!handle.valid() ||
            !outcomes ||
            handle.device != state_.device_id ||
            handle.request_count > stochastic_batch_output_request_capacity_)
        {
            return false;
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return false;

        const int request_count = handle.request_count;
        const size_t output_token_elements =
            static_cast<size_t>(request_count) *
            static_cast<size_t>(handle.output_token_stride);
        const size_t meta_elements =
            static_cast<size_t>(request_count) *
            static_cast<size_t>(handle.meta_stride);
        std::vector<int32_t> cpu_output_tokens_storage;
        std::vector<int> cpu_meta_storage;
        int32_t *output_tokens = nullptr;
        int *meta = nullptr;

        if (handle.device.is_gpu())
        {
            if (!stochastic_batch_output_host_scratch_ ||
                !stochastic_batch_output_host_scratch_->canServe(
                    request_count,
                    handle.output_token_stride,
                    handle.meta_stride))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Missing pinned stochastic outcome host scratch for "
                          << request_count << " requests on " << state_.device_id.toString());
                return false;
            }
            output_tokens = stochastic_batch_output_host_scratch_->output_tokens;
            meta = stochastic_batch_output_host_scratch_->meta;
        }
        else
        {
            cpu_output_tokens_storage.assign(output_token_elements, -1);
            cpu_meta_storage.assign(meta_elements, 0);
            output_tokens = cpu_output_tokens_storage.data();
            meta = cpu_meta_storage.data();
        }

        {
            PerfStatsCollector::ScopedTimer total_timer(
                "mtp",
                "stochastic_request_batch_summary_d2h_sync",
                "decode",
                state_.device_id.toString(),
                {{"requests", std::to_string(request_count)}});
            /*
             * Queue both compact copies on a dedicated response bridge stream.
             * Host response materialization is already the ownership handoff for
             * emitted tokens, so split the unavoidable wait into two pieces:
             * response-ready dependency wait and the actual tiny D2H copy wait.
             * Without this split, deferred verifier graph execution shows up as
             * "D2H wait" and hides the real kernel target.
             */
            void *copy_stream = handle.stream;
            if (handle.device.is_gpu())
            {
                if (!stochastic_outcome_response_bridge_stream_)
                {
                    void *raw_copy_stream = nullptr;
                    {
                        PerfStatsCollector::ScopedTimer create_timer(
                            "mtp",
                            "stochastic_request_batch_summary_bridge_stream_create",
                            "decode",
                            state_.device_id.toString(),
                            {{"requests", std::to_string(request_count)}});
                        raw_copy_stream =
                            backend->createStream(state_.device_id.gpu_ordinal());
                    }
                    if (!raw_copy_stream)
                    {
                        LOG_ERROR("[DeviceGraphOrchestrator] Failed to create explicit stochastic outcome D2H bridge stream");
                        return false;
                    }
                    const int device_ordinal = state_.device_id.gpu_ordinal();
                    stochastic_outcome_response_bridge_stream_.reset(
                        raw_copy_stream,
                        [backend, device_ordinal](void *stream)
                        {
                            if (stream)
                                backend->destroyStream(stream, device_ordinal);
                        });
                    PerfStatsCollector::addCounter(
                        "mtp",
                        "stochastic_request_batch_summary_bridge_stream_creations",
                        1.0,
                        "decode",
                        state_.device_id.toString());
                }
                else
                {
                    PerfStatsCollector::addCounter(
                        "mtp",
                        "stochastic_request_batch_summary_bridge_stream_reuses",
                        1.0,
                        "decode",
                        state_.device_id.toString());
                }
                copy_stream = stochastic_outcome_response_bridge_stream_.get();
                {
                    PerfStatsCollector::ScopedTimer dependency_timer(
                        "mtp",
                        "stochastic_request_batch_summary_response_dependency_enqueue",
                        "decode",
                        state_.device_id.toString(),
                        {{"requests", std::to_string(request_count)}});
                    /*
                     * The response bridge is a GPU consumer of the compact
                     * verifier result. Express that producer/consumer edge on
                     * device; a host event wait here would serialize launch
                     * submission and then make the final D2H stream wait below
                     * pay for the same work a second time.
                     */
                    const DeviceTimelinePoint response_point =
                        handle.response_ready_after_rank_collective
                            ? DeviceTimelinePoint::
                                  RankCompactSpeculativeResponseReady
                            : DeviceTimelinePoint::
                                  CompactSpeculativeResponseReady;
                    const DeviceTimelineRole response_producer =
                        handle.response_ready_after_rank_collective
                            ? DeviceTimelineRole::RankCollective
                            : DeviceTimelineRole::VerifierSummary;
                    if (!DeviceEventEdge::at(response_point)
                             .from(response_producer)
                             .to(DeviceTimelineRole::HostResultBridge)
                             .enqueueWait(
                                 *backend,
                                 state_.device_id,
                                 handle.response_ready_event.get(),
                                 handle.stream,
                                 copy_stream))
                    {
                        LOG_ERROR("[DeviceGraphOrchestrator] Failed to enqueue stochastic outcome response-ready dependency");
                        return false;
                    }
                }
            }
            {
                PerfStatsCollector::ScopedTimer enqueue_timer(
                    "mtp",
                    "stochastic_request_batch_summary_d2h_enqueue",
                    "decode",
                    state_.device_id.toString(),
                    {{"requests", std::to_string(request_count)}});
                if (!backend->deviceToHostOnStream(
                        output_tokens,
                        handle.output_tokens_device,
                        sizeof(int32_t) * output_token_elements,
                        state_.device_id.gpu_ordinal(),
                        copy_stream) ||
                    !backend->deviceToHostOnStream(
                        meta,
                        handle.meta_device,
                        sizeof(int) * meta_elements,
                        state_.device_id.gpu_ordinal(),
                        copy_stream))
                {
                    return false;
                }
            }
            {
                PerfStatsCollector::ScopedTimer wait_timer(
                    "mtp",
                    "stochastic_request_batch_summary_d2h_wait",
                    "decode",
                    state_.device_id.toString(),
                    {{"requests", std::to_string(request_count)}});
                if (!backend->synchronizeStream(
                        copy_stream,
                        state_.device_id.gpu_ordinal()))
                {
                    return false;
                }
            }
            drainPendingGpuTimingMeasurements(backend);
            if (handle.producer_start_timing_event &&
                handle.producer_stop_timing_event)
            {
                float elapsed_ms = 0.0f;
                if (backend->eventElapsedTimeMs(
                        handle.producer_start_timing_event.get(),
                        handle.producer_stop_timing_event.get(),
                        state_.device_id.gpu_ordinal(),
                        &elapsed_ms))
                {
                    const double clamped_ms =
                        std::max(0.0, static_cast<double>(elapsed_ms));
                    PerfStatsCollector::recordTimingNs(
                        "mtp",
                        "stochastic_request_batch_summary_gpu_reducer",
                        static_cast<uint64_t>(clamped_ms * 1000000.0),
                        "decode",
                        state_.device_id.toString(),
                        {{"requests", std::to_string(request_count)}});
                }
                else
                {
                    PerfStatsCollector::addCounter(
                        "mtp",
                        "stochastic_request_batch_summary_gpu_timing_read_failures",
                        1.0,
                        "decode",
                        state_.device_id.toString(),
                        {{"requests", std::to_string(request_count)}});
                }
            }
        }

        for (int request_idx = 0; request_idx < request_count; ++request_idx)
        {
            const auto token_base =
                static_cast<size_t>(request_idx) *
                static_cast<size_t>(handle.output_token_stride);
            const auto meta_base =
                static_cast<size_t>(request_idx) *
                static_cast<size_t>(handle.meta_stride);
            const int *request_meta = meta + meta_base;
            if (request_meta[kSpecBatchMetaOk] == 0 ||
                request_meta[kSpecBatchMetaOutputCount] < 0 ||
                request_meta[kSpecBatchMetaOutputCount] >
                    handle.output_token_stride)
            {
                return false;
            }

            DeviceSpeculativeVerifyBatchOutcome &outcome =
                outcomes[request_idx];
            outcome = DeviceSpeculativeVerifyBatchOutcome(
                static_cast<size_t>(handle.output_token_stride));
            for (int output_idx = 0;
                 output_idx < request_meta[kSpecBatchMetaOutputCount];
                 ++output_idx)
            {
                const int32_t token =
                    output_tokens[token_base + static_cast<size_t>(output_idx)];
                if (token < 0)
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Request-batched stochastic summary produced invalid token="
                              << token << " request=" << request_idx
                              << " output_index=" << output_idx);
                    return false;
                }
                outcome.output_tokens[static_cast<size_t>(output_idx)] = token;
            }
            outcome.ok = true;
            outcome.output_token_count =
                request_meta[kSpecBatchMetaOutputCount];
            outcome.accepted_speculative_prefix =
                request_meta[kSpecBatchMetaAcceptedSpeculativePrefix];
            outcome.target_verifier_state_commit_count =
                request_meta[kSpecBatchMetaTargetVerifierStateCommitCount];
            outcome.ready_token = request_meta[kSpecBatchMetaReadyToken];
            outcome.rejected_verified_token =
                request_meta[kSpecBatchMetaRejectedVerifiedToken];
            outcome.stopped_on_output =
                request_meta[kSpecBatchMetaStoppedOnOutput] != 0;
            outcome.all_speculative_accepted =
                request_meta[kSpecBatchMetaAllSpeculativeAccepted] != 0;
            outcome.consumed_verifier_rows =
                request_meta[kSpecBatchMetaConsumedVerifierRows];
            outcome.sampled_terminal =
                request_meta[kSpecBatchMetaSampledTerminal] != 0;
        }

        PerfStatsCollector::addCounter(
            "mtp",
            "stochastic_verify_request_batch_outcomes",
            static_cast<double>(request_count),
            "decode",
            state_.device_id.toString());
        return true;
    }

    bool DeviceGraphOrchestrator::verifyStochasticDistributionsBatchOutcomeOnDeviceCommon(
        int first_target_slot,
        int first_draft_slot,
        const int32_t *draft_tokens,
        const float *accept_thresholds,
        const float *residual_thresholds,
        const float *sample_thresholds,
        int row_count,
        int32_t first_token,
        int first_target_sample_slot,
        int first_token_row_offset,
        int first_token_row_stride,
        bool first_token_from_device,
        const int32_t *stop_tokens,
        int stop_token_count,
        int bonus_target_slot,
        float bonus_threshold,
        DeviceSpeculativeVerifyBatchOutcome *out,
        uint64_t inverse_sample_seed,
        int inverse_sample_first_logical_position,
        const int32_t *threshold_base_position_device,
        int threshold_position_offset,
        bool use_vllm_probability_rejection,
        bool serial_sample_equivalent,
        int output_request_slot,
        void *stream_override,
        bool copy_summary_to_host)
    {
        using namespace sampling_math;
        (void)draft_tokens;
        auto reject = [&](const std::string &reason) -> bool
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Stochastic compact outcome rejected on "
                      << state_.device_id.toString()
                      << ": " << reason
                      << " target_slot=" << first_target_slot
                      << " draft_slot=" << first_draft_slot
                      << " rows=" << row_count
                      << " bonus_slot=" << bonus_target_slot
                      << " output_slot=" << output_request_slot
                      << " first_token_from_device=" << boolTag(first_token_from_device)
                      << " first_target_sample_slot=" << first_target_sample_slot
                      << " token_row_offset=" << first_token_row_offset
                      << " token_row_stride=" << first_token_row_stride
                      << " materialized_batch_valid="
                      << boolTag(materialized_mtp_verifier_device_token_batch_.valid)
                      << " materialized_batch_requests="
                      << materialized_mtp_verifier_device_token_batch_.request_count
                      << " materialized_batch_stride="
                      << materialized_mtp_verifier_device_token_batch_.padded_seq_len
                      << " materialized_batch_capacity="
                      << materialized_mtp_verifier_device_token_batch_.total_token_capacity
                      << " serial_equivalent=" << boolTag(serial_sample_equivalent)
                      << " vllm_rejection=" << boolTag(use_vllm_probability_rejection)
                      << " host_position=" << inverse_sample_first_logical_position
                      << " device_position=" << boolTag(threshold_base_position_device != nullptr));
            return false;
        };
        if (!out)
            return reject("missing compact outcome destination");
        *out = DeviceSpeculativeVerifyBatchOutcome{};

        const bool has_bonus = bonus_target_slot >= 0;
        const bool derive_rejection_thresholds_from_seed =
            accept_thresholds == nullptr &&
            residual_thresholds == nullptr &&
            !serial_sample_equivalent &&
            use_vllm_probability_rejection &&
            inverse_sample_seed != 0 &&
            (inverse_sample_first_logical_position >= 0 ||
             threshold_base_position_device != nullptr);
        const bool has_host_thresholds =
            accept_thresholds != nullptr && residual_thresholds != nullptr;
        const bool has_sample_thresholds = sample_thresholds != nullptr;
        const bool derive_sample_thresholds_from_device_position =
            serial_sample_equivalent &&
            !has_sample_thresholds &&
            inverse_sample_seed != 0 &&
            inverse_sample_first_logical_position < 0 &&
            threshold_base_position_device != nullptr;
        const bool has_resident_threshold_position =
            threshold_base_position_device != nullptr;
        if (has_resident_threshold_position &&
            inverse_sample_first_logical_position >= 0)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Stochastic threshold position must be either device-owned or host-scalar, never both");
            return false;
        }
        const bool first_token_from_target_sample =
            first_token_from_device && first_target_sample_slot >= 0;
        const bool first_token_from_verifier_tokens =
            first_token_from_device && first_token_row_offset >= 0;
        if (!supportsDeviceStochasticMTPVerification())
            return reject("device stochastic verification workspace is unavailable");
        if (first_target_slot < 0 || first_draft_slot < 0)
            return reject("negative target or draft slot");
        if (row_count <= 0 || row_count > mtp_max_draft_depth_)
            return reject("row count is outside the compact verifier limit");
        const int verifier_token_count = row_count + 1;
        const bool materialized_batch_row_matches =
            mtp_verifier_input_tokens_dev_ &&
            materialized_mtp_verifier_device_token_batch_.valid &&
            first_token_row_offset >= 0 &&
            first_token_row_stride ==
                materialized_mtp_verifier_device_token_batch_.padded_seq_len &&
            verifier_token_count <= first_token_row_stride &&
            first_token_row_offset + verifier_token_count <=
                materialized_mtp_verifier_device_token_batch_
                    .total_token_capacity;
        const bool materialized_scalar_row_matches =
            mtp_verifier_input_tokens_dev_ &&
            materialized_mtp_verifier_device_token_row_.valid &&
            first_token_row_offset == 0 &&
            first_token_row_stride == verifier_token_count &&
            materialized_mtp_verifier_device_token_row_
                    .total_verifier_input_tokens == verifier_token_count &&
            materialized_mtp_verifier_device_token_row_.draft_token_count ==
                row_count;
        if (first_target_slot + row_count > stochastic_target_row_capacity_)
            return reject("target rows exceed the allocated stochastic target capacity");
        if (first_draft_slot + row_count > stochastic_draft_row_capacity_)
            return reject("draft rows exceed the allocated stochastic draft capacity");
        if (stop_token_count < 0 ||
            stop_token_count > kSpeculativeBatchMaxStopTokens ||
            (stop_token_count > 0 && !stop_tokens))
        {
            return reject("stop-token descriptor is malformed");
        }
        if (first_token_from_device &&
            first_token_from_target_sample == first_token_from_verifier_tokens)
        {
            return reject("device first token must name exactly one resident source");
        }
        if (first_token_from_target_sample &&
            (first_target_sample_slot >= stochastic_target_row_capacity_ ||
             !stochastic_target_sample_tokens_dev_))
        {
            return reject("target-sample first-token source is outside the resident sample workspace");
        }
        if (first_token_from_verifier_tokens &&
            !materialized_batch_row_matches &&
            !materialized_scalar_row_matches)
        {
            return reject("verifier-token first-token source does not match a complete materialized verifier row");
        }
        if (has_bonus && bonus_target_slot >= stochastic_target_row_capacity_)
            return reject("bonus row exceeds the allocated stochastic target capacity");
        if (output_request_slot < 0 ||
            output_request_slot >= stochastic_batch_output_request_capacity_)
        {
            return reject("compact output request slot exceeds the allocated batch capacity");
        }
        if (serial_sample_equivalent &&
            !has_sample_thresholds &&
            !derive_sample_thresholds_from_device_position)
        {
            return reject("serial-equivalent sampling has no explicit or device-position threshold authority");
        }
        if (!serial_sample_equivalent &&
            !has_host_thresholds &&
            !derive_rejection_thresholds_from_seed)
        {
            return reject("probability rejection has no explicit or seeded threshold authority");
        }

        IBackend *backend = getBackendFor(state_.device_id);
        if (!backend)
            return reject("backend lookup failed");
        /*
         * If the verifier replay was launch-only deferred, all target
         * distribution builds have already been enqueued on this stream. The
         * batch reducer and compact D2H copy consume the same stream and close
         * the handoff. Falling back to a fresh explicit stream would race the
         * verifier rows, so consume-and-clear the pending stream here.
         */
        void *stream = stream_override;
        if (!stream)
        {
            stream = consumePendingLogitsStream(
                PendingLogitsStreamRole::AllPositionVerifier,
                "verifyStochasticDistributionsBatchOutcomeOnDevice");
        }
        if (!stream)
        {
            stream = explicitGPUStreamForOperation(
                "verifyStochasticDistributionsBatchOutcomeOnDevice");
        }
        if (!stream)
            return reject("no explicit verifier stream is available");

        const int target_top_k =
            stochastic_target_top_k_[static_cast<size_t>(first_target_slot)];
        const StochasticRowFormat target_row_format =
            stochastic_target_row_formats_[static_cast<size_t>(first_target_slot)];
        const bool use_processed_target_rows =
            use_vllm_probability_rejection &&
            target_row_format == StochasticRowFormat::ProcessedLogits;
        const bool verifier_uses_one_hot_draft_tokens =
            use_vllm_probability_rejection || serial_sample_equivalent;
        if (target_top_k <= 0 ||
            target_top_k > static_cast<int>(kStochasticDistributionMaxK))
        {
            return reject("target distribution has an invalid top-k width");
        }
        if (target_row_format != StochasticRowFormat::CompactDistribution &&
            target_row_format != StochasticRowFormat::ProcessedLogits)
        {
            return reject("target distribution row format is empty or unsupported");
        }

        for (int row = 0; row < row_count; ++row)
        {
            const int target_slot = first_target_slot + row;
            const int draft_slot = first_draft_slot + row;
            const int draft_top_k =
                stochastic_draft_top_k_[static_cast<size_t>(draft_slot)];
            if (stochastic_target_top_k_[static_cast<size_t>(target_slot)] != target_top_k ||
                stochastic_target_row_formats_[static_cast<size_t>(target_slot)] != target_row_format ||
                (!verifier_uses_one_hot_draft_tokens &&
                 draft_top_k != target_top_k))
            {
                return reject(
                    "target/draft distribution rows disagree on top-k width or row format at row " +
                    std::to_string(row));
            }
        }
        if (has_bonus &&
            (stochastic_target_top_k_[static_cast<size_t>(bonus_target_slot)] != target_top_k ||
             stochastic_target_row_formats_[static_cast<size_t>(bonus_target_slot)] != target_row_format))
        {
            return reject("bonus target distribution disagrees with verifier row format");
        }

        const int full_vocab_size =
            graph_builder_ ? graph_builder_->config().vocab_size : state_.vocab_size;
        if (full_vocab_size <= 0)
            return reject("graph exposes no positive full-vocabulary size");
        auto *target_ids =
            static_cast<int *>(stochastic_target_token_ids_dev_) +
            static_cast<size_t>(first_target_slot) * kStochasticDistributionMaxK;
        auto *target_probs =
            static_cast<float *>(stochastic_target_probs_dev_) +
            static_cast<size_t>(first_target_slot) * kStochasticDistributionMaxK;
        auto *draft_ids =
            static_cast<int *>(stochastic_draft_token_ids_dev_) +
            static_cast<size_t>(first_draft_slot) * kStochasticDistributionMaxK;
        auto *draft_probs =
            static_cast<float *>(stochastic_draft_probs_dev_) +
            static_cast<size_t>(first_draft_slot) * kStochasticDistributionMaxK;
        auto *sampled_draft_tokens =
            static_cast<int *>(stochastic_draft_sample_tokens_dev_) + first_draft_slot;
        auto *sampled_draft_probs =
            (!verifier_uses_one_hot_draft_tokens && stochastic_draft_sample_probs_dev_)
                ? static_cast<float *>(stochastic_draft_sample_probs_dev_) + first_draft_slot
                : nullptr;
        auto *processed_target_logits =
            use_processed_target_rows
                ? static_cast<float *>(stochastic_processed_logits_dev_) +
                      static_cast<size_t>(first_target_slot) *
                          static_cast<size_t>(full_vocab_size)
                : nullptr;
        auto *out_token_dev =
            static_cast<int *>(stochastic_verify_tokens_dev_) + first_target_slot;
        auto *out_accepted_dev =
            static_cast<int *>(stochastic_verify_accepted_dev_) + first_target_slot;
        auto *out_accept_prob_dev =
            static_cast<float *>(stochastic_verify_accept_probs_dev_) + first_target_slot;
        auto *out_threshold_dev =
            static_cast<float *>(stochastic_verify_thresholds_dev_) + first_target_slot;
        auto *summary_tokens_dev =
            static_cast<int32_t *>(stochastic_batch_output_tokens_dev_) +
            static_cast<size_t>(output_request_slot) *
                stochastic_batch_output_token_stride_;
        auto *summary_meta_dev =
            static_cast<int *>(stochastic_batch_output_meta_dev_) +
            static_cast<size_t>(output_request_slot) * kSpeculativeBatchMetaCount;
        const int32_t *summary_draft_tokens_device = nullptr;
        if (materialized_batch_row_matches)
        {
            summary_draft_tokens_device =
                static_cast<const int32_t *>(mtp_verifier_input_tokens_dev_) +
                first_token_row_offset;
        }
        else if (materialized_scalar_row_matches)
        {
            summary_draft_tokens_device =
                static_cast<const int32_t *>(mtp_verifier_input_tokens_dev_);
        }
        if (serial_sample_equivalent && !summary_draft_tokens_device)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Serial-equivalent stochastic MTP outcome requires a materialized verifier-token row");
            return false;
        }

        if (!waitForRequiredStochasticDraftSampleReadyRange(
                first_draft_slot,
                row_count,
                stream,
                "stochastic_batch_verifier"))
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Failed to order stochastic batch verifier after deferred draft samples");
            return false;
        }

        if (debugEnv().validation.validate_buffers)
        {
            std::vector<int32_t> sampled_drafts(
                static_cast<size_t>(row_count));
            if (!backend->deviceToHostFast(
                    sampled_drafts.data(),
                    sampled_draft_tokens,
                    sizeof(int32_t) * static_cast<size_t>(row_count),
                    state_.device_id.gpu_ordinal(),
                    stream))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to inspect deferred stochastic draft tokens");
                return false;
            }
            for (int row = 0; row < row_count; ++row)
            {
                const int32_t token = sampled_drafts[static_cast<size_t>(row)];
                if (token < 0)
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Deferred stochastic draft sample slot="
                              << (first_draft_slot + row)
                              << " is invalid before batch verifier: token="
                              << token);
                    return false;
                }
            }
        }

        if (serial_sample_equivalent)
        {
            if (!has_bonus ||
                target_row_format != StochasticRowFormat::CompactDistribution ||
                (!has_sample_thresholds &&
                 !derive_sample_thresholds_from_device_position) ||
                first_target_slot + row_count >= stochastic_target_row_capacity_)
            {
                return reject("serial-equivalent reducer requires compact target rows, a bonus row, and device-position thresholds");
            }

            std::array<int, kSpeculativeBatchMaxStopTokens> packed_stop_tokens =
                {-1, -1, -1, -1, -1, -1, -1, -1};
            for (int i = 0; i < stop_token_count; ++i)
                packed_stop_tokens[static_cast<size_t>(i)] = stop_tokens[i];

            {
                PerfStatsCollector::ScopedTimer timer(
                    "mtp",
                    "stochastic_serial_equivalent_target_sample_enqueue",
                    "decode",
                    state_.device_id.toString(),
                    {{"rows", std::to_string(row_count)},
                     {"top_k", std::to_string(target_top_k)}});
                for (int row = 0; row < row_count; ++row)
                {
                    const int target_slot = first_target_slot + row;
                    auto *row_ids =
                        static_cast<int *>(stochastic_target_token_ids_dev_) +
                        static_cast<size_t>(target_slot) *
                            kStochasticDistributionMaxK;
                    auto *row_probs =
                        static_cast<float *>(stochastic_target_probs_dev_) +
                        static_cast<size_t>(target_slot) *
                            kStochasticDistributionMaxK;
                    if (!backend->enqueueSampleDistributionF32Device(
                            row_ids,
                            row_probs,
                            target_top_k,
                            has_sample_thresholds
                                ? sample_thresholds[row]
                                : 0.0f,
                            state_.device_id.gpu_ordinal(),
                            stream,
                            out_token_dev + row,
                            /*out_probability_device=*/nullptr,
                            derive_sample_thresholds_from_device_position
                                ? inverse_sample_seed
                                : 0,
                            derive_sample_thresholds_from_device_position
                                ? threshold_base_position_device
                                : nullptr,
                            threshold_position_offset + row))
                    {
                        return reject(
                            "backend rejected serial-equivalent target sample row " +
                            std::to_string(row));
                    }
                }

                auto *bonus_ids =
                    static_cast<int *>(stochastic_target_token_ids_dev_) +
                    static_cast<size_t>(bonus_target_slot) *
                        kStochasticDistributionMaxK;
                auto *bonus_probs =
                    static_cast<float *>(stochastic_target_probs_dev_) +
                    static_cast<size_t>(bonus_target_slot) *
                        kStochasticDistributionMaxK;
                if (!backend->enqueueSampleDistributionF32Device(
                        bonus_ids,
                        bonus_probs,
                        target_top_k,
                        derive_sample_thresholds_from_device_position
                            ? 0.0f
                            : bonus_threshold,
                        state_.device_id.gpu_ordinal(),
                        stream,
                        out_token_dev + row_count,
                        /*out_probability_device=*/nullptr,
                        derive_sample_thresholds_from_device_position
                            ? inverse_sample_seed
                            : 0,
                        derive_sample_thresholds_from_device_position
                            ? threshold_base_position_device
                            : nullptr,
                        threshold_position_offset + row_count))
                {
                    return reject("backend rejected the serial-equivalent bonus sample row");
                }
            }

            bool summary_enqueued = false;
            {
                PerfStatsCollector::ScopedTimer timer(
                    "mtp",
                    "stochastic_serial_equivalent_summary_enqueue",
                    "decode",
                    state_.device_id.toString(),
                    {{"rows", std::to_string(row_count)},
                     {"top_k", std::to_string(target_top_k)}});
                summary_enqueued =
                    backend->enqueueSummarizeGreedySpeculativeVerifyBatch(
                        out_token_dev,
                        summary_draft_tokens_device,
                        row_count,
                        first_token,
                        packed_stop_tokens.data(),
                        stop_token_count,
                        state_.device_id.gpu_ordinal(),
                        stream,
                        stochastic_batch_output_token_stride_,
                        summary_tokens_dev,
                        summary_meta_dev);
            }
            if (!summary_enqueued)
                return reject("backend rejected the serial-equivalent compact summary launch");

            PerfStatsCollector::addCounter(
                "mtp",
                "stochastic_serial_equivalent_verify_batch_device_token_rows",
                static_cast<double>(row_count),
                "decode",
                state_.device_id.toString(),
                {{"top_k", std::to_string(target_top_k)}});
            if (derive_sample_thresholds_from_device_position)
            {
                PerfStatsCollector::addCounter(
                    "mtp",
                    "stochastic_serial_equivalent_resident_position_sample_rows",
                    static_cast<double>(row_count + 1),
                    "decode",
                    state_.device_id.toString(),
                    {{"position_owner", "verifier_base_snapshot"},
                     {"includes_bonus", "true"}});
            }

            if (!copy_summary_to_host)
                return true;

            std::vector<int32_t> output_tokens(
                static_cast<size_t>(stochastic_batch_output_token_stride_));
            std::array<int, kSpeculativeBatchMetaCount> meta{};
            if (!backend->deviceToHostFast(output_tokens.data(),
                                           summary_tokens_dev,
                                           sizeof(int32_t) * output_tokens.size(),
                                           state_.device_id.gpu_ordinal(),
                                           stream) ||
                !backend->deviceToHostFast(meta.data(),
                                           summary_meta_dev,
                                           sizeof(int) * meta.size(),
                                           state_.device_id.gpu_ordinal(),
                                           stream))
            {
                return false;
            }
            return fillSpeculativeVerifyOutcomeFromMeta(
                output_tokens.data(),
                stochastic_batch_output_token_stride_,
                meta.data(),
                out);
        }

        /*
         * First launch: row-local stochastic accept/reject decisions. The
         * sampled MTP draft tokens come from STOCHASTIC_DRAFT_SAMPLE_TOKENS,
         * which is written by sampleStochasticDistributionOnDevice(). The
         * compact outcome path never reads a host draft-token shadow.
         */
        bool verify_enqueued = false;
        if (sampled_draft_tokens)
        {
            if (use_vllm_probability_rejection)
            {
                if (first_target_slot + row_count > stochastic_target_row_capacity_ ||
                    first_draft_slot + row_count > stochastic_draft_row_capacity_)
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] vLLM stochastic verifier requested invalid compact target rows");
                    return false;
                }

                PerfStatsCollector::ScopedTimer timer(
                    "mtp",
                    use_processed_target_rows
                        ? "stochastic_vllm_processed_batch_verify_enqueue"
                        : "stochastic_vllm_compact_batch_verify_enqueue",
                    "decode",
                    state_.device_id.toString(),
                    {{"rows", std::to_string(row_count)},
                     {"top_k", std::to_string(target_top_k)},
                     {"draft", "one_hot"},
                     {"target_format", use_processed_target_rows
                                           ? "processed_logits"
                                           : "compact_distribution"}});
                if (use_processed_target_rows)
                {
                    verify_enqueued =
                        processed_target_logits &&
                        backend->enqueueSpeculativeVerifyProcessedTargetDraftProbabilitiesF32DeviceThresholdsBatchDeviceTokens(
                            processed_target_logits,
                            /*draft_probabilities_device=*/nullptr,
                            row_count,
                            full_vocab_size,
                            full_vocab_size,
                            full_vocab_size,
                            sampled_draft_tokens,
                            accept_thresholds,
                            inverse_sample_seed,
                            inverse_sample_first_logical_position,
                            state_.device_id.gpu_ordinal(),
                            stream,
                            out_token_dev,
                            out_accepted_dev,
                            out_accept_prob_dev,
                            out_threshold_dev,
                            /*no_draft_probabilities=*/true,
                            threshold_base_position_device,
                            threshold_position_offset);
                }
                else
                {
                    verify_enqueued =
                        backend->enqueueSpeculativeVerifyDistributionsF32DeviceThresholdsBatchDeviceTokens(
                            target_ids,
                            target_probs,
                            /*draft_token_ids_device=*/nullptr,
                            /*draft_probs_device=*/nullptr,
                            target_top_k,
                            static_cast<int>(kStochasticDistributionMaxK),
                            sampled_draft_tokens,
                            accept_thresholds,
                            residual_thresholds,
                            row_count,
                            state_.device_id.gpu_ordinal(),
                            stream,
                            out_token_dev,
                            out_accepted_dev,
                            out_accept_prob_dev,
                            out_threshold_dev,
                            /*draft_token_probabilities_device=*/nullptr,
                            inverse_sample_seed,
                            inverse_sample_first_logical_position,
                            full_vocab_size,
                            threshold_base_position_device,
                            threshold_position_offset);
                }
            }
            else
            {
                PerfStatsCollector::ScopedTimer timer(
                    "mtp",
                    "stochastic_batch_verify_enqueue",
                    "decode",
                    state_.device_id.toString(),
                    {{"rows", std::to_string(row_count)},
                     {"top_k", std::to_string(target_top_k)}});
                verify_enqueued =
                    backend->enqueueSpeculativeVerifyDistributionsF32DeviceThresholdsBatchDeviceTokens(
                        target_ids,
                        target_probs,
                        draft_ids,
                        draft_probs,
                        target_top_k,
                        static_cast<int>(kStochasticDistributionMaxK),
                        sampled_draft_tokens,
                        accept_thresholds,
                        residual_thresholds,
                        row_count,
                        state_.device_id.gpu_ordinal(),
                        stream,
                        out_token_dev,
                        out_accepted_dev,
                        out_accept_prob_dev,
                        out_threshold_dev,
                        sampled_draft_probs);
            }
        }
        if (!verify_enqueued)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] GPU stochastic batch verifier requires device-resident draft tokens");
            return false;
        }
        PerfStatsCollector::addCounter(
            "mtp",
            use_vllm_probability_rejection
                ? "stochastic_vllm_compact_one_hot_verify_batch_device_token_rows"
                : "stochastic_verify_batch_device_token_rows",
            static_cast<double>(row_count),
            "decode",
            state_.device_id.toString(),
            {{"top_k", std::to_string(target_top_k)}});
        if (has_resident_threshold_position)
        {
            PerfStatsCollector::addCounter(
                "mtp",
                "stochastic_request_batch_resident_position_threshold_rows",
                static_cast<double>(row_count),
                "decode",
                state_.device_id.toString(),
                {{"target_format",
                  use_processed_target_rows
                      ? "processed_logits"
                      : "compact_distribution"}});
        }

        if (debugEnv().validation.validate_buffers)
        {
            std::vector<int32_t> verifier_tokens(static_cast<size_t>(row_count));
            std::vector<int32_t> verifier_accepted(static_cast<size_t>(row_count));
            if (!backend->deviceToHostFast(
                    verifier_tokens.data(),
                    out_token_dev,
                    sizeof(int32_t) * static_cast<size_t>(row_count),
                    state_.device_id.gpu_ordinal(),
                    stream) ||
                !backend->deviceToHostFast(
                    verifier_accepted.data(),
                    out_accepted_dev,
                    sizeof(int32_t) * static_cast<size_t>(row_count),
                    state_.device_id.gpu_ordinal(),
                    stream))
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to inspect stochastic verifier row outputs");
                return false;
            }
            for (int row = 0; row < row_count; ++row)
            {
                const int32_t token = verifier_tokens[static_cast<size_t>(row)];
                if (token < 0)
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Stochastic verifier row="
                              << row << " produced invalid token=" << token
                              << " accepted="
                              << verifier_accepted[static_cast<size_t>(row)]);
                    return false;
                }
            }
        }

        std::array<int, kSpeculativeBatchMaxStopTokens> packed_stop_tokens =
            {-1, -1, -1, -1, -1, -1, -1, -1};
        for (int i = 0; i < stop_token_count; ++i)
            packed_stop_tokens[static_cast<size_t>(i)] = stop_tokens[i];

        const int *first_token_dev = nullptr;
        if (first_token_from_device)
        {
            if (first_token_from_verifier_tokens)
            {
                first_token_dev =
                    static_cast<const int *>(mtp_verifier_input_tokens_dev_) +
                    first_token_row_offset;
            }
            else
            {
                first_token_dev =
                    static_cast<const int *>(stochastic_target_sample_tokens_dev_) +
                    first_target_sample_slot;
                if (!waitForRequiredStochasticTargetSampleReady(
                        first_target_sample_slot,
                        stream,
                        "stochastic_batch_summary_first_token"))
                {
                    LOG_ERROR("[DeviceGraphOrchestrator] Failed to order stochastic batch summary after deferred target sample");
                    return false;
                }
            }
        }

        const int *bonus_token_dev = nullptr;
        if (has_bonus)
        {
            auto *bonus_out =
                static_cast<int *>(stochastic_verify_tokens_dev_) + bonus_target_slot;
            bool bonus_enqueued = false;
            {
                PerfStatsCollector::ScopedTimer timer(
                    "mtp",
                    use_processed_target_rows
                        ? "stochastic_batch_processed_bonus_sample_enqueue"
                        : "stochastic_batch_bonus_sample_enqueue",
                    "decode",
                    state_.device_id.toString(),
                    {{"top_k", std::to_string(target_top_k)},
                     {"lazy", use_processed_target_rows ? "true" : "false"},
                     {"verifier", "compact_draft_table"}});
                if (use_processed_target_rows)
                {
                    auto *bonus_logits =
                        static_cast<float *>(stochastic_processed_logits_dev_) +
                        static_cast<size_t>(bonus_target_slot) *
                            static_cast<size_t>(full_vocab_size);
                    bonus_enqueued =
                        backend->enqueueSampleProcessedLogitsF32DeviceIfSpeculativeBatchNeedsBonus(
                            bonus_logits,
                            full_vocab_size,
                            full_vocab_size,
                            bonus_threshold,
                            out_token_dev,
                            out_accepted_dev,
                            row_count,
                            first_token_from_device ? -1 : first_token,
                            first_token_dev,
                            packed_stop_tokens.data(),
                            stop_token_count,
                            state_.device_id.gpu_ordinal(),
                            stream,
                            bonus_out,
                            /*out_probability_device=*/nullptr,
                            inverse_sample_seed,
                            threshold_base_position_device,
                            threshold_position_offset + row_count);
                }
                else
                {
                    auto *bonus_ids =
                        static_cast<int *>(stochastic_target_token_ids_dev_) +
                        static_cast<size_t>(bonus_target_slot) * kStochasticDistributionMaxK;
                    auto *bonus_probs =
                        static_cast<float *>(stochastic_target_probs_dev_) +
                        static_cast<size_t>(bonus_target_slot) * kStochasticDistributionMaxK;
                    bonus_enqueued = backend->enqueueSampleDistributionF32Device(
                        bonus_ids,
                        bonus_probs,
                        target_top_k,
                        bonus_threshold,
                        state_.device_id.gpu_ordinal(),
                        stream,
                        bonus_out,
                        /*out_probability_device=*/nullptr,
                        inverse_sample_seed,
                        threshold_base_position_device,
                        threshold_position_offset + row_count);
                }
            }
            if (!bonus_enqueued)
            {
                return false;
            }
            bonus_token_dev = bonus_out;
        }

        bool summary_enqueued = false;
        {
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "stochastic_batch_summary_enqueue",
                "decode",
                state_.device_id.toString(),
                {{"rows", std::to_string(row_count)},
                 {"top_k", std::to_string(target_top_k)},
                 {"first_token_source",
                  first_token_from_device
                      ? (first_token_from_verifier_tokens
                             ? "verifier_token_batch"
                             : "device")
                      : "host"},
                 {"has_bonus", has_bonus ? "true" : "false"}});
            summary_enqueued =
                first_token_from_device
                    ? backend->enqueueSummarizeSpeculativeVerifyBatchDeviceFirstToken(
                          out_token_dev,
                          out_accepted_dev,
                          row_count,
                          first_token_dev,
                          packed_stop_tokens.data(),
                          stop_token_count,
                          bonus_token_dev,
                          has_bonus,
                          state_.device_id.gpu_ordinal(),
                          stream,
                          stochastic_batch_output_token_stride_,
                          summary_tokens_dev,
                          summary_meta_dev)
                    : backend->enqueueSummarizeSpeculativeVerifyBatch(
                          out_token_dev,
                          out_accepted_dev,
                          row_count,
                          first_token,
                          packed_stop_tokens.data(),
                          stop_token_count,
                          bonus_token_dev,
                          has_bonus,
                          state_.device_id.gpu_ordinal(),
                          stream,
                          stochastic_batch_output_token_stride_,
                          summary_tokens_dev,
                          summary_meta_dev);
        }
        if (!summary_enqueued)
        {
            return false;
        }
        if (first_token_from_device)
        {
            PerfStatsCollector::addCounter(
                "mtp",
                "stochastic_batch_summary_device_first_tokens",
                1.0,
                "decode",
                state_.device_id.toString(),
                {{"source",
                  first_token_from_verifier_tokens
                      ? "verifier_token_batch"
                      : "target_sample_slot"},
                 {"slot", std::to_string(first_target_sample_slot)}});
        }

        std::vector<int32_t> output_tokens(
            static_cast<size_t>(stochastic_batch_output_token_stride_));
        std::array<int, kSpeculativeBatchMetaCount> meta{};
        const bool capture_row_debug =
            debugEnv().validation.validate_buffers ||
            Logger::getInstance().shouldLog(LogLevel::VERBOSITY_DEBUG);
        std::vector<float> debug_accept_probs(static_cast<size_t>(row_count));
        std::vector<float> debug_accept_thresholds(static_cast<size_t>(row_count));
        std::vector<int32_t> debug_draft_tokens(static_cast<size_t>(row_count));
        std::vector<float> debug_draft_probs(static_cast<size_t>(row_count));
        /*
         * The batch metadata is fixed-shape and the token payload is bounded by
         * the graph's configured verifier-row capacity. Fast D2H is safe here
         * and keeps ROCm from spending more time validating the pointer than
         * copying the result.
         */
        bool copied_summary = !copy_summary_to_host;
        if (copy_summary_to_host)
        {
            /*
             * This is the intentional host-visible boundary for the compact
             * stochastic outcome. Its time includes any previously enqueued
             * distribution or verifier kernels that have not yet completed.
             */
            PerfStatsCollector::ScopedTimer timer(
                "mtp",
                "stochastic_batch_summary_d2h_sync",
                "decode",
                state_.device_id.toString(),
                {{"rows", std::to_string(row_count)},
                 {"top_k", std::to_string(target_top_k)}});
            copied_summary =
                backend->deviceToHostFast(output_tokens.data(),
                                          summary_tokens_dev,
                                          sizeof(int32_t) * output_tokens.size(),
                                          state_.device_id.gpu_ordinal(),
                                          stream) &&
                backend->deviceToHostFast(meta.data(),
                                          summary_meta_dev,
                                          sizeof(int) * meta.size(),
                                          state_.device_id.gpu_ordinal(),
                                          stream);
            /*
             * The row-detail arrays exist only for debug logging and buffer
             * validation.  Keep production verification to the two semantic
             * transfers above: output tokens and compact outcome metadata.
             * On ROCm each fast D2H copy synchronizes the stream, so copying
             * debug-only rows here would turn one intentional host boundary
             * into several extra synchronization points.
             */
            if (copy_summary_to_host && copied_summary && capture_row_debug)
            {
                copied_summary =
                    backend->deviceToHostFast(debug_accept_probs.data(),
                                              out_accept_prob_dev,
                                              sizeof(float) * static_cast<size_t>(row_count),
                                              state_.device_id.gpu_ordinal(),
                                              stream) &&
                    backend->deviceToHostFast(debug_accept_thresholds.data(),
                                              out_threshold_dev,
                                              sizeof(float) * static_cast<size_t>(row_count),
                                              state_.device_id.gpu_ordinal(),
                                              stream) &&
                    backend->deviceToHostFast(debug_draft_tokens.data(),
                                              sampled_draft_tokens,
                                              sizeof(int32_t) * static_cast<size_t>(row_count),
                                              state_.device_id.gpu_ordinal(),
                                              stream) &&
                    (!sampled_draft_probs ||
                     backend->deviceToHostFast(debug_draft_probs.data(),
                                               sampled_draft_probs,
                                               sizeof(float) * static_cast<size_t>(row_count),
                                               state_.device_id.gpu_ordinal(),
                                               stream));
            }
        }
        if (!copied_summary)
        {
            return false;
        }
        if (copy_summary_to_host)
        {
            drainPendingGpuTimingMeasurements(backend);
        }
        if (!copy_summary_to_host)
        {
            for (int row = 0; row < row_count; ++row)
            {
                stochastic_target_distribution_streams_[
                    static_cast<size_t>(first_target_slot + row)] = nullptr;
                stochastic_target_row_formats_[
                    static_cast<size_t>(first_target_slot + row)] =
                    StochasticRowFormat::Empty;
                stochastic_draft_distribution_streams_[
                    static_cast<size_t>(first_draft_slot + row)] = nullptr;
                stochastic_draft_row_formats_[
                    static_cast<size_t>(first_draft_slot + row)] =
                    StochasticRowFormat::Empty;
                stochastic_draft_top_k_[static_cast<size_t>(first_draft_slot + row)] = 0;
                clearStochasticDraftSampleReadySlot(
                    first_draft_slot + row,
                    StochasticSampleReadyClearMode::Force);
            }
            if (has_bonus)
            {
                stochastic_target_distribution_streams_[
                    static_cast<size_t>(bonus_target_slot)] = nullptr;
                stochastic_target_row_formats_[
                    static_cast<size_t>(bonus_target_slot)] =
                    StochasticRowFormat::Empty;
            }
            if (first_token_from_target_sample)
            {
                clearStochasticTargetSampleReadySlot(
                    first_target_sample_slot,
                    StochasticSampleReadyClearMode::Force);
            }

            PerfStatsCollector::addCounter(
                "mtp",
                "stochastic_verify_batch_outcome_rows",
                static_cast<double>(row_count),
                "decode",
                state_.device_id.toString(),
                {{"top_k", std::to_string(target_top_k)}});
            return true;
        }
        if (capture_row_debug && row_count > 0)
        {
            std::ostringstream row_debug;
            row_debug << "[DeviceGraphOrchestrator] stochastic batch outcome rows="
                      << row_count
                      << " output_count=" << meta[kSpecBatchMetaOutputCount]
                      << " accepted_prefix=" << meta[kSpecBatchMetaAcceptedSpeculativePrefix]
                      << " all_accepted=" << meta[kSpecBatchMetaAllSpeculativeAccepted]
                      << " sampled_terminal=" << meta[kSpecBatchMetaSampledTerminal]
                      << " ready_token=" << meta[kSpecBatchMetaReadyToken]
                      << " rejected_token=" << meta[kSpecBatchMetaRejectedVerifiedToken]
                      << " per_row=";
            for (int row = 0; row < row_count; ++row)
            {
                if (row > 0)
                    row_debug << ",";
                row_debug << "{p=" << debug_accept_probs[static_cast<size_t>(row)]
                          << ",u=" << debug_accept_thresholds[static_cast<size_t>(row)]
                          << ",draft=" << debug_draft_tokens[static_cast<size_t>(row)]
                          << ",q=";
                if (sampled_draft_probs)
                    row_debug << debug_draft_probs[static_cast<size_t>(row)];
                else
                    row_debug << "one_hot";
                row_debug
                          << "}";
            }
            LOG_DEBUG(row_debug.str());
        }

        if (meta[kSpecBatchMetaOk] == 0 ||
            meta[kSpecBatchMetaOutputCount] < 0 ||
            meta[kSpecBatchMetaOutputCount] >
                stochastic_batch_output_token_stride_)
        {
            return false;
        }
        for (int i = 0; i < meta[kSpecBatchMetaOutputCount]; ++i)
        {
            if (output_tokens[static_cast<size_t>(i)] < 0)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Stochastic batch summary produced invalid output token="
                          << output_tokens[static_cast<size_t>(i)]
                          << " at index=" << i
                          << " output_count=" << meta[kSpecBatchMetaOutputCount]
                          << " accepted_prefix="
                          << meta[kSpecBatchMetaAcceptedSpeculativePrefix]
                          << " consumed_rows="
                          << meta[kSpecBatchMetaConsumedVerifierRows]);
                return false;
            }
        }

        for (int row = 0; row < row_count; ++row)
        {
            stochastic_target_distribution_streams_[
                static_cast<size_t>(first_target_slot + row)] = nullptr;
            stochastic_target_row_formats_[
                static_cast<size_t>(first_target_slot + row)] =
                StochasticRowFormat::Empty;
            stochastic_draft_distribution_streams_[
                static_cast<size_t>(first_draft_slot + row)] = nullptr;
            stochastic_draft_row_formats_[
                static_cast<size_t>(first_draft_slot + row)] =
                StochasticRowFormat::Empty;
            stochastic_draft_top_k_[static_cast<size_t>(first_draft_slot + row)] = 0;
            clearStochasticDraftSampleReadySlot(
                first_draft_slot + row,
                StochasticSampleReadyClearMode::Force);
        }
        if (has_bonus)
        {
            stochastic_target_distribution_streams_[
                static_cast<size_t>(bonus_target_slot)] = nullptr;
            stochastic_target_row_formats_[
                static_cast<size_t>(bonus_target_slot)] =
                StochasticRowFormat::Empty;
        }
        if (first_token_from_target_sample)
        {
            clearStochasticTargetSampleReadySlot(
                first_target_sample_slot,
                StochasticSampleReadyClearMode::Force);
        }

        out->ok = true;
        out->output_tokens = output_tokens;
        out->output_token_count = meta[kSpecBatchMetaOutputCount];
        out->accepted_speculative_prefix =
            meta[kSpecBatchMetaAcceptedSpeculativePrefix];
        out->target_verifier_state_commit_count =
            meta[kSpecBatchMetaTargetVerifierStateCommitCount];
        out->ready_token = meta[kSpecBatchMetaReadyToken];
        out->rejected_verified_token = meta[kSpecBatchMetaRejectedVerifiedToken];
        out->stopped_on_output = meta[kSpecBatchMetaStoppedOnOutput] != 0;
        out->all_speculative_accepted =
            meta[kSpecBatchMetaAllSpeculativeAccepted] != 0;
        out->consumed_verifier_rows = meta[kSpecBatchMetaConsumedVerifierRows];
        out->sampled_terminal = meta[kSpecBatchMetaSampledTerminal] != 0;

        PerfStatsCollector::addCounter(
            "mtp",
            "stochastic_verify_batch_outcome_rows",
            static_cast<double>(row_count),
            "decode",
            state_.device_id.toString(),
            {{"top_k", std::to_string(target_top_k)}});
        return true;
    }

    // =========================================================================
    // Batch Interface Implementation
    // =========================================================================

    bool DeviceGraphOrchestrator::forward_batch(const std::vector<std::vector<int>> &token_batches)
    {
        // Enable device-scoped logging for this execution
        ScopedDeviceLog device_log(state_.device_id);

        if (token_batches.empty())
        {
            LOG_ERROR("[DeviceGraphOrchestrator] forward_batch() called with empty batch");
            return false;
        }

        int batch_size = static_cast<int>(token_batches.size());
        if (batch_size > state_.batch_size)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Batch size " << batch_size
                                                              << " exceeds initialized batch size " << state_.batch_size);
            return false;
        }

        // Find max sequence length (for padding)
        int max_len = 0;
        for (const auto &seq : token_batches)
        {
            max_len = std::max(max_len, static_cast<int>(seq.size()));
        }
        padded_seq_len_ = max_len;

        // Store actual lengths BEFORE calling forward and publish them through
        // state_.sequence_lengths so attention masks see request-local lengths
        // during the padded graph execution. forward() increments positions and
        // sequence lengths by padded_seq_len; we restore old+actual below.
        std::vector<int> actual_lengths(batch_size);
        for (int i = 0; i < batch_size; ++i)
        {
            actual_lengths[i] = static_cast<int>(token_batches[i].size());
        }
        std::vector<int> old_positions = state_.positions;
        std::vector<int> old_sequence_lengths = state_.sequence_lengths;
        state_.sequence_lengths.resize(batch_size);
        for (int i = 0; i < batch_size; ++i)
        {
            state_.sequence_lengths[i] = actual_lengths[i];
        }

        /*
         * Only ordinary request-batched prefill needs synthetic terminal-row
         * logits. Batched MTP verifier forwards also use forward_batch(), but
         * they intentionally run with all-position logits enabled and carry
         * their own verifier row metadata plan.
         */
        const bool compact_prefill_logits =
            state_.device_id.is_gpu() &&
            batch_size > 1 &&
            !compute_all_position_logits_;
        if (compact_prefill_logits &&
            graph_builder_ &&
            graph_builder_->config().mtp.enabled)
        {
            /*
             * The first sampled token immediately completes a resident mailbox
             * row. Size its persistent metadata before graph construction so
             * admission-time position publication never reallocates after the
             * compact logits tensor has been produced.
             */
            MTPSpecDecodeMetadataShape metadata_shape =
                mtp_spec_decode_metadata_binding_.shape();
            metadata_shape.max_requests =
                std::max(metadata_shape.max_requests, batch_size);
            metadata_shape.max_draft_tokens =
                std::max(
                    metadata_shape.max_draft_tokens,
                    std::max(1, graph_builder_->config().mtp.draft_tokens));
            mtp_spec_decode_metadata_binding_.setShape(metadata_shape);
        }
        auto restore_prefill_logits_mode = [&]()
        {
            if (!compact_prefill_logits)
                return;
            request_batched_prefill_logits_row_count_ = 0;
            if (graph_builder_)
                graph_builder_->setRowIndexedAllPositionLogitRows({});
            setComputeRowIndexedAllPositionLogits(false, 0);
            setComputeAllPositionLogits(false);
        };
        if (compact_prefill_logits)
        {
            if (!setComputeAllPositionLogits(true) ||
                !setComputeRowIndexedAllPositionLogits(true, batch_size) ||
                !graph_builder_)
            {
                LOG_ERROR("[DeviceGraphOrchestrator] Failed to configure "
                          "request-batched terminal logits row selection");
                restore_prefill_logits_mode();
                state_.sequence_lengths = old_sequence_lengths;
                return false;
            }
            request_batched_prefill_logits_row_count_ = batch_size;
        }

        // Create flattened, padded token array [batch_size * padded_seq_len]
        std::vector<int> flat_tokens(batch_size * padded_seq_len_, 0); // pad with 0
        for (int b = 0; b < batch_size; ++b)
        {
            const auto &seq = token_batches[b];
            for (size_t s = 0; s < seq.size(); ++s)
            {
                flat_tokens[b * padded_seq_len_ + s] = seq[s];
            }
        }

        // Call the 3-parameter forward() with padded tokens
        // Note: forward() will set sequence_lengths[b] = padded_seq_len for all b
        const float *result = forward(flat_tokens.data(), padded_seq_len_, batch_size);
        if (compact_prefill_logits)
        {
            /*
             * Keep request_batched_prefill_logits_row_count_ until the sampler
             * consumes the compact logits buffer, but restore graph-builder
             * knobs so the following decode/verifier graph starts from a clean
             * normal-logits configuration.
             */
            if (graph_builder_)
                graph_builder_->setRowIndexedAllPositionLogitRows({});
            setComputeRowIndexedAllPositionLogits(false, 0);
            setComputeAllPositionLogits(false);
            if (!result)
                request_batched_prefill_logits_row_count_ = 0;
        }

        // Restore actual request progress after the padded graph execution.
        // This is important for:
        // 1. Proper logits extraction (only extract non-padded logits)
        // 2. Snapshot comparison (shapes should match actual token count)
        // 3. KV cache position tracking (only actual tokens contribute to cache)
        state_.positions.resize(batch_size);
        state_.sequence_lengths.resize(batch_size);
        for (int i = 0; i < batch_size; ++i)
        {
            const int old_pos =
                i < static_cast<int>(old_positions.size()) ? old_positions[i] : 0;
            const int old_len =
                i < static_cast<int>(old_sequence_lengths.size()) ? old_sequence_lengths[i] : old_pos;
            state_.positions[i] = old_pos + actual_lengths[i];
            state_.sequence_lengths[i] = old_len + actual_lengths[i];
        }

        return result != nullptr;
    }

    const float *DeviceGraphOrchestrator::getLogits(int seq_idx) const
    {
        if (!state_.logits)
        {
            return nullptr;
        }

        if (seq_idx < 0 || seq_idx >= state_.batch_size)
        {
            LOG_ERROR("[DeviceGraphOrchestrator] Invalid sequence index " << seq_idx
                                                                          << " (batch_size=" << state_.batch_size << ")");
            return nullptr;
        }

        // Return pointer to logits for requested sequence
        // Layout: [batch_size, vocab_size] (LM head always computes M=1 per batch entry)
        // For sequence seq_idx, logits start at row seq_idx
        const float *base = state_.logits->fp32_data();
        if (!base)
        {
            return nullptr;
        }

        return base + (seq_idx * state_.vocab_size);
    }

    int DeviceGraphOrchestrator::getPosition(int seq_idx) const
    {
        if (seq_idx < 0 || static_cast<size_t>(seq_idx) >= state_.positions.size())
        {
            return 0;
        }
        return state_.positions[seq_idx];
    }

    // =========================================================================
    // Private Helpers
    // =========================================================================

    void DeviceGraphOrchestrator::updateCachedGraphParams(ComputeGraph &graph, int pos_offset, int seq_len)
    {
        // Update all stages in the graph that have dynamic parameters
        const auto &order = graph.getExecutionOrder();

        for (const auto &node_name : order)
        {
            ComputeNode *node = graph.getNode(node_name);
            if (!node || !node->stage)
                continue;

            // Update dynamic params (pos_offset, seq_len)
            // Only stages that override updateDynamicParams will actually do anything
            node->stage->updateDynamicParams(pos_offset, seq_len);
        }

        LOG_TRACE("[DeviceGraphOrchestrator] Updated cached graph params: pos_offset="
                  << pos_offset << " seq_len=" << seq_len);
    }

    bool DeviceGraphOrchestrator::canUseCachedGraph(int layer_idx, int seq_len) const
    {
        if (!cache_config_.enabled)
            return false;
        if (layer_idx < 0 || static_cast<size_t>(layer_idx) >= layer_graph_cache_.size())
            return false;

        const auto &cache = layer_graph_cache_[layer_idx];
        return cache.valid && cache.cached_seq_len == seq_len;
    }

    // =========================================================================
    // MoE Expert Rebalance Controller
    // =========================================================================

    void DeviceGraphOrchestrator::setMoERebalanceController(
        std::unique_ptr<MoERebalanceController> controller)
    {
        moe_rebalance_extra_controllers_.clear();
        moe_rebalance_controller_ = std::move(controller);
    }

    void DeviceGraphOrchestrator::addMoERebalanceController(
        std::unique_ptr<MoERebalanceController> controller)
    {
        if (!controller)
            return;
        if (!moe_rebalance_controller_)
        {
            moe_rebalance_controller_ = std::move(controller);
            return;
        }
        moe_rebalance_extra_controllers_.push_back(std::move(controller));
    }

    std::vector<MoERebalanceController *> DeviceGraphOrchestrator::moeRebalanceControllers() const
    {
        std::vector<MoERebalanceController *> controllers;
        if (moe_rebalance_controller_)
            controllers.push_back(moe_rebalance_controller_.get());
        for (const auto &controller : moe_rebalance_extra_controllers_)
        {
            if (controller)
                controllers.push_back(controller.get());
        }
        return controllers;
    }

    MoERebalanceController *DeviceGraphOrchestrator::moeRebalanceControllerForDomain(
        const std::string &domain_id) const
    {
        if (moe_rebalance_controller_ && moe_rebalance_controller_->domainId() == domain_id)
            return moe_rebalance_controller_.get();
        for (const auto &controller : moe_rebalance_extra_controllers_)
        {
            if (controller && controller->domainId() == domain_id)
                return controller.get();
        }
        return nullptr;
    }

    int DeviceGraphOrchestrator::moeRebalanceParticipantId() const
    {
        if (const auto *global_ctx = globalTPContextForMTPCoordination())
            return global_ctx->myIndex();
        if (graph_builder_ && graph_builder_->config().tp_ctx &&
            graph_builder_->config().tp_ctx->isLocal() &&
            graph_builder_->config().tp_device_idx >= 0)
        {
            return graph_builder_->config().tp_device_idx;
        }
        if (mpi_ctx_ && mpi_ctx_->world_size() > 1)
            return mpi_ctx_->rank();
        return 0;
    }

    void DeviceGraphOrchestrator::initializeExpertPayloadProvider()
    {
        // Count MoE stages to decide if a provider is needed
        int moe_stage_count = 0;
        if (forward_engine_)
        {
            forward_engine_->forEachCachedStage(
                ComputeStageType::MOE_EXPERT_FFN,
                [&](IComputeStage *)
                { ++moe_stage_count; });
        }

        if (moe_stage_count == 0)
        {
            LOG_DEBUG("[DGO] No MoE stages found — skipping payload provider initialization");
            return;
        }

        // Create provider
        expert_payload_provider_ = std::make_unique<ExpertWeightPayloadProvider>();

        // Wire to all cached MoE stages
        int wired = 0;
        forward_engine_->forEachCachedStage(
            ComputeStageType::MOE_EXPERT_FFN,
            [&](IComputeStage *s)
            {
                auto *moe = dynamic_cast<MoEExpertComputeStage *>(s);
                if (moe)
                {
                    moe->setPayloadProvider(expert_payload_provider_.get());
                    ++wired;
                }
            });

        // Wire to WeightManager for host retention decisions
        if (weight_manager_)
        {
            weight_manager_->setExpertPayloadProvider(expert_payload_provider_.get());
        }

        LOG_DEBUG("[DGO] Expert payload provider initialized and wired to "
                  << wired << " MoE stages");
    }

    void DeviceGraphOrchestrator::initializePreparedWeightStore(DeviceId device)
    {
        if (!weight_manager_)
        {
            LOG_DEBUG("[DGO] No weight manager — skipping prepared weight store");
            return;
        }

        ModelContextId requested_model_id{};
        requested_model_id.value = reinterpret_cast<uint64_t>(this); // Fallback only when no model-owned store exists
        if (frozen_weight_set_ && frozen_weight_set_->strategy().model_id.value != 0)
            requested_model_id = frozen_weight_set_->strategy().model_id;

        if (!prepared_weight_store_)
        {
            if (auto concrete_weight_manager = std::dynamic_pointer_cast<WeightManager>(weight_manager_))
            {
                prepared_weight_store_ = concrete_weight_manager->preparedWeightStoreIfInitialized();
            }
            if (!prepared_weight_store_)
            {
                prepared_weight_store_ = std::make_shared<PreparedWeightStore>(requested_model_id);
            }
            if (auto concrete_weight_manager = std::dynamic_pointer_cast<WeightManager>(weight_manager_))
            {
                concrete_weight_manager->setPreparedWeightStore(prepared_weight_store_);
            }
        }
        if (!frozen_weight_set_ && prepared_weight_store_->modelId().value != 0)
            requested_model_id = prepared_weight_store_->modelId();

        if (!prepared_weight_store_->bindModelIdIfUnset(requested_model_id))
        {
            throw std::runtime_error(
                "[DGO] Prepared weight store model id mismatch: store=" +
                std::to_string(prepared_weight_store_->modelId().value) +
                " requested=" + std::to_string(requested_model_id.value));
        }

        ModelContextId model_id = prepared_weight_store_->modelId();
        if (model_id.value == 0)
            model_id = requested_model_id;

        int registered = 0;
        uint64_t next_binding_id = 1;
        if (frozen_weight_set_)
        {
            for (const auto &binding : frozen_weight_set_->bindings())
                next_binding_id = std::max(next_binding_id, binding.binding_id + 1);
        }
        if (decode_replicated_dense_weight_set_)
        {
            for (const auto &binding : decode_replicated_dense_weight_set_->bindings())
                next_binding_id = std::max(next_binding_id, binding.binding_id + 1);
        }

        auto embedding_vocab_metadata = [&](const WeightBinding &binding)
        {
            size_t vocab_offset = binding.slice.row_start;
            size_t total_vocab = binding.slice.source_rows;
            if (total_vocab == 0 && binding.slice.row_count > 0)
                total_vocab = binding.slice.row_start + binding.slice.row_count;

            if (total_vocab == 0)
            {
                const auto &cfg = graph_builder_->config();
                vocab_offset = 0;
                total_vocab = static_cast<size_t>(cfg.vocab_size);
                if (cfg.tp_config)
                {
                    try
                    {
                        const auto &assignment = cfg.tp_config->forDevice(device);
                        vocab_offset = static_cast<size_t>(assignment.vocab_start);
                        total_vocab = static_cast<size_t>(cfg.tp_config->totalVocab());
                    }
                    catch (const std::exception &)
                    {
                        // Fall back to unsharded metadata above.
                    }
                }
            }

            return std::pair<size_t, size_t>{vocab_offset, total_vocab};
        };

        auto register_if_prepared = [&](const WeightBinding &source_binding)
        {
            const std::string &name = source_binding.identity.canonical_name;
            TensorBase *tensor = source_binding.tensor;
            if (!tensor)
                return;

            WeightBinding binding = source_binding;

            if (!frozen_weight_set_)
                binding.identity.model_id = model_id;
            else if (binding.identity.model_id.value == 0)
                binding.identity.model_id = model_id;
            binding.residency.home_device = device;
            binding.residency.resident_device = device;

            try
            {
                if (binding.identity.role == WeightRole::Embedding)
                {
                    const auto *unpackable = dynamic_cast<const IINT8Unpackable *>(tensor);
                    if (device.is_gpu() && unpackable && unpackable->vnniFormatInfo())
                    {
                        if (prepared_weight_store_->preparedRefForBinding(binding.binding_id, device).has_value())
                            return;
                        const auto &cfg = graph_builder_->config();
                        const auto [vocab_offset, total_vocab] =
                            embedding_vocab_metadata(binding);

                        prepared_weight_store_->prepareEmbedding(
                            binding,
                            cfg.d_model,
                            vocab_offset,
                            total_vocab);
                        ++registered;
                    }
                    return;
                }

                if (binding.identity.role == WeightRole::Embedding ||
                    binding.identity.role == WeightRole::Norm ||
                    binding.identity.role == WeightRole::Bias ||
                    tensor->shape().size() != 2)
                {
                    return;
                }

                if (prepared_weight_store_->preparedRefForBinding(binding.binding_id, device).has_value())
                {
                    return;
                }

                if (device.is_cpu())
                {
                    prepared_weight_store_->prepareGemm(binding);
                    ++registered;
                }
            }
            catch (const std::exception &e)
            {
                LOG_WARN("[DGO] Failed to register prepared weight '"
                         << name << "' in store: " << e.what());
            }
        };

        if (frozen_weight_set_)
        {
            // Iterate graph-frozen bindings rather than WeightManager names so
            // aliases such as tied output.weight -> token_embd.weight keep their
            // own binding ids and roles.
            for (const auto &binding : frozen_weight_set_->bindings())
                register_if_prepared(binding);
        }
        if (decode_replicated_dense_weight_set_)
        {
            for (const auto &binding : decode_replicated_dense_weight_set_->bindings())
                register_if_prepared(binding);
        }
        if (!frozen_weight_set_ && !decode_replicated_dense_weight_set_)
        {
            // Fallback for non-frozen legacy graph setup.
            weight_manager_->forEachPreparedWeight([&](const std::string &name, TensorBase *tensor)
                                                   {
                WeightBinding binding;
                binding.binding_id = next_binding_id++;
                binding.identity.canonical_name = name;
                binding.identity.role = inferWeightRole(name);
                binding.identity.layer = inferWeightLayer(name);
                binding.tensor = tensor;
                register_if_prepared(binding); });
        }

        LOG_DEBUG("[DGO] Prepared weight store initialized with "
                  << prepared_weight_store_->size() << " entries for device " << device.toString()
                  << " (new=" << registered << ")");
        if (auto concrete_weight_manager = std::dynamic_pointer_cast<WeightManager>(weight_manager_))
            concrete_weight_manager->logHostMemorySummary("after base preparation");

        // Phase 10: Wire prepared weight store to graph builder so stages
        // can resolve kernels through the store instead of KernelFactory fallbacks.
        if (graph_builder_)
        {
            graph_builder_->setPreparedWeightStore(prepared_weight_store_.get());
        }

        if (!prepareMTPMoEExpertSlabs(device))
        {
            throw std::runtime_error(
                "[DGO] Failed to prepare MTP MoE expert slabs before host weight release");
        }
    }

    bool DeviceGraphOrchestrator::prepareMTPMoEExpertSlabs(DeviceId device)
    {
        if (!device.is_cpu())
            return true;
        if (!prepared_weight_store_ || !frozen_weight_set_ || !graph_builder_)
            return true;

        const auto bindings = makeModelWeightBindings(*frozen_weight_set_);
        if (bindings.mtp.empty() || bindings.mtp.depths.empty())
            return true;

        const GraphConfig &cfg = graph_builder_->config();
        int prepared_depths = 0;

        for (const auto &depth : bindings.mtp.depths)
        {
            const bool has_any_moe_weight =
                depth.fa_block.moe_gate ||
                depth.fa_block.moe_gate_exps ||
                depth.fa_block.moe_up_exps ||
                depth.fa_block.moe_down_exps;
            if (!has_any_moe_weight)
                continue;

            TensorBase *gate_exps = legacyTensor(depth.fa_block.moe_gate_exps);
            TensorBase *up_exps = legacyTensor(depth.fa_block.moe_up_exps);
            TensorBase *down_exps = legacyTensor(depth.fa_block.moe_down_exps);
            if (!gate_exps || !up_exps || !down_exps)
            {
                LOG_ERROR("[DGO] MTP depth " << depth.depth_index
                                             << " has partial MoE expert tensor bindings; refusing lazy raw fallback");
                return false;
            }

            const auto &shape = gate_exps->shape();
            if (shape.size() != 3 || shape[1] == 0)
            {
                LOG_ERROR("[DGO] MTP depth " << depth.depth_index
                                             << " MoE gate expert tensor must be 3D [cols, rows, experts]");
                return false;
            }

            MoEExpertComputeStage::Params params;
            params.device_id = device;
            params.num_experts = cfg.moe.num_experts;
            params.top_k = cfg.moe.top_k;
            params.d_model = cfg.d_model;
            params.expert_intermediate = cfg.moe.intermediate_size > 0
                                             ? cfg.moe.intermediate_size
                                             : static_cast<int>(shape[1]);
            params.layer_idx = depth.source_layer_index >= 0
                                   ? depth.source_layer_index
                                   : cfg.n_layers + depth.depth_index;
            params.gate_exps = gate_exps;
            params.up_exps = up_exps;
            params.down_exps = down_exps;
            params.prepared_store = prepared_weight_store_.get();

            if (cfg.moe.routed_compute_policy == RoutedExpertComputePolicy::Apportioned)
            {
                params.local_expert_start = cfg.moe.local_expert_start;
                params.local_expert_count = cfg.moe.local_expert_count;
                if (params.local_expert_count >= 0)
                {
                    params.expert_mask.assign(cfg.moe.num_experts, false);
                    const int start = std::max(0, params.local_expert_start);
                    const int end = std::min(cfg.moe.num_experts,
                                             start + params.local_expert_count);
                    for (int expert = start; expert < end; ++expert)
                        params.expert_mask[static_cast<size_t>(expert)] = true;
                }
            }

            if (!MoEExpertComputeStage::extractExpertViews(params) ||
                !MoEExpertComputeStage::prepareExpertGemmEngines(params))
            {
                LOG_ERROR("[DGO] Failed to prepare MTP MoE expert slabs for depth "
                          << depth.depth_index << " source_layer=" << params.layer_idx
                          << " on " << device.to_string());
                return false;
            }

            ++prepared_depths;
        }

        if (prepared_depths > 0)
        {
            LOG_DEBUG("[DGO] Prepared " << prepared_depths
                                        << " MTP MoE expert slab set(s) for "
                                        << device.to_string()
                                        << " before host raw weight release");
            PerfStatsCollector::addCounter(
                "weight_loading",
                "mtp_moe_expert_slab_preparations",
                static_cast<double>(prepared_depths),
                "load",
                device.to_string());
        }

        return true;
    }

    void DeviceGraphOrchestrator::applyExpertMasks(
        const std::vector<std::vector<bool>> &masks,
        const ReceivedWeightsMap &received_weights)
    {
        applyExpertMasksForDomain({}, masks, received_weights);
    }

    void DeviceGraphOrchestrator::applyExpertMasksForDomain(
        const std::string &domain_id,
        const std::vector<std::vector<bool>> &masks,
        const ReceivedWeightsMap &received_weights)
    {
        auto t_start = std::chrono::high_resolution_clock::now();
        validateMoERebalanceDomain(*this, domain_id, "applyExpertMasks");

        // Lazily initialize payload provider on first mask application
        if (!expert_payload_provider_)
        {
            initializeExpertPayloadProvider();
        }

        // ── Step 1: Collect all MoE stages ──────────────────────────────
        const bool graph_stable_gpu_rebalance = usesGraphStableGpuMoERebalance();
        if (graph_stable_gpu_rebalance && forward_engine_)
        {
            const size_t invalidated =
                forward_engine_->invalidateMoEPlacementSensitiveGraphsForStablePlacement();
            if (invalidated > 0)
            {
                PerfStatsCollector::addCounter(
                    "moe_rebalance",
                    "graph_stable_placement_cache_invalidations",
                    static_cast<double>(invalidated),
                    "rebalance",
                    primaryDeviceId().is_valid() ? primaryDeviceId().toString() : std::string{},
                    {{"domain_id", domain_id.empty() ? "default" : domain_id}});
                LOG_DEBUG("[DGO] Invalidated " << invalidated
                                               << " MoE placement-sensitive cached graph(s); "
                                               << "fixed prefill and single-token decode remain graph-stable");
            }
        }

        struct StageInfo
        {
            MoEExpertComputeStage *stage;
            int layer;
        };
        std::vector<StageInfo> moe_stages;
        auto accepts_moe_rebalance_stage = [&](MoEExpertComputeStage *stage)
        {
            if (!stage)
                return false;
            return !graph_stable_gpu_rebalance ||
                   stage->usesGraphStableMoEPlacement();
        };

        if (forward_engine_)
            if (prepared_weight_store_)
            {
                forward_engine_->forEachCachedStage(
                    ComputeStageType::MOE_EXPERT_FFN,
                    [&](IComputeStage *s)
                    {
                        auto *moe = dynamic_cast<MoEExpertComputeStage *>(s);
                        if (!accepts_moe_rebalance_stage(moe))
                            return;
                        int layer = moe->layerIndex();
                        if (layer >= 0 && static_cast<size_t>(layer) < masks.size())
                            moe_stages.push_back({moe, layer});
                    });
            }

        // Fallback: legacy layer_graph_cache_ path
        if (moe_stages.empty())
        {
            for (size_t layer = 0; layer < layer_graph_cache_.size() && layer < masks.size(); ++layer)
            {
                auto &cache = layer_graph_cache_[layer];
                if (!cache.valid || !cache.ffn_decode)
                    continue;
                for (const auto &node_name : cache.ffn_decode->getExecutionOrder())
                {
                    auto *node = cache.ffn_decode->getNode(node_name);
                    if (!node || !node->stage)
                        continue;
                    if (node->stage->type() == ComputeStageType::MOE_EXPERT_FFN)
                    {
                        auto *moe = dynamic_cast<MoEExpertComputeStage *>(node->stage.get());
                        if (accepts_moe_rebalance_stage(moe))
                            moe_stages.push_back({moe, static_cast<int>(layer)});
                    }
                }
            }
        }

        if (graph_stable_gpu_rebalance && !masks.empty() && moe_stages.empty())
        {
            throw std::runtime_error(
                "GPU graph-stable MoE rebalance requires cached graph-stable MoE stages");
        }

        const bool has_gpu_publish_stage =
            std::any_of(moe_stages.begin(),
                        moe_stages.end(),
                        [](const StageInfo &info)
                        {
                            return info.stage && info.stage->device().is_gpu();
                        });
        void *publication_stream = nullptr;
        if (has_gpu_publish_stage)
        {
            /*
             * Mask publication mutates graph-stable device tables outside a
             * normal stage execution pass. Cached stages may have had their
             * execution stream cleared at a request boundary, so bind an
             * orchestrator-owned explicit stream before any register/refresh path
             * reaches backend kernels.
             */
            publication_stream = explicitGPUStreamForOperation("moe_expert_mask_publish");
            if (!publication_stream)
            {
                throw std::runtime_error(
                    "MoE expert mask publication requires an explicit non-null GPU stream");
            }
        }

        auto bind_publication_stream = [&](MoEExpertComputeStage *stage)
        {
            if (stage && stage->device().is_gpu())
                stage->setGPUStream(publication_stream);
        };

        for (auto &[stage, layer] : moe_stages)
        {
            (void)layer;
            bind_publication_stream(stage);
        }

        auto release_departed = [&]()
        {
            for (auto &[stage, layer] : moe_stages)
            {
                (void)stage->releaseDepartedExperts(masks[layer]);
            }
        };

        /*
         * Graph-stable GPU rebalance may have several cached MoE stages for the
         * same layer: fixed-topology prefill, single-token decode, and any other
         * preserved graph-stable owners. GPU-direct activation publishes arrivals
         * to the shared PreparedWeightStore before mask application. If one stage
         * releases departures from that store before sibling stages adopt their
         * newly-arrived engines, those siblings can incorrectly fall through to
         * the forbidden host/raw fallback. Adopt first in graph-stable mode, then
         * release once every selected stage has local GEMM handles.
         */
        if (!graph_stable_gpu_rebalance)
            release_departed();

        // ── Step 2: register + prepare (parallel across stages) ─────────
        std::atomic<int> applied{0};
        const int n = static_cast<int>(moe_stages.size());

#pragma omp parallel for schedule(dynamic)
        for (int i = 0; i < n; ++i)
        {
            auto &[stage, layer] = moe_stages[i];
            const std::unordered_map<int, ExpertWeightBlobs> *layer_received = nullptr;
            auto layer_it = received_weights.find(layer);
            if (layer_it != received_weights.end())
                layer_received = &layer_it->second;

            if (stage->registerAndPrepareNewExperts(masks[layer], layer_received))
                applied.fetch_add(1, std::memory_order_relaxed);
        }

        if (applied.load(std::memory_order_relaxed) != n)
        {
            LOG_ERROR("[DGO] Failed to prepare " << (n - applied.load(std::memory_order_relaxed))
                                                 << " MoEExpertComputeStages during expert mask application");
            throw std::runtime_error("MoE expert mask application failed: missing prepared expert weights");
        }

        if (graph_stable_gpu_rebalance)
            release_departed();

        // ── Step 3: apply masks (fast, no heavy ops) ───────────────────
        for (auto &[stage, layer] : moe_stages)
            stage->applyExpertMask(masks[layer]);

        const bool mask_placement_changed = current_expert_masks_ != masks;
        if (mask_placement_changed)
        {
            current_expert_masks_ = masks;
            ++current_expert_mask_epoch_;
            if (graph_stable_gpu_rebalance)
            {
                /*
                 * Graph-stable GPU rebalance deliberately pins
                 * moePlacementEpoch() so decode/prefill graphs keep replaying
                 * through persistent runtime tables. Prefix-cache entries are
                 * different: they encode KV/logits produced under the current
                 * expert residency, so host-published graph-stable mask changes
                 * must still invalidate prefix fingerprints.
                 */
                ++moe_runtime_movement_epoch_;
                PerfStatsCollector::addCounter(
                    "moe_rebalance",
                    "expert_runtime_movement_epoch",
                    static_cast<double>(moe_runtime_movement_epoch_),
                    "rebalance",
                    primaryDeviceId().is_valid() ? primaryDeviceId().toString() : std::string{},
                    {{"domain_id", domain_id.empty() ? "default" : domain_id},
                     {"source", "mask_publish"}});
            }
            PerfStatsCollector::addCounter(
                "moe_rebalance",
                "expert_mask_placement_epoch",
                static_cast<double>(current_expert_mask_epoch_),
                "rebalance",
                primaryDeviceId().is_valid() ? primaryDeviceId().toString() : std::string{},
                {{"domain_id", domain_id.empty() ? "default" : domain_id}});
        }

        LOG_DEBUG("[DGO] Applied expert masks to " << applied.load()
                                                   << " MoEExpertComputeStages across " << masks.size()
                                                   << " layers mask_epoch=" << current_expert_mask_epoch_
                                                   << " changed=" << (mask_placement_changed ? "true" : "false"));

        auto t_end = std::chrono::high_resolution_clock::now();
        double prep_ms = std::chrono::duration<double, std::milli>(t_end - t_start).count();
        if (moe_rebalance_controller_)
            moe_rebalance_controller_->recordPrepDuration(prep_ms);
        LOG_DEBUG("[DGO] Expert mask application + engine prep took "
                  << std::fixed << std::setprecision(1) << prep_ms << " ms");
    }

    ReceivedWeightsMap DeviceGraphOrchestrator::collectExpertWeightsForMasks(
        const std::vector<std::vector<bool>> &masks) const
    {
        ReceivedWeightsMap result;

        std::unordered_map<int, const MoEExpertComputeStage *> moe_by_layer;
        if (forward_engine_)
        {
            forward_engine_->forEachCachedStage(
                ComputeStageType::MOE_EXPERT_FFN,
                [&](IComputeStage *stage)
                {
                    const auto *moe_stage = dynamic_cast<const MoEExpertComputeStage *>(stage);
                    if (moe_stage && moe_stage->layerIndex() >= 0)
                        moe_by_layer[moe_stage->layerIndex()] = moe_stage;
                });
        }

        for (size_t layer_idx = 0; layer_idx < masks.size(); ++layer_idx)
        {
            auto stage_it = moe_by_layer.find(static_cast<int>(layer_idx));
            if (stage_it == moe_by_layer.end())
                continue;

            const auto &mask = masks[layer_idx];
            for (size_t expert_idx = 0; expert_idx < mask.size(); ++expert_idx)
            {
                if (!mask[expert_idx])
                    continue;
                auto blobs = stage_it->second->serializeExpert(static_cast<int>(expert_idx));
                if (!blobs.empty())
                    result[static_cast<int>(layer_idx)][static_cast<int>(expert_idx)] = std::move(blobs);
            }
        }

        return result;
    }

    DeviceGraphOrchestrator::PreparedDirectExpertTransfer
    DeviceGraphOrchestrator::prepareExpertWeightsDirectForMasksFrom(
        DeviceGraphOrchestrator &source,
        const std::vector<std::vector<bool>> &masks)
    {
        PreparedDirectExpertTransfer prepared;
        prepared.remaining_masks = masks;
        retireCompletedGpuDirectActivationCompletions();
        if (&source == this)
            return prepared;

        auto collect_moe_stages = [](DeviceGraphOrchestrator &orchestrator)
        {
            std::unordered_map<int, std::vector<MoEExpertComputeStage *>> by_layer;

            if (orchestrator.forward_engine_)
            {
                orchestrator.forward_engine_->forEachCachedStage(
                    ComputeStageType::MOE_EXPERT_FFN,
                    [&](IComputeStage *stage)
                    {
                        auto *moe_stage = dynamic_cast<MoEExpertComputeStage *>(stage);
                        if (moe_stage && moe_stage->layerIndex() >= 0)
                            by_layer[moe_stage->layerIndex()].push_back(moe_stage);
                    });
            }

            if (by_layer.empty())
            {
                for (size_t layer = 0; layer < orchestrator.layer_graph_cache_.size(); ++layer)
                {
                    auto &cache = orchestrator.layer_graph_cache_[layer];
                    if (!cache.valid || !cache.ffn_decode)
                        continue;
                    for (const auto &node_name : cache.ffn_decode->getExecutionOrder())
                    {
                        auto *node = cache.ffn_decode->getNode(node_name);
                        if (!node || !node->stage ||
                            node->stage->type() != ComputeStageType::MOE_EXPERT_FFN)
                        {
                            continue;
                        }
                        auto *moe_stage = dynamic_cast<MoEExpertComputeStage *>(node->stage.get());
                        if (moe_stage && moe_stage->layerIndex() >= 0)
                            by_layer[moe_stage->layerIndex()].push_back(moe_stage);
                    }
                }
            }

            return by_layer;
        };

        auto src_by_layer = collect_moe_stages(source);
        auto dst_by_layer = collect_moe_stages(*this);
        if (src_by_layer.empty() || dst_by_layer.empty())
            return prepared;

        const bool graph_stable_gpu_rebalance = usesGraphStableGpuMoERebalance();
        auto select_rebalance_destination_stages =
            [&](const std::vector<MoEExpertComputeStage *> &candidates)
        {
            std::vector<MoEExpertComputeStage *> selected;
            selected.reserve(candidates.size());
            for (auto *stage : candidates)
            {
                if (!stage)
                    continue;
                if (graph_stable_gpu_rebalance &&
                    !stage->usesGraphStableMoEPlacement())
                {
                    continue;
                }
                selected.push_back(stage);
            }
            return selected;
        };

        const size_t wave_experts = static_cast<size_t>(
            std::max(1, debugEnv().moe_rebalance.gpu_direct_transfer_wave_experts));
        const size_t staging_buffers = static_cast<size_t>(
            std::max(1, debugEnv().moe_rebalance.gpu_direct_transfer_buffers));
        size_t requested_arrival_entries = 0;
        for (size_t layer_idx = 0; layer_idx < masks.size(); ++layer_idx)
        {
            auto dst_it = dst_by_layer.find(static_cast<int>(layer_idx));
            if (dst_it == dst_by_layer.end())
                continue;

            std::vector<int> expert_ids;
            const auto &layer_mask = masks[layer_idx];
            expert_ids.reserve(static_cast<size_t>(
                std::count(layer_mask.begin(), layer_mask.end(), true)));
            for (size_t expert_idx = 0; expert_idx < layer_mask.size(); ++expert_idx)
            {
                if (layer_mask[expert_idx])
                    expert_ids.push_back(static_cast<int>(expert_idx));
            }
            if (expert_ids.empty())
                continue;

            const auto dst_stages =
                select_rebalance_destination_stages(dst_it->second);
            for (auto *dst_stage : dst_stages)
            {
                if (!dst_stage)
                    continue;
                requested_arrival_entries +=
                    dst_stage->missingPreparedExpertIds(expert_ids).size();
            }
        }
        const size_t staging_pool_capacity =
            std::max(wave_experts * staging_buffers, requested_arrival_entries);

        auto abort_prepared = [&]() -> PreparedDirectExpertTransfer
        {
            prepared.remaining_masks = masks;
            prepared.staged_arrivals.clear();
            pending_gpu_direct_transfer_slot_arrivals_.clear();
            return prepared;
        };

        int staged_layers = 0;
        int staged_experts = 0;
        int staged_stage_arrivals = 0;
        for (size_t layer_idx = 0; layer_idx < prepared.remaining_masks.size(); ++layer_idx)
        {
            auto src_it = src_by_layer.find(static_cast<int>(layer_idx));
            auto dst_it = dst_by_layer.find(static_cast<int>(layer_idx));
            if (src_it == src_by_layer.end() || dst_it == dst_by_layer.end())
                continue;

            std::vector<int> expert_ids;
            const auto &layer_mask = prepared.remaining_masks[layer_idx];
            for (size_t expert_idx = 0; expert_idx < layer_mask.size(); ++expert_idx)
            {
                if (layer_mask[expert_idx])
                    expert_ids.push_back(static_cast<int>(expert_idx));
            }
            if (expert_ids.empty())
                continue;

            std::vector<int> satisfied_counts(prepared.remaining_masks[layer_idx].size(), 0);
            const auto dst_stages =
                select_rebalance_destination_stages(dst_it->second);
            if (dst_stages.empty())
                continue;

            int required_stage_count = 0;
            for (auto *dst_stage : dst_stages)
            {
                ++required_stage_count;
                std::vector<int> stage_pending = dst_stage->missingPreparedExpertIds(expert_ids);
                const size_t active_arrival_capacity = stage_pending.size();
                for (int expert_id : expert_ids)
                {
                    if (std::find(stage_pending.begin(), stage_pending.end(), expert_id) != stage_pending.end())
                        continue;
                    if (expert_id >= 0 &&
                        expert_id < static_cast<int>(satisfied_counts.size()))
                    {
                        ++satisfied_counts[static_cast<size_t>(expert_id)];
                    }
                }

                if (stage_pending.empty())
                    continue;

                for (auto *src_stage : src_it->second)
                {
                    if (!src_stage || stage_pending.empty())
                        continue;

                    void *source_producer_stream = src_stage->gpuStream();
                    if (!source_producer_stream && source.primaryDeviceId().is_gpu())
                    {
                        source_producer_stream =
                            source.explicitGPUStreamForOperation("moe_gpu_direct_transfer_source");
                    }
                    if (!source_producer_stream)
                        continue;

                    std::vector<int> source_satisfied;
                    while (!stage_pending.empty())
                    {
                        const size_t wave_count = std::min(stage_pending.size(), wave_experts);
                        std::vector<int> wave_expert_ids;
                        wave_expert_ids.reserve(wave_count);
                        for (size_t wave_idx = 0; wave_idx < wave_count; ++wave_idx)
                            wave_expert_ids.push_back(stage_pending[wave_idx]);
                        if (wave_expert_ids.empty())
                            continue;

                        GpuDirectTransferSlotArrivals stage_arrivals;
                        auto satisfied_experts =
                            dst_stage->stageExpertsGPUDirectToTransferSlotsFrom(
                                *src_stage,
                                wave_expert_ids,
                                source_producer_stream,
                                &stage_arrivals,
                                active_arrival_capacity,
                                staging_pool_capacity,
                                &gpu_direct_transfer_staging_pools_);
                        if (satisfied_experts.empty())
                            break;

                        if (!stage_arrivals.empty())
                        {
                            PendingGpuDirectTransferSlotArrival pending;
                            pending.destination_stage = dst_stage;
                            pending.arrivals = std::move(stage_arrivals);
                            prepared.staged_arrivals.push_back(pending);
                            pending_gpu_direct_transfer_slot_arrivals_.push_back(std::move(pending));
                            ++staged_stage_arrivals;
                        }

                        source_satisfied.insert(
                            source_satisfied.end(),
                            satisfied_experts.begin(),
                            satisfied_experts.end());

                        std::sort(satisfied_experts.begin(), satisfied_experts.end());
                        satisfied_experts.erase(
                            std::unique(satisfied_experts.begin(), satisfied_experts.end()),
                            satisfied_experts.end());
                        stage_pending.erase(
                            std::remove_if(stage_pending.begin(),
                                           stage_pending.end(),
                                           [&](int expert_id)
                                           {
                                               return std::find(satisfied_experts.begin(),
                                                                satisfied_experts.end(),
                                                                expert_id) != satisfied_experts.end();
                                           }),
                            stage_pending.end());
                    }

                    if (source_satisfied.empty())
                        continue;
                    std::sort(source_satisfied.begin(), source_satisfied.end());
                    source_satisfied.erase(
                        std::unique(source_satisfied.begin(), source_satisfied.end()),
                        source_satisfied.end());
                    for (int expert_id : source_satisfied)
                    {
                        if (expert_id >= 0 &&
                            expert_id < static_cast<int>(satisfied_counts.size()))
                        {
                            ++satisfied_counts[static_cast<size_t>(expert_id)];
                        }
                    }
                }
            }

            if (required_stage_count == 0)
                continue;

            bool any_layer_staged = false;
            for (int expert_id : expert_ids)
            {
                if (expert_id >= 0 &&
                    expert_id < static_cast<int>(prepared.remaining_masks[layer_idx].size()) &&
                    prepared.remaining_masks[layer_idx][static_cast<size_t>(expert_id)] &&
                    expert_id < static_cast<int>(satisfied_counts.size()) &&
                    satisfied_counts[static_cast<size_t>(expert_id)] >= required_stage_count)
                {
                    prepared.remaining_masks[layer_idx][static_cast<size_t>(expert_id)] = false;
                    ++staged_experts;
                    any_layer_staged = true;
                }
            }
            if (any_layer_staged)
                ++staged_layers;
        }

        if (staged_experts > 0)
        {
            LOG_DEBUG("[DGO] GPU-direct/local staged " << staged_experts
                                                       << " expert arrival mask entries across "
                                                       << staged_layers << " layer(s) from sibling orchestrator"
                                                       << " in " << staged_stage_arrivals
                                                       << " async transfer-slot wave(s); activation is deferred until publish");
            PerfStatsCollector::addCounter(
                "moe_rebalance",
                "gpu_direct_transfer_slot_prepare_pending_batches",
                static_cast<double>(staged_stage_arrivals),
                "rebalance",
                primaryDeviceId().to_string(),
                {});
        }

        return prepared;
    }

    bool DeviceGraphOrchestrator::activatePreparedGpuDirectExpertTransfers(
        const std::vector<PendingGpuDirectTransferSlotArrival> &staged_arrivals)
    {
        if (staged_arrivals.empty())
            return true;

        void *activation_stream = explicitGPUStreamForOperation("moe_gpu_direct_transfer_activation");
        if (!activation_stream)
        {
            LOG_ERROR("[DGO] GPU-direct staged expert activation requires an explicit stream on "
                      << primaryDeviceId().to_string());
            return false;
        }

        int activated_batches = 0;
        int activated_experts = 0;
        const bool graph_stable_gpu_rebalance = usesGraphStableGpuMoERebalance();
        for (const auto &pending : staged_arrivals)
        {
            if (pending.empty())
                continue;

            auto expected_experts = pending.arrivals.expertIds();
            GpuDirectTransferCompletion activation_completion;
            auto activated =
                pending.destination_stage->activateGpuDirectTransferSlotArrivals(
                    pending.arrivals,
                    activation_stream,
                    graph_stable_gpu_rebalance ? &activation_completion : nullptr,
                    !graph_stable_gpu_rebalance);
            std::sort(activated.begin(), activated.end());
            activated.erase(std::unique(activated.begin(), activated.end()), activated.end());
            if (activated != expected_experts)
            {
                LOG_ERROR("[DGO] GPU-direct staged expert activation mismatch on "
                          << primaryDeviceId().to_string()
                          << " expected=" << expected_experts.size()
                          << " activated=" << activated.size());
                return false;
            }
            if (graph_stable_gpu_rebalance && activation_completion.valid())
                pending_gpu_direct_activation_completions_.push_back(std::move(activation_completion));
            ++activated_batches;
            activated_experts += static_cast<int>(activated.size());
        }

        PerfStatsCollector::addCounter(
            "moe_rebalance",
            "gpu_direct_transfer_slot_publish_batches",
            static_cast<double>(activated_batches),
            "rebalance",
            primaryDeviceId().to_string(),
            {});
        PerfStatsCollector::addCounter(
            "moe_rebalance",
            "gpu_direct_transfer_slot_publish_experts",
            static_cast<double>(activated_experts),
            "rebalance",
            primaryDeviceId().to_string(),
            {});
        return true;
    }

    void DeviceGraphOrchestrator::clearPendingGpuDirectExpertTransfers()
    {
        pending_gpu_direct_transfer_slot_arrivals_.clear();
        pending_gpu_direct_activation_completions_.clear();
    }

    void DeviceGraphOrchestrator::retireCompletedGpuDirectActivationCompletions()
    {
        if (pending_gpu_direct_activation_completions_.empty())
            return;

        std::vector<GpuDirectTransferCompletion> still_pending;
        still_pending.reserve(pending_gpu_direct_activation_completions_.size());
        int retired = 0;
        for (auto &completion : pending_gpu_direct_activation_completions_)
        {
            if (!completion.valid())
                continue;

            bool ready = false;
            bool queried = false;
            try
            {
                auto &gpu_ctx = GPUDeviceContextPool::instance().getContext(completion.device_id);
                queried = gpu_ctx.queryEventChecked(completion.ready_event.get(), ready);
            }
            catch (const std::exception &e)
            {
                LOG_DEBUG("[DGO] Could not query graph-stable GPU-direct activation completion on "
                          << completion.device_id.to_string() << ": " << e.what());
            }

            if (queried && ready)
            {
                ++retired;
                continue;
            }
            still_pending.push_back(std::move(completion));
        }

        pending_gpu_direct_activation_completions_.swap(still_pending);
        if (retired > 0)
        {
            PerfStatsCollector::addCounter(
                "moe_rebalance",
                "gpu_direct_activation_completions_retired",
                static_cast<double>(retired),
                "rebalance",
                primaryDeviceId().to_string(),
                {});
        }
    }

    bool DeviceGraphOrchestrator::activatePendingGpuDirectExpertTransfers()
    {
        retireCompletedGpuDirectActivationCompletions();
        std::vector<PendingGpuDirectTransferSlotArrival> pending;
        pending.swap(pending_gpu_direct_transfer_slot_arrivals_);
        const bool ok = activatePreparedGpuDirectExpertTransfers(pending);
        if (!ok)
            pending_gpu_direct_transfer_slot_arrivals_.clear();
        return ok;
    }

    std::vector<std::vector<bool>> DeviceGraphOrchestrator::transferExpertWeightsDirectForMasksFrom(
        DeviceGraphOrchestrator &source,
        const std::vector<std::vector<bool>> &masks)
    {
        std::vector<std::vector<bool>> remaining = masks;
        if (&source == this)
            return remaining;

        auto collect_moe_stages = [](DeviceGraphOrchestrator &orchestrator)
        {
            std::unordered_map<int, std::vector<MoEExpertComputeStage *>> by_layer;

            if (orchestrator.forward_engine_)
            {
                orchestrator.forward_engine_->forEachCachedStage(
                    ComputeStageType::MOE_EXPERT_FFN,
                    [&](IComputeStage *stage)
                    {
                        auto *moe_stage = dynamic_cast<MoEExpertComputeStage *>(stage);
                        if (moe_stage && moe_stage->layerIndex() >= 0)
                            by_layer[moe_stage->layerIndex()].push_back(moe_stage);
                    });
            }

            if (by_layer.empty())
            {
                for (size_t layer = 0; layer < orchestrator.layer_graph_cache_.size(); ++layer)
                {
                    auto &cache = orchestrator.layer_graph_cache_[layer];
                    if (!cache.valid || !cache.ffn_decode)
                        continue;
                    for (const auto &node_name : cache.ffn_decode->getExecutionOrder())
                    {
                        auto *node = cache.ffn_decode->getNode(node_name);
                        if (!node || !node->stage ||
                            node->stage->type() != ComputeStageType::MOE_EXPERT_FFN)
                        {
                            continue;
                        }
                        auto *moe_stage = dynamic_cast<MoEExpertComputeStage *>(node->stage.get());
                        if (moe_stage && moe_stage->layerIndex() >= 0)
                            by_layer[moe_stage->layerIndex()].push_back(moe_stage);
                    }
                }
            }

            return by_layer;
        };

        auto src_by_layer = collect_moe_stages(source);
        auto dst_by_layer = collect_moe_stages(*this);
        if (src_by_layer.empty() || dst_by_layer.empty())
            return remaining;

        int copied_layers = 0;
        int copied_experts = 0;
        for (size_t layer_idx = 0; layer_idx < remaining.size(); ++layer_idx)
        {
            auto src_it = src_by_layer.find(static_cast<int>(layer_idx));
            auto dst_it = dst_by_layer.find(static_cast<int>(layer_idx));
            if (src_it == src_by_layer.end() || dst_it == dst_by_layer.end())
                continue;

            std::vector<int> expert_ids;
            const auto &layer_mask = remaining[layer_idx];
            for (size_t expert_idx = 0; expert_idx < layer_mask.size(); ++expert_idx)
            {
                if (layer_mask[expert_idx])
                    expert_ids.push_back(static_cast<int>(expert_idx));
            }
            if (expert_ids.empty())
                continue;

            std::vector<int> satisfied_counts(remaining[layer_idx].size(), 0);
            int required_stage_count = 0;
            for (auto *dst_stage : dst_it->second)
            {
                if (!dst_stage)
                    continue;
                ++required_stage_count;

                std::vector<int> stage_pending = expert_ids;
                for (auto *src_stage : src_it->second)
                {
                    if (!src_stage || stage_pending.empty())
                        continue;

                    void *source_producer_stream = src_stage->gpuStream();
                    if (!source_producer_stream && source.primaryDeviceId().is_gpu())
                    {
                        source_producer_stream =
                            source.explicitGPUStreamForOperation("moe_gpu_direct_transfer_source");
                    }
                    if (!source_producer_stream)
                        continue;

                    auto satisfied_experts =
                        dst_stage->transferExpertsGPUDirectFrom(
                            *src_stage,
                            stage_pending,
                            source_producer_stream);
                    if (satisfied_experts.empty())
                        continue;

                    for (int expert_id : satisfied_experts)
                    {
                        if (expert_id >= 0 &&
                            expert_id < static_cast<int>(satisfied_counts.size()))
                        {
                            ++satisfied_counts[static_cast<size_t>(expert_id)];
                        }
                    }

                    stage_pending.erase(
                        std::remove_if(stage_pending.begin(),
                                       stage_pending.end(),
                                       [&](int expert_id)
                                       {
                                           return std::find(satisfied_experts.begin(),
                                                            satisfied_experts.end(),
                                                            expert_id) != satisfied_experts.end();
                                       }),
                        stage_pending.end());
                }
            }

            if (required_stage_count == 0)
                continue;

            for (int expert_id : expert_ids)
            {
                if (expert_id >= 0 &&
                    expert_id < static_cast<int>(remaining[layer_idx].size()) &&
                    remaining[layer_idx][static_cast<size_t>(expert_id)] &&
                    expert_id < static_cast<int>(satisfied_counts.size()) &&
                    satisfied_counts[static_cast<size_t>(expert_id)] >= required_stage_count)
                {
                    remaining[layer_idx][static_cast<size_t>(expert_id)] = false;
                    ++copied_experts;
                }
            }
            ++copied_layers;
        }

        if (copied_experts > 0)
        {
            LOG_DEBUG("[DGO] GPU-direct/local satisfied " << copied_experts
                                                          << " expert arrival mask entries across "
                                                          << copied_layers << " layer(s) from sibling orchestrator");
        }

        return remaining;
    }

    void DeviceGraphOrchestrator::setExpertReplicaSetForParticipant(
        const ExpertReplicaSet &replicas, int participant_id)
    {
        ExpertReplicaSet normalized_replicas = replicas;
        normalized_replicas.rebuildAggregateReplicaFlags();
        validateMoERebalanceDomain(*this, normalized_replicas.domain_id, "setExpertReplicaSetForParticipant");

        const bool replica_placement_changed =
            current_expert_replica_participant_id_ != participant_id ||
            !normalized_replicas.sameReplicaPlacement(current_expert_replica_set_);
        current_expert_replica_set_ = normalized_replicas;
        current_expert_replica_participant_id_ = participant_id;
        if (replica_placement_changed)
            ++current_expert_replica_epoch_;

        int count = 0;
        void *publication_stream = nullptr;
        auto ensure_replica_publication_stream = [&]() -> void *
        {
            if (publication_stream)
                return publication_stream;
            publication_stream = explicitGPUStreamForOperation("moe_replica_set_publish");
            if (!publication_stream)
            {
                throw std::runtime_error(
                    "MoE replica set publication requires an explicit non-null GPU stream");
            }
            return publication_stream;
        };

        if (forward_engine_)
        {
            forward_engine_->forEachCachedStage(
                ComputeStageType::MOE_EXPERT_FFN,
                [&](IComputeStage *s)
                {
                    auto *moe = dynamic_cast<MoEExpertComputeStage *>(s);
                    if (moe)
                    {
                        if (moe->device().is_gpu())
                            moe->setGPUStream(ensure_replica_publication_stream());
                        moe->setReplicaSet(normalized_replicas, participant_id);
                        count++;
                    }
                });
        }

        const std::string device =
            graph_builder_ ? graph_builder_->config().default_device.toString() : std::string{};
        PerfStatsCollector::addCounter(
            "moe_rebalance",
            "replica_set_cached_stage_applications",
            static_cast<double>(count),
            "rebalance",
            device,
            {{"domain_id", normalized_replicas.domain_id},
             {"participant", std::to_string(participant_id)},
             {"replicas", std::to_string(normalized_replicas.num_replicated)},
             {"replica_epoch", std::to_string(current_expert_replica_epoch_)},
             {"placement_changed", replica_placement_changed ? "true" : "false"},
             {"forward_engine", forward_engine_ ? "true" : "false"}});

        LOG_DEBUG("[DGO] Set expert replica info (" << normalized_replicas.num_replicated
                                                    << " replicas) on " << count
                                                    << " MoE stages (participant " << participant_id << ")");
    }

    void DeviceGraphOrchestrator::setExpertReplicaSet(
        const ExpertReplicaSet &replicas, int socket_id)
    {
        setExpertReplicaSetForParticipant(replicas, socket_id);
    }

    size_t DeviceGraphOrchestrator::releaseRawExpertWeights()
    {
        size_t total_freed = 0;
        int stage_count = 0;
        PreparedWeightStore *summary_store = prepared_weight_store_.get();

        if (forward_engine_)
        {
            forward_engine_->forEachCachedStage(
                ComputeStageType::MOE_EXPERT_FFN,
                [&](IComputeStage *s)
                {
                    auto *moe = dynamic_cast<MoEExpertComputeStage *>(s);
                    if (moe)
                    {
                        if (!summary_store)
                            summary_store = moe->buildWeightContext().prepared_store;
                        total_freed += moe->releaseRawExpertWeights();
                        ++stage_count;
                    }
                });
        }

        LOG_DEBUG("[DGO] Released raw expert weights across " << stage_count
                                                              << " MoE stages: " << (total_freed >> 20) << " MB freed");
        if (summary_store)
            if (auto concrete_weight_manager = std::dynamic_pointer_cast<WeightManager>(weight_manager_))
                concrete_weight_manager->logHostMemorySummary("after rebalance raw release");
        return total_freed;
    }

    bool DeviceGraphOrchestrator::materializeForwardGraphForShape(int seq_len, int batch_size)
    {
        if (!state_.isInitialized())
        {
            LOG_ERROR("[DGO] Cannot materialize forward graph before inference state initialization");
            return false;
        }
        if (!hasGlobalWeights())
        {
            LOG_ERROR("[DGO] Cannot materialize forward graph before weights are configured");
            return false;
        }
        if (seq_len <= 0 || batch_size <= 0)
        {
            LOG_ERROR("[DGO] Invalid materialization shape: seq_len=" << seq_len
                                                                      << " batch_size=" << batch_size);
            return false;
        }
        if (batch_size > state_.batch_size)
        {
            LOG_ERROR("[DGO] Materialization batch size " << batch_size
                                                          << " exceeds initialized batch size " << state_.batch_size);
            return false;
        }

        const int total_tokens = batch_size * seq_len;
        if (total_tokens > state_.batch_size * state_.max_seq_len)
        {
            LOG_ERROR("[DGO] Materialization token count " << total_tokens
                                                           << " exceeds buffer capacity "
                                                           << (state_.batch_size * state_.max_seq_len));
            return false;
        }
        const int activation_seq_len =
            state_.activation_seq_len > 0 ? state_.activation_seq_len : state_.max_seq_len;
        if (total_tokens > state_.batch_size * activation_seq_len)
        {
            LOG_ERROR("[DGO] Materialization token count " << total_tokens
                                                           << " exceeds activation graph buffer capacity "
                                                           << (state_.batch_size * activation_seq_len)
                                                           << " (context capacity is "
                                                           << (state_.batch_size * state_.max_seq_len)
                                                           << ")");
            return false;
        }

        if (pp_stage_config_.has_value() && !pp_stage_config_->has_embedding)
        {
            LOG_DEBUG("[DGO] Skipping eager graph materialization for non-embedding PP stage");
            return true;
        }

        std::vector<int> token_ids(static_cast<size_t>(total_tokens), 0);
        std::vector<int> position_ids(static_cast<size_t>(total_tokens));
        for (int i = 0; i < total_tokens; ++i)
            position_ids[static_cast<size_t>(i)] = i % seq_len;

        ModelBuffers model_buffers = state_.toModelBuffers();
        setBuffers(model_buffers);

        ForwardInput input;
        input.token_ids = token_ids.data();
        input.position_ids = position_ids.data();
        input.batch_size = batch_size;
        input.seq_len = seq_len;
        input.position_offset = 0;
        input.device = state_.device_id;
        input.kv_cache = state_.kv_cache.get();

        std::unordered_map<DeviceId, IKVCache *> pp_kv_cache_ptrs;
        if (!state_.pp_kv_caches.empty())
        {
            for (const auto &[device, cache] : state_.pp_kv_caches)
                pp_kv_cache_ptrs[device] = cache.get();
            input.pp_kv_caches = &pp_kv_cache_ptrs;
        }

        auto result = buildForwardGraph(input);
        if (!result)
        {
            LOG_ERROR("[DGO] Eager forward graph materialization failed: " << result.error());
            return false;
        }

        if (!ensureDeviceWorkspaceAllocated(result.graph(), seq_len))
        {
            LOG_ERROR("[DGO] Eager forward graph workspace materialization failed for "
                      << (graph_builder_ ? graph_builder_->architectureName() : std::string("unknown"))
                      << " shape=[batch=" << batch_size << ", seq=" << seq_len << "]");
            return false;
        }

        const size_t stage_count = result.graph().size();
        LOG_DEBUG("[DGO] Eagerly materialized forward graph for "
                  << (graph_builder_ ? graph_builder_->architectureName() : std::string("unknown"))
                  << " shape=[batch=" << batch_size << ", seq=" << seq_len << "]"
                  << " stages=" << stage_count);
        return true;
    }

    ReceivedWeightsMap DeviceGraphOrchestrator::transferExpertWeights(
        const std::vector<ExpertMigration> &manifest,
        int num_layers)
    {
        if (manifest.empty() || !mpi_ctx_)
            return {};

        int my_rank = mpi_ctx_->rank();
        MPI_Comm comm = mpi_ctx_->communicator();

        // Collect MoE stages by layer from forward engine's graph cache.
        std::unordered_map<int, MoEExpertComputeStage *> moe_by_layer;
        if (forward_engine_)
        {
            forward_engine_->forEachCachedStage(
                ComputeStageType::MOE_EXPERT_FFN,
                [&](IComputeStage *stage)
                {
                    auto *moe_stage = dynamic_cast<MoEExpertComputeStage *>(stage);
                    if (moe_stage && moe_stage->layerIndex() >= 0)
                        moe_by_layer[moe_stage->layerIndex()] = moe_stage;
                });
        }

        // Fallback: legacy layer_graph_cache_
        if (moe_by_layer.empty())
        {
            for (size_t layer_idx = 0; layer_idx < layer_graph_cache_.size(); ++layer_idx)
            {
                auto &cache = layer_graph_cache_[layer_idx];
                if (!cache.valid || !cache.ffn_decode)
                    continue;
                for (const auto &node_name : cache.ffn_decode->getExecutionOrder())
                {
                    auto *node = cache.ffn_decode->getNode(node_name);
                    if (!node || !node->stage)
                        continue;
                    if (node->stage->type() == ComputeStageType::MOE_EXPERT_FFN)
                    {
                        auto *moe_stage = dynamic_cast<MoEExpertComputeStage *>(node->stage.get());
                        if (moe_stage)
                            moe_by_layer[static_cast<int>(layer_idx)] = moe_stage;
                    }
                }
            }
        }

        LOG_DEBUG("[DGO] Found " << moe_by_layer.size() << " MoE stages for weight transfer"
                                 << " (forward_engine=" << (forward_engine_ ? "yes" : "no") << ")");

        auto get_blobs = [&](int layer_idx, int expert_id) -> ExpertWeightBlobs
        {
            auto it = moe_by_layer.find(layer_idx);
            if (it == moe_by_layer.end())
                return {};
            return it->second->detachAndSerializeExpert(expert_id);
        };

        return ExpertWeightTransfer::transferAllLayers(manifest, num_layers, get_blobs, my_rank, comm);
    }

    ReceivedWeightsMap DeviceGraphOrchestrator::transferReplicaWeights(
        const ExpertReplicaSet &replicas,
        int num_layers)
    {
        if (replicas.num_replicated == 0 || !mpi_ctx_)
            return {};

        int my_rank = mpi_ctx_->rank();
        int world_size = mpi_ctx_->world_size();
        MPI_Comm comm = mpi_ctx_->communicator();

        // Legacy cross-rank path: aggregate replica sets send each replicated
        // expert from its owner to all non-owner ranks across every layer.
        // LocalTP same-backend GPU domains use RankOrchestrator's layer-aware
        // transfer masks instead of this manifest.
        std::vector<ExpertMigration> manifest;
        for (int e = 0; e < static_cast<int>(replicas.is_replicated.size()); ++e)
        {
            if (!replicas.is_replicated[e])
                continue;
            int owner = replicas.owner_socket[e];
            // Owner sends to every other rank
            for (int r = 0; r < world_size; ++r)
            {
                if (r != owner)
                    manifest.push_back({e, owner, r});
            }
        }

        if (manifest.empty())
            return {};

        LOG_DEBUG("[DGO] Transferring " << replicas.num_replicated
                                        << " replicated experts × " << num_layers << " layers via MPI");

        // Collect MoE stages by layer
        std::unordered_map<int, MoEExpertComputeStage *> moe_by_layer;
        if (forward_engine_)
        {
            forward_engine_->forEachCachedStage(
                ComputeStageType::MOE_EXPERT_FFN,
                [&](IComputeStage *stage)
                {
                    auto *moe_stage = dynamic_cast<MoEExpertComputeStage *>(stage);
                    if (moe_stage && moe_stage->layerIndex() >= 0)
                        moe_by_layer[moe_stage->layerIndex()] = moe_stage;
                });
        }

        // Non-destructive serialize callback — owner keeps its weights
        auto get_blobs = [&](int layer_idx, int expert_id) -> ExpertWeightBlobs
        {
            auto it = moe_by_layer.find(layer_idx);
            if (it == moe_by_layer.end())
                return {};
            return it->second->serializeExpert(expert_id);
        };

        return ExpertWeightTransfer::transferAllLayers(manifest, num_layers, get_blobs, my_rank, comm);
    }

